const COLLECTION_DATA = {
  cms:         { title: 'Count-Min Sketch',              file: 'collection/cms.html',         tag: 'Algorithm' },
  topk:        { title: 'Top-K End-to-End Design',       file: 'collection/topk.html',        tag: 'System Design' },
  ai_handbook: { title: 'AI Leadership Handbook',        file: 'collection/ai_handbook.html', tag: 'AI / Leadership' },
  databases:   { title: 'Databases Compared',            srcdoc: "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Database Showdown: PostgreSQL vs MongoDB vs DynamoDB vs Cassandra</title>\n<link href=\"https://fonts.googleapis.com/css2?family=Playfair+Display:wght@700;900&family=Source+Sans+3:wght@300;400;500;600&family=JetBrains+Mono:wght@400;600&display=swap\" rel=\"stylesheet\">\n<style>\n:root{--ink:#0f0e0c;--page:#f7f5f0;--surface:#eeecea;--surface2:#e5e2dc;--border:#d4d0c8;--muted:#7a7568;--pg:#336791;--pg-bg:#eef4fb;--mg:#13aa52;--mg-bg:#edfaf2;--dy:#ff9900;--dy-bg:#fff8ec;--ca:#1287b1;--ca-bg:#eaf6fb;--red:#c0392b;--red-bg:#fdf0ee;--green:#1a7a4a;--green-bg:#edf8f2;--amber:#b8720a;--amber-bg:#fdf6e8;--blue:#1a4f8a;--blue-bg:#edf2fb;--mono:'JetBrains Mono',monospace;--serif:'Playfair Display',serif;--sans:'Source Sans 3',sans-serif;}\n*{box-sizing:border-box;margin:0;padding:0;}html{scroll-behavior:smooth;}\nbody{background:var(--page);color:var(--ink);font-family:var(--sans);font-size:15px;line-height:1.75;}\n.hero{background:var(--ink);color:#e8e4dc;padding:72px 24px 56px;position:relative;overflow:hidden;}\n.hero::before{content:'';position:absolute;inset:0;background:repeating-linear-gradient(45deg,transparent,transparent 40px,rgba(255,255,255,.015) 40px,rgba(255,255,255,.015) 41px);}\n.hero-inner{max-width:960px;margin:0 auto;position:relative;}\n.hero-tag{font-family:var(--mono);font-size:10px;letter-spacing:4px;color:#6a6458;text-transform:uppercase;margin-bottom:20px;}\nh1{font-family:var(--serif);font-size:clamp(32px,5vw,58px);font-weight:900;line-height:1.05;letter-spacing:-.5px;margin-bottom:20px;color:#f0ece4;}\nh1 em{color:#e8b84b;font-style:normal;}\n.hero-sub{font-size:15px;color:#7a7060;max-width:640px;line-height:1.7;margin-bottom:32px;}\n.db-pills{display:flex;flex-wrap:wrap;gap:8px;}\n.db-pill{font-family:var(--mono);font-size:10px;padding:5px 14px;border-radius:3px;border:1px solid;letter-spacing:.5px;}\n.pill-pg{border-color:#336791;color:#336791;background:rgba(51,103,145,.08);}\n.pill-mg{border-color:#13aa52;color:#13aa52;background:rgba(19,170,82,.08);}\n.pill-dy{border-color:#ff9900;color:#cc7a00;background:rgba(255,153,0,.08);}\n.pill-ca{border-color:#1287b1;color:#1287b1;background:rgba(18,135,177,.08);}\n.nav{position:sticky;top:0;z-index:100;background:var(--ink);border-bottom:1px solid #1e1c18;display:flex;overflow-x:auto;scrollbar-width:none;padding:0 20px;}\n.nav::-webkit-scrollbar{display:none;}\n.nav a{font-family:var(--mono);font-size:10px;letter-spacing:1px;color:#4a4840;text-decoration:none;padding:14px 12px;white-space:nowrap;border-bottom:2px solid transparent;transition:.18s;}\n.nav a:hover{color:#e8b84b;border-color:#e8b84b;}\n.wrap{max-width:960px;margin:0 auto;padding:0 20px;}\nsection{padding:56px 0 36px;border-bottom:2px solid var(--border);}\nsection:last-child{border:none;}\n.sec-tag{font-family:var(--mono);font-size:9px;letter-spacing:4px;text-transform:uppercase;color:var(--muted);margin-bottom:8px;display:flex;align-items:center;gap:10px;}\n.sec-tag::before{content:'';width:20px;height:1px;background:var(--border);}\nh2{font-family:var(--serif);font-size:clamp(22px,3.5vw,32px);font-weight:700;line-height:1.15;margin-bottom:18px;}\nh3{font-family:var(--sans);font-size:17px;font-weight:600;margin:32px 0 10px;border-bottom:1px solid var(--border);padding-bottom:6px;}\nh4{font-size:13px;font-weight:600;margin:16px 0 6px;text-transform:uppercase;letter-spacing:.5px;}\np{color:#3a3830;font-size:14.5px;margin-bottom:12px;}\nstrong{color:var(--ink);}\ncode{font-family:var(--mono);font-size:11.5px;background:var(--surface2);padding:1px 5px;border-radius:3px;color:var(--blue);}\n.db-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:14px;margin:24px 0;}\n.db-card{background:white;border:1px solid var(--border);border-radius:8px;padding:20px;position:relative;overflow:hidden;}\n.db-card::before{content:'';position:absolute;top:0;left:0;right:0;height:4px;}\n.db-card.pg::before{background:var(--pg);}\n.db-card.mg::before{background:var(--mg);}\n.db-card.dy::before{background:var(--dy);}\n.db-card.ca::before{background:var(--ca);}\n.db-logo{font-size:22px;margin-bottom:6px;}\n.db-name{font-family:var(--serif);font-size:17px;font-weight:700;margin-bottom:4px;}\n.db-type{font-family:var(--mono);font-size:9px;letter-spacing:2px;color:var(--muted);margin-bottom:10px;text-transform:uppercase;}\n.db-tagline{font-size:13px;color:#5a5848;line-height:1.55;}\n.db-born{font-family:var(--mono);font-size:9px;color:var(--muted);margin-top:8px;}\n.analogy{background:var(--ink);color:#c8c4b8;border-radius:8px;padding:24px 28px;margin:24px 0;}\n.analogy-label{font-family:var(--mono);font-size:9px;letter-spacing:3px;color:#6a6458;margin-bottom:10px;text-transform:uppercase;}\n.analogy-text{font-size:15px;line-height:1.75;color:#d8d4c8;}\n.analogy-text strong{color:#e8b84b;}\n.callout{border-radius:4px;padding:14px 18px;margin:18px 0;font-size:13.5px;border-left:3px solid;line-height:1.65;}\n.callout p{font-size:13.5px;margin-bottom:6px;}\n.callout p:last-child{margin:0;}\n.cl-blue{background:var(--blue-bg);border-color:var(--blue);color:#1a2a4a;}\n.cl-green{background:var(--green-bg);border-color:var(--green);color:#0a2a1a;}\n.cl-amber{background:var(--amber-bg);border-color:var(--amber);color:#3a2a08;}\n.cl-red{background:var(--red-bg);border-color:var(--red);color:#3a0a08;}\n.cl-lbl{font-family:var(--mono);font-size:9px;letter-spacing:3px;text-transform:uppercase;margin-bottom:6px;opacity:.7;}\n.codeblock{background:var(--ink);border-radius:6px;padding:20px 22px;font-family:var(--mono);font-size:11.5px;line-height:2;overflow-x:auto;margin:14px 0;color:#c8c4b8;border:1px solid #1e1c18;}\n.codeblock .c{color:#3e3d36;}.codeblock .k{color:#e8b84b;}.codeblock .s{color:#8bc4a0;}.codeblock .n{color:#e8946a;}.codeblock .t{color:#7aaee0;}.codeblock .g{color:#a8d878;}.codeblock .r{color:#e87878;}\n.comp-table{width:100%;border-collapse:collapse;margin:20px 0;font-size:13px;}\n.comp-table th{padding:10px 14px;border:1px solid var(--border);background:var(--surface2);font-family:var(--mono);font-size:9px;letter-spacing:1.5px;text-transform:uppercase;color:var(--muted);}\n.comp-table td{padding:11px 14px;border:1px solid var(--border);vertical-align:top;color:#3a3830;line-height:1.6;}\n.comp-table .row-head{font-family:var(--mono);font-size:11px;font-weight:600;background:var(--surface);color:var(--ink);white-space:nowrap;}\n.good{color:var(--green);font-weight:600;}.warn{color:var(--amber);font-weight:600;}.bad{color:var(--red);font-weight:600;}\n.dot{display:inline-block;width:9px;height:9px;border-radius:50%;margin-right:4px;vertical-align:middle;}\n.dot.g{background:var(--green);}.dot.a{background:var(--amber);}.dot.r{background:var(--red);}\n.use-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:14px;margin:20px 0;}\n.use-card{border:1px solid var(--border);border-radius:6px;padding:18px;background:white;}\n.use-card-head{font-family:var(--mono);font-size:11px;font-weight:600;margin-bottom:10px;display:flex;align-items:center;gap:8px;}\n.use-card ul{padding-left:16px;font-size:13px;color:#4a4838;line-height:1.7;}\n.use-card ul li{margin-bottom:4px;}\n.shard-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:14px;margin:20px 0;}\n.shard-card{background:var(--ink);border-radius:8px;padding:20px;color:#c8c4b8;}\n.shard-title{font-family:var(--mono);font-size:10px;letter-spacing:2px;color:#6a6458;margin-bottom:10px;text-transform:uppercase;}\n.shard-name{font-family:var(--serif);font-size:16px;font-weight:700;color:#e8b84b;margin-bottom:8px;}\n.shard-body{font-size:12.5px;line-height:1.65;color:#a8a49c;}\n.shard-verdict{margin-top:10px;font-family:var(--mono);font-size:10px;padding:4px 10px;border-radius:3px;display:inline-block;}\n.sv-easy{background:rgba(26,122,74,.2);color:#5ac882;}.sv-med{background:rgba(184,114,10,.2);color:#e8943a;}.sv-hard{background:rgba(192,57,43,.2);color:#e87868;}\n.faq-item{border:1px solid var(--border);border-radius:4px;margin-bottom:8px;overflow:hidden;}\n.faq-q{padding:14px 18px;display:flex;justify-content:space-between;align-items:center;cursor:pointer;background:white;font-size:14px;font-weight:500;color:var(--ink);user-select:none;}\n.faq-q:hover{background:var(--surface);}\n.faq-q .tog{font-size:18px;color:#e8b84b;flex-shrink:0;margin-left:12px;transition:transform .2s;font-family:var(--mono);}\n.faq-a{display:none;padding:18px;background:var(--surface);font-size:13.5px;color:#3a3830;line-height:1.75;border-top:1px solid var(--border);}\n.faq-item.open .faq-a{display:block;}.faq-item.open .tog{transform:rotate(45deg);}\n.sd-example{background:white;border:1px solid var(--border);border-radius:8px;margin:20px 0;overflow:hidden;}\n.sd-example-head{background:var(--ink);padding:14px 20px;display:flex;align-items:center;gap:12px;}\n.sd-example-title{font-family:var(--serif);font-size:16px;color:#f0ece4;font-weight:700;}\n.sd-example-tag{font-family:var(--mono);font-size:9px;letter-spacing:2px;color:#6a6458;border:1px solid #2e2c28;padding:3px 8px;border-radius:2px;}\n.sd-example-body{padding:20px;}\n.choice-row{display:flex;gap:10px;align-items:flex-start;padding:10px 0;border-bottom:1px solid var(--border);font-size:13px;}\n.choice-row:last-child{border:none;}\n.choice-label{font-family:var(--mono);font-size:10px;letter-spacing:1px;color:var(--muted);width:120px;flex-shrink:0;padding-top:2px;}\n.choice-val{flex:1;color:#3a3830;line-height:1.6;}\n.badge{display:inline-block;font-family:var(--mono);font-size:9px;padding:2px 7px;border-radius:2px;border:1px solid;margin-right:4px;font-weight:500;}\n.b-pg{background:var(--pg-bg);border-color:var(--pg);color:var(--pg);}.b-mg{background:var(--mg-bg);border-color:var(--mg);color:var(--mg);}.b-dy{background:var(--dy-bg);border-color:var(--dy);color:#b06000;}.b-ca{background:var(--ca-bg);border-color:var(--ca);color:var(--ca);}.b-g{background:var(--green-bg);border-color:var(--green);color:var(--green);}.b-r{background:var(--red-bg);border-color:var(--red);color:var(--red);}.b-a{background:var(--amber-bg);border-color:var(--amber);color:var(--amber);}\n.footer{background:var(--ink);text-align:center;padding:36px 20px;font-family:var(--mono);font-size:10px;color:#3a3830;letter-spacing:2px;}\n\n.step-block{background:#fff;border:1px solid var(--border);border-radius:8px;margin:20px 0;overflow:hidden;}\n.step-block-header{background:var(--ink);color:#e8e4dc;padding:13px 18px;font-family:var(--mono);font-size:10px;letter-spacing:2px;text-transform:uppercase;display:flex;align-items:center;gap:10px;}\n.sb-icon{font-size:16px;}\n.step-block-body{padding:0;}\n.step-row{display:flex;gap:0;border-bottom:1px solid var(--border);}\n.step-row:last-child{border-bottom:none;}\n.step-num{background:var(--surface);min-width:46px;display:flex;align-items:flex-start;justify-content:center;padding:16px 6px;font-family:var(--mono);font-size:11px;font-weight:700;color:var(--muted);flex-shrink:0;border-right:1px solid var(--border);}\n.step-content{padding:14px 18px;flex:1;}\n.step-q{font-weight:600;font-size:14px;color:var(--ink);margin-bottom:10px;}\n.step-options{display:flex;flex-direction:column;gap:6px;}\n.step-option{display:flex;gap:10px;align-items:flex-start;padding:9px 13px;border-radius:5px;font-size:13px;line-height:1.65;}\n.opt-yes{background:#edf8f2;border:1px solid #b8ddc8;}\n.opt-no{background:#fdf6e8;border:1px solid #e8c870;}\n.opt-mid{background:#edf2fb;border:1px solid #b8c8e8;}\n.opt-any{background:#f4f0fb;border:1px solid #c8b8e8;}\n.opt-arrow{font-family:var(--mono);font-size:12px;font-weight:700;flex-shrink:0;margin-top:1px;min-width:120px;}\n.opt-yes .opt-arrow{color:#1a7a4a;}\n.opt-no .opt-arrow{color:#b8720a;}\n.opt-mid .opt-arrow{color:#1a4f8a;}\n.opt-any .opt-arrow{color:#5a3c9a;}\n.opt-text{flex:1;color:#3a3830;}\n.concept-grid{display:grid;grid-template-columns:1fr;gap:0;margin:20px 0;border:1px solid var(--border);border-radius:8px;overflow:hidden;}\n.concept-row{display:flex;gap:0;border-bottom:1px solid var(--border);}\n.concept-row:last-child{border-bottom:none;}\n.concept-term{background:var(--ink);color:#e8b84b;font-family:var(--mono);font-size:11.5px;font-weight:600;min-width:155px;padding:14px 16px;flex-shrink:0;border-right:1px solid #2a2820;display:flex;align-items:flex-start;line-height:1.5;}\n.concept-def{padding:13px 16px;flex:1;font-size:13.5px;color:#3a3830;line-height:1.7;background:#fff;}\n.concept-def strong{color:var(--ink);}\n.concept-def code{background:var(--surface);padding:1px 5px;border-radius:3px;font-family:var(--mono);font-size:11px;color:var(--blue);}\n@media(max-width:560px){.concept-row{flex-direction:column;}.concept-term{min-width:auto;border-right:none;border-bottom:1px solid #2a2820;}.opt-arrow{min-width:80px;}}\n\n</style>\n</head>\n<body>\n<div class=\"hero\">\n  <div class=\"hero-inner\">\n    <div class=\"hero-tag\">System Design \u00b7 Database Selection \u00b7 Manish-Almanac</div>\n    <h1>The Database<br><em>Showdown</em></h1>\n    <p class=\"hero-sub\">PostgreSQL vs MongoDB vs DynamoDB vs Cassandra \u2014 every dimension that matters in a FAANG interview, explained so clearly a layman would get it. Includes real system design examples and every follow-up question.</p>\n    <div class=\"db-pills\">\n      <span class=\"db-pill pill-pg\">PostgreSQL</span>\n      <span class=\"db-pill pill-mg\">MongoDB</span>\n      <span class=\"db-pill pill-dy\">DynamoDB</span>\n      <span class=\"db-pill pill-ca\">Cassandra</span>\n    </div>\n  </div>\n</div>\n<nav class=\"nav\">\n  <a href=\"#intuition\">Intuition</a>\n  <a href=\"#identity\">Identity</a>\n  <a href=\"#comparison\">Full Comparison</a>\n  <a href=\"#sharding\">Sharding</a>\n  <a href=\"#consistency\">Consistency</a>\n  <a href=\"#examples\">System Design</a>\n  <a href=\"#decision\">Decision Tree</a>\n  <a href=\"#followups\">Follow-ups</a>\n</nav>\n<div class=\"wrap\">\n\n<section id=\"intuition\">\n  <div class=\"sec-tag\">00 \u00b7 Start Here</div>\n  <h2>Before picking a database, answer one question</h2>\n  <p>Most candidates jump straight to \"I'll use PostgreSQL\" or \"I'll use Cassandra\" without justifying the choice. The interviewer doesn't care which database you pick \u2014 they care <strong>whether you understand what each is optimised for and why it matches your access pattern</strong>.</p>\n  <div class=\"analogy\">\n    <div class=\"analogy-label\">The filing cabinet analogy \u2014 for a complete layman</div>\n    <div class=\"analogy-text\">\n      Imagine you're running a law firm with four types of filing systems:<br><br>\n      <strong>PostgreSQL</strong> is a meticulous paralegal with a master index. Ask anything \u2014 \"all cases involving John AND contract law from 2022\" \u2014 and they find it. But they can only work so fast, and adding more paralegals requires careful coordination.<br><br>\n      <strong>MongoDB</strong> is a flexible folder system. Each folder can hold anything \u2014 a mix of documents, photos, notes. Great when your documents have varying shapes and you're still figuring out what you need to ask.<br><br>\n      <strong>DynamoDB</strong> is a warehouse with perfectly labelled shelves. If you know the shelf number, retrieval is instant and the warehouse grows infinitely. But you can only ask \"what's on shelf 7B\" \u2014 not \"show me everything red.\"<br><br>\n      <strong>Cassandra</strong> is a warehouse distributed across 10 cities. Every city holds a copy of relevant files. Writes go to all 10 simultaneously. No city going down stops you. But reorganising the filing system later is painful.\n    </div>\n  </div>\n  <div class=\"callout cl-amber\">\n    <div class=\"cl-lbl\">The only three questions that matter</div>\n    <p><strong>1. What is your write pattern?</strong> Low-volume transactional writes (PostgreSQL/MongoDB) vs high-throughput append-heavy writes (Cassandra/DynamoDB)?</p>\n    <p><strong>2. What is your read pattern?</strong> Flexible ad-hoc queries (PostgreSQL) vs known key-based lookups (DynamoDB/Cassandra)?</p>\n    <p><strong>3. Do you need ACID transactions?</strong> If yes: PostgreSQL. If no: the others can offer far more scale.</p>\n  </div>\n</section>\n\n<section id=\"identity\">\n  <div class=\"sec-tag\">01 \u00b7 Who Are They</div>\n  <h2>The Four Databases \u2014 Their Core Identity</h2>\n  <div class=\"db-grid\">\n    <div class=\"db-card pg\">\n      <div class=\"db-logo\">\ud83d\udc18</div>\n      <div class=\"db-name\">PostgreSQL</div>\n      <div class=\"db-type\">Relational \u00b7 RDBMS</div>\n      <div class=\"db-tagline\">The Swiss Army knife. When in doubt, reach for Postgres. ACID transactions, joins, complex queries, full-text search, JSON support, and extensions for almost anything.</div>\n      <div class=\"db-born\">Born 1996 \u00b7 Open Source \u00b7 UC Berkeley lineage</div>\n    </div>\n    <div class=\"db-card mg\">\n      <div class=\"db-logo\">\ud83c\udf43</div>\n      <div class=\"db-name\">MongoDB</div>\n      <div class=\"db-type\">Document \u00b7 NoSQL</div>\n      <div class=\"db-tagline\">The developer favourite. Store JSON-like documents with flexible schemas. Great when your data is hierarchical, varies in shape, and you want to iterate fast without migrations.</div>\n      <div class=\"db-born\">Born 2009 \u00b7 MongoDB Inc \u00b7 Document model</div>\n    </div>\n    <div class=\"db-card dy\">\n      <div class=\"db-logo\">\u26a1</div>\n      <div class=\"db-name\">DynamoDB</div>\n      <div class=\"db-type\">Key-Value / Document \u00b7 NoSQL</div>\n      <div class=\"db-tagline\">The infinite scaler. Amazon's fully managed beast. Sub-10ms at any scale, automatic partitioning, built-in TTL, zero operational burden. You pay for predictability.</div>\n      <div class=\"db-born\">Born 2012 \u00b7 AWS Managed \u00b7 Dynamo paper lineage</div>\n    </div>\n    <div class=\"db-card ca\">\n      <div class=\"db-logo\">\ud83d\udc8e</div>\n      <div class=\"db-name\">Cassandra</div>\n      <div class=\"db-type\">Wide-Column \u00b7 NoSQL</div>\n      <div class=\"db-tagline\">The write monster. Designed for 500K writes/sec across multiple data centers. No single point of failure. Used by Netflix, Apple, Discord. But design your tables around your queries \u2014 upfront.</div>\n      <div class=\"db-born\">Born 2008 \u00b7 Apache \u00b7 Facebook lineage</div>\n    </div>\n  </div>\n\n  <h3>The Mental Model: What Type of Storage Are They Really?</h3>\n  <table class=\"comp-table\">\n    <thead><tr><th>Database</th><th>Core Data Unit</th><th>Primary Access Pattern</th><th>Think of it as</th></tr></thead>\n    <tbody>\n      <tr><td class=\"row-head\">PostgreSQL</td><td>Row in a table</td><td>Any SQL \u2014 joins, aggregations, filters</td><td>Excel spreadsheet with a PhD</td></tr>\n      <tr><td class=\"row-head\">MongoDB</td><td>JSON Document</td><td>Query by any field in the document</td><td>A folder of JSON files with indexes</td></tr>\n      <tr><td class=\"row-head\">DynamoDB</td><td>Item (key-value)</td><td>Get by partition key (+ optional sort key)</td><td>A perfectly organised hashmap in the cloud</td></tr>\n      <tr><td class=\"row-head\">Cassandra</td><td>Row in a partition</td><td>Query by partition key, range on clustering key</td><td>Distributed sorted log, partitioned globally</td></tr>\n    </tbody>\n  </table>\n</section>\n\n<section id=\"comparison\">\n  <div class=\"sec-tag\">02 \u00b7 The Full Picture</div>\n  <h2>Every Dimension That Matters in an Interview</h2>\n  <table class=\"comp-table\">\n    <thead><tr><th>Dimension</th><th>PostgreSQL \ud83d\udc18</th><th>MongoDB \ud83c\udf43</th><th>DynamoDB \u26a1</th><th>Cassandra \ud83d\udc8e</th></tr></thead>\n    <tbody>\n      <tr><td class=\"row-head\">Data Model</td><td>Relational \u2014 strict schema</td><td>Document \u2014 flexible JSON</td><td>Key-value + document</td><td>Wide-column \u2014 partition + clustering</td></tr>\n      <tr><td class=\"row-head\">Write Throughput</td><td><span class=\"warn\">~5K\u201320K TPS</span> single node</td><td><span class=\"warn\">~20K\u201350K</span> writes/sec</td><td><span class=\"good\">Millions/sec</span> auto-scaled</td><td><span class=\"good\">500K\u20131M</span> writes/sec</td></tr>\n      <tr><td class=\"row-head\">Read Latency</td><td><span class=\"warn\">1ms\u2013seconds</span> query-dependent</td><td><span class=\"warn\">1ms\u2013100ms</span> index-dependent</td><td><span class=\"good\">Sub-10ms</span> guaranteed</td><td><span class=\"good\">Sub-10ms</span> on partition key</td></tr>\n      <tr><td class=\"row-head\">ACID Transactions</td><td><span class=\"good\">Full ACID</span> multi-table</td><td><span class=\"warn\">Partial</span> multi-doc in v4+ (slow)</td><td><span class=\"warn\">Single-item ACID</span> only</td><td><span class=\"bad\">Limited</span> single-partition only</td></tr>\n      <tr><td class=\"row-head\">Query Flexibility</td><td><span class=\"good\">Unlimited</span> \u2014 full SQL</td><td><span class=\"good\">High</span> \u2014 any field</td><td><span class=\"bad\">Very limited</span> \u2014 by key only</td><td><span class=\"warn\">Constrained</span> \u2014 design for queries</td></tr>\n      <tr><td class=\"row-head\">Horizontal Scale</td><td><span class=\"bad\">Hard</span> \u2014 Citus or manual</td><td><span class=\"warn\">Built-in</span> but complex</td><td><span class=\"good\">Invisible</span> \u2014 AWS auto</td><td><span class=\"good\">Native</span> \u2014 add nodes</td></tr>\n      <tr><td class=\"row-head\">Multi-Region HA</td><td><span class=\"bad\">Manual setup</span></td><td><span class=\"warn\">Replica sets</span></td><td><span class=\"good\">Global Tables</span> managed</td><td><span class=\"good\">Native</span> multi-DC</td></tr>\n      <tr><td class=\"row-head\">Schema Flexibility</td><td><span class=\"bad\">Rigid</span> \u2014 migrations needed</td><td><span class=\"good\">Fully flexible</span></td><td><span class=\"good\">Flexible</span> \u2014 keys only fixed</td><td><span class=\"warn\">Semi-rigid</span> \u2014 upfront design</td></tr>\n      <tr><td class=\"row-head\">Consistency</td><td><span class=\"good\">Strong</span> \u2014 serialisable</td><td><span class=\"warn\">Tunable</span> via write concern</td><td><span class=\"warn\">Eventual default</span>, strong 2x cost</td><td><span class=\"warn\">Tunable</span> ONE/QUORUM/ALL</td></tr>\n      <tr><td class=\"row-head\">Ops Burden</td><td><span class=\"warn\">Self-managed</span></td><td><span class=\"warn\">Self or Atlas</span></td><td><span class=\"good\">Zero ops</span></td><td><span class=\"bad\">High</span> \u2014 complex</td></tr>\n      <tr><td class=\"row-head\">Scale Ceiling</td><td>~10TB, ~50K TPS</td><td>~100TB sharded</td><td>Unlimited (managed)</td><td>Petabyte scale</td></tr>\n      <tr><td class=\"row-head\">Who Uses It</td><td>Instagram, GitHub, Shopify</td><td>Forbes, eBay, EA Games</td><td>Amazon, Lyft, Airbnb</td><td>Netflix, Apple, Discord</td></tr>\n    </tbody>\n  </table>\n</section>\n\n<section id=\"sharding\">\n  <div class=\"sec-tag\">03 \u00b7 The Hard Part</div>\n  <h2>Sharding \u2014 How Each Database Splits Data Across Machines</h2>\n  <p>Sharding is splitting your data across multiple machines so no single machine holds everything. This is the most-tested topic in FAANG interviews because it forces you to confront real trade-offs.</p>\n  <div class=\"analogy\">\n    <div class=\"analogy-label\">Sharding explained with a phone book</div>\n    <div class=\"analogy-text\">\n      You have a phone book with 1 billion entries. It's too heavy for one shelf. You split it:<br><br>\n      <strong>Range sharding</strong> \u2014 A\u2013F on shelf 1, G\u2013M on shelf 2, N\u2013Z on shelf 3. Simple, but \"S\" names might dominate (hot shard).<br><br>\n      <strong>Hash sharding</strong> \u2014 Run the name through a hash function, result tells you which shelf. Perfectly balanced, but you can't look up \"everyone between Adams and Brown\" anymore.<br><br>\n      <strong>Consistent hashing</strong> \u2014 Like hash sharding but when you add a new shelf, you only move a fraction of entries, not half of everything.\n    </div>\n  </div>\n  <div class=\"shard-grid\">\n    <div class=\"shard-card\">\n      <div class=\"shard-title\">PostgreSQL</div>\n      <div class=\"shard-name\">Manual / Citus</div>\n      <div class=\"shard-body\">Postgres doesn't shard natively. You either shard at the application layer or use the Citus extension. Both are complex to operate. Cross-shard joins require careful design. Great for read replicas; write sharding is painful.</div>\n      <span class=\"shard-verdict sv-hard\">HARD \u2014 DIY or Citus</span>\n    </div>\n    <div class=\"shard-card\">\n      <div class=\"shard-title\">MongoDB</div>\n      <div class=\"shard-name\">Built-in Sharding</div>\n      <div class=\"shard-body\">Native range and hash sharding via a mongos router. Shard key choice is the most critical decision. Bad shard key (low cardinality or monotonically increasing) causes hot spots and is very hard to fix after the fact.</div>\n      <span class=\"shard-verdict sv-med\">MEDIUM \u2014 Built-in but tricky</span>\n    </div>\n    <div class=\"shard-card\">\n      <div class=\"shard-title\">DynamoDB</div>\n      <div class=\"shard-name\">Invisible Partitioning</div>\n      <div class=\"shard-body\">AWS handles all partitioning automatically based on your partition key using consistent hashing. You just define a good partition key (high cardinality, evenly distributed). Hot partitions are still your problem if keys are skewed.</div>\n      <span class=\"shard-verdict sv-easy\">EASY \u2014 AWS managed</span>\n    </div>\n    <div class=\"shard-card\">\n      <div class=\"shard-title\">Cassandra</div>\n      <div class=\"shard-name\">Token Ring</div>\n      <div class=\"shard-body\">Uses a consistent hash token ring. Each node owns a range of tokens. Data is hashed to a token, written to that node + N replicas. Adding nodes redistributes tokens automatically. No downtime for scaling.</div>\n      <span class=\"shard-verdict sv-easy\">EASY \u2014 Native, automatic</span>\n    </div>\n  </div>\n\n  <h3>The Hot Partition Problem \u2014 All Four Face It</h3>\n  <div class=\"callout cl-red\">\n    <div class=\"cl-lbl\">\u26a0\ufe0f The problem interviewers always probe</div>\n    <p><strong>What it is:</strong> One shard/partition gets disproportionately more traffic. Example: a celebrity user \u2014 all writes for their posts hit the same shard.</p>\n    <p><strong>The fix (universal):</strong> Add a random suffix \u2014 write <code>user_123#0</code> through <code>user_123#7</code>. This distributes across 8 shards. A scatter-gather read merges results. Or use write-time fan-out.</p>\n    <p><strong>Cassandra-specific:</strong> Time-based keys cause one partition per time window to become hot during peak. Use bucketing: <code>entity_type + date_bucket</code> as partition key to distribute load.</p>\n    <p><strong>DynamoDB-specific:</strong> Adaptive Capacity auto-absorbs bursts, but consistent hot keys still cause throttling. Write sharding with a <code>#bucket</code> suffix is the right fix.</p>\n  </div>\n\n  <h3>Partition Key Design Rules</h3>\n  <table class=\"comp-table\">\n    <thead><tr><th>Rule</th><th>Good Example</th><th>Bad Example</th><th>Why Bad</th></tr></thead>\n    <tbody>\n      <tr><td class=\"row-head\">High cardinality</td><td><code>user_id</code> (millions of users)</td><td><code>country</code> (only ~200 values)</td><td>All US users hit one shard</td></tr>\n      <tr><td class=\"row-head\">Even distribution</td><td><code>hash(user_id)</code></td><td><code>timestamp</code></td><td>All current writes hit the newest partition</td></tr>\n      <tr><td class=\"row-head\">Matches access pattern</td><td><code>entity_type + region</code> for Top-K</td><td><code>event_id</code> (never queried directly)</td><td>Every query needs a full scan</td></tr>\n      <tr><td class=\"row-head\">Not monotonically increasing</td><td><code>uuid_v4()</code></td><td><code>auto_increment id</code></td><td>All inserts go to the last partition</td></tr>\n    </tbody>\n  </table>\n</section>\n\n<section id=\"consistency\">\n  <div class=\"sec-tag\">04 \u00b7 CAP Theorem in Practice</div>\n  <h2>Consistency, Availability, Partition Tolerance</h2>\n  <p>CAP theorem: in a distributed system, you can guarantee only two of: <strong>Consistency</strong> (every read gets the latest write), <strong>Availability</strong> (every request gets a response), <strong>Partition Tolerance</strong> (system works even if network splits). Since network partitions always happen, the real choice is <strong>CP vs AP</strong>.</p>\n  <div class=\"callout cl-blue\">\n    <div class=\"cl-lbl\">Plain English</div>\n    <p><strong>CP (Consistency + Partition Tolerance):</strong> \"I'd rather return an error than return stale data.\" A bank is CP \u2014 you never want a wrong balance.</p>\n    <p><strong>AP (Availability + Partition Tolerance):</strong> \"I'd rather return slightly old data than nothing.\" Twitter's trending list is AP \u2014 seeing a hashtag ranked #3 vs #4 is fine.</p>\n  </div>\n  <table class=\"comp-table\">\n    <thead><tr><th>Database</th><th>CAP</th><th>Default Consistency</th><th>Tunable?</th><th>Best For</th></tr></thead>\n    <tbody>\n      <tr><td class=\"row-head\">PostgreSQL</td><td><strong>CP</strong></td><td>Serialisable / Read Committed</td><td>Yes \u2014 isolation levels</td><td>Financial transactions, inventory</td></tr>\n      <tr><td class=\"row-head\">MongoDB</td><td><strong>CP default</strong></td><td>Strong (writeConcern: majority)</td><td>Yes \u2014 read/write concerns</td><td>User profiles, catalogs, CMS</td></tr>\n      <tr><td class=\"row-head\">DynamoDB</td><td><strong>AP default</strong></td><td>Eventually consistent</td><td>Yes \u2014 strong reads at 2x cost</td><td>Sessions, carts, leaderboards</td></tr>\n      <tr><td class=\"row-head\">Cassandra</td><td><strong>AP tunable</strong></td><td>Eventual (ONE)</td><td>Yes \u2014 QUORUM for strong</td><td>IoT, time-series, event logs</td></tr>\n    </tbody>\n  </table>\n\n  <h3>Cassandra Consistency Levels \u2014 Understand This Deeply</h3>\n  <div class=\"concept-grid\">\n  <div class=\"concept-row\"><div class=\"concept-term\">ONE</div><div class=\"concept-def\"><strong>Confirmed by 1 replica.</strong> Fastest. Least consistent. If that one node is behind, you get stale data.<br><span style=\"color:#5a5848;font-size:12.5px;\">Best for: metrics, logs \u2014 stale reads are acceptable.</span></div></div>\n  <div class=\"concept-row\"><div class=\"concept-term\">QUORUM</div><div class=\"concept-def\"><strong>Confirmed by majority: (RF/2)+1 = 2 of 3 replicas.</strong> Balanced speed and correctness.<br><span style=\"color:#5a5848;font-size:12.5px;\">Best for: user data, session state. Write QUORUM + Read QUORUM = 4 &gt; RF(3) \u2192 guaranteed to read your own writes.</span></div></div>\n  <div class=\"concept-row\"><div class=\"concept-term\">ALL</div><div class=\"concept-def\"><strong>Confirmed by ALL replicas.</strong> Strongest consistency. One node down = total failure.<br><span style=\"color:#5a5848;font-size:12.5px;\">Best for: financial data only. Rarely used in practice.</span></div></div>\n  <div class=\"concept-row\"><div class=\"concept-term\">The Golden Rule</div><div class=\"concept-def\"><code>write_CL + read_CL &gt; RF</code> \u2192 guaranteed to read your own writes.<br><br><span style=\"color:#1a7a4a;font-size:13px;\">\u2713 QUORUM(2) + QUORUM(2) = 4 &gt; RF(3) \u2192 Strong consistency</span><br><span style=\"color:#b83030;font-size:13px;\">\u2717 ONE(1) + ONE(1) = 2 &lt; RF(3) \u2192 May read stale data</span></div></div>\n</div>\n</section>\n\n<section id=\"examples\">\n  <div class=\"sec-tag\">05 \u00b7 Applied to Real Systems</div>\n  <h2>Which Database Wins in Which System?</h2>\n\n  <div class=\"sd-example\">\n    <div class=\"sd-example-head\">\n      <div class=\"sd-example-title\">Top-K Trending (YouTube / Twitter)</div>\n      <span class=\"sd-example-tag\">500K EVENTS/SEC</span>\n    </div>\n    <div class=\"sd-example-body\">\n      <div class=\"choice-row\"><div class=\"choice-label\">HOT STORE</div><div class=\"choice-val\"><span class=\"badge b-g\">Redis ZSET</span> Not one of the four \u2014 Redis wins for real-time sorted sets. ZINCRBY + ZREVRANGE at sub-ms. None of the four match this for live ranking.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">WARM STORE</div><div class=\"choice-val\"><span class=\"badge b-ca\">Cassandra \u2713</span> 50K rows/sec from Flink flush. Partition by entity_type+region, cluster by window_bucket. Range queries by time are Cassandra's home ground. PostgreSQL would be bottlenecked at this write rate.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">Why NOT Postgres</div><div class=\"choice-val\"><span class=\"badge b-r\">PostgreSQL \u2717</span> Sustained 50K writes/sec saturates a single node. Sharding Postgres is operationally complex. And we don't need joins \u2014 pre-aggregated counts need no relational features.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">Why NOT DynamoDB</div><div class=\"choice-val\"><span class=\"badge b-a\">DynamoDB \u26a0</span> Could work technically but cost is prohibitive. At $1.25 per million writes \u00d7 4.3B writes/day \u2248 $5,400/day. Cassandra on 10 nodes \u2248 $200/day at the same scale.</div></div>\n    </div>\n  </div>\n\n  <div class=\"sd-example\">\n    <div class=\"sd-example-head\">\n      <div class=\"sd-example-title\">Ride-Sharing App (Uber)</div>\n      <span class=\"sd-example-tag\">MIXED WORKLOAD</span>\n    </div>\n    <div class=\"sd-example-body\">\n      <div class=\"choice-row\"><div class=\"choice-label\">RIDE ENTITY</div><div class=\"choice-val\"><span class=\"badge b-pg\">PostgreSQL \u2713</span> Ride lifecycle: create \u2192 assign driver \u2192 update status \u2192 charge payment \u2192 close. You need ACID transactions across tables. PostgreSQL prevents double-assignment and double-charging atomically.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">DRIVER LOCATION</div><div class=\"choice-val\"><span class=\"badge b-ca\">Cassandra \u2713</span> Location history: partition by driver_id, cluster by timestamp DESC. For real-time queries use Redis GEOADD. Cassandra stores the durable time-series history.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">USER PROFILES</div><div class=\"choice-val\"><span class=\"badge b-mg\">MongoDB \u2713</span> Profiles vary: saved addresses, payment methods, preferences, ratings. Document model is natural. No joins needed \u2014 just fetch the user document by user_id.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">SESSION TOKENS</div><div class=\"choice-val\"><span class=\"badge b-dy\">DynamoDB \u2713</span> Token \u2192 user_id + expiry. DynamoDB TTL auto-expires sessions. Millions of sessions, single-key lookups, zero ops. Perfect fit.</div></div>\n    </div>\n  </div>\n\n  <div class=\"sd-example\">\n    <div class=\"sd-example-head\">\n      <div class=\"sd-example-title\">E-Commerce (Amazon-style)</div>\n      <span class=\"sd-example-tag\">MULTI-MODEL</span>\n    </div>\n    <div class=\"sd-example-body\">\n      <div class=\"choice-row\"><div class=\"choice-label\">ORDERS / PAYMENTS</div><div class=\"choice-val\"><span class=\"badge b-pg\">PostgreSQL \u2713</span> Money moves. \"Deduct inventory AND create order AND charge payment\" must be atomic. PostgreSQL's ACID guarantees this in a single transaction. Nothing else on this list does it reliably.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">PRODUCT CATALOG</div><div class=\"choice-val\"><span class=\"badge b-mg\">MongoDB \u2713</span> A T-shirt has size/color. A laptop has RAM/CPU. A book has ISBN. Product attributes vary wildly \u2014 flexible schema is perfect. Add new product types without migration.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">SHOPPING CART</div><div class=\"choice-val\"><span class=\"badge b-dy\">DynamoDB \u2713</span> Cart = user_id \u2192 [items]. Single-key access. TTL to expire abandoned carts. Millions of concurrent sessions. Zero ops burden.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">ORDER HISTORY</div><div class=\"choice-val\"><span class=\"badge b-ca\">Cassandra \u2713</span> \"All orders for user X sorted by date\" \u2014 perfect Cassandra query. Partition by user_id, cluster by order_date DESC. Append-only, high write throughput during sale events.</div></div>\n    </div>\n  </div>\n</section>\n\n<section id=\"decision\">\n  <div class=\"sec-tag\">06 \u00b7 The Decision Framework</div>\n  <h2>How to Pick in an Interview \u2014 in 60 Seconds</h2>\n  <div class=\"step-block\">\n  <div class=\"step-block-header\"><span class=\"sb-icon\">\ud83c\udfaf</span>How to Pick a Database \u2014 Ask in Order</div>\n  <div class=\"step-block-body\">\n    <div class=\"step-row\"><div class=\"step-num\">01</div><div class=\"step-content\">\n      <div class=\"step-q\">Do you need ACID transactions across multiple entities?</div>\n      <div class=\"step-options\">\n        <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">\u2713 YES \u2192</span><span class=\"opt-text\"><strong>PostgreSQL. Full stop.</strong> Financial data, inventory, orders \u2014 anything where a failed write must roll back atomically across tables.</span></div>\n        <div class=\"step-option opt-no\"><span class=\"opt-arrow\">\u2192 NO \u2192</span><span class=\"opt-text\">Continue to Step 2.</span></div>\n      </div>\n    </div></div>\n    <div class=\"step-row\"><div class=\"step-num\">02</div><div class=\"step-content\">\n      <div class=\"step-q\">What is your write volume?</div>\n      <div class=\"step-options\">\n        <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">&lt;10K/sec \u2192</span><span class=\"opt-text\"><strong>PostgreSQL or MongoDB.</strong> Single-node handles this comfortably with proper indexing.</span></div>\n        <div class=\"step-option opt-mid\"><span class=\"opt-arrow\">10K\u2013100K/sec \u2192</span><span class=\"opt-text\"><strong>MongoDB (sharded) or DynamoDB.</strong> Need horizontal write scaling.</span></div>\n        <div class=\"step-option opt-no\"><span class=\"opt-arrow\">&gt;100K/sec \u2192</span><span class=\"opt-text\"><strong>Cassandra or DynamoDB.</strong> Built for massive write throughput \u2014 Cassandra handles 500K+/sec.</span></div>\n      </div>\n    </div></div>\n    <div class=\"step-row\"><div class=\"step-num\">03</div><div class=\"step-content\">\n      <div class=\"step-q\">What is your read pattern?</div>\n      <div class=\"step-options\">\n        <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">Ad-hoc SQL \u2192</span><span class=\"opt-text\"><strong>PostgreSQL or MongoDB.</strong> Joins, filters, aggregations, full-text search \u2014 all supported.</span></div>\n        <div class=\"step-option opt-mid\"><span class=\"opt-arrow\">Key lookups \u2192</span><span class=\"opt-text\"><strong>DynamoDB or Cassandra.</strong> Always querying by user_id, entity_id \u2014 single-key access patterns.</span></div>\n        <div class=\"step-option opt-no\"><span class=\"opt-arrow\">Range by time \u2192</span><span class=\"opt-text\"><strong>Cassandra.</strong> Partition by entity, cluster by timestamp DESC \u2014 its strongest access pattern.</span></div>\n      </div>\n    </div></div>\n    <div class=\"step-row\"><div class=\"step-num\">04</div><div class=\"step-content\">\n      <div class=\"step-q\">Do you control your infrastructure?</div>\n      <div class=\"step-options\">\n        <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">Self-hosted \u2192</span><span class=\"opt-text\"><strong>PostgreSQL / Cassandra / MongoDB.</strong> Cost-efficient at scale, full control.</span></div>\n        <div class=\"step-option opt-no\"><span class=\"opt-arrow\">Managed \u2192</span><span class=\"opt-text\"><strong>DynamoDB.</strong> Zero ops, auto-scaling, AWS-native. Pay for predictability.</span></div>\n      </div>\n    </div></div>\n    <div class=\"step-row\"><div class=\"step-num\">05</div><div class=\"step-content\">\n      <div class=\"step-q\">Does your schema change frequently?</div>\n      <div class=\"step-options\">\n        <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">Still evolving \u2192</span><span class=\"opt-text\"><strong>MongoDB.</strong> Flexible document model \u2014 add fields to individual documents without migration.</span></div>\n        <div class=\"step-option opt-no\"><span class=\"opt-arrow\">Stable \u2192</span><span class=\"opt-text\"><strong>PostgreSQL or Cassandra.</strong> Schema stability enables better optimisation.</span></div>\n      </div>\n    </div></div>\n  </div>\n</div>\n\n  <h3>The Rules You Must Know</h3>\n  <div class=\"use-grid\">\n    <div class=\"use-card\">\n      <div class=\"use-card-head\" style=\"color:var(--pg)\">\ud83d\udc18 Never use PostgreSQL for\u2026</div>\n      <ul><li>Write-heavy workloads &gt;50K TPS</li><li>Multi-region active-active writes</li><li>Flexible evolving schemas</li><li>IoT sensor streams (millions of tiny writes)</li></ul>\n    </div>\n    <div class=\"use-card\">\n      <div class=\"use-card-head\" style=\"color:var(--mg)\">\ud83c\udf43 Never use MongoDB for\u2026</div>\n      <ul><li>Strict ACID transactions at high volume</li><li>Write throughput &gt;100K/sec reliably</li><li>Inherently relational data with complex joins</li><li>When you need Cassandra-style time partitioning</li></ul>\n    </div>\n    <div class=\"use-card\">\n      <div class=\"use-card-head\" style=\"color:#cc8800\">\u26a1 Never use DynamoDB for\u2026</div>\n      <ul><li>Ad-hoc queries (pay for full table scans)</li><li>Complex joins or aggregations</li><li>High-volume cross-item ACID transactions</li><li>Non-AWS deployments</li></ul>\n    </div>\n    <div class=\"use-card\">\n      <div class=\"use-card-head\" style=\"color:var(--ca)\">\ud83d\udc8e Never use Cassandra for\u2026</div>\n      <ul><li>ACID transactions or financial data</li><li>Ad-hoc queries</li><li>Small teams without ops expertise</li><li>Frequently changing query patterns</li></ul>\n    </div>\n  </div>\n</section>\n\n<section id=\"followups\">\n  <div class=\"sec-tag\">07 \u00b7 Interview Follow-up Playbook</div>\n  <h2>Every Hard Follow-up, Answered</h2>\n\n  <div class=\"faq-item\">\n    <div class=\"faq-q\" onclick=\"toggle(this)\">Why not just use PostgreSQL for everything?<span class=\"tog\">+</span></div>\n    <div class=\"faq-a\"><strong>This is right for 80% of startups.</strong> With proper indexing and read replicas, Postgres handles tens of thousands of TPS and terabytes of data. Instagram ran on PostgreSQL until billions of photos \u2014 they added sharding only when forced.<br><br>The threshold: when you need <strong>multi-region active-active writes</strong>, <strong>&gt;50K sustained writes/sec</strong>, or <strong>petabyte-scale storage</strong>. Below those thresholds, Postgres with read replicas is correct and introduces less complexity.</div>\n  </div>\n\n  <div class=\"faq-item\">\n    <div class=\"faq-q\" onclick=\"toggle(this)\">Cassandra says \"no joins\" \u2014 how does a social app do \"get tweets liked by users I follow\"?<span class=\"tog\">+</span></div>\n    <div class=\"faq-a\"><strong>Denormalise and pre-compute.</strong> Design tables for your queries, not your entities.<br><br>Store <code>user_liked_tweets(user_id, tweet_id, liked_at)</code> for \"show me what I liked.\" Store <code>tweet_liked_by(tweet_id, user_id)</code> for \"show me who liked this tweet.\" Same data, two tables, two access patterns. Write fan-out handles both. Storage is cheap; compute is expensive.</div>\n  </div>\n\n  <div class=\"faq-item\">\n    <div class=\"faq-q\" onclick=\"toggle(this)\">DynamoDB vs Cassandra \u2014 they seem to do the same thing?<span class=\"tog\">+</span></div>\n    <div class=\"faq-a\">They share a heritage (Dynamo paper) but differ in practice:<br><br><strong>DynamoDB:</strong> Fully managed, AWS-only, pay per request, zero ops. Expensive at massive scale, AWS lock-in.<br><br><strong>Cassandra:</strong> Self-hosted or Astra, any cloud, pay for machines. Requires ops expertise. Dramatically cheaper at extreme scale \u2014 Netflix uses it because at their scale (trillions of rows) savings justify the ops investment.<br><br>Decision: <strong>team size and cloud commitment.</strong> Small team on AWS \u2192 DynamoDB. Large team, predictable massive load \u2192 Cassandra.</div>\n  </div>\n\n  <div class=\"faq-item\">\n    <div class=\"faq-q\" onclick=\"toggle(this)\">How does Cassandra handle a node going down mid-write?<span class=\"tog\">+</span></div>\n    <div class=\"faq-a\"><strong>Hinted Handoff + Read Repair.</strong><br><br><strong>Hinted Handoff:</strong> Write to 3 nodes; node 2 is down. Coordinator stores a hint \u2014 \"send this write to node 2 when it recovers.\" Node 2 receives all missed writes on restart.<br><br><strong>Read Repair:</strong> On a QUORUM read, if replicas return different values, Cassandra detects inconsistency and repairs the stale replica in the background.<br><br><strong>Anti-Entropy Repair:</strong> Weekly background process comparing replicas via Merkle trees. Skipping this causes data loss over time.</div>\n  </div>\n\n  <div class=\"faq-item\">\n    <div class=\"faq-q\" onclick=\"toggle(this)\">When would you choose MongoDB over PostgreSQL?<span class=\"tog\">+</span></div>\n    <div class=\"faq-a\">MongoDB wins when:<br><br><strong>1. Schema is genuinely unknown or rapidly evolving</strong> \u2014 CMS, product catalog with 50 different product types, configuration system. Each document legitimately has different fields.<br><br><strong>2. Data is hierarchically structured</strong> \u2014 blog post with embedded comments, tags, and author info as one document. Faster than 4 JOINed tables.<br><br><strong>3. Prototyping fast without a DBA</strong> \u2014 no migrations, no ALTER TABLE.<br><br><strong>MongoDB loses when:</strong> You need transactions, your \"flexible\" schema has become inconsistent garbage no one understands, or your aggregation pipeline is 200 lines of nested JSON.</div>\n  </div>\n\n  <div class=\"faq-item\">\n    <div class=\"faq-q\" onclick=\"toggle(this)\">What's the difference between a secondary index in DynamoDB vs Cassandra?<span class=\"tog\">+</span></div>\n    <div class=\"faq-a\"><strong>DynamoDB:</strong> Two types \u2014 Local Secondary Index (same partition key, different sort key, created at table creation, can't be deleted) and Global Secondary Index (different partition key entirely, created any time, has its own read/write capacity). GSIs are eventually consistent and cost additional write capacity units for every write to the base table.<br><br><strong>Cassandra:</strong> Secondary indexes are a trap. They scatter queries across all nodes (each node checks its local data), creating latency spikes and hot spots. <strong>The correct Cassandra approach is to create a new table</strong> denormalised for the access pattern, not add a secondary index. Materialized Views are an alternative but have their own consistency trade-offs.</div>\n  </div>\n</section>\n\n</div>\n<div class=\"footer\">DATABASES \u00b7 POSTGRESQL \u00b7 MONGODB \u00b7 DYNAMODB \u00b7 CASSANDRA \u00b7 MANISH-ALMANAC</div>\n\u003cscript>function toggle(el){el.parentElement.classList.toggle('open');}<\/script>\n</body>\n</html>\n", tag: 'Databases' },
  olap:        { title: 'OLAP Engines Compared',         srcdoc: "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>OLAP Showdown: ClickHouse vs Druid vs BigQuery vs Redshift</title>\n<link href=\"https://fonts.googleapis.com/css2?family=DM+Serif+Display:ital@0;1&family=DM+Sans:wght@300;400;500;600;700&family=JetBrains+Mono:wght@400;600&display=swap\" rel=\"stylesheet\">\n<style>\n:root{--ink:#08090d;--page:#f0f2f8;--surface:#e4e7f0;--surface2:#d8dcea;--border:#c8ccda;--muted:#6a6e7e;--ch:#f90000;--ch-bg:#fff0f0;--dr:#3ea8ff;--dr-bg:#eef6ff;--bq:#4285f4;--bq-bg:#eef2ff;--rs:#ff9900;--rs-bg:#fff6ee;--red:#c0392b;--red-bg:#fdf0ee;--green:#1a7a4a;--green-bg:#edf8f2;--amber:#b8720a;--amber-bg:#fdf6e8;--blue:#1a4f8a;--blue-bg:#edf2fb;--purple:#6040a0;--purple-bg:#f2eefb;--mono:'JetBrains Mono',monospace;--serif:'DM Serif Display',serif;--sans:'DM Sans',sans-serif;}\n*{box-sizing:border-box;margin:0;padding:0;}html{scroll-behavior:smooth;}\nbody{background:var(--page);color:var(--ink);font-family:var(--sans);font-size:15px;line-height:1.75;}\n.hero{background:var(--ink);color:#e0e4f0;padding:72px 24px 56px;position:relative;overflow:hidden;}\n.hero::before{content:'';position:absolute;inset:0;background:radial-gradient(ellipse 60% 50% at 80% 50%,rgba(63,168,255,.06) 0%,transparent 70%);}\n.hero-inner{max-width:960px;margin:0 auto;position:relative;}\n.hero-tag{font-family:var(--mono);font-size:10px;letter-spacing:4px;color:#4a4e5e;text-transform:uppercase;margin-bottom:20px;}\nh1{font-family:var(--serif);font-size:clamp(30px,5vw,56px);font-weight:400;font-style:italic;line-height:1.08;letter-spacing:-.5px;margin-bottom:20px;color:#f0f2fa;}\nh1 em{color:#3ea8ff;font-style:normal;}\n.hero-sub{font-size:15px;color:#6a6e7e;max-width:640px;line-height:1.7;margin-bottom:32px;}\n.db-pills{display:flex;flex-wrap:wrap;gap:8px;}\n.db-pill{font-family:var(--mono);font-size:10px;padding:5px 14px;border-radius:3px;border:1px solid;letter-spacing:.5px;}\n.pill-ch{border-color:#f90000;color:#c00;background:rgba(249,0,0,.06);}\n.pill-dr{border-color:#3ea8ff;color:#2080cc;background:rgba(62,168,255,.06);}\n.pill-bq{border-color:#4285f4;color:#2060cc;background:rgba(66,133,244,.06);}\n.pill-rs{border-color:#ff9900;color:#cc7000;background:rgba(255,153,0,.06);}\n.nav{position:sticky;top:0;z-index:100;background:var(--ink);border-bottom:1px solid #14161e;display:flex;overflow-x:auto;scrollbar-width:none;padding:0 20px;}\n.nav::-webkit-scrollbar{display:none;}\n.nav a{font-family:var(--mono);font-size:10px;letter-spacing:1px;color:#3a3e4e;text-decoration:none;padding:14px 12px;white-space:nowrap;border-bottom:2px solid transparent;transition:.18s;}\n.nav a:hover{color:#3ea8ff;border-color:#3ea8ff;}\n.wrap{max-width:960px;margin:0 auto;padding:0 20px;}\nsection{padding:56px 0 36px;border-bottom:2px solid var(--border);}\nsection:last-child{border:none;}\n.sec-tag{font-family:var(--mono);font-size:9px;letter-spacing:4px;text-transform:uppercase;color:var(--muted);margin-bottom:8px;display:flex;align-items:center;gap:10px;}\n.sec-tag::before{content:'';width:20px;height:1px;background:var(--border);}\nh2{font-family:var(--serif);font-size:clamp(22px,3.5vw,32px);font-style:italic;line-height:1.15;margin-bottom:18px;}\nh3{font-family:var(--sans);font-size:17px;font-weight:600;margin:32px 0 10px;border-bottom:1px solid var(--border);padding-bottom:6px;}\np{color:#3a3d4e;font-size:14.5px;margin-bottom:12px;}\nstrong{color:var(--ink);}\ncode{font-family:var(--mono);font-size:11.5px;background:var(--surface2);padding:1px 5px;border-radius:3px;color:var(--blue);}\n.db-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:14px;margin:24px 0;}\n.db-card{background:white;border:1px solid var(--border);border-radius:8px;padding:20px;position:relative;overflow:hidden;}\n.db-card::before{content:'';position:absolute;top:0;left:0;right:0;height:4px;}\n.db-card.ch::before{background:var(--ch);}.db-card.dr::before{background:var(--dr);}.db-card.bq::before{background:var(--bq);}.db-card.rs::before{background:var(--rs);}\n.db-logo{font-size:22px;margin-bottom:6px;}\n.db-name{font-family:var(--serif);font-size:17px;font-style:italic;margin-bottom:4px;}\n.db-type{font-family:var(--mono);font-size:9px;letter-spacing:2px;color:var(--muted);margin-bottom:10px;text-transform:uppercase;}\n.db-tagline{font-size:13px;color:#5a5870;line-height:1.55;}\n.db-born{font-family:var(--mono);font-size:9px;color:var(--muted);margin-top:8px;}\n.analogy{background:var(--ink);color:#c8ccd8;border-radius:8px;padding:24px 28px;margin:24px 0;}\n.analogy-label{font-family:var(--mono);font-size:9px;letter-spacing:3px;color:#4a4e5e;margin-bottom:10px;text-transform:uppercase;}\n.analogy-text{font-size:15px;line-height:1.75;color:#d0d4e0;}\n.analogy-text strong{color:#3ea8ff;}\n.callout{border-radius:4px;padding:14px 18px;margin:18px 0;font-size:13.5px;border-left:3px solid;line-height:1.65;}\n.callout p{font-size:13.5px;margin-bottom:6px;}.callout p:last-child{margin:0;}\n.cl-blue{background:var(--blue-bg);border-color:var(--blue);color:#1a2a4a;}\n.cl-green{background:var(--green-bg);border-color:var(--green);color:#0a2a1a;}\n.cl-amber{background:var(--amber-bg);border-color:var(--amber);color:#3a2a08;}\n.cl-red{background:var(--red-bg);border-color:var(--red);color:#3a0a08;}\n.cl-purple{background:var(--purple-bg);border-color:var(--purple);color:#2a1a4a;}\n.cl-lbl{font-family:var(--mono);font-size:9px;letter-spacing:3px;text-transform:uppercase;margin-bottom:6px;opacity:.7;}\n.codeblock{background:var(--ink);border-radius:6px;padding:20px 22px;font-family:var(--mono);font-size:11.5px;line-height:2;overflow-x:auto;margin:14px 0;color:#c8ccd8;border:1px solid #14161e;}\n.codeblock .c{color:#3a3e4e;}.codeblock .k{color:#3ea8ff;}.codeblock .s{color:#8bc4a0;}.codeblock .n{color:#e8946a;}.codeblock .g{color:#a8d878;}.codeblock .r{color:#e87878;}\n.comp-table{width:100%;border-collapse:collapse;margin:20px 0;font-size:13px;}\n.comp-table th{padding:10px 14px;border:1px solid var(--border);background:var(--surface2);font-family:var(--mono);font-size:9px;letter-spacing:1.5px;text-transform:uppercase;color:var(--muted);}\n.comp-table td{padding:11px 14px;border:1px solid var(--border);vertical-align:top;color:#3a3d4e;line-height:1.6;}\n.comp-table .row-head{font-family:var(--mono);font-size:11px;font-weight:600;background:var(--surface);color:var(--ink);white-space:nowrap;}\n.good{color:var(--green);font-weight:600;}.warn{color:var(--amber);font-weight:600;}.bad{color:var(--red);font-weight:600;}\n.use-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:14px;margin:20px 0;}\n.use-card{border:1px solid var(--border);border-radius:6px;padding:18px;background:white;}\n.use-card-head{font-family:var(--mono);font-size:11px;font-weight:600;margin-bottom:10px;}\n.use-card ul{padding-left:16px;font-size:13px;color:#4a4858;line-height:1.7;}\n.use-card ul li{margin-bottom:4px;}\n.sd-example{background:white;border:1px solid var(--border);border-radius:8px;margin:20px 0;overflow:hidden;}\n.sd-example-head{background:var(--ink);padding:14px 20px;display:flex;align-items:center;gap:12px;}\n.sd-example-title{font-family:var(--serif);font-size:16px;font-style:italic;color:#f0f2fa;font-weight:400;}\n.sd-example-tag{font-family:var(--mono);font-size:9px;letter-spacing:2px;color:#4a4e5e;border:1px solid #2a2e3e;padding:3px 8px;border-radius:2px;}\n.sd-example-body{padding:20px;}\n.choice-row{display:flex;gap:10px;align-items:flex-start;padding:10px 0;border-bottom:1px solid var(--border);font-size:13px;}\n.choice-row:last-child{border:none;}\n.choice-label{font-family:var(--mono);font-size:10px;letter-spacing:1px;color:var(--muted);width:120px;flex-shrink:0;padding-top:2px;}\n.choice-val{flex:1;color:#3a3d4e;line-height:1.6;}\n.badge{display:inline-block;font-family:var(--mono);font-size:9px;padding:2px 7px;border-radius:2px;border:1px solid;margin-right:4px;font-weight:500;}\n.b-ch{background:var(--ch-bg);border-color:var(--ch);color:#c00;}.b-dr{background:var(--dr-bg);border-color:var(--dr);color:#1a70cc;}.b-bq{background:var(--bq-bg);border-color:var(--bq);color:#1a50cc;}.b-rs{background:var(--rs-bg);border-color:var(--rs);color:#cc7000;}.b-g{background:var(--green-bg);border-color:var(--green);color:var(--green);}.b-r{background:var(--red-bg);border-color:var(--red);color:var(--red);}.b-a{background:var(--amber-bg);border-color:var(--amber);color:var(--amber);}\n.faq-item{border:1px solid var(--border);border-radius:4px;margin-bottom:8px;overflow:hidden;}\n.faq-q{padding:14px 18px;display:flex;justify-content:space-between;align-items:center;cursor:pointer;background:white;font-size:14px;font-weight:500;color:var(--ink);user-select:none;}\n.faq-q:hover{background:var(--surface);}\n.faq-q .tog{font-size:18px;color:#3ea8ff;flex-shrink:0;margin-left:12px;transition:transform .2s;font-family:var(--mono);}\n.faq-a{display:none;padding:18px;background:var(--surface);font-size:13.5px;color:#3a3d4e;line-height:1.75;border-top:1px solid var(--border);}\n.faq-item.open .faq-a{display:block;}.faq-item.open .tog{transform:rotate(45deg);}\n.footer{background:var(--ink);text-align:center;padding:36px 20px;font-family:var(--mono);font-size:10px;color:#2a2e3e;letter-spacing:2px;}\n\n.step-block{background:#fff;border:1px solid var(--border);border-radius:8px;margin:20px 0;overflow:hidden;}\n.step-block-header{background:var(--ink);color:#e8e4dc;padding:13px 18px;font-family:var(--mono);font-size:10px;letter-spacing:2px;text-transform:uppercase;display:flex;align-items:center;gap:10px;}\n.sb-icon{font-size:16px;}\n.step-block-body{padding:0;}\n.step-row{display:flex;gap:0;border-bottom:1px solid var(--border);}\n.step-row:last-child{border-bottom:none;}\n.step-num{background:var(--surface);min-width:46px;display:flex;align-items:flex-start;justify-content:center;padding:16px 6px;font-family:var(--mono);font-size:11px;font-weight:700;color:var(--muted);flex-shrink:0;border-right:1px solid var(--border);}\n.step-content{padding:14px 18px;flex:1;}\n.step-q{font-weight:600;font-size:14px;color:var(--ink);margin-bottom:10px;}\n.step-options{display:flex;flex-direction:column;gap:6px;}\n.step-option{display:flex;gap:10px;align-items:flex-start;padding:9px 13px;border-radius:5px;font-size:13px;line-height:1.65;}\n.opt-yes{background:#edf8f2;border:1px solid #b8ddc8;}\n.opt-no{background:#fdf6e8;border:1px solid #e8c870;}\n.opt-mid{background:#edf2fb;border:1px solid #b8c8e8;}\n.opt-any{background:#f4f0fb;border:1px solid #c8b8e8;}\n.opt-arrow{font-family:var(--mono);font-size:12px;font-weight:700;flex-shrink:0;margin-top:1px;min-width:120px;}\n.opt-yes .opt-arrow{color:#1a7a4a;}\n.opt-no .opt-arrow{color:#b8720a;}\n.opt-mid .opt-arrow{color:#1a4f8a;}\n.opt-any .opt-arrow{color:#5a3c9a;}\n.opt-text{flex:1;color:#3a3830;}\n.concept-grid{display:grid;grid-template-columns:1fr;gap:0;margin:20px 0;border:1px solid var(--border);border-radius:8px;overflow:hidden;}\n.concept-row{display:flex;gap:0;border-bottom:1px solid var(--border);}\n.concept-row:last-child{border-bottom:none;}\n.concept-term{background:var(--ink);color:#e8b84b;font-family:var(--mono);font-size:11.5px;font-weight:600;min-width:155px;padding:14px 16px;flex-shrink:0;border-right:1px solid #2a2820;display:flex;align-items:flex-start;line-height:1.5;}\n.concept-def{padding:13px 16px;flex:1;font-size:13.5px;color:#3a3830;line-height:1.7;background:#fff;}\n.concept-def strong{color:var(--ink);}\n.concept-def code{background:var(--surface);padding:1px 5px;border-radius:3px;font-family:var(--mono);font-size:11px;color:var(--blue);}\n@media(max-width:560px){.concept-row{flex-direction:column;}.concept-term{min-width:auto;border-right:none;border-bottom:1px solid #2a2820;}.opt-arrow{min-width:80px;}}\n\n</style>\n</head>\n<body>\n<div class=\"hero\">\n  <div class=\"hero-inner\">\n    <div class=\"hero-tag\">System Design \u00b7 OLAP Selection \u00b7 Manish-Almanac</div>\n    <h1>Choosing Your<br><em>OLAP Engine</em></h1>\n    <p class=\"hero-sub\">ClickHouse vs Apache Druid vs BigQuery vs Amazon Redshift \u2014 how to pick the right analytical database for every system design scenario, with real examples and every interview follow-up answered.</p>\n    <div class=\"db-pills\">\n      <span class=\"db-pill pill-ch\">ClickHouse</span>\n      <span class=\"db-pill pill-dr\">Apache Druid</span>\n      <span class=\"db-pill pill-bq\">BigQuery</span>\n      <span class=\"db-pill pill-rs\">Redshift</span>\n    </div>\n  </div>\n</div>\n<nav class=\"nav\">\n  <a href=\"#what\">What is OLAP?</a>\n  <a href=\"#identity\">Identity</a>\n  <a href=\"#internals\">How They Work</a>\n  <a href=\"#comparison\">Full Comparison</a>\n  <a href=\"#examples\">System Design</a>\n  <a href=\"#decision\">Decision Tree</a>\n  <a href=\"#followups\">Follow-ups</a>\n</nav>\n<div class=\"wrap\">\n\n<section id=\"what\">\n  <div class=\"sec-tag\">00 \u00b7 The Foundation</div>\n  <h2>What is OLAP and why is it different?</h2>\n  <p>OLAP stands for <strong>Online Analytical Processing</strong>. It's the class of databases built for <em>reading a lot of data to answer complex questions</em>, as opposed to OLTP (Online Transaction Processing) databases which are built for <em>many small reads and writes</em>.</p>\n  <div class=\"analogy\">\n    <div class=\"analogy-label\">OLTP vs OLAP \u2014 the supermarket analogy</div>\n    <div class=\"analogy-text\">\n      <strong>OLTP (PostgreSQL, MySQL, DynamoDB):</strong> The cash register. Each transaction is tiny \u2014 scan item, charge card, update inventory. Thousands happening simultaneously. Each one must be fast and correct.<br><br>\n      <strong>OLAP (ClickHouse, BigQuery, Druid):</strong> The quarterly business review. The manager asks \"which products sold most in the North last Tuesday compared to the same Tuesday last year, broken down by hour?\" This query needs to scan millions of rows. No one expects it in 10ms \u2014 but they want it in under 2 seconds, not 2 hours.<br><br>\n      <strong>The core difference:</strong> OLTP is optimised for <strong>row access</strong> (get me order #12345). OLAP is optimised for <strong>column scans</strong> (sum all sales values in column X across 10 billion rows). This is why OLAP databases store data column-by-column instead of row-by-row.\n    </div>\n  </div>\n  <h3>Why Columnar Storage Changes Everything</h3>\n  <div class=\"callout cl-blue\">\n    <div class=\"cl-lbl\">The Key Insight</div>\n    <p><strong>Row storage (PostgreSQL):</strong> Each row is stored together on disk. To compute <code>SUM(revenue)</code> across 1 billion rows, you read ALL columns of ALL rows \u2014 most of which you don't need.</p>\n    <p><strong>Column storage (ClickHouse/BigQuery):</strong> Each column is stored together. To compute <code>SUM(revenue)</code>, you only read the revenue column. 10x\u2013100x less data read. And integers in the same column compress 10\u201320x better than mixed row data.</p>\n    <p><strong>Real impact:</strong> A query that takes 10 minutes in PostgreSQL takes 300ms in ClickHouse \u2014 on the same data.</p>\n  </div>\n</section>\n\n<section id=\"identity\">\n  <div class=\"sec-tag\">01 \u00b7 Who Are They</div>\n  <h2>The Four OLAP Engines</h2>\n  <div class=\"db-grid\">\n    <div class=\"db-card ch\">\n      <div class=\"db-logo\">\ud83d\udd34</div>\n      <div class=\"db-name\">ClickHouse</div>\n      <div class=\"db-type\">Columnar OLAP \u00b7 Self-Hosted</div>\n      <div class=\"db-tagline\">The speed demon. Built by Yandex for web analytics. Ingests 500K rows/sec, answers GROUP BY on 100B rows in under 2 seconds. Battle-tested at Cloudflare, Uber, eBay. Self-host or ClickHouse Cloud.</div>\n      <div class=\"db-born\">Born 2016 \u00b7 Yandex \u2192 Apache \u00b7 MergeTree engine</div>\n    </div>\n    <div class=\"db-card dr\">\n      <div class=\"db-logo\">\ud83d\udd35</div>\n      <div class=\"db-name\">Apache Druid</div>\n      <div class=\"db-type\">Real-Time OLAP \u00b7 Self-Hosted</div>\n      <div class=\"db-tagline\">The sub-second explorer. Designed for interactive dashboards with &lt;1s query response. Pre-aggregates data at ingest time (rollup). Used by Lyft, Twitter, Netflix for operational analytics.</div>\n      <div class=\"db-born\">Born 2011 \u00b7 Metamarkets \u2192 Apache \u00b7 Segment-based</div>\n    </div>\n    <div class=\"db-card bq\">\n      <div class=\"db-logo\">\ud83d\udd37</div>\n      <div class=\"db-name\">BigQuery</div>\n      <div class=\"db-type\">Serverless OLAP \u00b7 Managed GCP</div>\n      <div class=\"db-tagline\">The serverless giant. No clusters to manage. Pay per query. Scales to petabytes automatically. Perfect for data warehouses, data science teams, and ad-hoc exploration. Google's backbone for internal analytics.</div>\n      <div class=\"db-born\">Born 2010 \u00b7 Google \u00b7 Dremel paper lineage</div>\n    </div>\n    <div class=\"db-card rs\">\n      <div class=\"db-logo\">\ud83d\udfe0</div>\n      <div class=\"db-name\">Amazon Redshift</div>\n      <div class=\"db-type\">MPP Data Warehouse \u00b7 Managed AWS</div>\n      <div class=\"db-tagline\">The AWS native warehouse. Massive Parallel Processing (MPP), deep S3 integration (Redshift Spectrum), familiar SQL. Best for structured warehouse queries in the AWS ecosystem.</div>\n      <div class=\"db-born\">Born 2012 \u00b7 Amazon AWS \u00b7 ParAccel / PostgreSQL lineage</div>\n    </div>\n  </div>\n\n  <h3>How They Fundamentally Differ in Architecture</h3>\n  <div class=\"callout cl-purple\">\n    <div class=\"cl-lbl\">The Critical Architectural Distinction</div>\n    <p><strong>ClickHouse &amp; Druid:</strong> Shared-nothing architecture. Each node stores data and computes. Data is co-located with compute. Extremely fast for co-located queries. Hard to scale compute independently of storage.</p>\n    <p><strong>BigQuery &amp; Redshift Spectrum:</strong> Separate storage from compute. Data lives in object storage (GCS/S3). Compute scales independently. Slower for hot data but infinitely scalable and cheaper for cold data.</p>\n  </div>\n</section>\n\n<section id=\"internals\">\n  <div class=\"sec-tag\">02 \u00b7 Under the Hood</div>\n  <h2>How Each One Actually Works</h2>\n\n  <h3>ClickHouse \u2014 MergeTree Engine</h3>\n  <div class=\"concept-grid\">\n  <div class=\"concept-row\"><div class=\"concept-term\">Parts</div><div class=\"concept-def\"><strong>Data is written as immutable sorted chunks called \"parts\".</strong> Each batch of INSERTs creates a new part on disk. No in-place updates \u2014 new parts are written, old ones merged in the background.<br><span style=\"color:#5a5848;font-size:12.5px;\">Why: immutable parts = no write locks = extremely fast concurrent writes at 500K rows/sec.</span></div></div>\n  <div class=\"concept-row\"><div class=\"concept-term\">Background Merge</div><div class=\"concept-def\"><strong>Small parts are continuously merged into larger ones</strong> by a background process \u2014 like an LSM tree (similar to RocksDB or Cassandra's SSTables).<br><span style=\"color:#5a5848;font-size:12.5px;\">Why: keeps read performance high \u2014 fewer parts to open and scan per query.</span></div></div>\n  <div class=\"concept-row\"><div class=\"concept-term\">ORDER BY = Sort</div><div class=\"concept-def\"><strong>Data is physically sorted on disk by the ORDER BY key.</strong> A query filtering on <code>(entity_type, region, entity_id)</code> skips to the right block immediately.<br><code>ORDER BY (entity_type, region, entity_id, event_hour)</code><br><span style=\"color:#5a5848;font-size:12.5px;\">Effect: a filter on entity_type='video' AND region='IN' skips 99% of the file without reading it.</span></div></div>\n  <div class=\"concept-row\"><div class=\"concept-term\">Sparse Index</div><div class=\"concept-def\"><strong>One index entry per 8,192 rows</strong> \u2014 tiny enough to fit entirely in RAM. Tells ClickHouse which disk block to start reading from.<br><span style=\"color:#5a5848;font-size:12.5px;\">No row-by-row index scan needed. Query jumps directly to the correct block on disk.</span></div></div>\n  <div class=\"concept-row\"><div class=\"concept-term\">LowCardinality</div><div class=\"concept-def\"><strong>Columns with few distinct values are dictionary-encoded as integers.</strong><br>\"video\" \u2192 1, \"hashtag\" \u2192 2. Stores integers instead of strings in every row.<br><span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 10x smaller storage. 10x faster string comparisons. Use for: entity_type, region, device.</span></div></div>\n  <div class=\"concept-row\"><div class=\"concept-term\">Partitioning</div><div class=\"concept-def\"><strong>Data is split into partitions by a partition key</strong> \u2014 usually date or month.<br><code>PARTITION BY toYYYYMM(event_date)</code><br><span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Partition pruning: a query on today only reads today's partition. A year of history is 364/365 untouched.</span></div></div>\n</div>\n\n  <h3>Apache Druid \u2014 Pre-Aggregation at Ingest (Rollup)</h3>\n  <div class=\"concept-grid\">\n  <div class=\"concept-row\"><div class=\"concept-term\">What is Rollup?</div><div class=\"concept-def\"><strong>Druid pre-aggregates data at ingest time.</strong> Events sharing the same dimensions within the same time granularity are collapsed into a single aggregated row before writing to disk.<br><span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Result: 100M raw events \u2192 2M aggregated rows. 50x storage reduction.</span></div></div>\n  <div class=\"concept-row\"><div class=\"concept-term\">Before Rollup</div><div class=\"concept-def\">100 million raw events, each stored individually:<br><code style=\"display:block;margin:4px 0;\">user_id=123, video_id=456, ts=14:23:45, region=IN</code><code style=\"display:block;margin:4px 0;\">user_id=789, video_id=456, ts=14:23:52, region=IN</code><span style=\"color:#5a5848;font-size:12.5px;\">847 different users watching the same video in the same minute.</span></div></div>\n  <div class=\"concept-row\"><div class=\"concept-term\">After Rollup</div><div class=\"concept-def\">2 million aggregated rows:<br><code style=\"display:block;margin:4px 0;\">video_id=456, minute=14:23, region=IN, <strong>count=847</strong></code><span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 847 events collapsed into 1 row. The count query is already answered \u2014 no scanning needed.</span></div></div>\n  <div class=\"concept-row\"><div class=\"concept-term\">The Trade-off</div><div class=\"concept-def\"><strong>You permanently lose individual row detail.</strong> Can no longer answer \"how many unique users?\" unless you included a HyperLogLog sketch column at ingest time.<br><span style=\"color:#b83030;font-size:12.5px;\">\u26a0\ufe0f Rollup is irreversible. Choose your dimensions and time granularity carefully before going live.</span></div></div>\n  <div class=\"concept-row\"><div class=\"concept-term\">vs ClickHouse</div><div class=\"concept-def\">ClickHouse's AggregatingMergeTree aggregates <strong>in the background after ingest</strong> \u2014 stores full data initially, then merges. More flexible, but higher initial storage. Druid rollup is more aggressive: collapses at ingest, far less storage, less flexibility.</div></div>\n</div>\n\n  <h3>BigQuery \u2014 Dremel's Columnar Tree</h3>\n  <div class=\"concept-grid\">\n  <div class=\"concept-row\"><div class=\"concept-term\">Dremel Tree</div><div class=\"concept-def\"><strong>BigQuery distributes your query across thousands of worker nodes in a tree.</strong> Root node splits your SQL into sub-tasks. Leaf nodes read columns from Google's Colossus storage in parallel. Thousands reading simultaneously = 1TB scanned in seconds.<br><span style=\"color:#5a5848;font-size:12.5px;\">You don't manage these workers \u2014 they spin up and down invisibly per query.</span></div></div>\n  <div class=\"concept-row\"><div class=\"concept-term\">Cost Model</div><div class=\"concept-def\"><strong>You pay per byte scanned \u2014 not per compute time.</strong><br><span style=\"color:#b83030;font-size:12.5px;\">SELECT * FROM table \u2192 scans ALL columns \u2192 expensive</span><br><span style=\"color:#1a7a4a;font-size:12.5px;\">SELECT revenue FROM table \u2192 scans 1 column \u2192 cheap (~10x less)</span><br><span style=\"color:#5a5848;font-size:12.5px;\">Rule: never SELECT * in BigQuery. Always specify only the columns you need.</span></div></div>\n  <div class=\"concept-row\"><div class=\"concept-term\">Partition Pruning</div><div class=\"concept-def\"><strong>Partition your table by date.</strong> A query with <code>WHERE event_date = '2026-03-20'</code> skips every other day's data entirely.<br><code>PARTITION BY DATE(event_time)</code><br><span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 A query on 1 year of data only scans 1/365th of the bytes.</span></div></div>\n  <div class=\"concept-row\"><div class=\"concept-term\">Clustering</div><div class=\"concept-def\"><strong>Cluster by your most common filter columns.</strong> BigQuery co-locates rows with the same cluster values in the same physical block within each partition.<br><code>CLUSTER BY entity_type, region</code><br><span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 A filter on entity_type='video' AND region='IN' skips all other blocks. Combined with partitioning: 2000x less data scanned.</span></div></div>\n  <div class=\"concept-row\"><div class=\"concept-term\">Slot Reservations</div><div class=\"concept-def\"><strong>For predictable, high-volume workloads: buy compute slots at flat rate.</strong> A slot = one unit of BigQuery compute. Buy 500 slots vs paying $5/TB per query.<br><span style=\"color:#5a5848;font-size:12.5px;\">Break-even: if you consistently scan &gt;20TB/day, flat-rate slots are cheaper than on-demand pricing.</span></div></div>\n</div>\n</section>\n\n<section id=\"comparison\">\n  <div class=\"sec-tag\">03 \u00b7 Full Comparison</div>\n  <h2>Every Dimension That Matters</h2>\n  <table class=\"comp-table\">\n    <thead><tr><th>Dimension</th><th>ClickHouse \ud83d\udd34</th><th>Druid \ud83d\udd35</th><th>BigQuery \ud83d\udd37</th><th>Redshift \ud83d\udfe0</th></tr></thead>\n    <tbody>\n      <tr><td class=\"row-head\">Architecture</td><td>Columnar, shared-nothing</td><td>Columnar, pre-aggregated segments</td><td>Serverless, storage-compute separated</td><td>MPP cluster, semi-managed</td></tr>\n      <tr><td class=\"row-head\">Ingest Speed</td><td><span class=\"good\">500K rows/sec</span> streaming</td><td><span class=\"good\">Streaming + batch</span> real-time rollup</td><td><span class=\"warn\">Batch primary</span> streaming via Pub/Sub</td><td><span class=\"warn\">Batch primary</span> COPY from S3</td></tr>\n      <tr><td class=\"row-head\">Query Latency</td><td><span class=\"good\">300ms\u20132s</span> on 100B rows</td><td><span class=\"good\">&lt;1s</span> interactive dashboards</td><td><span class=\"warn\">2\u201360s</span> depends on data scanned</td><td><span class=\"warn\">2\u201330s</span> for complex queries</td></tr>\n      <tr><td class=\"row-head\">Sub-Second Queries</td><td><span class=\"warn\">Yes for pre-sorted data</span></td><td><span class=\"good\">Yes \u2014 that's the whole point</span></td><td><span class=\"bad\">Rarely without caching</span></td><td><span class=\"bad\">No \u2014 MPP startup overhead</span></td></tr>\n      <tr><td class=\"row-head\">Storage Cost</td><td><span class=\"good\">Low</span> \u2014 self-hosted, great compression</td><td><span class=\"warn\">Medium</span> \u2014 segment overhead</td><td><span class=\"warn\">$0.02/GB/month</span> GCS</td><td><span class=\"warn\">$0.024/GB/month</span> Redshift storage</td></tr>\n      <tr><td class=\"row-head\">Compute Cost</td><td><span class=\"good\">Fixed</span> \u2014 you own the nodes</td><td><span class=\"good\">Fixed</span> \u2014 self-managed</td><td><span class=\"warn\">$5 per TB scanned</span></td><td><span class=\"warn\">Node-hours</span> even when idle</td></tr>\n      <tr><td class=\"row-head\">Ops Burden</td><td><span class=\"warn\">Medium</span> \u2014 manage nodes, merges</td><td><span class=\"bad\">High</span> \u2014 complex: Zookeeper, deep storage, etc.</td><td><span class=\"good\">Zero</span> \u2014 fully serverless</td><td><span class=\"warn\">Medium</span> \u2014 managed but not serverless</td></tr>\n      <tr><td class=\"row-head\">Scale Ceiling</td><td>Petabytes (sharded)</td><td>Petabytes</td><td><span class=\"good\">Truly unlimited</span></td><td>~Petabyte with RA3</td></tr>\n      <tr><td class=\"row-head\">SQL Compatibility</td><td>ClickHouse SQL (non-standard)</td><td>Druid SQL + native JSON</td><td>Standard SQL</td><td>PostgreSQL-compatible</td></tr>\n      <tr><td class=\"row-head\">Streaming Ingest</td><td><span class=\"good\">Native</span> Kafka engine</td><td><span class=\"good\">Native</span> real-time ingestion</td><td><span class=\"warn\">Via Dataflow/Pub/Sub</span></td><td><span class=\"bad\">Not native</span> \u2014 batch COPY</td></tr>\n      <tr><td class=\"row-head\">Cloud Lock-in</td><td><span class=\"good\">None</span> \u2014 open source</td><td><span class=\"good\">None</span> \u2014 open source</td><td><span class=\"bad\">GCP only</span></td><td><span class=\"bad\">AWS only</span></td></tr>\n      <tr><td class=\"row-head\">Best For</td><td>High-frequency event analytics</td><td>Sub-second operational dashboards</td><td>Ad-hoc exploration, data science</td><td>Structured DW in AWS ecosystem</td></tr>\n      <tr><td class=\"row-head\">Used By</td><td>Cloudflare, Uber, eBay</td><td>Lyft, Twitter, Netflix</td><td>Twitter, Spotify, The Trade Desk</td><td>NYSE, Yelp, McDonald's</td></tr>\n    </tbody>\n  </table>\n\n  <h3>Cost at Scale \u2014 Real Numbers</h3>\n  <div class=\"callout cl-amber\">\n    <div class=\"cl-lbl\">BigQuery vs ClickHouse at Top-K Scale</div>\n    <p>Assume: 500K events/sec \u2192 43B events/day \u2192 100 bytes per row after aggregation \u2192 ~4.3TB of aggregated data written per day. Analytical queries run 1,000 times/day each scanning ~500GB.</p>\n    <p><strong>BigQuery:</strong> 1,000 queries \u00d7 500GB \u00d7 $5/TB = <strong>$2,500/day</strong> in query costs alone. Plus storage: 4.3TB \u00d7 30 days \u00d7 $0.02 = $2,580/month.</p>\n    <p><strong>ClickHouse (10 nodes, 16-core, 64GB each, AWS r6i.4xlarge):</strong> 10 \u00d7 $1.00/hr \u00d7 24hr = <strong>$240/day</strong>. Handles all 1,000 queries easily. Same queries, same data, ~10x cheaper at this scale.</p>\n    <p><strong>BigQuery wins for:</strong> Unpredictable, bursty, data-science workloads where you'd otherwise pay for idle cluster capacity.</p>\n  </div>\n</section>\n\n<section id=\"examples\">\n  <div class=\"sec-tag\">04 \u00b7 Applied to Real Systems</div>\n  <h2>Which OLAP Engine for Which System?</h2>\n\n  <div class=\"sd-example\">\n    <div class=\"sd-example-head\">\n      <div class=\"sd-example-title\">Top-K Trending (YouTube / Twitter)</div>\n      <span class=\"sd-example-tag\">HIGH FREQUENCY \u00b7 500K EVENTS/SEC</span>\n    </div>\n    <div class=\"sd-example-body\">\n      <div class=\"choice-row\"><div class=\"choice-label\">WINNER</div><div class=\"choice-val\"><span class=\"badge b-ch\">ClickHouse \u2713</span> Flink flushes aggregated rows every 30s directly into ClickHouse via its Kafka engine. AggregatingMergeTree + columnar storage = \"top 10 videos in India last hour\" in 300ms on 100B rows. Streaming ingest is native \u2014 no extra pipeline.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">WHY NOT DRUID</div><div class=\"choice-val\"><span class=\"badge b-a\">Druid \u26a0</span> Druid's rollup would actually work well here \u2014 but the operational complexity (ZooKeeper, Historical nodes, Broker nodes, Coordinator, Overlord) is far higher than ClickHouse. For Top-K specifically, ClickHouse's window functions and GROUP BY are cleaner.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">WHY NOT BIGQUERY</div><div class=\"choice-val\"><span class=\"badge b-r\">BigQuery \u2717</span> At 43B writes/day, BigQuery Storage Write API costs would be significant. And the 2\u20135s query latency makes \"what's trending right now\" feel slow. ClickHouse is 10x cheaper and 10x faster for this specific workload.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">QUERIES ENABLED</div><div class=\"choice-val\">Historical Top-K (\"what was #1 last Tuesday?\") \u00b7 Trend analysis hour-over-hour \u00b7 Breakdown by device/region \u00b7 Rank history for a specific entity \u2014 all in &lt;2s.</div></div>\n    </div>\n  </div>\n\n  <div class=\"sd-example\">\n    <div class=\"sd-example-head\">\n      <div class=\"sd-example-title\">Ride-Sharing Analytics (Uber)</div>\n      <span class=\"sd-example-tag\">OPERATIONAL DASHBOARDS</span>\n    </div>\n    <div class=\"sd-example-body\">\n      <div class=\"choice-row\"><div class=\"choice-label\">REAL-TIME OPS</div><div class=\"choice-val\"><span class=\"badge b-dr\">Druid \u2713</span> Uber uses Druid for operational dashboards: \"How many rides completed in the last 5 minutes by city?\" Sub-second queries on streaming data let operations teams react in real time. Druid's rollup pre-aggregates by city+minute, making this near-instant.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">LONG-TERM ANALYTICS</div><div class=\"choice-val\"><span class=\"badge b-bq\">BigQuery \u2713</span> Historical analysis: \"Compare Q4 ride completion rates by city 2024 vs 2025.\" Petabytes of historical data, ad-hoc exploration by data scientists, no need for sub-second latency. BigQuery's serverless model is perfect \u2014 data scientists don't need to manage clusters.</div></div>\n    </div>\n  </div>\n\n  <div class=\"sd-example\">\n    <div class=\"sd-example-head\">\n      <div class=\"sd-example-title\">Ad Analytics Platform</div>\n      <span class=\"sd-example-tag\">HIGH CARDINALITY \u00b7 REAL-TIME BILLING</span>\n    </div>\n    <div class=\"sd-example-body\">\n      <div class=\"choice-row\"><div class=\"choice-label\">WINNER</div><div class=\"choice-val\"><span class=\"badge b-ch\">ClickHouse \u2713</span> Ad click aggregation: entity_id, campaign_id, impression counts, CTR \u2014 high write throughput, complex GROUP BY queries, need accurate counts for billing. ClickHouse's exactly-once semantics via Kafka + ReplacingMergeTree prevents double-counting.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">WHY NOT DRUID</div><div class=\"choice-val\"><span class=\"badge b-r\">Druid \u2717</span> Druid's rollup loses individual event detail. For billing, you need exact click counts per ad per user. Rollup would lose the granularity needed for fraud detection and accurate billing.</div></div>\n    </div>\n  </div>\n\n  <div class=\"sd-example\">\n    <div class=\"sd-example-head\">\n      <div class=\"sd-example-title\">Data Warehouse / Business Intelligence</div>\n      <span class=\"sd-example-tag\">AD-HOC \u00b7 DATA SCIENCE</span>\n    </div>\n    <div class=\"sd-example-body\">\n      <div class=\"choice-row\"><div class=\"choice-label\">WINNER</div><div class=\"choice-val\"><span class=\"badge b-bq\">BigQuery \u2713</span> For a BI team running diverse queries across petabytes of historical data with unpredictable patterns, BigQuery's serverless model wins. No cluster to right-size, pay only for what you query. Connects natively to Looker, Tableau, dbt.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">AWS EQUIVALENT</div><div class=\"choice-val\"><span class=\"badge b-rs\">Redshift \u2713</span> Same use case but in the AWS ecosystem. Redshift Spectrum lets you query data directly in S3 without loading it. Deep integration with Glue, EMR, QuickSight. If you're all-in on AWS, Redshift + Spectrum is the natural choice.</div></div>\n    </div>\n  </div>\n</section>\n\n<section id=\"decision\">\n  <div class=\"sec-tag\">05 \u00b7 The Decision Framework</div>\n  <h2>How to Pick in an Interview</h2>\n  <div class=\"step-block\">\n  <div class=\"step-block-header\"><span class=\"sb-icon\">\ud83c\udfaf</span>How to Pick an OLAP Engine \u2014 Ask in Order</div>\n  <div class=\"step-block-body\">\n    <div class=\"step-row\"><div class=\"step-num\">01</div><div class=\"step-content\">\n      <div class=\"step-q\">What is your query latency requirement?</div>\n      <div class=\"step-options\">\n        <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">&lt;1s interactive \u2192</span><span class=\"opt-text\"><strong>Apache Druid.</strong> Pre-aggregation at ingest means most of the work is already done before the query arrives.</span></div>\n        <div class=\"step-option opt-mid\"><span class=\"opt-arrow\">1\u20135s analytical \u2192</span><span class=\"opt-text\"><strong>ClickHouse.</strong> Columnar MergeTree on sorted data returns GROUP BY results in 300ms\u20132s on 100B rows.</span></div>\n        <div class=\"step-option opt-no\"><span class=\"opt-arrow\">5\u201360s ad-hoc \u2192</span><span class=\"opt-text\"><strong>BigQuery or Redshift.</strong> Serverless/MPP \u2014 accepts higher latency in exchange for unlimited scale and zero ops.</span></div>\n      </div>\n    </div></div>\n    <div class=\"step-row\"><div class=\"step-num\">02</div><div class=\"step-content\">\n      <div class=\"step-q\">What is your ingest pattern?</div>\n      <div class=\"step-options\">\n        <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">Streaming (Kafka) \u2192</span><span class=\"opt-text\"><strong>ClickHouse</strong> (native Kafka engine, 500K rows/sec) or <strong>Druid</strong> (streaming ingestion with rollup).</span></div>\n        <div class=\"step-option opt-no\"><span class=\"opt-arrow\">Batch loads \u2192</span><span class=\"opt-text\"><strong>BigQuery</strong> (batch load API, free) or <strong>Redshift</strong> (COPY from S3).</span></div>\n      </div>\n    </div></div>\n    <div class=\"step-row\"><div class=\"step-num\">03</div><div class=\"step-content\">\n      <div class=\"step-q\">Do you need exact counts, or are approximations OK?</div>\n      <div class=\"step-options\">\n        <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">Exact (billing) \u2192</span><span class=\"opt-text\"><strong>ClickHouse or BigQuery.</strong> No rollup \u2014 every raw row is stored and counted precisely.</span></div>\n        <div class=\"step-option opt-no\"><span class=\"opt-arrow\">Approx OK \u2192</span><span class=\"opt-text\"><strong>Druid with rollup + HyperLogLog.</strong> 50x storage reduction; accepts \u00b10.1% count error.</span></div>\n      </div>\n    </div></div>\n    <div class=\"step-row\"><div class=\"step-num\">04</div><div class=\"step-content\">\n      <div class=\"step-q\">What are your ops constraints?</div>\n      <div class=\"step-options\">\n        <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">Small team \u2192</span><span class=\"opt-text\"><strong>BigQuery</strong> (fully serverless) or <strong>Redshift</strong> (managed). No nodes to manage.</span></div>\n        <div class=\"step-option opt-no\"><span class=\"opt-arrow\">Infra capacity \u2192</span><span class=\"opt-text\"><strong>ClickHouse or Druid.</strong> Self-hosted on commodity hardware. 10x cheaper at extreme scale.</span></div>\n      </div>\n    </div></div>\n    <div class=\"step-row\"><div class=\"step-num\">05</div><div class=\"step-content\">\n      <div class=\"step-q\">Cloud commitment?</div>\n      <div class=\"step-options\">\n        <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">Agnostic \u2192</span><span class=\"opt-text\"><strong>ClickHouse or Druid.</strong> Open source, runs anywhere.</span></div>\n        <div class=\"step-option opt-mid\"><span class=\"opt-arrow\">GCP \u2192</span><span class=\"opt-text\"><strong>BigQuery.</strong> Native GCS, Looker, Vertex AI integration.</span></div>\n        <div class=\"step-option opt-no\"><span class=\"opt-arrow\">AWS \u2192</span><span class=\"opt-text\"><strong>Redshift.</strong> Deep S3/Glue/EMR/QuickSight integration.</span></div>\n      </div>\n    </div></div>\n  </div>\n</div>\n\n  <div class=\"use-grid\">\n    <div class=\"use-card\">\n      <div class=\"use-card-head\" style=\"color:#c00\">\ud83d\udd34 ClickHouse is perfect for\u2026</div>\n      <ul><li>High-frequency event analytics (Top-K, ad clicks)</li><li>Need streaming ingest + fast queries</li><li>Self-managed, cost-sensitive at scale</li><li>Time-series with complex aggregations</li></ul>\n    </div>\n    <div class=\"use-card\">\n      <div class=\"use-card-head\" style=\"color:#1a70cc\">\ud83d\udd35 Druid is perfect for\u2026</div>\n      <ul><li>Sub-second operational dashboards</li><li>High-cardinality dimensions (millions of unique values)</li><li>Pre-aggregation acceptable (approx counts ok)</li><li>Real-time + historical unified queries</li></ul>\n    </div>\n    <div class=\"use-card\">\n      <div class=\"use-card-head\" style=\"color:#1a50cc\">\ud83d\udd37 BigQuery is perfect for\u2026</div>\n      <ul><li>Petabyte-scale data warehouse</li><li>Data science, ML training data, ad-hoc</li><li>Bursty, unpredictable query patterns</li><li>Team without infra/ops capacity</li></ul>\n    </div>\n    <div class=\"use-card\">\n      <div class=\"use-card-head\" style=\"color:#cc7000\">\ud83d\udfe0 Redshift is perfect for\u2026</div>\n      <ul><li>Structured ETL pipelines in AWS</li><li>Traditional BI/reporting workloads</li><li>Deep integration with AWS ecosystem</li><li>Familiar PostgreSQL-compatible SQL</li></ul>\n    </div>\n  </div>\n</section>\n\n<section id=\"followups\">\n  <div class=\"sec-tag\">06 \u00b7 Interview Follow-up Playbook</div>\n  <h2>Every Hard Follow-up, Answered</h2>\n\n  <div class=\"faq-item\">\n    <div class=\"faq-q\" onclick=\"toggle(this)\">Why can't I just use PostgreSQL for analytics? It has window functions and GROUP BY.<span class=\"tog\">+</span></div>\n    <div class=\"faq-a\"><strong>You can \u2014 until you can't.</strong> PostgreSQL is fine for analytics up to ~100GB and simple aggregations. But at billions of rows, a single <code>GROUP BY</code> on PostgreSQL requires a full sequential scan reading every column. ClickHouse on the same data reads only the columns you reference, compresses integers 10\u201320x, and parallelises across all CPU cores.<br><br>Benchmark: <code>SELECT entity_type, SUM(view_count) FROM events WHERE event_date = today() GROUP BY entity_type</code> \u2014 PostgreSQL on 1B rows: ~8 minutes. ClickHouse: ~400ms. Same query, same data. That's why OLAP exists.</div>\n  </div>\n\n  <div class=\"faq-item\">\n    <div class=\"faq-q\" onclick=\"toggle(this)\">ClickHouse says it can ingest 500K rows/sec. How does that work with Kafka?<span class=\"tog\">+</span></div>\n    <div class=\"faq-a\"><strong>ClickHouse has a native Kafka engine \u2014 you define a Kafka table and ClickHouse becomes a consumer.</strong><br><br><code>CREATE TABLE kafka_events ENGINE = Kafka SETTINGS kafka_broker_list = 'kafka:9092', kafka_topic_list = 'events', kafka_format = 'JSONEachRow';</code><br><br>Then a Materialized View continuously reads from the Kafka table and inserts into your main MergeTree table. ClickHouse batches these inserts internally \u2014 it doesn't write each message individually. Batches of thousands of rows are written as a single \"part\" to disk, keeping write amplification low. The result: Kafka \u2192 ClickHouse pipeline with 30-60 second latency and 500K rows/sec throughput.</div>\n  </div>\n\n  <div class=\"faq-item\">\n    <div class=\"faq-q\" onclick=\"toggle(this)\">What's the difference between Druid's rollup and ClickHouse's AggregatingMergeTree?<span class=\"tog\">+</span></div>\n    <div class=\"faq-a\"><strong>Both pre-aggregate \u2014 but at different points in the pipeline and with different flexibility.</strong><br><br><strong>Druid rollup</strong> happens at ingest time. Raw events with the same dimensions within the same time granularity are collapsed into a single aggregate row. You define rollup at table creation. If you didn't include a dimension at ingest, you can never query by it. This achieves 50\u2013100x storage reduction but is irreversible.<br><br><strong>ClickHouse AggregatingMergeTree</strong> aggregates during background merge. Raw data is initially stored, then merged and aggregated in the background. You keep the full resolution until merged. More flexible, but storage reduction comes later and is less extreme than Druid's rollup.<br><br><strong>The choice:</strong> Known, fixed query patterns with approximate counts OK \u2192 Druid rollup. Need full granularity or exact counts \u2192 ClickHouse AggregatingMergeTree.</div>\n  </div>\n\n  <div class=\"faq-item\">\n    <div class=\"faq-q\" onclick=\"toggle(this)\">BigQuery charges per TB scanned. How do you control costs in a large team?<span class=\"tog\">+</span></div>\n    <div class=\"faq-a\"><strong>Four cost control techniques used at production scale:</strong><br><br><strong>1. Partition pruning:</strong> Always filter on the partition column (usually date). <code>WHERE event_date = '2026-03-20'</code> scans only one day's partition instead of all-time data. Mandatory in every query policy.<br><br><strong>2. Column selection:</strong> Never <code>SELECT *</code>. Each column selected costs proportional to its size. <code>SELECT event_type, COUNT(*)</code> is 10x cheaper than <code>SELECT *</code> on the same rows.<br><br><strong>3. Clustering:</strong> Cluster tables by high-cardinality filter columns. BigQuery skips irrelevant blocks within a partition when the filter matches a clustered column.<br><br><strong>4. Materialized Views / cached results:</strong> Common dashboard queries are cached for 24 hours. BigQuery caches identical queries automatically at no cost. Materialised Views pre-compute and store expensive aggregations.<br><br><strong>5. Reservations:</strong> Buy BigQuery slots (fixed compute) for predictable workloads instead of paying per query.</div>\n  </div>\n\n  <div class=\"faq-item\">\n    <div class=\"faq-q\" onclick=\"toggle(this)\">In the Top-K system, why is ClickHouse used instead of Cassandra for analytics?<span class=\"tog\">+</span></div>\n    <div class=\"faq-a\"><strong>Cassandra and ClickHouse serve fundamentally different query profiles.</strong><br><br><strong>Cassandra (warm store in Top-K):</strong> \"Give me all hourly counts for entity X in region IN over the last 30 days\" \u2014 a narrow range scan within one partition. Fast because it reads very little data. Good for: backfilling Redis, known entity lookups.<br><br><strong>ClickHouse (OLAP layer in Top-K):</strong> \"Give me the top 10 entities globally across all regions for the last 7 days, broken down by device, with hour-over-hour change\" \u2014 a full table scan across billions of rows with complex aggregation. Cassandra would do a full cluster scan for this query \u2014 every node would need to respond. ClickHouse scans only relevant columns and returns the answer in 500ms.<br><br><strong>Rule of thumb:</strong> Cassandra is for \"fetch a specific partition.\" ClickHouse is for \"aggregate across many partitions.\" They're complementary, not competitive.</div>\n  </div>\n</section>\n\n</div>\n<div class=\"footer\">OLAP \u00b7 CLICKHOUSE \u00b7 DRUID \u00b7 BIGQUERY \u00b7 REDSHIFT \u00b7 MANISH-ALMANAC</div>\n\u003cscript>function toggle(el){el.parentElement.classList.toggle('open');}<\/script>\n</body>\n</html>\n", tag: 'Analytics DB' },
  streaming:   { title: 'Stream Processing Decoded',     srcdoc: "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Stream Processing Showdown: Kafka vs Flink vs Kinesis vs Spark Streaming</title>\n<link href=\"https://fonts.googleapis.com/css2?family=Sora:wght@300;400;600;700;800&family=JetBrains+Mono:wght@400;600&display=swap\" rel=\"stylesheet\">\n<style>\n:root{--ink:#080c14;--page:#f2f4f8;--surface:#e6eaf2;--surface2:#d8dcec;--border:#c8cdd8;--muted:#687088;\n--kf:#000000;--kf-bg:#f0f0f0;--fl:#e35400;--fl-bg:#fff4ef;--ki:#ff9900;--ki-bg:#fff8ee;--ss:#e25100;--ss-bg:#fff3ee;\n--red:#c0392b;--red-bg:#fdf0ee;--green:#1a7a4a;--green-bg:#edf8f2;--amber:#b8720a;--amber-bg:#fdf6e8;--blue:#1a4f8a;--blue-bg:#edf2fb;--teal:#0a7070;--teal-bg:#edf6f6;\n--mono:'JetBrains Mono',monospace;--sans:'Sora',sans-serif;}\n*{box-sizing:border-box;margin:0;padding:0;}html{scroll-behavior:smooth;}\nbody{background:var(--page);color:var(--ink);font-family:var(--sans);font-size:15px;line-height:1.75;}\n.hero{background:var(--ink);color:#dde0ec;padding:72px 24px 56px;position:relative;overflow:hidden;}\n.hero::before{content:'';position:absolute;inset:0;background:repeating-linear-gradient(90deg,transparent,transparent 80px,rgba(255,255,255,.008) 80px,rgba(255,255,255,.008) 81px);}\n.hero-inner{max-width:960px;margin:0 auto;position:relative;}\n.hero-tag{font-family:var(--mono);font-size:10px;letter-spacing:4px;color:#3a3e50;text-transform:uppercase;margin-bottom:20px;}\nh1{font-family:var(--sans);font-size:clamp(30px,5vw,56px);font-weight:800;line-height:1.05;letter-spacing:-1.5px;margin-bottom:20px;color:#eef0f8;}\nh1 em{color:#f77f3a;font-style:normal;}\n.hero-sub{font-size:15px;color:#5a5e70;max-width:640px;line-height:1.7;margin-bottom:32px;}\n.db-pills{display:flex;flex-wrap:wrap;gap:8px;}\n.db-pill{font-family:var(--mono);font-size:10px;padding:5px 14px;border-radius:3px;border:1px solid;letter-spacing:.5px;}\n.pill-kf{border-color:#666;color:#666;background:rgba(0,0,0,.05);}\n.pill-fl{border-color:#e35400;color:#c04400;background:rgba(227,84,0,.06);}\n.pill-ki{border-color:#ff9900;color:#cc7000;background:rgba(255,153,0,.06);}\n.pill-ss{border-color:#e25100;color:#b04000;background:rgba(226,81,0,.06);}\n.nav{position:sticky;top:0;z-index:100;background:var(--ink);border-bottom:1px solid #101420;display:flex;overflow-x:auto;scrollbar-width:none;padding:0 20px;}\n.nav::-webkit-scrollbar{display:none;}\n.nav a{font-family:var(--mono);font-size:10px;letter-spacing:1px;color:#2a2e40;text-decoration:none;padding:14px 12px;white-space:nowrap;border-bottom:2px solid transparent;transition:.18s;}\n.nav a:hover{color:#f77f3a;border-color:#f77f3a;}\n.wrap{max-width:960px;margin:0 auto;padding:0 20px;}\nsection{padding:56px 0 36px;border-bottom:2px solid var(--border);}\nsection:last-child{border:none;}\n.sec-tag{font-family:var(--mono);font-size:9px;letter-spacing:4px;text-transform:uppercase;color:#7a7e90;margin-bottom:8px;display:flex;align-items:center;gap:10px;}\n.sec-tag::before{content:'';width:20px;height:1px;background:var(--border);}\nh2{font-family:var(--sans);font-size:clamp(22px,3.5vw,32px);font-weight:700;line-height:1.15;margin-bottom:18px;letter-spacing:-.5px;}\nh3{font-family:var(--sans);font-size:17px;font-weight:600;margin:32px 0 10px;border-bottom:1px solid var(--border);padding-bottom:6px;}\np{color:#3a3d50;font-size:14.5px;margin-bottom:12px;}\nstrong{color:var(--ink);}\ncode{font-family:var(--mono);font-size:11.5px;background:var(--surface2);padding:1px 5px;border-radius:3px;color:var(--blue);}\n.db-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:14px;margin:24px 0;}\n.db-card{background:white;border:1px solid var(--border);border-radius:8px;padding:20px;position:relative;overflow:hidden;}\n.db-card::before{content:'';position:absolute;top:0;left:0;right:0;height:4px;}\n.db-card.kf::before{background:#333;}.db-card.fl::before{background:var(--fl);}.db-card.ki::before{background:var(--ki);}.db-card.ss::before{background:var(--ss);}\n.db-logo{font-size:22px;margin-bottom:6px;}\n.db-name{font-family:var(--sans);font-size:17px;font-weight:700;letter-spacing:-.3px;margin-bottom:4px;}\n.db-type{font-family:var(--mono);font-size:9px;letter-spacing:2px;color:#7a7e90;margin-bottom:10px;text-transform:uppercase;}\n.db-tagline{font-size:13px;color:#5a5e70;line-height:1.55;}\n.db-born{font-family:var(--mono);font-size:9px;color:#7a7e90;margin-top:8px;}\n.role-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:16px;margin:24px 0;}\n.role-card{border-radius:8px;padding:20px;border:1px solid var(--border);}\n.role-card.transport{background:#f8f0e8;border-color:#d8b88a;}\n.role-card.processing{background:#e8f4f0;border-color:#8ac8b0;}\n.role-title{font-family:var(--mono);font-size:10px;letter-spacing:2px;text-transform:uppercase;margin-bottom:8px;font-weight:600;}\n.role-body{font-size:13.5px;color:#3a3d50;line-height:1.65;}\n.analogy{background:var(--ink);color:#c8ccd8;border-radius:8px;padding:24px 28px;margin:24px 0;}\n.analogy-label{font-family:var(--mono);font-size:9px;letter-spacing:3px;color:#3a3e50;margin-bottom:10px;text-transform:uppercase;}\n.analogy-text{font-size:15px;line-height:1.75;color:#d0d4e0;}\n.analogy-text strong{color:#f77f3a;}\n.callout{border-radius:4px;padding:14px 18px;margin:18px 0;font-size:13.5px;border-left:3px solid;line-height:1.65;}\n.callout p{font-size:13.5px;margin-bottom:6px;}.callout p:last-child{margin:0;}\n.cl-blue{background:var(--blue-bg);border-color:var(--blue);color:#1a2a4a;}\n.cl-green{background:var(--green-bg);border-color:var(--green);color:#0a2a1a;}\n.cl-amber{background:var(--amber-bg);border-color:var(--amber);color:#3a2a08;}\n.cl-red{background:var(--red-bg);border-color:var(--red);color:#3a0a08;}\n.cl-teal{background:var(--teal-bg);border-color:var(--teal);color:#0a2a2a;}\n.cl-lbl{font-family:var(--mono);font-size:9px;letter-spacing:3px;text-transform:uppercase;margin-bottom:6px;opacity:.7;}\n.codeblock{background:var(--ink);border-radius:6px;padding:20px 22px;font-family:var(--mono);font-size:11.5px;line-height:2;overflow-x:auto;margin:14px 0;color:#c8ccd8;border:1px solid #101420;}\n.codeblock .c{color:#2a2e40;}.codeblock .k{color:#f77f3a;}.codeblock .s{color:#8bc4a0;}.codeblock .n{color:#e8a06a;}.codeblock .g{color:#a8d878;}.codeblock .r{color:#e87878;}.codeblock .t{color:#7ab8e0;}\n.comp-table{width:100%;border-collapse:collapse;margin:20px 0;font-size:13px;}\n.comp-table th{padding:10px 14px;border:1px solid var(--border);background:var(--surface2);font-family:var(--mono);font-size:9px;letter-spacing:1.5px;text-transform:uppercase;color:#7a7e90;}\n.comp-table td{padding:11px 14px;border:1px solid var(--border);vertical-align:top;color:#3a3d50;line-height:1.6;}\n.comp-table .row-head{font-family:var(--mono);font-size:11px;font-weight:600;background:var(--surface);color:var(--ink);white-space:nowrap;}\n.good{color:var(--green);font-weight:600;}.warn{color:var(--amber);font-weight:600;}.bad{color:var(--red);font-weight:600;}\n.sd-example{background:white;border:1px solid var(--border);border-radius:8px;margin:20px 0;overflow:hidden;}\n.sd-example-head{background:var(--ink);padding:14px 20px;display:flex;align-items:center;gap:12px;}\n.sd-example-title{font-family:var(--sans);font-size:16px;font-weight:700;color:#eef0f8;}\n.sd-example-tag{font-family:var(--mono);font-size:9px;letter-spacing:2px;color:#3a3e50;border:1px solid #1a1e30;padding:3px 8px;border-radius:2px;}\n.sd-example-body{padding:20px;}\n.choice-row{display:flex;gap:10px;align-items:flex-start;padding:10px 0;border-bottom:1px solid var(--border);font-size:13px;}\n.choice-row:last-child{border:none;}\n.choice-label{font-family:var(--mono);font-size:10px;letter-spacing:1px;color:#7a7e90;width:120px;flex-shrink:0;padding-top:2px;}\n.choice-val{flex:1;color:#3a3d50;line-height:1.6;}\n.badge{display:inline-block;font-family:var(--mono);font-size:9px;padding:2px 7px;border-radius:2px;border:1px solid;margin-right:4px;font-weight:500;}\n.b-kf{background:#f0f0f0;border-color:#999;color:#444;}.b-fl{background:var(--fl-bg);border-color:var(--fl);color:#c04400;}.b-ki{background:var(--ki-bg);border-color:var(--ki);color:#cc7000;}.b-ss{background:var(--ss-bg);border-color:var(--ss);color:#b04000;}.b-g{background:var(--green-bg);border-color:var(--green);color:var(--green);}.b-r{background:var(--red-bg);border-color:var(--red);color:var(--red);}.b-a{background:var(--amber-bg);border-color:var(--amber);color:var(--amber);}\n.faq-item{border:1px solid var(--border);border-radius:4px;margin-bottom:8px;overflow:hidden;}\n.faq-q{padding:14px 18px;display:flex;justify-content:space-between;align-items:center;cursor:pointer;background:white;font-size:14px;font-weight:500;color:var(--ink);user-select:none;}\n.faq-q:hover{background:var(--surface);}\n.faq-q .tog{font-size:18px;color:#f77f3a;flex-shrink:0;margin-left:12px;transition:transform .2s;font-family:var(--mono);}\n.faq-a{display:none;padding:18px;background:var(--surface);font-size:13.5px;color:#3a3d50;line-height:1.75;border-top:1px solid var(--border);}\n.faq-item.open .faq-a{display:block;}.faq-item.open .tog{transform:rotate(45deg);}\n.use-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:14px;margin:20px 0;}\n.use-card{border:1px solid var(--border);border-radius:6px;padding:18px;background:white;}\n.use-card-head{font-family:var(--mono);font-size:11px;font-weight:600;margin-bottom:10px;}\n.use-card ul{padding-left:16px;font-size:13px;color:#4a4e60;line-height:1.7;}\n.use-card ul li{margin-bottom:4px;}\n.footer{background:var(--ink);text-align:center;padding:36px 20px;font-family:var(--mono);font-size:10px;color:#1a1e30;letter-spacing:2px;}\n\n.step-block{background:#fff;border:1px solid var(--border);border-radius:8px;margin:20px 0;overflow:hidden;}\n.step-block-header{background:var(--ink);color:#e8e4dc;padding:13px 18px;font-family:var(--mono);font-size:10px;letter-spacing:2px;text-transform:uppercase;display:flex;align-items:center;gap:10px;}\n.sb-icon{font-size:16px;}\n.step-block-body{padding:0;}\n.step-row{display:flex;gap:0;border-bottom:1px solid var(--border);}\n.step-row:last-child{border-bottom:none;}\n.step-num{background:var(--surface);min-width:46px;display:flex;align-items:flex-start;justify-content:center;padding:16px 6px;font-family:var(--mono);font-size:11px;font-weight:700;color:var(--muted);flex-shrink:0;border-right:1px solid var(--border);}\n.step-content{padding:14px 18px;flex:1;}\n.step-q{font-weight:600;font-size:14px;color:var(--ink);margin-bottom:10px;}\n.step-options{display:flex;flex-direction:column;gap:6px;}\n.step-option{display:flex;gap:10px;align-items:flex-start;padding:9px 13px;border-radius:5px;font-size:13px;line-height:1.65;}\n.opt-yes{background:#edf8f2;border:1px solid #b8ddc8;}\n.opt-no{background:#fdf6e8;border:1px solid #e8c870;}\n.opt-mid{background:#edf2fb;border:1px solid #b8c8e8;}\n.opt-any{background:#f4f0fb;border:1px solid #c8b8e8;}\n.opt-arrow{font-family:var(--mono);font-size:12px;font-weight:700;flex-shrink:0;margin-top:1px;min-width:120px;}\n.opt-yes .opt-arrow{color:#1a7a4a;}\n.opt-no .opt-arrow{color:#b8720a;}\n.opt-mid .opt-arrow{color:#1a4f8a;}\n.opt-any .opt-arrow{color:#5a3c9a;}\n.opt-text{flex:1;color:#3a3830;}\n.concept-grid{display:grid;grid-template-columns:1fr;gap:0;margin:20px 0;border:1px solid var(--border);border-radius:8px;overflow:hidden;}\n.concept-row{display:flex;gap:0;border-bottom:1px solid var(--border);}\n.concept-row:last-child{border-bottom:none;}\n.concept-term{background:var(--ink);color:#e8b84b;font-family:var(--mono);font-size:11.5px;font-weight:600;min-width:155px;padding:14px 16px;flex-shrink:0;border-right:1px solid #2a2820;display:flex;align-items:flex-start;line-height:1.5;}\n.concept-def{padding:13px 16px;flex:1;font-size:13.5px;color:#3a3830;line-height:1.7;background:#fff;}\n.concept-def strong{color:var(--ink);}\n.concept-def code{background:var(--surface);padding:1px 5px;border-radius:3px;font-family:var(--mono);font-size:11px;color:var(--blue);}\n@media(max-width:560px){.concept-row{flex-direction:column;}.concept-term{min-width:auto;border-right:none;border-bottom:1px solid #2a2820;}.opt-arrow{min-width:80px;}}\n\n</style>\n</head>\n<body>\n<div class=\"hero\">\n  <div class=\"hero-inner\">\n    <div class=\"hero-tag\">System Design \u00b7 Stream Processing \u00b7 Manish-Almanac</div>\n    <h1>Stream Processing<br><em>Decoded</em></h1>\n    <p class=\"hero-sub\">Kafka vs Apache Flink vs Amazon Kinesis vs Spark Streaming \u2014 understand the roles, the differences, and exactly how to use each in a FAANG-level system design interview. With real examples and every follow-up answered.</p>\n    <div class=\"db-pills\">\n      <span class=\"db-pill pill-kf\">Apache Kafka</span>\n      <span class=\"db-pill pill-fl\">Apache Flink</span>\n      <span class=\"db-pill pill-ki\">Amazon Kinesis</span>\n      <span class=\"db-pill pill-ss\">Spark Streaming</span>\n    </div>\n  </div>\n</div>\n<nav class=\"nav\">\n  <a href=\"#roles\">Transport vs Processing</a>\n  <a href=\"#identity\">Identity</a>\n  <a href=\"#kafka-deep\">Kafka Deep</a>\n  <a href=\"#processing\">Processing Engines</a>\n  <a href=\"#comparison\">Full Comparison</a>\n  <a href=\"#examples\">System Design</a>\n  <a href=\"#decision\">Decision Tree</a>\n  <a href=\"#followups\">Follow-ups</a>\n</nav>\n<div class=\"wrap\">\n\n<section id=\"roles\">\n  <div class=\"sec-tag\">00 \u00b7 The Critical Distinction</div>\n  <h2>Transport vs Processing \u2014 they're not the same thing</h2>\n  <p>The biggest mistake candidates make is treating Kafka, Flink, Kinesis, and Spark Streaming as competing alternatives. <strong>They're not.</strong> They play fundamentally different roles in a streaming architecture.</p>\n  <div class=\"role-grid\">\n    <div class=\"role-card transport\">\n      <div class=\"role-title\" style=\"color:#8a6020\">\ud83d\ude8c Transport / Message Bus</div>\n      <div class=\"role-body\"><strong>Kafka, Kinesis, Pulsar</strong><br><br>Like a highway \u2014 vehicles (messages) enter, travel through, and exit. The highway stores vehicles temporarily so producers don't have to wait for consumers to be ready. It decouples producers from consumers.<br><br>Key properties: durable storage, ordered delivery within partition, multiple consumers reading the same message independently, replay old messages.</div>\n    </div>\n    <div class=\"role-card processing\">\n      <div class=\"role-title\" style=\"color:#1a6a4a\">\u2699\ufe0f Stream Processor</div>\n      <div class=\"role-body\"><strong>Flink, Spark Streaming, Kafka Streams</strong><br><br>Like a factory that processes vehicles as they pass through \u2014 counting them, sorting them, combining them with data from other sources, detecting anomalies. The processor does the actual computation.<br><br>Key properties: stateful computation, windowing (tumbling, sliding, session), joins across streams, exactly-once semantics, fault tolerance with checkpoints.</div>\n    </div>\n  </div>\n  <div class=\"callout cl-teal\">\n    <div class=\"cl-lbl\">The correct mental model for Top-K</div>\n    <p><strong>Kafka</strong> = the highway. Events from users flow in, get durably stored, and multiple consumers can read them independently and at their own pace.</p>\n    <p><strong>Flink</strong> = the factory. Consumes from Kafka, applies the Count-Min Sketch, maintains the local heap, and every 30 seconds flushes the Top-K results to Redis and Cassandra.</p>\n    <p>You <strong>always use a transport layer AND a processing layer</strong> together. They're complementary, not competitive.</p>\n  </div>\n</section>\n\n<section id=\"identity\">\n  <div class=\"sec-tag\">01 \u00b7 Who Are They</div>\n  <h2>The Four Technologies</h2>\n  <div class=\"db-grid\">\n    <div class=\"db-card kf\">\n      <div class=\"db-logo\">\u2b1b</div>\n      <div class=\"db-name\">Apache Kafka</div>\n      <div class=\"db-type\">Distributed Message Bus</div>\n      <div class=\"db-tagline\">The gold standard for event streaming. Durable, ordered, replayable. Processes trillions of events/day at LinkedIn, Netflix, Uber. The backbone of nearly every modern data platform.</div>\n      <div class=\"db-born\">Born 2011 \u00b7 LinkedIn \u2192 Apache \u00b7 Log-structured storage</div>\n    </div>\n    <div class=\"db-card fl\">\n      <div class=\"db-logo\">\ud83d\udd36</div>\n      <div class=\"db-name\">Apache Flink</div>\n      <div class=\"db-type\">Stateful Stream Processor</div>\n      <div class=\"db-tagline\">The stream processing heavyweight. True streaming (not micro-batch), exactly-once semantics, millisecond latency, complex windowing, stateful operations. Used by Uber, Alibaba, Apple for real-time pipelines.</div>\n      <div class=\"db-born\">Born 2014 \u00b7 TU Berlin \u2192 Apache \u00b7 Dataflow model</div>\n    </div>\n    <div class=\"db-card ki\">\n      <div class=\"db-logo\">\ud83d\udfe0</div>\n      <div class=\"db-name\">Amazon Kinesis</div>\n      <div class=\"db-type\">Managed Event Streaming (AWS)</div>\n      <div class=\"db-tagline\">Kafka's managed AWS alternative. Zero ops, auto-scaling shards, deep AWS integration (Lambda, S3, Redshift). Perfect if you're all-in AWS and don't want to manage a Kafka cluster.</div>\n      <div class=\"db-born\">Born 2013 \u00b7 Amazon AWS \u00b7 Shard-based partitioning</div>\n    </div>\n    <div class=\"db-card ss\">\n      <div class=\"db-logo\">\u2726</div>\n      <div class=\"db-name\">Spark Streaming</div>\n      <div class=\"db-type\">Micro-Batch Stream Processor</div>\n      <div class=\"db-tagline\">Streaming built on Spark's batch engine. Uses micro-batches (seconds) rather than true streaming. Best when you already use Spark for batch ETL and want a unified pipeline. Not ideal for millisecond-latency requirements.</div>\n      <div class=\"db-born\">Born 2013 \u00b7 UC Berkeley \u2192 Apache \u00b7 Micro-batch model</div>\n    </div>\n  </div>\n</section>\n\n<section id=\"kafka-deep\">\n  <div class=\"sec-tag\">02 \u00b7 Transport Layer Deep Dive</div>\n  <h2>Kafka \u2014 Understanding It at Interview Depth</h2>\n  <div class=\"analogy\">\n    <div class=\"analogy-label\">Kafka explained for a complete layman</div>\n    <div class=\"analogy-text\">\n      Imagine a newspaper printing plant. Every morning, thousands of reporters (producers) submit stories. The plant prints millions of copies (events) and distributes them to hundreds of newsstands (partitions). Each newsstand keeps its newspapers for 7 days (retention).<br><br>\n      Any reader (consumer) can pick up a paper from any newsstand, and two readers picking up the same paper both get the full content \u2014 the paper isn't destroyed when read. A reader can also go back and re-read papers from last Tuesday (replay).<br><br>\n      <strong>The magic:</strong> Reporters don't wait for readers. Readers don't wait for reporters. The newsstand (Kafka) acts as a durable buffer between them.\n    </div>\n  </div>\n\n  <h3>The Core Kafka Concepts Every Interviewer Expects</h3>\n  <div class=\"concept-grid\">\n  <div class=\"concept-row\"><div class=\"concept-term\">Topic</div><div class=\"concept-def\"><strong>A named, ordered stream of events.</strong> Like a table in a database but append-only.<br><code>\"user-clicks\"</code>, <code>\"video-views\"</code>, <code>\"payment-events\"</code><br><span style=\"color:#5a5848;font-size:12.5px;\">Producers write to a topic. Consumers read from a topic. They never interact directly \u2014 Kafka decouples them.</span></div></div>\n  <div class=\"concept-row\"><div class=\"concept-term\">Partition</div><div class=\"concept-def\"><strong>A topic is split into N ordered partitions for parallelism.</strong> Each event is assigned based on its key:<br><code>partition = hash(entity_id) % N</code><br><span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Within a partition: order is GUARANTEED.</span> <span style=\"color:#b83030;font-size:12.5px;\">\u2717 Across partitions: NOT guaranteed.</span><br><span style=\"color:#5a5848;font-size:12.5px;\">Partitioning by entity_id means all events for video_123 go to the same partition \u2192 same Flink worker \u2192 no coordination needed.</span></div></div>\n  <div class=\"concept-row\"><div class=\"concept-term\">Offset</div><div class=\"concept-def\"><strong>A sequential integer ID for each event within a partition.</strong> Consumers track their own position \u2014 \"I have read up to message #12,847\".<br><span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Enables replay: if Flink crashes, it restarts from offset #12,847. Kafka still has all the events (7-day retention).</span></div></div>\n  <div class=\"concept-row\"><div class=\"concept-term\">Consumer Group</div><div class=\"concept-def\"><strong>A set of consumers sharing work on a topic.</strong> Each partition is consumed by exactly ONE consumer in the group. Multiple groups can read the same topic simultaneously and independently.<br><span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Flink, ClickHouse Kafka engine, and S3 sink can all read the same topic at the same time \u2014 each at their own pace, each with their own offset.</span></div></div>\n  <div class=\"concept-row\"><div class=\"concept-term\">Broker</div><div class=\"concept-def\"><strong>A Kafka server node.</strong> Usually 3\u20135 brokers in production. Each partition is replicated across brokers (replication factor = 3).<br><span style=\"color:#5a5848;font-size:12.5px;\">Leader broker accepts writes. Followers replicate. If leader fails, a follower is promoted automatically \u2014 no downtime.</span></div></div>\n  <div class=\"concept-row\"><div class=\"concept-term\">Retention</div><div class=\"concept-def\"><strong>How long Kafka stores events before deleting.</strong> Default 7 days. Configurable to forever.<br><span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 This is what makes replay possible. Flink crashed? Kafka still has 7 days of events. Resume from last checkpoint offset \u2014 no data loss.</span></div></div>\n</div>\n\n  <h3>Kafka vs Kinesis \u2014 The Managed vs Self-Managed Decision</h3>\n  <table class=\"comp-table\">\n    <thead><tr><th>Dimension</th><th>Apache Kafka \u2b1b</th><th>Amazon Kinesis \ud83d\udfe0</th></tr></thead>\n    <tbody>\n      <tr><td class=\"row-head\">Throughput</td><td><span class=\"good\">Millions/sec</span> per cluster</td><td><span class=\"warn\">1MB/sec or 1000 records/sec</span> per shard</td></tr>\n      <tr><td class=\"row-head\">Latency</td><td><span class=\"good\">Sub-millisecond</span></td><td><span class=\"warn\">70\u2013200ms</span> typical</td></tr>\n      <tr><td class=\"row-head\">Retention</td><td><span class=\"good\">Configurable</span> \u2014 days to forever</td><td><span class=\"warn\">24h default</span>, max 7 days (Kinesis Firehose: unlimited)</td></tr>\n      <tr><td class=\"row-head\">Replay</td><td><span class=\"good\">Any offset, any time</span></td><td><span class=\"warn\">Within retention window</span> only</td></tr>\n      <tr><td class=\"row-head\">Partitioning</td><td>Topics \u2192 Partitions (flexible count)</td><td>Streams \u2192 Shards (auto-scaling available)</td></tr>\n      <tr><td class=\"row-head\">Consumer Groups</td><td><span class=\"good\">Unlimited</span> independent consumer groups</td><td><span class=\"warn\">Limited</span> \u2014 5 consumers per shard by default</td></tr>\n      <tr><td class=\"row-head\">Ops Burden</td><td><span class=\"bad\">High</span> \u2014 manage brokers, ZK/KRaft, rebalancing</td><td><span class=\"good\">Zero</span> \u2014 fully managed</td></tr>\n      <tr><td class=\"row-head\">Cost Model</td><td>Fixed infra cost (predictable at scale)</td><td>Pay per shard-hour + data volume</td></tr>\n      <tr><td class=\"row-head\">Cloud Lock-in</td><td><span class=\"good\">None</span> \u2014 open source, any cloud</td><td><span class=\"bad\">AWS only</span></td></tr>\n      <tr><td class=\"row-head\">AWS Integration</td><td>Manual connectors</td><td><span class=\"good\">Native</span> Lambda triggers, S3 Firehose, Redshift</td></tr>\n    </tbody>\n  </table>\n</section>\n\n<section id=\"processing\">\n  <div class=\"sec-tag\">03 \u00b7 Processing Layer Deep Dive</div>\n  <h2>Flink vs Spark Streaming \u2014 True Streaming vs Micro-Batch</h2>\n\n  <div class=\"callout cl-amber\">\n    <div class=\"cl-lbl\">The Core Difference</div>\n    <p><strong>Apache Flink:</strong> True streaming. Processes each event as it arrives. State is maintained in memory/RocksDB between events. Latency: milliseconds. Results are continuously updated.</p>\n    <p><strong>Spark Streaming (Structured Streaming):</strong> Micro-batch. Collects events for X seconds (e.g., 5s), then processes the batch. Latency: minimum is the batch interval. Simpler programming model, reuses Spark's batch optimisations.</p>\n  </div>\n\n  <div class=\"analogy\">\n    <div class=\"analogy-label\">True streaming vs micro-batch \u2014 the toll booth analogy</div>\n    <div class=\"analogy-text\">\n      <strong>True streaming (Flink):</strong> Each car approaches the toll booth and is processed individually as it arrives. The attendant collects, processes, and lets through each car without waiting. Immediate, real-time.<br><br>\n      <strong>Micro-batch (Spark Streaming):</strong> Cars are held at a red light for 5 seconds. Then the light turns green, all cars are processed together as a batch, then the light turns red again. Slightly delayed but can be more efficient for high volumes.\n    </div>\n  </div>\n\n  <h3>Flink's Key Capabilities \u2014 What Makes It the FAANG Choice</h3>\n  <div class=\"concept-grid\">\n  <div class=\"concept-row\"><div class=\"concept-term\">Tumbling Window</div><div class=\"concept-def\"><strong>Fixed-size, non-overlapping time buckets.</strong> Events from t=0 to t=30s form one window. At t=30s: window closes, results emitted, new window starts from scratch.<br><span style=\"color:#1a7a4a;font-size:12.5px;\">Used in Top-K: flush Top-K results to Redis + Cassandra every 30 seconds. Simple, low memory, predictable cost.</span></div></div>\n  <div class=\"concept-row\"><div class=\"concept-term\">Sliding Window</div><div class=\"concept-def\"><strong>Overlapping windows \u2014 span Y, slide every X.</strong> A 1-hour window sliding every 5 minutes keeps 12 overlapping windows active simultaneously.<br><span style=\"color:#5a5848;font-size:12.5px;\">Used for: \"trending in the last hour\" with smooth continuous updates. Cost: 12\u00d7 the memory and compute of a tumbling window.</span></div></div>\n  <div class=\"concept-row\"><div class=\"concept-term\">Session Window</div><div class=\"concept-def\"><strong>Window stays open while user is active, closes after an idle gap.</strong> Gap timeout = 30 minutes: session ends after 30 min of inactivity.<br><span style=\"color:#5a5848;font-size:12.5px;\">Used for: user session analytics, funnel analysis, engagement time measurement.</span></div></div>\n  <div class=\"concept-row\"><div class=\"concept-term\">Exactly-Once</div><div class=\"concept-def\"><strong>Each event is counted exactly once even if Flink crashes and restarts.</strong><br>Every 60s: Flink saves its full state (Count-Min Sketch, heap, Bloom filter) + last Kafka offset to S3. On crash: restore state from S3, resume reading Kafka from saved offset.<br><span style=\"color:#1a7a4a;font-size:12.5px;\">Two-phase commit: Flink only confirms the offset to Kafka AFTER the S3 checkpoint completes. No event lost or double-counted.</span></div></div>\n  <div class=\"concept-row\"><div class=\"concept-term\">RocksDB State</div><div class=\"concept-def\"><strong>Flink state can be larger than available RAM.</strong> RocksDB spills to local disk, keeping only hot entries in memory. Checkpointed to S3 for fault tolerance.<br><span style=\"color:#5a5848;font-size:12.5px;\">In Top-K: the Count-Min Sketch (~6KB) and local min-heap ARE Flink state. They survive restarts because they're in the checkpoint.</span></div></div>\n  <div class=\"concept-row\"><div class=\"concept-term\">Watermarks</div><div class=\"concept-def\"><strong>Flink's mechanism for handling late-arriving events.</strong> A watermark at t=14:24:00 signals \"all events before 14:24:00 have probably arrived.\" Windows only close when the watermark passes the window end.<br><span style=\"color:#5a5848;font-size:12.5px;\">Allowed lateness: after a window closes, Flink waits X more seconds for stragglers. Late events re-trigger the window with a corrected result.</span></div></div>\n</div>\n\n  <h3>When to Use Each Processing Engine</h3>\n  <table class=\"comp-table\">\n    <thead><tr><th>Dimension</th><th>Apache Flink \ud83d\udd36</th><th>Spark Streaming \u2726</th><th>Kafka Streams</th></tr></thead>\n    <tbody>\n      <tr><td class=\"row-head\">Processing Model</td><td><span class=\"good\">True streaming</span></td><td><span class=\"warn\">Micro-batch</span> (1\u201310s)</td><td><span class=\"good\">True streaming</span></td></tr>\n      <tr><td class=\"row-head\">Latency</td><td><span class=\"good\">Milliseconds</span></td><td><span class=\"warn\">Seconds</span> (batch interval)</td><td><span class=\"good\">Milliseconds</span></td></tr>\n      <tr><td class=\"row-head\">Exactly-Once</td><td><span class=\"good\">Yes</span> \u2014 native</td><td><span class=\"warn\">Yes</span> \u2014 with idempotent sinks</td><td><span class=\"good\">Yes</span> \u2014 within Kafka</td></tr>\n      <tr><td class=\"row-head\">Complexity</td><td><span class=\"warn\">High</span> \u2014 dedicated cluster</td><td><span class=\"warn\">Medium</span> \u2014 reuses Spark</td><td><span class=\"good\">Low</span> \u2014 library, no cluster</td></tr>\n      <tr><td class=\"row-head\">State Management</td><td><span class=\"good\">RocksDB</span>, large state ok</td><td><span class=\"warn\">In-memory</span> \u2014 limited state</td><td><span class=\"good\">RocksDB</span> local to app</td></tr>\n      <tr><td class=\"row-head\">Best For</td><td>Complex stateful streaming, low latency</td><td>Already using Spark batch; simple streaming</td><td>Lightweight per-service streaming</td></tr>\n      <tr><td class=\"row-head\">Throughput</td><td>Millions events/sec</td><td>Millions events/sec (in batch)</td><td>Hundreds K/sec per app</td></tr>\n      <tr><td class=\"row-head\">Used By</td><td>Uber, Alibaba, Apple, Netflix</td><td>Databricks customers, Spark shops</td><td>Microservice architectures</td></tr>\n    </tbody>\n  </table>\n</section>\n\n<section id=\"comparison\">\n  <div class=\"sec-tag\">04 \u00b7 The Full Stack</div>\n  <h2>How They Combine in a Real Architecture</h2>\n\n  <div class=\"callout cl-blue\">\n    <div class=\"cl-lbl\">The standard streaming stack pattern</div>\n    <p><strong>Layer 1 \u2014 Producers:</strong> Applications, services, IoT sensors emit events.</p>\n    <p><strong>Layer 2 \u2014 Transport (Kafka / Kinesis):</strong> Events are durably stored, decoupling producers from consumers. Multiple downstream consumers read independently.</p>\n    <p><strong>Layer 3 \u2014 Stream Processor (Flink / Spark):</strong> Consumes from transport layer, applies business logic (windowing, aggregation, enrichment, filtering), outputs results.</p>\n    <p><strong>Layer 4 \u2014 Sinks:</strong> Results written to Redis (hot), Cassandra (warm), ClickHouse (analytics), S3 (cold/archive).</p>\n  </div>\n\n  <div class=\"step-block\">\n  <div class=\"step-block-header\"><span class=\"sb-icon\">\ud83c\udfaf</span>How to Pick Streaming Technology \u2014 Ask in Order</div>\n  <div class=\"step-block-body\">\n    <div class=\"step-row\"><div class=\"step-num\">01</div><div class=\"step-content\">\n      <div class=\"step-q\">What is your latency requirement?</div>\n      <div class=\"step-options\">\n        <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">Sub-second \u2192</span><span class=\"opt-text\"><strong>Kafka + Flink.</strong> True streaming \u2014 each event processed in milliseconds. Required for fraud detection, real-time alerts, live scoring.</span></div>\n        <div class=\"step-option opt-mid\"><span class=\"opt-arrow\">Seconds OK \u2192</span><span class=\"opt-text\"><strong>Kafka + Flink or Kafka + Spark Streaming.</strong> Either works. Flink is cleaner; Spark if you already have it running.</span></div>\n        <div class=\"step-option opt-no\"><span class=\"opt-arrow\">Minutes OK \u2192</span><span class=\"opt-text\"><strong>Kafka/Kinesis + Spark Structured Streaming.</strong> Micro-batch ETL into data warehouse. Simple, proven, cost-effective.</span></div>\n      </div>\n    </div></div>\n    <div class=\"step-row\"><div class=\"step-num\">02</div><div class=\"step-content\">\n      <div class=\"step-q\">Do you need stateful computation?</div>\n      <div class=\"step-options\">\n        <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">YES \u2192</span><span class=\"opt-text\"><strong>Flink.</strong> Best-in-class: RocksDB state backend survives restarts, scales beyond RAM, checkpoints to S3. Running counts, windowed aggregations, per-user history.</span></div>\n        <div class=\"step-option opt-no\"><span class=\"opt-arrow\">NO \u2192</span><span class=\"opt-text\"><strong>Kafka Streams</strong> (library, no cluster) or <strong>Kinesis Data Analytics.</strong> Simple filter, transform, route without managing state.</span></div>\n      </div>\n    </div></div>\n    <div class=\"step-row\"><div class=\"step-num\">03</div><div class=\"step-content\">\n      <div class=\"step-q\">Transport: managed cloud or self-hosted?</div>\n      <div class=\"step-options\">\n        <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">AWS, zero ops \u2192</span><span class=\"opt-text\"><strong>Amazon Kinesis.</strong> Auto-scaling shards, Lambda triggers, Firehose to S3/Redshift. No brokers to manage.</span></div>\n        <div class=\"step-option opt-mid\"><span class=\"opt-arrow\">High throughput \u2192</span><span class=\"opt-text\"><strong>Apache Kafka.</strong> Millions/sec per cluster. 7-day replay. Multiple independent consumer groups. Cheaper at scale.</span></div>\n        <div class=\"step-option opt-no\"><span class=\"opt-arrow\">GCP / Azure \u2192</span><span class=\"opt-text\"><strong>Google Pub/Sub</strong> or <strong>Azure Event Hubs</strong> \u2014 cloud-native equivalents of Kinesis.</span></div>\n      </div>\n    </div></div>\n    <div class=\"step-row\"><div class=\"step-num\">04</div><div class=\"step-content\">\n      <div class=\"step-q\">Processing: team expertise?</div>\n      <div class=\"step-options\">\n        <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">Already use Spark \u2192</span><span class=\"opt-text\"><strong>Spark Structured Streaming.</strong> Same API, same cluster, unified batch + streaming codebase. No new technology to learn.</span></div>\n        <div class=\"step-option opt-mid\"><span class=\"opt-arrow\">Low-latency + state \u2192</span><span class=\"opt-text\"><strong>Apache Flink.</strong> Industry standard for stateful streaming at FAANG scale. Uber, Apple, Alibaba all use it.</span></div>\n        <div class=\"step-option opt-no\"><span class=\"opt-arrow\">Simple, per-service \u2192</span><span class=\"opt-text\"><strong>Kafka Streams.</strong> A library \u2014 runs inside your service process. No separate cluster. Perfect for microservices.</span></div>\n      </div>\n    </div></div>\n  </div>\n</div>\n\n  <div class=\"use-grid\">\n    <div class=\"use-card\">\n      <div class=\"use-card-head\" style=\"color:#444\">\u2b1b Use Kafka when\u2026</div>\n      <ul><li>High throughput (&gt;100K/sec per topic)</li><li>Long retention / replay needed</li><li>Multiple independent consumers</li><li>Not locked into AWS</li></ul>\n    </div>\n    <div class=\"use-card\">\n      <div class=\"use-card-head\" style=\"color:#c04400\">\ud83d\udd36 Use Flink when\u2026</div>\n      <ul><li>Sub-second latency needed</li><li>Complex stateful operations</li><li>Windowed aggregations</li><li>Exactly-once critical (fraud, billing)</li></ul>\n    </div>\n    <div class=\"use-card\">\n      <div class=\"use-card-head\" style=\"color:#cc7000\">\ud83d\udfe0 Use Kinesis when\u2026</div>\n      <ul><li>AWS-native, zero ops priority</li><li>Moderate throughput</li><li>Lambda integration needed</li><li>Firehose delivery to S3/Redshift</li></ul>\n    </div>\n    <div class=\"use-card\">\n      <div class=\"use-card-head\" style=\"color:#b04000\">\u2726 Use Spark Streaming when\u2026</div>\n      <ul><li>Already have Spark infrastructure</li><li>ETL/data warehouse loading</li><li>Unified batch + streaming code</li><li>Seconds latency is acceptable</li></ul>\n    </div>\n  </div>\n</section>\n\n<section id=\"followups\">\n  <div class=\"sec-tag\">07 \u00b7 Interview Follow-up Playbook</div>\n  <h2>Every Hard Follow-up, Answered</h2>\n\n  <div class=\"faq-item\">\n    <div class=\"faq-q\" onclick=\"toggle(this)\">Kafka guarantees at-most-once, at-least-once, or exactly-once?<span class=\"tog\">+</span></div>\n    <div class=\"faq-a\"><strong>All three \u2014 depending on how you configure it.</strong><br><br><strong>At-most-once:</strong> Consumer reads message, immediately commits offset, then processes. If processing crashes, the message is lost (offset already advanced).<br><br><strong>At-least-once:</strong> Consumer reads, processes, then commits offset. If processing crashes before commit, message is reprocessed on restart. May be processed twice.<br><br><strong>Exactly-once (EOS):</strong> Requires both idempotent producers (enable.idempotence=true) AND transactional producers + consumers. Kafka ensures each message is written exactly once even with retries. Combined with Flink's two-phase commit, this gives exactly-once end-to-end. Performance overhead: ~20% throughput reduction.</div>\n  </div>\n\n  <div class=\"faq-item\">\n    <div class=\"faq-q\" onclick=\"toggle(this)\">What happens to in-flight Flink state when a node crashes?<span class=\"tog\">+</span></div>\n    <div class=\"faq-a\"><strong>Flink recovers from its last checkpoint.</strong><br><br>Every 60 seconds (configurable), Flink performs a distributed snapshot: all operator states (Count-Min Sketch, local heap, Bloom filter) are saved to S3. The corresponding Kafka offset consumed up to that point is also saved.<br><br>On crash: Flink restarts from the last successful checkpoint. It resumes reading Kafka from the saved offset. Events between the checkpoint and the crash are replayed from Kafka (this is why Kafka retention matters). State is restored from S3.<br><br>If Flink uses exactly-once mode (two-phase commit), the output (writes to Redis/Cassandra) is also rolled back if the checkpoint was not completed. This prevents double-counting even across crashes.</div>\n  </div>\n\n  <div class=\"faq-item\">\n    <div class=\"faq-q\" onclick=\"toggle(this)\">How do you handle late-arriving events in Flink?<span class=\"tog\">+</span></div>\n    <div class=\"faq-a\"><strong>Watermarks and allowed lateness.</strong><br><br><strong>The problem:</strong> Events arrive out of order. An event with timestamp t=14:23:45 might arrive at t=14:24:10 (25 seconds late) due to network delays. If the 30-second window for 14:23 already closed and was flushed, what do you do?<br><br><strong>Watermarks:</strong> Flink maintains a \"watermark\" \u2014 its best guess of the current event time. A watermark of t=14:24:00 means \"all events with timestamp &lt; 14:24:00 have probably arrived.\" Windows only close when the watermark passes the window end time.<br><br><strong>Allowed lateness:</strong> Even after a window closes, Flink can wait for late events up to X seconds. Late events trigger a window update (re-emit corrected results). Events arriving after the allowed lateness are either dropped or sent to a side output for separate handling.<br><br>In Top-K, we use a 5-second watermark lag \u2014 accepting that our Top-K results may be 5 seconds stale in exchange for near-complete accuracy.</div>\n  </div>\n\n  <div class=\"faq-item\">\n    <div class=\"faq-q\" onclick=\"toggle(this)\">Why does Kafka partitioning by entity_id matter so much for Top-K?<span class=\"tog\">+</span></div>\n    <div class=\"faq-a\"><strong>It eliminates cross-worker coordination \u2014 the fundamental scalability trick.</strong><br><br>If all events for video_123 go to the same Kafka partition, they're consumed by the same Flink worker. That worker maintains the local count for video_123 in its own Count-Min Sketch, entirely in local memory. No network calls needed to coordinate with other workers.<br><br>If video_123's events were spread across multiple partitions, three things would go wrong: (1) Multiple Flink workers would each have a partial count for video_123. (2) To merge them, every worker would need to communicate with every other worker after each event. (3) At 500K events/sec, this coordination traffic would overwhelm the cluster.<br><br>Partitioning by entity_id makes the problem embarrassingly parallel \u2014 each worker handles a disjoint subset of entities, does all its computation locally, and the only cross-worker step is the final merge of top-K lists at flush time.</div>\n  </div>\n\n  <div class=\"faq-item\">\n    <div class=\"faq-q\" onclick=\"toggle(this)\">Can you replace Kafka with a database in the streaming pipeline?<span class=\"tog\">+</span></div>\n    <div class=\"faq-a\"><strong>Technically yes, practically no \u2014 and interviewers will probe this.</strong><br><br>You could write events to a PostgreSQL table and have Flink poll it. This is called \"Change Data Capture\" (CDC) and it works for low-throughput pipelines. But it fails at 500K events/sec because:<br><br>1. Each INSERT is a full row write with WAL logging \u2014 massive I/O overhead at scale.<br>2. Polling introduces latency: Flink polls every X seconds, creating inherent lag.<br>3. Ordering guarantees are weak: multiple writers can write with slightly different timestamps.<br>4. Backpressure handling: if Flink falls behind, the database table grows unbounded (no TTL like Kafka retention).<br>5. Multiple consumers: each consumer needs its own polling mechanism and state tracking.<br><br>Kafka is purpose-built for this. Its log-structured storage makes sequential writes extremely fast. Consumers maintain their own offset. Backpressure is handled naturally \u2014 consumers just read slower while Kafka buffers the data within retention limits.</div>\n  </div>\n</section>\n\n</div>\n<div class=\"footer\">STREAMING \u00b7 KAFKA \u00b7 FLINK \u00b7 KINESIS \u00b7 SPARK \u00b7 MANISH-ALMANAC</div>\n\u003cscript>function toggle(el){el.parentElement.classList.toggle('open');}<\/script>\n</body>\n</html>\n", tag: 'Streaming' },
  protocols:   { title: 'API Protocols Decoded',           srcdoc: "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>API Protocols: REST vs gRPC vs GraphQL vs WebSocket vs SSE vs Long Polling</title>\n<link href=\"https://fonts.googleapis.com/css2?family=Playfair+Display:wght@700;900&family=Source+Sans+3:wght@300;400;500;600&family=JetBrains+Mono:wght@400;600&display=swap\" rel=\"stylesheet\">\n<style>\n:root{\n  --ink:#0f0e0c;--page:#f7f5f0;--surface:#eeecea;--surface2:#e5e2dc;--border:#d4d0c8;--muted:#7a7568;\n  --rest:#1a4f8a;--rest-bg:#edf2fb;\n  --grpc:#1a7a4a;--grpc-bg:#edf8f2;\n  --gql:#a0208a;--gql-bg:#faedf8;\n  --ws:#b8720a;--ws-bg:#fdf6e8;\n  --sse:#1287b1;--sse-bg:#eaf6fb;\n  --lp:#6040a0;--lp-bg:#f2eefb;\n  --red:#c0392b;--red-bg:#fdf0ee;\n  --green:#1a7a4a;--green-bg:#edf8f2;\n  --amber:#b8720a;--amber-bg:#fdf6e8;\n  --blue:#1a4f8a;--blue-bg:#edf2fb;\n  --mono:'JetBrains Mono',monospace;--serif:'Playfair Display',serif;--sans:'Source Sans 3',sans-serif;\n}\n*{box-sizing:border-box;margin:0;padding:0;}html{scroll-behavior:smooth;}\nbody{background:var(--page);color:var(--ink);font-family:var(--sans);font-size:15px;line-height:1.75;}\n.hero{background:var(--ink);color:#e8e4dc;padding:72px 24px 56px;position:relative;overflow:hidden;}\n.hero::before{content:'';position:absolute;inset:0;background:repeating-linear-gradient(45deg,transparent,transparent 40px,rgba(255,255,255,.015) 40px,rgba(255,255,255,.015) 41px);}\n.hero-inner{max-width:960px;margin:0 auto;position:relative;}\n.hero-tag{font-family:var(--mono);font-size:10px;letter-spacing:4px;color:#6a6458;text-transform:uppercase;margin-bottom:20px;}\nh1{font-family:var(--serif);font-size:clamp(32px,5vw,58px);font-weight:900;line-height:1.05;letter-spacing:-.5px;margin-bottom:20px;color:#f0ece4;}\nh1 em{color:#e8b84b;font-style:normal;}\n.hero-sub{font-size:15px;color:#7a7060;max-width:640px;line-height:1.7;margin-bottom:32px;}\n.db-pills{display:flex;flex-wrap:wrap;gap:8px;}\n.db-pill{font-family:var(--mono);font-size:10px;padding:5px 14px;border-radius:3px;border:1px solid;letter-spacing:.5px;}\n.pill-rest{border-color:var(--rest);color:var(--rest);background:rgba(26,79,138,.08);}\n.pill-grpc{border-color:var(--grpc);color:var(--grpc);background:rgba(26,122,74,.08);}\n.pill-gql{border-color:var(--gql);color:var(--gql);background:rgba(160,32,138,.08);}\n.pill-ws{border-color:var(--ws);color:var(--ws);background:rgba(184,114,10,.08);}\n.pill-sse{border-color:var(--sse);color:var(--sse);background:rgba(18,135,177,.08);}\n.pill-lp{border-color:var(--lp);color:var(--lp);background:rgba(96,64,160,.08);}\n.nav{position:sticky;top:0;z-index:100;background:var(--ink);border-bottom:1px solid #1e1c18;display:flex;overflow-x:auto;scrollbar-width:none;padding:0 20px;}\n.nav::-webkit-scrollbar{display:none;}\n.nav a{font-family:var(--mono);font-size:10px;letter-spacing:1px;color:#4a4840;text-decoration:none;padding:14px 12px;white-space:nowrap;border-bottom:2px solid transparent;transition:.18s;}\n.nav a:hover{color:#e8b84b;border-color:#e8b84b;}\n.wrap{max-width:960px;margin:0 auto;padding:0 20px;}\nsection{padding:56px 0 36px;border-bottom:2px solid var(--border);}\nsection:last-child{border:none;}\n.sec-tag{font-family:var(--mono);font-size:9px;letter-spacing:4px;text-transform:uppercase;color:var(--muted);margin-bottom:8px;display:flex;align-items:center;gap:10px;}\n.sec-tag::before{content:'';width:20px;height:1px;background:var(--border);}\nh2{font-family:var(--serif);font-size:clamp(22px,3.5vw,32px);font-weight:700;line-height:1.15;margin-bottom:18px;}\nh3{font-family:var(--sans);font-size:17px;font-weight:600;margin:32px 0 10px;border-bottom:1px solid var(--border);padding-bottom:6px;}\nh4{font-size:13px;font-weight:600;margin:16px 0 6px;text-transform:uppercase;letter-spacing:.5px;}\np{color:#3a3830;font-size:14.5px;margin-bottom:12px;max-width:820px;}\nstrong{color:var(--ink);}\ncode{font-family:var(--mono);font-size:11.5px;background:var(--surface2);padding:1px 5px;border-radius:3px;color:var(--blue);}\n/* Protocol identity cards */\n.db-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:14px;margin:24px 0;}\n.db-card{background:white;border:1px solid var(--border);border-radius:8px;padding:20px;position:relative;overflow:hidden;}\n.db-card::before{content:'';position:absolute;top:0;left:0;right:0;height:4px;}\n.db-card.rest::before{background:var(--rest);}\n.db-card.grpc::before{background:var(--grpc);}\n.db-card.gql::before{background:var(--gql);}\n.db-card.ws::before{background:var(--ws);}\n.db-card.sse::before{background:var(--sse);}\n.db-card.lp::before{background:var(--lp);}\n.db-logo{font-size:22px;margin-bottom:6px;}\n.db-name{font-family:var(--serif);font-size:17px;font-weight:700;margin-bottom:4px;}\n.db-type{font-family:var(--mono);font-size:9px;letter-spacing:2px;color:var(--muted);margin-bottom:10px;text-transform:uppercase;}\n.db-tagline{font-size:13px;color:#5a5848;line-height:1.55;}\n.db-born{font-family:var(--mono);font-size:9px;color:var(--muted);margin-top:8px;}\n/* Analogy block */\n.analogy{background:var(--ink);color:#c8c4b8;border-radius:8px;padding:24px 28px;margin:24px 0;}\n.analogy-label{font-family:var(--mono);font-size:9px;letter-spacing:3px;color:#6a6458;margin-bottom:10px;text-transform:uppercase;}\n.analogy-text{font-size:15px;line-height:1.75;color:#d8d4c8;}\n.analogy-text strong{color:#e8b84b;}\n/* Callouts */\n.callout{border-radius:4px;padding:14px 18px;margin:18px 0;font-size:13.5px;border-left:3px solid;line-height:1.65;}\n.callout p{font-size:13.5px;margin-bottom:6px;}.callout p:last-child{margin:0;}\n.cl-blue{background:var(--blue-bg);border-color:var(--blue);color:#1a2a4a;}\n.cl-green{background:var(--green-bg);border-color:var(--green);color:#0a2a1a;}\n.cl-amber{background:var(--amber-bg);border-color:var(--amber);color:#3a2a08;}\n.cl-red{background:var(--red-bg);border-color:var(--red);color:#3a0a08;}\n.cl-lbl{font-family:var(--mono);font-size:9px;letter-spacing:3px;text-transform:uppercase;margin-bottom:6px;opacity:.7;}\n/* Comparison table */\n.comp-table{width:100%;border-collapse:collapse;margin:20px 0;font-size:13px;}\n.comp-table th{padding:10px 14px;border:1px solid var(--border);background:var(--surface2);font-family:var(--mono);font-size:9px;letter-spacing:1.5px;text-transform:uppercase;color:var(--muted);}\n.comp-table td{padding:11px 14px;border:1px solid var(--border);vertical-align:top;color:#3a3830;line-height:1.6;}\n.comp-table .row-head{font-family:var(--mono);font-size:11px;font-weight:600;background:var(--surface);color:var(--ink);white-space:nowrap;}\n.good{color:var(--green);font-weight:600;}.warn{color:var(--amber);font-weight:600;}.bad{color:var(--red);font-weight:600;}\n/* System design examples */\n.sd-example{background:white;border:1px solid var(--border);border-radius:8px;margin:20px 0;overflow:hidden;}\n.sd-example-head{background:var(--ink);padding:14px 20px;display:flex;align-items:center;gap:12px;}\n.sd-example-title{font-family:var(--serif);font-size:16px;color:#f0ece4;font-weight:700;}\n.sd-example-tag{font-family:var(--mono);font-size:9px;letter-spacing:2px;color:#6a6458;border:1px solid #2e2c28;padding:3px 8px;border-radius:2px;}\n.sd-example-body{padding:20px;}\n.choice-row{display:flex;gap:10px;align-items:flex-start;padding:10px 0;border-bottom:1px solid var(--border);font-size:13px;}\n.choice-row:last-child{border:none;}\n.choice-label{font-family:var(--mono);font-size:10px;letter-spacing:1px;color:var(--muted);width:130px;flex-shrink:0;padding-top:2px;}\n.choice-val{flex:1;color:#3a3830;line-height:1.6;}\n/* Badges */\n.badge{display:inline-block;font-family:var(--mono);font-size:9px;padding:2px 7px;border-radius:2px;border:1px solid;margin-right:4px;font-weight:500;}\n.b-rest{background:var(--rest-bg);border-color:var(--rest);color:var(--rest);}\n.b-grpc{background:var(--grpc-bg);border-color:var(--grpc);color:var(--grpc);}\n.b-gql{background:var(--gql-bg);border-color:var(--gql);color:var(--gql);}\n.b-ws{background:var(--ws-bg);border-color:var(--ws);color:var(--ws);}\n.b-sse{background:var(--sse-bg);border-color:var(--sse);color:var(--sse);}\n.b-lp{background:var(--lp-bg);border-color:var(--lp);color:var(--lp);}\n.b-g{background:var(--green-bg);border-color:var(--green);color:var(--green);}\n.b-r{background:var(--red-bg);border-color:var(--red);color:var(--red);}\n.b-a{background:var(--amber-bg);border-color:var(--amber);color:var(--amber);}\n/* FAQ */\n.faq-item{border:1px solid var(--border);border-radius:4px;margin-bottom:8px;overflow:hidden;}\n.faq-q{padding:14px 18px;display:flex;justify-content:space-between;align-items:center;cursor:pointer;background:white;font-size:14px;font-weight:500;color:var(--ink);user-select:none;}\n.faq-q:hover{background:var(--surface);}\n.faq-q .tog{font-size:18px;color:#e8b84b;flex-shrink:0;margin-left:12px;transition:transform .2s;font-family:var(--mono);}\n.faq-a{display:none;padding:18px;background:var(--surface);font-size:13.5px;color:#3a3830;line-height:1.75;border-top:1px solid var(--border);}\n.faq-item.open .faq-a{display:block;}.faq-item.open .tog{transform:rotate(45deg);}\n.faq-a ul{padding-left:18px;margin:8px 0;}.faq-a li{margin-bottom:6px;}\n/* Concept grid */\n.concept-grid{display:grid;grid-template-columns:1fr;gap:0;margin:20px 0;border:1px solid var(--border);border-radius:8px;overflow:hidden;}\n.concept-row{display:flex;gap:0;border-bottom:1px solid var(--border);}\n.concept-row:last-child{border-bottom:none;}\n.concept-term{background:var(--ink);color:#e8b84b;font-family:var(--mono);font-size:11.5px;font-weight:600;min-width:155px;padding:14px 16px;flex-shrink:0;border-right:1px solid #2a2820;display:flex;align-items:flex-start;line-height:1.5;}\n.concept-def{padding:13px 16px;flex:1;font-size:13.5px;color:#3a3830;line-height:1.7;background:#fff;}\n.concept-def strong{color:var(--ink);}\n.concept-def code{background:var(--surface);padding:1px 5px;border-radius:3px;font-family:var(--mono);font-size:11px;color:var(--blue);}\n/* Step block */\n.step-block{background:#fff;border:1px solid var(--border);border-radius:8px;margin:20px 0;overflow:hidden;}\n.step-block-header{background:var(--ink);color:#e8e4dc;padding:13px 18px;font-family:var(--mono);font-size:10px;letter-spacing:2px;text-transform:uppercase;display:flex;align-items:center;gap:10px;}\n.sb-icon{font-size:16px;}\n.step-block-body{padding:0;}\n.step-row{display:flex;gap:0;border-bottom:1px solid var(--border);}\n.step-row:last-child{border-bottom:none;}\n.step-num{background:var(--surface);min-width:46px;display:flex;align-items:flex-start;justify-content:center;padding:16px 6px;font-family:var(--mono);font-size:11px;font-weight:700;color:var(--muted);flex-shrink:0;border-right:1px solid var(--border);}\n.step-content{padding:14px 18px;flex:1;}\n.step-q{font-weight:600;font-size:14px;color:var(--ink);margin-bottom:10px;}\n.step-options{display:flex;flex-direction:column;gap:6px;}\n.step-option{display:flex;gap:10px;align-items:flex-start;padding:9px 13px;border-radius:5px;font-size:13px;line-height:1.65;}\n.opt-yes{background:#edf8f2;border:1px solid #b8ddc8;}\n.opt-no{background:#fdf6e8;border:1px solid #e8c870;}\n.opt-mid{background:#edf2fb;border:1px solid #b8c8e8;}\n.opt-any{background:#f4f0fb;border:1px solid #c8b8e8;}\n.opt-arrow{font-family:var(--mono);font-size:12px;font-weight:700;flex-shrink:0;margin-top:1px;min-width:130px;}\n.opt-yes .opt-arrow{color:#1a7a4a;}\n.opt-no .opt-arrow{color:#b8720a;}\n.opt-mid .opt-arrow{color:#1a4f8a;}\n.opt-any .opt-arrow{color:#5a3c9a;}\n.opt-text{flex:1;color:#3a3830;}\n/* Use-card grid */\n.use-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:14px;margin:20px 0;}\n.use-card{border:1px solid var(--border);border-radius:6px;padding:18px;background:white;}\n.use-card-head{font-family:var(--mono);font-size:11px;font-weight:600;margin-bottom:10px;display:flex;align-items:center;gap:8px;}\n.use-card ul{padding-left:16px;font-size:13px;color:#4a4838;line-height:1.7;}\n.use-card ul li{margin-bottom:4px;}\n/* Combo pattern cards */\n.combo-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:16px;margin:20px 0;}\n.combo-card{background:white;border:1px solid var(--border);border-radius:8px;padding:20px;position:relative;}\n.combo-card::before{content:'';position:absolute;top:0;left:0;right:0;height:3px;border-radius:8px 8px 0 0;}\n.combo-card.c1::before{background:linear-gradient(90deg,var(--rest),var(--ws));}\n.combo-card.c2::before{background:linear-gradient(90deg,var(--rest),var(--sse));}\n.combo-card.c3::before{background:linear-gradient(90deg,var(--grpc),var(--grpc));}\n.combo-card.c4::before{background:linear-gradient(90deg,var(--gql),var(--ws));}\n.combo-card.c5::before{background:linear-gradient(90deg,var(--rest),var(--lp));}\n.combo-card.c6::before{background:linear-gradient(90deg,var(--rest),var(--grpc));}\n.combo-title{font-family:var(--serif);font-size:15px;font-weight:700;margin-bottom:6px;color:var(--ink);}\n.combo-formula{font-family:var(--mono);font-size:11px;color:var(--muted);margin-bottom:12px;letter-spacing:.5px;}\n.combo-body{font-size:13px;color:#5a5848;line-height:1.65;margin-bottom:10px;}\n.combo-used{font-family:var(--mono);font-size:10px;color:var(--muted);}\n/* Footer */\n.footer{background:var(--ink);text-align:center;padding:36px 20px;font-family:var(--mono);font-size:10px;color:#3a3830;letter-spacing:2px;}\n/* Responsive */\n@media(max-width:560px){\n  .concept-row{flex-direction:column;}.concept-term{min-width:auto;border-right:none;border-bottom:1px solid #2a2820;}\n  .opt-arrow{min-width:80px;}.choice-label{width:80px;}\n}\n</style>\n</head>\n<body>\n\n<div class=\"hero\">\n  <div class=\"hero-inner\">\n    <div class=\"hero-tag\">System Design \u00b7 API Design \u00b7 Manish-Almanac</div>\n    <h1>API Protocols<br><em>Decoded</em></h1>\n    <p class=\"hero-sub\">REST vs gRPC vs GraphQL vs WebSocket vs SSE vs Long Polling \u2014 every dimension that matters in a FAANG interview, explained from first principles. Includes when they complement each other, real system design examples, and every follow-up answered.</p>\n    <div class=\"db-pills\">\n      <span class=\"db-pill pill-rest\">REST</span>\n      <span class=\"db-pill pill-grpc\">gRPC</span>\n      <span class=\"db-pill pill-gql\">GraphQL</span>\n      <span class=\"db-pill pill-ws\">WebSocket</span>\n      <span class=\"db-pill pill-sse\">SSE</span>\n      <span class=\"db-pill pill-lp\">Long Polling</span>\n    </div>\n  </div>\n</div>\n\n<nav class=\"nav\">\n  <a href=\"#mental-model\">Mental Model</a>\n  <a href=\"#request-response\">Request-Response</a>\n  <a href=\"#realtime\">Real-Time</a>\n  <a href=\"#comparison\">Full Comparison</a>\n  <a href=\"#combos\">Combos</a>\n  <a href=\"#examples\">System Design</a>\n  <a href=\"#decision\">Decision Tree</a>\n  <a href=\"#followups\">Follow-ups</a>\n</nav>\n\n<div class=\"wrap\">\n\n<!-- \u2550\u2550 00 MENTAL MODEL \u2550\u2550 -->\n<section id=\"mental-model\">\n  <div class=\"sec-tag\">00 \u00b7 Start Here</div>\n  <h2>The mental model before memorising anything</h2>\n\n  <p>Most candidates treat REST, WebSocket, gRPC, and GraphQL as competing options. They're not \u2014 they solve <strong>different communication problems</strong>. Before picking any protocol, answer one question:</p>\n\n  <div class=\"callout cl-amber\">\n    <div class=\"cl-lbl\">The single question that matters</div>\n    <p><strong>Who initiates communication, and how often does data change?</strong></p>\n    <p>Client asks once, server replies once \u2192 <strong>Request-Response</strong> (REST, gRPC, GraphQL)</p>\n    <p>Server needs to push data to client without the client asking \u2192 <strong>Server Push</strong> (SSE, WebSocket, Long Polling)</p>\n    <p>Client and server need to talk simultaneously, continuously \u2192 <strong>Bidirectional</strong> (WebSocket, gRPC streaming)</p>\n  </div>\n\n  <div class=\"analogy\">\n    <div class=\"analogy-label\">The restaurant analogy \u2014 for a complete layman</div>\n    <div class=\"analogy-text\">\n      <strong>REST</strong> is a waiter who takes your order, goes to the kitchen, and comes back with exactly what you asked for. Simple, stateless, everyone knows the rules.<br><br>\n      <strong>gRPC</strong> is a waiter using a walkie-talkie with the kitchen using a shared codebook. Faster, more efficient, but both sides need the same codebook (Protobuf schema).<br><br>\n      <strong>GraphQL</strong> is a waiter who lets you design your own plate. \"I want 3 items from dish A and 2 from dish B, in one trip.\" You get exactly what you asked for \u2014 nothing more, nothing less.<br><br>\n      <strong>WebSocket</strong> is a phone call \u2014 once connected, both sides can speak at any moment without hanging up and redialling.<br><br>\n      <strong>SSE</strong> is a radio broadcast \u2014 the server talks continuously to all listeners, but listeners can't transmit back on the same channel.<br><br>\n      <strong>Long Polling</strong> is repeatedly calling the kitchen and asking \"is my order ready yet?\" \u2014 the kitchen keeps you on hold until it is, then hangs up. You immediately call back.\n    </div>\n  </div>\n\n  <h3>The Two Families</h3>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">Request-Response</div>\n      <div class=\"concept-def\"><strong>Client sends a request, server replies, connection closes.</strong> Each interaction is independent. The server has no memory of previous requests unless you send a session token.<br><span style=\"color:#5a5848;font-size:12.5px;\">Members: REST, gRPC (unary), GraphQL Query/Mutation. HTTP/1.1, HTTP/2, HTTP/3 are the transports.</span></div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">Persistent / Push</div>\n      <div class=\"concept-def\"><strong>Connection stays open. Server can push data without the client asking.</strong> Crucial for real-time features: live feeds, notifications, chat, collaborative editing.<br><span style=\"color:#5a5848;font-size:12.5px;\">Members: WebSocket (bidirectional), SSE (server\u2192client only), Long Polling (simulated push), gRPC streaming.</span></div>\n    </div>\n  </div>\n</section>\n\n<!-- \u2550\u2550 01 REQUEST-RESPONSE PROTOCOLS \u2550\u2550 -->\n<section id=\"request-response\">\n  <div class=\"sec-tag\">01 \u00b7 Request-Response Family</div>\n  <h2>REST, gRPC, and GraphQL \u2014 the three ways to ask</h2>\n\n  <div class=\"db-grid\">\n    <div class=\"db-card rest\">\n      <div class=\"db-logo\">\ud83c\udf10</div>\n      <div class=\"db-name\">REST</div>\n      <div class=\"db-type\">HTTP \u00b7 Stateless \u00b7 Resource-Oriented</div>\n      <div class=\"db-tagline\">The universal default. Every HTTP client speaks it. Resources are nouns (URLs), actions are verbs (GET/POST/PUT/DELETE). No special tooling needed. The right choice until it isn't.</div>\n      <div class=\"db-born\">Born 2000 \u00b7 Roy Fielding's PhD thesis \u00b7 HTTP/1.1 + HTTP/2</div>\n    </div>\n    <div class=\"db-card grpc\">\n      <div class=\"db-logo\">\u26a1</div>\n      <div class=\"db-name\">gRPC</div>\n      <div class=\"db-type\">HTTP/2 \u00b7 Binary \u00b7 Contract-First</div>\n      <div class=\"db-tagline\">Google's internal RPC framework. Define your API in a .proto file \u2014 both sides generate code from it. Binary encoding (Protobuf) makes it 5\u201310x smaller and faster than JSON REST. Built for internal service-to-service calls.</div>\n      <div class=\"db-born\">Born 2015 \u00b7 Google \u00b7 HTTP/2 + Protobuf</div>\n    </div>\n    <div class=\"db-card gql\">\n      <div class=\"db-logo\">\u25c8</div>\n      <div class=\"db-name\">GraphQL</div>\n      <div class=\"db-type\">HTTP \u00b7 Query Language \u00b7 Client-Driven</div>\n      <div class=\"db-tagline\">Facebook's answer to REST's over-fetching problem. The client describes exactly what data it needs in a typed query. One endpoint, infinite flexibility. Ideal when different clients (mobile/web/partner) need different shapes of the same data.</div>\n      <div class=\"db-born\">Born 2015 \u00b7 Facebook \u00b7 HTTP/1.1 + HTTP/2</div>\n    </div>\n  </div>\n\n  <h3>REST \u2014 How It Actually Works</h3>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">Resources & Verbs</div>\n      <div class=\"concept-def\"><strong>REST maps actions to HTTP methods and nouns to URLs.</strong><br>\n        <code>GET /users/123</code> \u2192 fetch user<br>\n        <code>POST /users</code> \u2192 create user<br>\n        <code>PUT /users/123</code> \u2192 replace user<br>\n        <code>PATCH /users/123</code> \u2192 partial update<br>\n        <code>DELETE /users/123</code> \u2192 delete user<br>\n        <span style=\"color:#5a5848;font-size:12.5px;\">The URL is the resource (noun). The HTTP method is the action (verb). This separation is REST's core design principle.</span>\n      </div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">Stateless</div>\n      <div class=\"concept-def\"><strong>Every request must contain everything the server needs to process it.</strong> The server stores no session between requests. Identity always comes from a token in the header \u2014 never assumed from context.<br><span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Statelessness makes REST trivially horizontally scalable \u2014 any server can handle any request. No sticky sessions needed.</span></div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">HTTP Caching</div>\n      <div class=\"concept-def\"><strong>GET requests are cacheable by default</strong> \u2014 CDNs, browsers, and proxies can cache them. This is one of REST's biggest advantages over gRPC and GraphQL.<br><code>Cache-Control: max-age=3600</code> tells every layer to cache for 1 hour.<br><span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 A public REST API with GET responses cached at Cloudflare reduces origin traffic by 95%+. gRPC and GraphQL cannot use HTTP caching natively.</span></div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">Status Codes</div>\n      <div class=\"concept-def\"><strong>HTTP status codes carry semantic meaning every client understands natively:</strong><br>\n        <code>200</code> OK \u00b7 <code>201</code> Created \u00b7 <code>204</code> No Content<br>\n        <code>400</code> Bad Request \u00b7 <code>401</code> Unauthorised \u00b7 <code>403</code> Forbidden \u00b7 <code>404</code> Not Found<br>\n        <code>429</code> Rate Limited \u00b7 <code>500</code> Server Error \u00b7 <code>503</code> Unavailable<br>\n        <span style=\"color:#5a5848;font-size:12.5px;\">Every HTTP client, load balancer, and monitoring tool understands these codes. GraphQL always returns 200 \u2014 errors are in the response body, invisible to infrastructure.</span>\n      </div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">Over-Fetching</div>\n      <div class=\"concept-def\"><strong>REST's biggest weakness: you get what the endpoint returns, not what you need.</strong><br><code>GET /users/123</code> returns all 40 fields. Your mobile app only needed name and avatar.<br><span style=\"color:#b83030;font-size:12.5px;\">\u26a0\ufe0f On mobile with limited bandwidth, over-fetching wastes data and slows rendering. This is exactly why Facebook invented GraphQL.</span></div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">Under-Fetching</div>\n      <div class=\"concept-def\"><strong>REST's second weakness: one endpoint rarely returns all the data you need.</strong><br>To show a user's profile with their posts and followers: <code>GET /users/123</code> + <code>GET /users/123/posts</code> + <code>GET /users/123/followers</code> \u2014 3 round trips.<br><span style=\"color:#b83030;font-size:12.5px;\">\u26a0\ufe0f On mobile, each extra round trip adds 50\u2013200ms. Waterfall requests add up fast. GraphQL solves this with a single query.</span></div>\n    </div>\n  </div>\n\n  <h3>gRPC \u2014 How It Actually Works</h3>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">Protocol Buffers</div>\n      <div class=\"concept-def\"><strong>gRPC uses Protobuf \u2014 a binary serialisation format \u2014 instead of JSON.</strong> You define your data schema in a <code>.proto</code> file. Both client and server generate code from it automatically.<br><span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Binary is 5\u201310x smaller than equivalent JSON. Parsing binary is 5\u201310x faster than parsing JSON text. At 1M requests/sec, this matters enormously.</span></div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">HTTP/2 Multiplexing</div>\n      <div class=\"concept-def\"><strong>gRPC runs on HTTP/2, which multiplexes multiple requests over a single TCP connection.</strong> With HTTP/1.1 REST, each request needs its own connection (or connection pooling). HTTP/2 sends hundreds of requests simultaneously over one connection.<br><span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Huge advantage for service-to-service calls where you're making thousands of RPCs per second between the same two services.</span></div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">Streaming Modes</div>\n      <div class=\"concept-def\"><strong>gRPC supports 4 modes \u2014 REST only supports request-response:</strong><br>\n        <strong>Unary</strong> \u2014 one request, one response (like REST)<br>\n        <strong>Server streaming</strong> \u2014 one request, stream of responses (like SSE)<br>\n        <strong>Client streaming</strong> \u2014 stream of requests, one response (uploading chunks)<br>\n        <strong>Bidirectional streaming</strong> \u2014 both sides stream simultaneously (like WebSocket)<br>\n        <span style=\"color:#5a5848;font-size:12.5px;\">Real example: Google Maps sends your location as a client stream, receives route updates as a server stream \u2014 all over one gRPC bidirectional connection.</span>\n      </div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">Schema Contract</div>\n      <div class=\"concept-def\"><strong>The .proto file is a strict API contract between client and server.</strong> Both sides must use the same schema. Adding a field is backwards-compatible; removing one breaks older clients.<br><span style=\"color:#b83030;font-size:12.5px;\">\u26a0\ufe0f gRPC requires code generation on every schema change. REST and GraphQL don't. This is operational overhead \u2014 significant for teams with many services.</span></div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">Browser Support</div>\n      <div class=\"concept-def\"><strong>Browsers cannot call gRPC directly.</strong> HTTP/2 trailers (which gRPC uses) are not exposed by browser APIs. You need gRPC-Web (a proxy layer) or gRPC-Gateway (which translates to REST).<br><span style=\"color:#b83030;font-size:12.5px;\">\u26a0\ufe0f This is why gRPC is almost exclusively used for internal service-to-service communication, not for public-facing APIs.</span></div>\n    </div>\n  </div>\n\n  <h3>GraphQL \u2014 How It Actually Works</h3>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">Single Endpoint</div>\n      <div class=\"concept-def\"><strong>GraphQL has one endpoint: <code>POST /graphql</code>.</strong> The query in the request body describes exactly what data to return. No URL routing, no versioning headaches \u2014 the schema evolves by adding fields (never removing).<br><span style=\"color:#5a5848;font-size:12.5px;\">This is how Facebook, GitHub, Shopify, and Twitter serve data to their apps \u2014 one endpoint, infinite flexibility.</span></div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">Query vs Mutation</div>\n      <div class=\"concept-def\"><strong>Query</strong> = read (like GET). <strong>Mutation</strong> = write (like POST/PUT/DELETE). <strong>Subscription</strong> = real-time push (like WebSocket).<br>\n        <code>query { user(id:\"123\") { name, avatar, followerCount } }</code><br>\n        <code>mutation { createPost(input:{...}) { id, createdAt } }</code><br>\n        <span style=\"color:#5a5848;font-size:12.5px;\">Subscriptions use WebSocket under the hood \u2014 GraphQL is a query language on top of a transport, not a transport itself.</span>\n      </div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">N+1 Problem</div>\n      <div class=\"concept-def\"><strong>GraphQL's biggest pitfall: a single query can trigger hundreds of database calls.</strong><br>Query for 100 posts, each needing its author \u2192 1 query for posts + 100 queries for authors = 101 DB calls.<br><span style=\"color:#b83030;font-size:12.5px;\">\u26a0\ufe0f Fix: DataLoader (batches and deduplicates database calls). Every GraphQL implementation needs it or performance degrades to unusable.</span></div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">Introspection</div>\n      <div class=\"concept-def\"><strong>GraphQL APIs are self-documenting.</strong> Clients can query the schema itself to discover all available types, fields, and operations \u2014 no separate Swagger/OpenAPI needed.<br><span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Tools like GraphiQL and Apollo Studio give developers interactive playgrounds. New team members explore the API without reading docs.</span><br><span style=\"color:#b83030;font-size:12.5px;\">\u26a0\ufe0f Disable introspection in production \u2014 it exposes your entire data model to attackers.</span></div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">Caching Problem</div>\n      <div class=\"concept-def\"><strong>GraphQL uses POST for queries \u2014 HTTP caching doesn't work natively.</strong> CDNs only cache GET requests. Every GraphQL query hits your origin.<br><span style=\"color:#5a5848;font-size:12.5px;\">Workarounds: Persisted Queries (assign each query a hash, send hash as GET), Apollo CDN caching, or Cloudflare Workers. More complexity than REST's built-in GET caching.</span></div>\n    </div>\n  </div>\n</section>\n\n<!-- \u2550\u2550 02 REAL-TIME PROTOCOLS \u2550\u2550 -->\n<section id=\"realtime\">\n  <div class=\"sec-tag\">02 \u00b7 Real-Time Family</div>\n  <h2>WebSocket, SSE, and Long Polling \u2014 the three ways to push</h2>\n\n  <div class=\"callout cl-blue\">\n    <div class=\"cl-lbl\">Why REST can't do real-time</div>\n    <p>REST is pull-only: <strong>the client must ask</strong> before the server can respond. For a chat app, polling every second means thousands of empty responses. For a live dashboard, you'd poll 60 times/minute per user. At 100K users, that's 6M requests/minute for mostly empty data.</p>\n    <p><strong>Real-time protocols invert this: the server pushes data the moment it's available.</strong> No polling, no wasted requests, no latency from the polling interval.</p>\n  </div>\n\n  <div class=\"db-grid\">\n    <div class=\"db-card ws\">\n      <div class=\"db-logo\">\ud83d\udd0c</div>\n      <div class=\"db-name\">WebSocket</div>\n      <div class=\"db-type\">Full-Duplex \u00b7 Persistent \u00b7 TCP</div>\n      <div class=\"db-tagline\">A persistent bidirectional connection over a single TCP socket. Once the HTTP handshake upgrades to WS, both client and server can send messages at any time, simultaneously. The gold standard for true real-time: chat, multiplayer games, collaborative editing.</div>\n      <div class=\"db-born\">Born 2011 \u00b7 RFC 6455 \u00b7 HTTP Upgrade handshake</div>\n    </div>\n    <div class=\"db-card sse\">\n      <div class=\"db-logo\">\ud83d\udce1</div>\n      <div class=\"db-name\">Server-Sent Events</div>\n      <div class=\"db-type\">Server\u2192Client Only \u00b7 HTTP \u00b7 Auto-Reconnect</div>\n      <div class=\"db-tagline\">A simple HTTP connection that stays open. The server pushes text events whenever it wants. The client cannot send data back on this connection. Simpler than WebSocket, works with HTTP/2 multiplexing, and auto-reconnects on disconnect.</div>\n      <div class=\"db-born\">Born 2006 \u00b7 W3C Standard \u00b7 HTTP/1.1 + HTTP/2</div>\n    </div>\n    <div class=\"db-card lp\">\n      <div class=\"db-logo\">\ud83d\udd04</div>\n      <div class=\"db-name\">Long Polling</div>\n      <div class=\"db-type\">Simulated Push \u00b7 HTTP \u00b7 Request-Response</div>\n      <div class=\"db-tagline\">Client sends a request. Server holds it open until data is available or a timeout occurs. Client immediately sends a new request. Simulates real-time over plain HTTP \u2014 no special protocol needed. The legacy fallback when WebSocket isn't available.</div>\n      <div class=\"db-born\">Born ~2000s \u00b7 No official standard \u00b7 Plain HTTP</div>\n    </div>\n  </div>\n\n  <h3>WebSocket \u2014 How It Actually Works</h3>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">The Upgrade Handshake</div>\n      <div class=\"concept-def\"><strong>WebSocket starts as an HTTP request, then upgrades to a persistent TCP connection.</strong><br>\n        Client sends: <code>GET /ws HTTP/1.1, Upgrade: websocket</code><br>\n        Server responds: <code>101 Switching Protocols</code><br>\n        Now: raw TCP frames flow in both directions \u2014 no HTTP overhead per message.<br>\n        <span style=\"color:#5a5848;font-size:12.5px;\">Why HTTP start? Firewalls and proxies block arbitrary TCP but allow HTTP port 80/443. The upgrade trick bypasses firewall restrictions.</span>\n      </div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">Full-Duplex</div>\n      <div class=\"concept-def\"><strong>Both client and server can send messages at any moment, simultaneously, over the same connection.</strong> No waiting for the other side. No request-response cycle.<br><span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 This is why WebSocket is used for chat (user sends and receives simultaneously), multiplayer games (constant position updates both directions), and collaborative editing (every keystroke sent immediately).</span></div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">Framing</div>\n      <div class=\"concept-def\"><strong>WebSocket sends data as frames, not HTTP requests.</strong> Each frame has a tiny 2\u201310 byte header (opcode, mask, length) vs HTTP's 200\u2013800 byte headers per request.<br><span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 A chat message sent via WebSocket costs ~10 bytes overhead. Via HTTP polling: 300\u2013800 bytes of headers per poll even when empty. At 1M active users, this difference is measured in gigabits per second.</span></div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">State & Scaling</div>\n      <div class=\"concept-def\"><strong>WebSocket connections are stateful and sticky \u2014 the connection lives on a specific server.</strong> If that server dies, all its connections drop. Clients must reconnect.<br><span style=\"color:#b83030;font-size:12.5px;\">\u26a0\ufe0f You cannot load-balance WebSocket with standard round-robin. You need sticky sessions (by user_id) or a pub/sub broker (Redis, Kafka) so any server can push to any user regardless of which server they're connected to.</span></div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">Heartbeats</div>\n      <div class=\"concept-def\"><strong>Idle WebSocket connections get killed by proxies and NAT gateways after 30\u201390 seconds.</strong> Solution: ping/pong heartbeat every 20\u201330 seconds. Server sends a ping frame, client echoes a pong. No pong = connection dead, clean up and notify.<br><span style=\"color:#5a5848;font-size:12.5px;\">Every production WebSocket implementation needs heartbeat logic. Without it, you get ghost connections \u2014 the server thinks the client is connected but the client is gone.</span></div>\n    </div>\n  </div>\n\n  <h3>SSE \u2014 How It Actually Works</h3>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">The Wire Format</div>\n      <div class=\"concept-def\"><strong>SSE is a plain HTTP response that never ends.</strong> Content-Type is <code>text/event-stream</code>. The server sends newline-delimited text events:<br>\n        <code>data: {\"type\":\"view\",\"count\":1247}\\n\\n</code><br>\n        <code>data: {\"type\":\"view\",\"count\":1248}\\n\\n</code><br>\n        <span style=\"color:#5a5848;font-size:12.5px;\">Two consecutive newlines signal the end of one event. The browser's EventSource API parses this automatically and fires events at your JavaScript handler.</span>\n      </div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">Auto-Reconnect</div>\n      <div class=\"concept-def\"><strong>The browser's EventSource automatically reconnects after a disconnect.</strong> The server sends an event ID with each event. On reconnect, the browser sends <code>Last-Event-ID</code> header \u2014 the server can replay missed events.<br><span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 This makes SSE dramatically simpler to operate than WebSocket. No custom reconnect logic needed on the client. Works out of the box.</span></div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">HTTP/2 Multiplexing</div>\n      <div class=\"concept-def\"><strong>Over HTTP/2, multiple SSE streams share one TCP connection.</strong> With HTTP/1.1, browsers limit connections per domain (typically 6). If you have 6 SSE streams, you've used all connections. HTTP/2 multiplexes hundreds over one connection.<br><span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Use HTTP/2 for SSE at scale. HTTP/1.1 SSE has a hard limit of ~6 concurrent streams per browser per domain.</span></div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">One Direction Only</div>\n      <div class=\"concept-def\"><strong>SSE is server-to-client only.</strong> The client cannot send data back on the same connection. For any client action (user sends a message, acknowledges a notification), you make a separate REST/HTTP POST call.<br><span style=\"color:#5a5848;font-size:12.5px;\">This is the key difference from WebSocket. In most notification/feed systems this is fine \u2014 client-to-server actions are already REST calls.</span></div>\n    </div>\n  </div>\n\n  <h3>Long Polling \u2014 How It Actually Works</h3>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">The Mechanism</div>\n      <div class=\"concept-def\"><strong>Step by step:</strong><br>\n        1. Client sends <code>GET /messages?since=1234</code><br>\n        2. Server checks if new messages exist. If yes \u2192 respond immediately. If no \u2192 <strong>hold the connection open</strong><br>\n        3. When a message arrives, server responds with it<br>\n        4. Client receives response, <strong>immediately sends a new request</strong><br>\n        5. Repeat forever<br>\n        <span style=\"color:#5a5848;font-size:12.5px;\">Timeout: if no data after 30 seconds, server responds with 204 No Content. Client retries. This prevents proxy timeouts.</span>\n      </div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">vs Regular Polling</div>\n      <div class=\"concept-def\"><strong>Regular polling</strong>: client asks every N seconds regardless. Empty responses waste bandwidth and add N seconds of latency.<br><strong>Long polling</strong>: client asks once, server responds only when there's data. Near-zero latency, zero empty responses.<br><span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Long polling is near-real-time with standard HTTP. No WebSocket, no special protocol. Works everywhere HTTP works.</span></div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">Scalability Challenge</div>\n      <div class=\"concept-def\"><strong>Long polling holds server threads/connections open while waiting.</strong> With 100K concurrent users each holding a long poll connection, you need 100K open connections on your servers \u2014 consuming file descriptors and memory even when idle.<br><span style=\"color:#b83030;font-size:12.5px;\">\u26a0\ufe0f Mitigate with async event loops (Node.js, Go goroutines, Nginx) that handle thousands of open connections on a single thread. Traditional thread-per-request servers (Java/Rails) cannot scale long polling.</span></div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">When Still Used</div>\n      <div class=\"concept-def\"><strong>Long polling is the fallback when WebSocket is unavailable</strong> (corporate firewalls blocking WS) or for systems where you need guaranteed delivery with replay.<br><span style=\"color:#5a5848;font-size:12.5px;\">Real usage: Slack originally used long polling before WebSocket. Some mobile apps in restricted networks still use it. XMPP Bosh protocol is long polling. Most modern systems use WebSocket or SSE instead.</span></div>\n    </div>\n  </div>\n</section>\n\n<!-- \u2550\u2550 03 FULL COMPARISON \u2550\u2550 -->\n<section id=\"comparison\">\n  <div class=\"sec-tag\">03 \u00b7 Side by Side</div>\n  <h2>Every dimension that matters in an interview</h2>\n\n  <table class=\"comp-table\">\n    <thead>\n      <tr>\n        <th>Dimension</th>\n        <th>REST \ud83c\udf10</th>\n        <th>gRPC \u26a1</th>\n        <th>GraphQL \u25c8</th>\n        <th>WebSocket \ud83d\udd0c</th>\n        <th>SSE \ud83d\udce1</th>\n        <th>Long Poll \ud83d\udd04</th>\n      </tr>\n    </thead>\n    <tbody>\n      <tr>\n        <td class=\"row-head\">Communication</td>\n        <td>Request-Response</td>\n        <td>RPC + Streaming</td>\n        <td>Request-Response</td>\n        <td>Bidirectional</td>\n        <td>Server\u2192Client</td>\n        <td>Simulated Push</td>\n      </tr>\n      <tr>\n        <td class=\"row-head\">Transport</td>\n        <td>HTTP/1.1, HTTP/2</td>\n        <td>HTTP/2 only</td>\n        <td>HTTP/1.1, HTTP/2</td>\n        <td>TCP (after upgrade)</td>\n        <td>HTTP/1.1, HTTP/2</td>\n        <td>HTTP/1.1, HTTP/2</td>\n      </tr>\n      <tr>\n        <td class=\"row-head\">Data Format</td>\n        <td>JSON, XML, anything</td>\n        <td>Protobuf (binary)</td>\n        <td>JSON</td>\n        <td>Any (text or binary)</td>\n        <td>Text (UTF-8)</td>\n        <td>JSON, anything</td>\n      </tr>\n      <tr>\n        <td class=\"row-head\">Latency</td>\n        <td><span class=\"warn\">1 RTT per request</span></td>\n        <td><span class=\"good\">~1 RTT, multiplexed</span></td>\n        <td><span class=\"warn\">1 RTT per query</span></td>\n        <td><span class=\"good\">Sub-ms after connect</span></td>\n        <td><span class=\"good\">Sub-ms after connect</span></td>\n        <td><span class=\"warn\">~1 RTT when data ready</span></td>\n      </tr>\n      <tr>\n        <td class=\"row-head\">Payload Size</td>\n        <td><span class=\"warn\">Large (JSON + HTTP headers)</span></td>\n        <td><span class=\"good\">5\u201310x smaller than REST</span></td>\n        <td><span class=\"warn\">Similar to REST</span></td>\n        <td><span class=\"good\">Tiny frame headers</span></td>\n        <td><span class=\"good\">Small (text events)</span></td>\n        <td><span class=\"warn\">HTTP headers per request</span></td>\n      </tr>\n      <tr>\n        <td class=\"row-head\">HTTP Caching</td>\n        <td><span class=\"good\">Full support (GET)</span></td>\n        <td><span class=\"bad\">None</span></td>\n        <td><span class=\"bad\">None natively</span></td>\n        <td><span class=\"bad\">None</span></td>\n        <td><span class=\"warn\">Limited</span></td>\n        <td><span class=\"bad\">None effectively</span></td>\n      </tr>\n      <tr>\n        <td class=\"row-head\">Browser Support</td>\n        <td><span class=\"good\">Universal</span></td>\n        <td><span class=\"bad\">Needs gRPC-Web proxy</span></td>\n        <td><span class=\"good\">Universal (HTTP)</span></td>\n        <td><span class=\"good\">All modern browsers</span></td>\n        <td><span class=\"good\">All modern browsers</span></td>\n        <td><span class=\"good\">Universal</span></td>\n      </tr>\n      <tr>\n        <td class=\"row-head\">Stateful?</td>\n        <td><span class=\"good\">Stateless</span></td>\n        <td><span class=\"warn\">Stream is stateful</span></td>\n        <td><span class=\"good\">Stateless (queries)</span></td>\n        <td><span class=\"bad\">Stateful connection</span></td>\n        <td><span class=\"bad\">Stateful connection</span></td>\n        <td><span class=\"warn\">Quasi-stateful</span></td>\n      </tr>\n      <tr>\n        <td class=\"row-head\">Load Balancing</td>\n        <td><span class=\"good\">Trivial</span></td>\n        <td><span class=\"good\">L7 with gRPC-aware LB</span></td>\n        <td><span class=\"good\">Trivial</span></td>\n        <td><span class=\"bad\">Sticky sessions needed</span></td>\n        <td><span class=\"bad\">Sticky sessions needed</span></td>\n        <td><span class=\"warn\">Manageable</span></td>\n      </tr>\n      <tr>\n        <td class=\"row-head\">Schema / Contract</td>\n        <td><span class=\"warn\">Optional (OpenAPI)</span></td>\n        <td><span class=\"good\">Mandatory .proto</span></td>\n        <td><span class=\"good\">Typed schema</span></td>\n        <td><span class=\"bad\">None by default</span></td>\n        <td><span class=\"bad\">None by default</span></td>\n        <td><span class=\"bad\">None by default</span></td>\n      </tr>\n      <tr>\n        <td class=\"row-head\">Tooling / Ecosystem</td>\n        <td><span class=\"good\">Massive</span></td>\n        <td><span class=\"warn\">Good, growing</span></td>\n        <td><span class=\"good\">Rich (Apollo, Relay)</span></td>\n        <td><span class=\"warn\">Good</span></td>\n        <td><span class=\"warn\">Lightweight</span></td>\n        <td><span class=\"warn\">Basic</span></td>\n      </tr>\n      <tr>\n        <td class=\"row-head\">Best For</td>\n        <td>Public APIs, CRUD</td>\n        <td>Internal services</td>\n        <td>Multi-client APIs</td>\n        <td>Chat, games, collab</td>\n        <td>Feeds, notifications</td>\n        <td>Legacy/fallback</td>\n      </tr>\n    </tbody>\n  </table>\n</section>\n\n<!-- \u2550\u2550 04 COMBOS \u2550\u2550 -->\n<section id=\"combos\">\n  <div class=\"sec-tag\">04 \u00b7 Where They Complement Each Other</div>\n  <h2>Protocols that work together \u2014 not against each other</h2>\n\n  <p>The biggest interview insight: <strong>real systems use multiple protocols simultaneously</strong>. The request-response and real-time families solve different problems and are designed to be combined. Here are the six most common patterns you'll see and need to justify in interviews.</p>\n\n  <div class=\"combo-grid\">\n\n    <div class=\"combo-card c1\">\n      <div class=\"combo-title\">REST + WebSocket</div>\n      <div class=\"combo-formula\">REST for actions \u00b7 WebSocket for events</div>\n      <div class=\"combo-body\">REST handles all mutations (send message, create post, update status). WebSocket delivers the real-time events (new message received, presence change, typing indicator). The REST call triggers the server-side change; WebSocket broadcasts the result to affected users.</div>\n      <div class=\"combo-used\">Used by: Slack, Discord, WhatsApp Web, Notion</div>\n    </div>\n\n    <div class=\"combo-card c2\">\n      <div class=\"combo-title\">REST + SSE</div>\n      <div class=\"combo-formula\">REST for writes \u00b7 SSE for live updates</div>\n      <div class=\"combo-body\">User submits actions via REST (POST /start-analysis). Server acknowledges immediately with a job ID. SSE stream delivers progress updates as the job runs. Simpler than WebSocket because the client never needs to send mid-stream. Classic for progress bars, live dashboards, AI streaming responses.</div>\n      <div class=\"combo-used\">Used by: GitHub Actions, Vercel deployments, OpenAI API (streaming tokens), monitoring dashboards</div>\n    </div>\n\n    <div class=\"combo-card c3\">\n      <div class=\"combo-title\">REST (external) + gRPC (internal)</div>\n      <div class=\"combo-formula\">REST at the edge \u00b7 gRPC between services</div>\n      <div class=\"combo-body\">Public API exposed as REST \u2014 universal browser support, HTTP caching, familiar to all clients. Internal microservice calls use gRPC \u2014 5\u201310x smaller payloads, strict typed contracts, HTTP/2 multiplexing. An API Gateway (like Envoy or Kong) translates REST\u2192gRPC at the boundary.</div>\n      <div class=\"combo-used\">Used by: Google, Uber, Netflix, most FAANG internal architectures</div>\n    </div>\n\n    <div class=\"combo-card c4\">\n      <div class=\"combo-title\">GraphQL + WebSocket</div>\n      <div class=\"combo-formula\">GraphQL Queries/Mutations + GraphQL Subscriptions</div>\n      <div class=\"combo-body\">GraphQL queries and mutations travel over HTTP for reads and writes. GraphQL Subscriptions use WebSocket under the hood for real-time updates. One unified schema \u2014 the client uses the same GraphQL types and vocabulary for both. Apollo Client handles both transports automatically.</div>\n      <div class=\"combo-used\">Used by: GitHub (GraphQL API + subscriptions), Hasura, Shopify Storefront API</div>\n    </div>\n\n    <div class=\"combo-card c5\">\n      <div class=\"combo-title\">REST + Long Polling (legacy)</div>\n      <div class=\"combo-formula\">REST everywhere \u00b7 Long polling as fallback</div>\n      <div class=\"combo-body\">When WebSocket or SSE is blocked by corporate firewalls or unsupported by old clients, long polling bridges the gap. Standard REST for all actions; long polling for the notification channel. Socket.io does exactly this \u2014 it tries WebSocket first, falls back to long polling automatically.</div>\n      <div class=\"combo-used\">Used by: Socket.io fallback, legacy enterprise apps, restricted network environments</div>\n    </div>\n\n    <div class=\"combo-card c6\">\n      <div class=\"combo-title\">gRPC Bidirectional Streaming</div>\n      <div class=\"combo-formula\">One protocol, four modes</div>\n      <div class=\"combo-body\">For pure service-to-service real-time, gRPC bidirectional streaming replaces both REST and WebSocket. Both sides stream simultaneously over a single HTTP/2 connection. Used for location tracking (client streams GPS, server streams route), audio/video processing, real-time ML inference pipelines.</div>\n      <div class=\"combo-used\">Used by: Google Maps, real-time ML pipelines, internal FAANG service meshes</div>\n    </div>\n\n  </div>\n\n  <div class=\"callout cl-green\">\n    <div class=\"cl-lbl\">The Interview Sound Bite</div>\n    <p><strong>\"In most production systems I would use REST for the request-response layer and pair it with either SSE or WebSocket for the real-time layer \u2014 depending on whether the client needs to send data back on the same connection. REST handles mutations; the real-time channel delivers server-initiated events. gRPC replaces REST for internal service-to-service calls where latency and throughput matter.\"</strong></p>\n  </div>\n</section>\n\n<!-- \u2550\u2550 05 SYSTEM DESIGN EXAMPLES \u2550\u2550 -->\n<section id=\"examples\">\n  <div class=\"sec-tag\">05 \u00b7 Applied to Real Systems</div>\n  <h2>Which protocol wins in which system?</h2>\n\n  <div class=\"sd-example\">\n    <div class=\"sd-example-head\">\n      <div class=\"sd-example-title\">Chat App (Slack / WhatsApp)</div>\n      <span class=\"sd-example-tag\">BIDIRECTIONAL \u00b7 REAL-TIME</span>\n    </div>\n    <div class=\"sd-example-body\">\n      <div class=\"choice-row\">\n        <div class=\"choice-label\">SEND MESSAGE</div>\n        <div class=\"choice-val\"><span class=\"badge b-rest\">REST \u2713</span> <code>POST /messages</code> \u2014 client sends message, server persists it, returns message ID + timestamp. REST because: idempotency key prevents duplicates on retry, HTTP status codes signal delivery failure clearly, easy to rate-limit with standard middleware.</div>\n      </div>\n      <div class=\"choice-row\">\n        <div class=\"choice-label\">RECEIVE MESSAGES</div>\n        <div class=\"choice-val\"><span class=\"badge b-ws\">WebSocket \u2713</span> Server pushes new messages to all room members the moment they arrive. Bidirectional needed: client also sends typing indicators and read receipts back on the same connection. Sub-10ms delivery vs 1\u20135 second polling lag.</div>\n      </div>\n      <div class=\"choice-row\">\n        <div class=\"choice-label\">PRESENCE / TYPING</div>\n        <div class=\"choice-val\"><span class=\"badge b-ws\">WebSocket \u2713</span> \"Alice is typing\u2026\" \u2014 client sends typing events over the WebSocket every keystroke. Server fans out to all members via pub/sub (Redis). Low-overhead frames, no HTTP headers per event.</div>\n      </div>\n      <div class=\"choice-row\">\n        <div class=\"choice-label\">INTERNAL SERVICES</div>\n        <div class=\"choice-val\"><span class=\"badge b-grpc\">gRPC \u2713</span> Message Service \u2192 Notification Service \u2192 Presence Service: all internal. Protobuf contracts prevent schema drift. HTTP/2 multiplexing handles thousands of RPCs/sec between services without connection explosion.</div>\n      </div>\n      <div class=\"choice-row\">\n        <div class=\"choice-label\">WHY NOT ALL WS</div>\n        <div class=\"choice-val\"><span class=\"badge b-a\">Tradeoff \u26a0</span> WebSocket for everything seems elegant but: WS mutations can't use HTTP caching, rate limiting is harder, retry logic needs custom implementation, and load balancing requires sticky sessions. REST for writes + WS for events is the industry standard split.</div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"sd-example\">\n    <div class=\"sd-example-head\">\n      <div class=\"sd-example-title\">Top-K Trending Dashboard (YouTube / Twitter)</div>\n      <span class=\"sd-example-tag\">SERVER PUSH \u00b7 READ-HEAVY</span>\n    </div>\n    <div class=\"sd-example-body\">\n      <div class=\"choice-row\">\n        <div class=\"choice-label\">LIVE RANKINGS</div>\n        <div class=\"choice-val\"><span class=\"badge b-sse\">SSE \u2713</span> Dashboard shows top 10 videos updating every 30 seconds. SSE stream pushes updates from Flink flush events. Client never sends data back \u2014 perfect SSE fit. Auto-reconnect handles network hiccups transparently. HTTP/2 multiplexes thousands of concurrent dashboard viewers.</div>\n      </div>\n      <div class=\"choice-row\">\n        <div class=\"choice-label\">INITIAL DATA LOAD</div>\n        <div class=\"choice-val\"><span class=\"badge b-rest\">REST \u2713</span> <code>GET /top-k?window=1h&region=IN</code> loads the initial ranked list. Cacheable at CDN edge (60s TTL). 95% of requests served from cache \u2014 SSE stream only delivers delta updates after the initial load.</div>\n      </div>\n      <div class=\"choice-row\">\n        <div class=\"choice-label\">WHY NOT WEBSOCKET</div>\n        <div class=\"choice-val\"><span class=\"badge b-a\">Overkill \u26a0</span> The dashboard is read-only \u2014 users never push data back. WebSocket's bidirectional capability is wasted. SSE is simpler: no handshake upgrade, works through HTTP/2 proxies without special configuration, auto-reconnects, and uses standard HTTP connections that load balancers understand natively.</div>\n      </div>\n      <div class=\"choice-row\">\n        <div class=\"choice-label\">WHY NOT POLLING</div>\n        <div class=\"choice-val\"><span class=\"badge b-r\">Inefficient \u2717</span> At 30s poll interval and 100K concurrent users: 100K requests every 30s = 3,333 requests/sec, most returning the same data. SSE uses a persistent connection per user \u2014 0 requests until data changes. Orders of magnitude less origin traffic.</div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"sd-example\">\n    <div class=\"sd-example-head\">\n      <div class=\"sd-example-title\">Mobile App API (Instagram / Uber)</div>\n      <span class=\"sd-example-tag\">MULTI-CLIENT \u00b7 BANDWIDTH-SENSITIVE</span>\n    </div>\n    <div class=\"sd-example-body\">\n      <div class=\"choice-row\">\n        <div class=\"choice-label\">WEB APP API</div>\n        <div class=\"choice-val\"><span class=\"badge b-rest\">REST \u2713</span> Desktop browser with good connectivity. REST with HTTP/2 is fast, cacheable, and familiar. No over-fetching problem at this scale \u2014 one REST response per screen is acceptable.</div>\n      </div>\n      <div class=\"choice-row\">\n        <div class=\"choice-label\">MOBILE APP API</div>\n        <div class=\"choice-val\"><span class=\"badge b-gql\">GraphQL \u2713</span> Mobile on 4G/5G with limited bandwidth. GraphQL lets the app fetch exactly the fields it needs \u2014 no wasted data. One query fetches feed + stories + story counts instead of 3 REST calls. Instagram's move to GraphQL reduced API response sizes by 30\u201350%.</div>\n      </div>\n      <div class=\"choice-row\">\n        <div class=\"choice-label\">PARTNER API</div>\n        <div class=\"choice-val\"><span class=\"badge b-rest\">REST \u2713</span> Third-party developer integrations use REST. Universal support, simple to understand, extensive documentation. GraphQL's flexibility is a liability here \u2014 partners need a stable, versioned contract, not an evolving schema.</div>\n      </div>\n      <div class=\"choice-row\">\n        <div class=\"choice-label\">DRIVER LOCATION (Uber)</div>\n        <div class=\"choice-val\"><span class=\"badge b-ws\">WebSocket \u2713</span> Driver app streams GPS location every 2 seconds. Rider app receives driver position updates in real-time. Both directions active simultaneously \u2014 classic WebSocket scenario. gRPC bidirectional streaming works equally well for this internal use case.</div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"sd-example\">\n    <div class=\"sd-example-head\">\n      <div class=\"sd-example-title\">Notification System (Apple Push / Firebase)</div>\n      <span class=\"sd-example-tag\">FAN-OUT \u00b7 MOBILE PUSH</span>\n    </div>\n    <div class=\"sd-example-body\">\n      <div class=\"choice-row\">\n        <div class=\"choice-label\">WEB NOTIFICATIONS</div>\n        <div class=\"choice-val\"><span class=\"badge b-sse\">SSE \u2713</span> Browser tab receives notifications via SSE stream. User doesn't send acknowledgements in the same connection \u2014 REST POST for \"mark as read\". Simple, reconnects automatically, works with HTTP/2.</div>\n      </div>\n      <div class=\"choice-row\">\n        <div class=\"choice-label\">MOBILE PUSH</div>\n        <div class=\"choice-val\"><span class=\"badge b-rest\">REST \u2713</span> Your server calls APNs (Apple) or FCM (Firebase) REST APIs to push notifications to iOS/Android. The OS maintains its own persistent connection to Apple/Google \u2014 you just trigger it via REST. Your app never holds a WebSocket open in the background.</div>\n      </div>\n      <div class=\"choice-row\">\n        <div class=\"choice-label\">INTERNAL FAN-OUT</div>\n        <div class=\"choice-val\"><span class=\"badge b-grpc\">gRPC \u2713</span> Notification Service fans out to User Service, Device Service, and APNs Gateway all via gRPC. Hundreds of millions of notifications/day means every millisecond and byte of payload overhead compounds. Protobuf binary encoding + HTTP/2 multiplexing handles the load.</div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"sd-example\">\n    <div class=\"sd-example-head\">\n      <div class=\"sd-example-title\">Collaborative Editing (Google Docs / Notion)</div>\n      <span class=\"sd-example-tag\">CRDT \u00b7 REAL-TIME \u00b7 MULTI-USER</span>\n    </div>\n    <div class=\"sd-example-body\">\n      <div class=\"choice-row\">\n        <div class=\"choice-label\">EDITS</div>\n        <div class=\"choice-val\"><span class=\"badge b-ws\">WebSocket \u2713</span> Every keystroke is an operation (insert/delete + position). Operations are sent over WebSocket immediately. Server applies OT (Operational Transformation) or CRDT to merge concurrent edits from multiple users. The merged result is broadcast back to all connected users via the same WebSocket.</div>\n      </div>\n      <div class=\"choice-row\">\n        <div class=\"choice-label\">CURSOR POSITIONS</div>\n        <div class=\"choice-val\"><span class=\"badge b-ws\">WebSocket \u2713</span> \"Alice is editing paragraph 3\" \u2014 cursor broadcast via WebSocket at ~10 events/sec. Ephemeral \u2014 not persisted. WebSocket's low per-frame overhead makes this affordable even for documents with 50 simultaneous editors.</div>\n      </div>\n      <div class=\"choice-row\">\n        <div class=\"choice-label\">DOCUMENT SAVE</div>\n        <div class=\"choice-val\"><span class=\"badge b-rest\">REST \u2713</span> Periodic snapshot of document state sent via REST POST. Idempotent, retryable, separate from the real-time stream. REST for durability; WebSocket for real-time sync.</div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- \u2550\u2550 06 DECISION TREE \u2550\u2550 -->\n<section id=\"decision\">\n  <div class=\"sec-tag\">06 \u00b7 The Decision Framework</div>\n  <h2>How to pick in an interview \u2014 in 60 seconds</h2>\n\n  <div class=\"step-block\">\n    <div class=\"step-block-header\"><span class=\"sb-icon\">\ud83c\udfaf</span>Protocol Selection \u2014 Ask in Order</div>\n    <div class=\"step-block-body\">\n      <div class=\"step-row\"><div class=\"step-num\">01</div><div class=\"step-content\">\n        <div class=\"step-q\">Does the server need to push data to the client without the client asking?</div>\n        <div class=\"step-options\">\n          <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">YES \u2192</span><span class=\"opt-text\">You need a real-time protocol. Go to Step 2. REST alone cannot solve this.</span></div>\n          <div class=\"step-option opt-no\"><span class=\"opt-arrow\">NO \u2192</span><span class=\"opt-text\">Request-Response is sufficient. Go to Step 4 to pick between REST, gRPC, and GraphQL.</span></div>\n        </div>\n      </div></div>\n      <div class=\"step-row\"><div class=\"step-num\">02</div><div class=\"step-content\">\n        <div class=\"step-q\">Does the client also need to send data back on the same real-time connection?</div>\n        <div class=\"step-options\">\n          <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">YES \u2192</span><span class=\"opt-text\"><strong>WebSocket.</strong> Chat messages, cursor positions, game inputs, collaborative edits \u2014 bidirectional continuous communication. Pair with REST for mutations that need HTTP semantics (retries, idempotency).</span></div>\n          <div class=\"step-option opt-no\"><span class=\"opt-arrow\">NO \u2192</span><span class=\"opt-text\"><strong>SSE</strong> (preferred) or <strong>Long Polling</strong> (fallback). Live feeds, notifications, progress bars, dashboards \u2014 server pushes, client only reads. SSE is simpler and HTTP/2-native. Long Polling if SSE is unavailable.</span></div>\n        </div>\n      </div></div>\n      <div class=\"step-row\"><div class=\"step-num\">03</div><div class=\"step-content\">\n        <div class=\"step-q\">Is this for browser clients or internal service-to-service?</div>\n        <div class=\"step-options\">\n          <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">Browser \u2192</span><span class=\"opt-text\"><strong>WebSocket or SSE.</strong> Both have native browser APIs (WebSocket API, EventSource API). No proxy needed.</span></div>\n          <div class=\"step-option opt-no\"><span class=\"opt-arrow\">Service-to-Service \u2192</span><span class=\"opt-text\"><strong>gRPC bidirectional streaming</strong> \u2014 all the benefits of gRPC (binary, typed, multiplexed) plus both sides can stream. Google Maps, real-time ML inference pipelines.</span></div>\n        </div>\n      </div></div>\n      <div class=\"step-row\"><div class=\"step-num\">04</div><div class=\"step-content\">\n        <div class=\"step-q\">Is this a public API, internal service, or multi-client API?</div>\n        <div class=\"step-options\">\n          <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">Public API \u2192</span><span class=\"opt-text\"><strong>REST.</strong> Universal support, HTTP caching, familiar to all developers, simple to rate limit and monitor. Default until you have a specific reason to deviate.</span></div>\n          <div class=\"step-option opt-mid\"><span class=\"opt-arrow\">Internal services \u2192</span><span class=\"opt-text\"><strong>gRPC.</strong> Binary Protobuf (5\u201310x smaller), HTTP/2 multiplexing, strict typed contracts. Ideal for service meshes where latency and throughput compound across hundreds of microservices.</span></div>\n          <div class=\"step-option opt-no\"><span class=\"opt-arrow\">Multi-client (web + mobile + partners) \u2192</span><span class=\"opt-text\"><strong>GraphQL.</strong> Different clients need different data shapes. One schema, client-driven queries, no over-fetching on mobile bandwidth. Requires DataLoader to avoid N+1.</span></div>\n        </div>\n      </div></div>\n      <div class=\"step-row\"><div class=\"step-num\">05</div><div class=\"step-content\">\n        <div class=\"step-q\">Do you have strict performance or bandwidth requirements?</div>\n        <div class=\"step-options\">\n          <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">Performance critical \u2192</span><span class=\"opt-text\"><strong>gRPC over REST</strong> for service-to-service. Binary vs JSON: 5\u201310x payload reduction. At 1M RPC/sec between services, the difference is measurable in infra costs and latency percentiles.</span></div>\n          <div class=\"step-option opt-no\"><span class=\"opt-arrow\">Standard requirements \u2192</span><span class=\"opt-text\"><strong>REST is fine.</strong> With HTTP/2 and proper JSON compression (gzip/brotli), REST performance is excellent for the vast majority of systems. Don't optimise prematurely.</span></div>\n        </div>\n      </div></div>\n    </div>\n  </div>\n\n  <h3>The Rules You Must Know</h3>\n  <div class=\"use-grid\">\n    <div class=\"use-card\">\n      <div class=\"use-card-head\" style=\"color:var(--rest)\">\ud83c\udf10 Always use REST when\u2026</div>\n      <ul>\n        <li>Building a public-facing API</li>\n        <li>Need HTTP caching (GET responses)</li>\n        <li>Clients are diverse (browsers, mobile, partners)</li>\n        <li>Team is small, simplicity matters</li>\n        <li>CRUD operations with standard semantics</li>\n      </ul>\n    </div>\n    <div class=\"use-card\">\n      <div class=\"use-card-head\" style=\"color:var(--grpc)\">\u26a1 Always use gRPC when\u2026</div>\n      <ul>\n        <li>Service-to-service internal calls</li>\n        <li>High-throughput, latency-sensitive RPCs</li>\n        <li>Need strong schema contract between teams</li>\n        <li>Polyglot microservices (code gen handles language)</li>\n        <li>Streaming between services (bidirectional)</li>\n      </ul>\n    </div>\n    <div class=\"use-card\">\n      <div class=\"use-card-head\" style=\"color:var(--gql)\">\u25c8 Always use GraphQL when\u2026</div>\n      <ul>\n        <li>Multiple client types with different data needs</li>\n        <li>Mobile bandwidth is constrained</li>\n        <li>Rapidly evolving product with frequent data shape changes</li>\n        <li>BFF (Backend-for-Frontend) pattern</li>\n        <li>Developer experience is a priority</li>\n      </ul>\n    </div>\n    <div class=\"use-card\">\n      <div class=\"use-card-head\" style=\"color:var(--ws)\">\ud83d\udd0c Always use WebSocket when\u2026</div>\n      <ul>\n        <li>Chat or messaging (bidirectional)</li>\n        <li>Multiplayer games or real-time collaboration</li>\n        <li>Both client AND server need to push continuously</li>\n        <li>Sub-100ms latency for every event</li>\n        <li>Persistent session with many small messages</li>\n      </ul>\n    </div>\n    <div class=\"use-card\">\n      <div class=\"use-card-head\" style=\"color:var(--sse)\">\ud83d\udce1 Always use SSE when\u2026</div>\n      <ul>\n        <li>Server pushes, client only reads</li>\n        <li>Live dashboards, feeds, notifications</li>\n        <li>AI streaming responses (token-by-token)</li>\n        <li>Progress bars for long-running jobs</li>\n        <li>Simpler alternative to WebSocket</li>\n      </ul>\n    </div>\n    <div class=\"use-card\">\n      <div class=\"use-card-head\" style=\"color:var(--lp)\">\ud83d\udd04 Long Polling only when\u2026</div>\n      <ul>\n        <li>WebSocket and SSE are unavailable (firewalls)</li>\n        <li>Legacy client support required</li>\n        <li>Using Socket.io (handles fallback automatically)</li>\n        <li>Low update frequency (&lt;1/min) where polling gap is fine</li>\n      </ul>\n    </div>\n  </div>\n</section>\n\n<!-- \u2550\u2550 07 FOLLOW-UPS \u2550\u2550 -->\n<section id=\"followups\">\n  <div class=\"sec-tag\">07 \u00b7 Interview Follow-up Playbook</div>\n  <h2>Every hard follow-up, answered</h2>\n\n  <div class=\"faq-item\">\n    <div class=\"faq-q\" onclick=\"toggle(this)\">How do you scale WebSocket to millions of concurrent connections?<span class=\"tog\">+</span></div>\n    <div class=\"faq-a\">\n      <strong>The core challenge:</strong> WebSocket connections are stateful and live on a specific server. Standard round-robin load balancing breaks \u2014 if user A is connected to server 1 and sends a message to user B connected to server 3, server 1 can't directly push to user B.<br><br>\n      <strong>The solution \u2014 pub/sub message bus:</strong>\n      <ul>\n        <li>Every server subscribes to a Redis Pub/Sub channel or Kafka topic</li>\n        <li>When server 1 needs to push to user B (connected to server 3), it publishes to the shared channel</li>\n        <li>Server 3 is subscribed, receives the message, and pushes it to user B's WebSocket connection</li>\n        <li>Any server can reach any user \u2014 no sticky sessions required for message delivery</li>\n      </ul>\n      <strong>Connection count:</strong> A single server with an async event loop (Node.js, Go, Nginx) can handle 100K\u20131M concurrent WebSocket connections. C10M is achievable with tuned Linux kernel settings (file descriptor limits, socket buffer sizes).<br><br>\n      <strong>Load balancing:</strong> Use sticky sessions (consistent hash by user_id) so a user's connection always routes to the same server \u2014 reduces pub/sub overhead. Failover: client reconnects to any available server on disconnect.\n    </div>\n  </div>\n\n  <div class=\"faq-item\">\n    <div class=\"faq-q\" onclick=\"toggle(this)\">REST vs gRPC \u2014 which is faster and by how much?<span class=\"tog\">+</span></div>\n    <div class=\"faq-a\">\n      <strong>In benchmarks, gRPC is typically 5\u201310x faster than JSON REST for equivalent payloads.</strong><br><br>\n      <strong>Why Protobuf is faster than JSON:</strong>\n      <ul>\n        <li><strong>Size:</strong> JSON is human-readable text. \"created_at\": \"2026-03-20T14:23:45Z\" is 37 bytes. Protobuf field 5 = timestamp = 8 bytes. 4\u20135x smaller is typical.</li>\n        <li><strong>Parsing:</strong> JSON parsing is string scanning and Unicode handling. Protobuf parsing is integer-indexed field lookup. 5\u201310x faster deserialization.</li>\n        <li><strong>HTTP/2 multiplexing:</strong> gRPC reuses one TCP connection for all RPCs between two services. HTTP/1.1 REST requires a connection per request or connection pooling.</li>\n      </ul>\n      <strong>Real-world numbers (Google's internal benchmarks):</strong> gRPC serialization is ~7x faster than JSON, payloads are ~3.5x smaller, leading to ~2\u20134x fewer CPU cycles per RPC.<br><br>\n      <strong>When the difference matters:</strong> At 10K RPC/sec between services, the CPU savings from Protobuf are measurable in infra cost. At 100 RPC/sec, use REST \u2014 the operational simplicity outweighs any performance gain.\n    </div>\n  </div>\n\n  <div class=\"faq-item\">\n    <div class=\"faq-q\" onclick=\"toggle(this)\">GraphQL solves over-fetching \u2014 but doesn't it create its own performance problems?<span class=\"tog\">+</span></div>\n    <div class=\"faq-a\">\n      <strong>Yes \u2014 GraphQL solves bandwidth but creates three new challenges:</strong><br><br>\n      <strong>1. N+1 queries (the biggest one):</strong> A query for 100 posts each needing their author resolves by calling getAuthor() 100 times. Without DataLoader, this is 101 database calls instead of 2.<br>\n      Fix: DataLoader batches all getAuthor() calls that occur in the same tick into one <code>SELECT * FROM users WHERE id IN (1,2,3...100)</code>.<br><br>\n      <strong>2. Query complexity attacks:</strong> A malicious client sends a deeply nested query: posts \u2192 comments \u2192 authors \u2192 posts \u2192 comments \u2192 authors \u2192 (\u221e). Without depth limiting, this triggers exponential resolver calls.<br>\n      Fix: Query depth limit (max 10 levels), query complexity scoring (each field costs points, reject queries over a budget), query whitelisting in production (only allow known queries).<br><br>\n      <strong>3. No HTTP caching:</strong> GraphQL uses POST \u2014 CDNs don't cache POST. Every query hits your origin.<br>\n      Fix: Persisted Queries \u2014 hash each known query, send the hash as a GET parameter. CDN caches the response. Only novel/uncached queries reach the origin.\n    </div>\n  </div>\n\n  <div class=\"faq-item\">\n    <div class=\"faq-q\" onclick=\"toggle(this)\">SSE vs WebSocket \u2014 when exactly do you pick SSE?<span class=\"tog\">+</span></div>\n    <div class=\"faq-a\">\n      <strong>Pick SSE when the data flow is one-directional and you want HTTP-native simplicity.</strong><br><br>\n      <strong>SSE wins over WebSocket when:</strong>\n      <ul>\n        <li>Client only reads \u2014 never sends data on the real-time channel (notifications, feeds, dashboards, AI token streaming)</li>\n        <li>You need automatic reconnection with event replay \u2014 SSE's <code>Last-Event-ID</code> mechanism gives you this for free; WebSocket requires custom client logic</li>\n        <li>HTTP/2 is available \u2014 SSE over HTTP/2 multiplexes thousands of streams over one TCP connection, solving HTTP/1.1's 6-connection limit</li>\n        <li>Your infrastructure doesn't support WebSocket upgrades (some corporate proxies block it)</li>\n        <li>You want standard HTTP monitoring, logging, and load balancing without special WebSocket-aware tooling</li>\n      </ul>\n      <strong>WebSocket wins when:</strong>\n      <ul>\n        <li>Client sends data frequently on the real-time channel (chat, collaborative editing, games, cursor positions)</li>\n        <li>Sub-frame latency matters \u2014 WebSocket frames are slightly lower overhead than SSE's HTTP text envelope</li>\n        <li>You need binary data (WebSocket supports binary frames natively; SSE is text-only)</li>\n      </ul>\n      <strong>The practical test:</strong> Draw an arrow for your data flow. If the arrow points server\u2192client only, use SSE. If arrows go both directions, use WebSocket.\n    </div>\n  </div>\n\n  <div class=\"faq-item\">\n    <div class=\"faq-q\" onclick=\"toggle(this)\">How does gRPC handle versioning when you change your .proto schema?<span class=\"tog\">+</span></div>\n    <div class=\"faq-a\">\n      <strong>Protobuf has designed-in backwards compatibility rules \u2014 but you must follow them religiously.</strong><br><br>\n      <strong>Safe changes (backwards and forwards compatible):</strong>\n      <ul>\n        <li>Adding a new field \u2014 old clients ignore it, new clients read it</li>\n        <li>Changing a field name \u2014 field numbers are what Protobuf uses on the wire, not names</li>\n        <li>Adding a new RPC method \u2014 old clients don't call it</li>\n      </ul>\n      <strong>Breaking changes (never do these in production):</strong>\n      <ul>\n        <li>Changing a field's number (field number = wire identity; changing it means old clients misread your data)</li>\n        <li>Changing a field's type (int32 \u2192 string will corrupt data in-flight)</li>\n        <li>Removing a required field (old clients still send it; new server rejects it)</li>\n        <li>Removing an RPC method that clients are calling</li>\n      </ul>\n      <strong>The strategy for major changes:</strong> Create a new package version (<code>package myapi.v2</code>). Run v1 and v2 in parallel. Migrate clients to v2 gradually. Retire v1 only after all clients have migrated. This is identical to REST's <code>/v1/</code> vs <code>/v2/</code> URL versioning.\n    </div>\n  </div>\n\n  <div class=\"faq-item\">\n    <div class=\"faq-q\" onclick=\"toggle(this)\">What's the difference between REST idempotency and GraphQL mutation safety?<span class=\"tog\">+</span></div>\n    <div class=\"faq-a\">\n      <strong>Idempotency means: calling the operation multiple times has the same effect as calling it once.</strong><br><br>\n      <strong>REST's HTTP methods have defined idempotency semantics:</strong>\n      <ul>\n        <li><code>GET, HEAD, OPTIONS</code> \u2014 safe (no side effects) and idempotent</li>\n        <li><code>PUT, DELETE</code> \u2014 idempotent (doing it twice = same result as once)</li>\n        <li><code>POST</code> \u2014 neither safe nor idempotent (creates a new resource each call)</li>\n        <li><code>PATCH</code> \u2014 not inherently idempotent (depends on implementation)</li>\n      </ul>\n      <strong>For POST idempotency:</strong> Use an Idempotency-Key header (unique UUID per request). Server stores the key \u2192 result mapping. If same key arrives twice, return the stored result instead of executing again. Stripe, Stripe, and most payment APIs require this.<br><br>\n      <strong>GraphQL mutations:</strong> All mutations use POST \u2014 no built-in idempotency. You must implement idempotency keys manually in your mutation resolvers if needed (e.g., payment mutations). This is GraphQL's operational weakness vs REST's verb semantics.<br><br>\n      <strong>Why it matters in interviews:</strong> Payment processing, order creation, and any mutation where double-execution has real consequences needs explicit idempotency handling regardless of protocol.\n    </div>\n  </div>\n\n  <div class=\"faq-item\">\n    <div class=\"faq-q\" onclick=\"toggle(this)\">How do you secure WebSocket connections?<span class=\"tog\">+</span></div>\n    <div class=\"faq-a\">\n      <strong>WebSocket has no built-in authentication \u2014 you must implement it explicitly.</strong><br><br>\n      <strong>Step 1 \u2014 Use WSS (WebSocket Secure):</strong> Always use <code>wss://</code> (TLS), never <code>ws://</code>. Same as HTTPS vs HTTP. Your certificate covers both.<br><br>\n      <strong>Step 2 \u2014 Authenticate at connection time:</strong> The HTTP Upgrade request is a standard HTTP request \u2014 you can read headers and cookies. Send a JWT or session token in the <code>Authorization</code> header or as a query parameter on the initial <code>wss://</code> URL. Validate before accepting the upgrade.<br><br>\n      <strong>Step 3 \u2014 Authorise at message time:</strong> Validate that the connected user has permission for every message they send. Don't assume that because they connected legitimately, all their subsequent messages are authorised.<br><br>\n      <strong>Step 4 \u2014 Rate limit messages:</strong> Unlike HTTP where rate limiting is standard middleware, WebSocket bypasses your HTTP layer. Implement per-connection message rate limiting at the WebSocket handler level. Without it, one client can flood your server with messages.<br><br>\n      <strong>Step 5 \u2014 Handle token expiry:</strong> JWTs expire. If a user's token expires mid-session, the server needs to close the WebSocket and force re-authentication. Implement token refresh via a REST call; send the new token over the WebSocket or reconnect with the new token.\n    </div>\n  </div>\n\n  <div class=\"faq-item\">\n    <div class=\"faq-q\" onclick=\"toggle(this)\">In the Uber system design, why use both REST and WebSocket \u2014 why not just WebSocket for everything?<span class=\"tog\">+</span></div>\n    <div class=\"faq-a\">\n      <strong>Using WebSocket for everything seems elegant but creates real problems:</strong><br><br>\n      <strong>1. HTTP semantics matter:</strong> REST gives you status codes (400 bad request, 402 payment required, 409 conflict) that load balancers, monitoring tools, and clients all understand natively. Over WebSocket, you'd invent custom error codes \u2014 invisible to your infrastructure.<br><br>\n      <strong>2. Idempotency and retries:</strong> When a user books a ride, you need idempotency guarantees. REST POST with an Idempotency-Key is standardised. WebSocket message delivery is at-most-once by default \u2014 you'd need to build your own ack/retry layer.<br><br>\n      <strong>3. Caching:</strong> Fare estimates, driver profiles, and static data are cacheable. REST GET responses are cached at CDN and browser level automatically. WebSocket has no caching layer.<br><br>\n      <strong>4. Load balancing:</strong> REST requests are stateless \u2014 any server handles any request. WebSocket connections are stateful \u2014 they need sticky sessions or a message bus. Running everything over WebSocket means every service needs WebSocket-aware infrastructure.<br><br>\n      <strong>5. Operational tooling:</strong> HTTP logs, traces, and metrics are supported by every monitoring tool out of the box. WebSocket message-level observability requires custom instrumentation.<br><br>\n      <strong>The correct split:</strong> WebSocket for what genuinely needs real-time bidirectional communication (location, status updates). REST for everything transactional (booking, payment, profile). The complexity-to-benefit ratio is much better.\n    </div>\n  </div>\n</section>\n\n</div>\n<div class=\"footer\">PROTOCOLS \u00b7 REST \u00b7 GRPC \u00b7 GRAPHQL \u00b7 WEBSOCKET \u00b7 SSE \u00b7 LONG POLLING \u00b7 MANISH-ALMANAC</div>\n\n\u003cscript>function toggle(el){el.parentElement.classList.toggle('open');}<\/script>\n</body>\n</html>\n", tag: 'Protocols' },
  caching: { title: 'Caching Deep Dive', srcdoc: "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Caching: Redis, Memcached & CDN</title>\n<link href=\"https://fonts.googleapis.com/css2?family=Playfair+Display:wght@700;900&family=Source+Sans+3:wght@300;400;500;600&family=JetBrains+Mono:wght@400;600&display=swap\" rel=\"stylesheet\">\n<style>\n\n:root{--ink:#0f0e0c;--page:#f7f5f0;--surface:#eeecea;--surface2:#e5e2dc;--border:#d4d0c8;--muted:#7a7568;--pg:#336791;--pg-bg:#eef4fb;--mg:#13aa52;--mg-bg:#edfaf2;--dy:#ff9900;--dy-bg:#fff8ec;--ca:#1287b1;--ca-bg:#eaf6fb;--red:#c0392b;--red-bg:#fdf0ee;--green:#1a7a4a;--green-bg:#edf8f2;--amber:#b8720a;--amber-bg:#fdf6e8;--blue:#1a4f8a;--blue-bg:#edf2fb;--mono:'JetBrains Mono',monospace;--serif:'Playfair Display',serif;--sans:'Source Sans 3',sans-serif;}\n*{box-sizing:border-box;margin:0;padding:0;}html{scroll-behavior:smooth;}\nbody{background:var(--page);color:var(--ink);font-family:var(--sans);font-size:15px;line-height:1.75;}\n.hero{background:var(--ink);color:#e8e4dc;padding:72px 24px 56px;position:relative;overflow:hidden;}\n.hero::before{content:'';position:absolute;inset:0;background:repeating-linear-gradient(45deg,transparent,transparent 40px,rgba(255,255,255,.015) 40px,rgba(255,255,255,.015) 41px);}\n.hero-inner{max-width:960px;margin:0 auto;position:relative;}\n.hero-tag{font-family:var(--mono);font-size:10px;letter-spacing:4px;color:#6a6458;text-transform:uppercase;margin-bottom:20px;}\nh1{font-family:var(--serif);font-size:clamp(32px,5vw,58px);font-weight:900;line-height:1.05;letter-spacing:-.5px;margin-bottom:20px;color:#f0ece4;}\nh1 em{color:#e8b84b;font-style:normal;}\n.hero-sub{font-size:15px;color:#7a7060;max-width:640px;line-height:1.7;margin-bottom:32px;}\n.db-pills{display:flex;flex-wrap:wrap;gap:8px;}\n.db-pill{font-family:var(--mono);font-size:10px;padding:5px 14px;border-radius:3px;border:1px solid;letter-spacing:.5px;}\n.pill-pg{border-color:#336791;color:#336791;background:rgba(51,103,145,.08);}\n.pill-mg{border-color:#13aa52;color:#13aa52;background:rgba(19,170,82,.08);}\n.pill-dy{border-color:#ff9900;color:#cc7a00;background:rgba(255,153,0,.08);}\n.pill-ca{border-color:#1287b1;color:#1287b1;background:rgba(18,135,177,.08);}\n.nav{position:sticky;top:0;z-index:100;background:var(--ink);border-bottom:1px solid #1e1c18;display:flex;overflow-x:auto;scrollbar-width:none;padding:0 20px;}\n.nav::-webkit-scrollbar{display:none;}\n.nav a{font-family:var(--mono);font-size:10px;letter-spacing:1px;color:#4a4840;text-decoration:none;padding:14px 12px;white-space:nowrap;border-bottom:2px solid transparent;transition:.18s;}\n.nav a:hover{color:#e8b84b;border-color:#e8b84b;}\n.wrap{max-width:960px;margin:0 auto;padding:0 20px;}\nsection{padding:56px 0 36px;border-bottom:2px solid var(--border);}\nsection:last-child{border:none;}\n.sec-tag{font-family:var(--mono);font-size:9px;letter-spacing:4px;text-transform:uppercase;color:var(--muted);margin-bottom:8px;display:flex;align-items:center;gap:10px;}\n.sec-tag::before{content:'';width:20px;height:1px;background:var(--border);}\nh2{font-family:var(--serif);font-size:clamp(22px,3.5vw,32px);font-weight:700;line-height:1.15;margin-bottom:18px;}\nh3{font-family:var(--sans);font-size:17px;font-weight:600;margin:32px 0 10px;border-bottom:1px solid var(--border);padding-bottom:6px;}\nh4{font-size:13px;font-weight:600;margin:16px 0 6px;text-transform:uppercase;letter-spacing:.5px;}\np{color:#3a3830;font-size:14.5px;margin-bottom:12px;}\nstrong{color:var(--ink);}\ncode{font-family:var(--mono);font-size:11.5px;background:var(--surface2);padding:1px 5px;border-radius:3px;color:var(--blue);}\n.db-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:14px;margin:24px 0;}\n.db-card{background:white;border:1px solid var(--border);border-radius:8px;padding:20px;position:relative;overflow:hidden;}\n.db-card::before{content:'';position:absolute;top:0;left:0;right:0;height:4px;}\n.db-card.pg::before{background:var(--pg);}\n.db-card.mg::before{background:var(--mg);}\n.db-card.dy::before{background:var(--dy);}\n.db-card.ca::before{background:var(--ca);}\n.db-logo{font-size:22px;margin-bottom:6px;}\n.db-name{font-family:var(--serif);font-size:17px;font-weight:700;margin-bottom:4px;}\n.db-type{font-family:var(--mono);font-size:9px;letter-spacing:2px;color:var(--muted);margin-bottom:10px;text-transform:uppercase;}\n.db-tagline{font-size:13px;color:#5a5848;line-height:1.55;}\n.db-born{font-family:var(--mono);font-size:9px;color:var(--muted);margin-top:8px;}\n.analogy{background:var(--ink);color:#c8c4b8;border-radius:8px;padding:24px 28px;margin:24px 0;}\n.analogy-label{font-family:var(--mono);font-size:9px;letter-spacing:3px;color:#6a6458;margin-bottom:10px;text-transform:uppercase;}\n.analogy-text{font-size:15px;line-height:1.75;color:#d8d4c8;}\n.analogy-text strong{color:#e8b84b;}\n.callout{border-radius:4px;padding:14px 18px;margin:18px 0;font-size:13.5px;border-left:3px solid;line-height:1.65;}\n.callout p{font-size:13.5px;margin-bottom:6px;}\n.callout p:last-child{margin:0;}\n.cl-blue{background:var(--blue-bg);border-color:var(--blue);color:#1a2a4a;}\n.cl-green{background:var(--green-bg);border-color:var(--green);color:#0a2a1a;}\n.cl-amber{background:var(--amber-bg);border-color:var(--amber);color:#3a2a08;}\n.cl-red{background:var(--red-bg);border-color:var(--red);color:#3a0a08;}\n.cl-lbl{font-family:var(--mono);font-size:9px;letter-spacing:3px;text-transform:uppercase;margin-bottom:6px;opacity:.7;}\n.codeblock{background:var(--ink);border-radius:6px;padding:20px 22px;font-family:var(--mono);font-size:11.5px;line-height:2;overflow-x:auto;margin:14px 0;color:#c8c4b8;border:1px solid #1e1c18;}\n.codeblock .c{color:#3e3d36;}.codeblock .k{color:#e8b84b;}.codeblock .s{color:#8bc4a0;}.codeblock .n{color:#e8946a;}.codeblock .t{color:#7aaee0;}.codeblock .g{color:#a8d878;}.codeblock .r{color:#e87878;}\n.comp-table{width:100%;border-collapse:collapse;margin:20px 0;font-size:13px;}\n.comp-table th{padding:10px 14px;border:1px solid var(--border);background:var(--surface2);font-family:var(--mono);font-size:9px;letter-spacing:1.5px;text-transform:uppercase;color:var(--muted);}\n.comp-table td{padding:11px 14px;border:1px solid var(--border);vertical-align:top;color:#3a3830;line-height:1.6;}\n.comp-table .row-head{font-family:var(--mono);font-size:11px;font-weight:600;background:var(--surface);color:var(--ink);white-space:nowrap;}\n.good{color:var(--green);font-weight:600;}.warn{color:var(--amber);font-weight:600;}.bad{color:var(--red);font-weight:600;}\n.dot{display:inline-block;width:9px;height:9px;border-radius:50%;margin-right:4px;vertical-align:middle;}\n.dot.g{background:var(--green);}.dot.a{background:var(--amber);}.dot.r{background:var(--red);}\n.use-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:14px;margin:20px 0;}\n.use-card{border:1px solid var(--border);border-radius:6px;padding:18px;background:white;}\n.use-card-head{font-family:var(--mono);font-size:11px;font-weight:600;margin-bottom:10px;display:flex;align-items:center;gap:8px;}\n.use-card ul{padding-left:16px;font-size:13px;color:#4a4838;line-height:1.7;}\n.use-card ul li{margin-bottom:4px;}\n.shard-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:14px;margin:20px 0;}\n.shard-card{background:var(--ink);border-radius:8px;padding:20px;color:#c8c4b8;}\n.shard-title{font-family:var(--mono);font-size:10px;letter-spacing:2px;color:#6a6458;margin-bottom:10px;text-transform:uppercase;}\n.shard-name{font-family:var(--serif);font-size:16px;font-weight:700;color:#e8b84b;margin-bottom:8px;}\n.shard-body{font-size:12.5px;line-height:1.65;color:#a8a49c;}\n.shard-verdict{margin-top:10px;font-family:var(--mono);font-size:10px;padding:4px 10px;border-radius:3px;display:inline-block;}\n.sv-easy{background:rgba(26,122,74,.2);color:#5ac882;}.sv-med{background:rgba(184,114,10,.2);color:#e8943a;}.sv-hard{background:rgba(192,57,43,.2);color:#e87868;}\n.faq-item{border:1px solid var(--border);border-radius:4px;margin-bottom:8px;overflow:hidden;}\n.faq-q{padding:14px 18px;display:flex;justify-content:space-between;align-items:center;cursor:pointer;background:white;font-size:14px;font-weight:500;color:var(--ink);user-select:none;}\n.faq-q:hover{background:var(--surface);}\n.faq-q .tog{font-size:18px;color:#e8b84b;flex-shrink:0;margin-left:12px;transition:transform .2s;font-family:var(--mono);}\n.faq-a{display:none;padding:18px;background:var(--surface);font-size:13.5px;color:#3a3830;line-height:1.75;border-top:1px solid var(--border);}\n.faq-item.open .faq-a{display:block;}.faq-item.open .tog{transform:rotate(45deg);}\n.sd-example{background:white;border:1px solid var(--border);border-radius:8px;margin:20px 0;overflow:hidden;}\n.sd-example-head{background:var(--ink);padding:14px 20px;display:flex;align-items:center;gap:12px;}\n.sd-example-title{font-family:var(--serif);font-size:16px;color:#f0ece4;font-weight:700;}\n.sd-example-tag{font-family:var(--mono);font-size:9px;letter-spacing:2px;color:#6a6458;border:1px solid #2e2c28;padding:3px 8px;border-radius:2px;}\n.sd-example-body{padding:20px;}\n.choice-row{display:flex;gap:10px;align-items:flex-start;padding:10px 0;border-bottom:1px solid var(--border);font-size:13px;}\n.choice-row:last-child{border:none;}\n.choice-label{font-family:var(--mono);font-size:10px;letter-spacing:1px;color:var(--muted);width:120px;flex-shrink:0;padding-top:2px;}\n.choice-val{flex:1;color:#3a3830;line-height:1.6;}\n.badge{display:inline-block;font-family:var(--mono);font-size:9px;padding:2px 7px;border-radius:2px;border:1px solid;margin-right:4px;font-weight:500;}\n.b-pg{background:var(--pg-bg);border-color:var(--pg);color:var(--pg);}.b-mg{background:var(--mg-bg);border-color:var(--mg);color:var(--mg);}.b-dy{background:var(--dy-bg);border-color:var(--dy);color:#b06000;}.b-ca{background:var(--ca-bg);border-color:var(--ca);color:var(--ca);}.b-g{background:var(--green-bg);border-color:var(--green);color:var(--green);}.b-r{background:var(--red-bg);border-color:var(--red);color:var(--red);}.b-a{background:var(--amber-bg);border-color:var(--amber);color:var(--amber);}\n.footer{background:var(--ink);text-align:center;padding:36px 20px;font-family:var(--mono);font-size:10px;color:#3a3830;letter-spacing:2px;}\n\n.step-block{background:#fff;border:1px solid var(--border);border-radius:8px;margin:20px 0;overflow:hidden;}\n.step-block-header{background:var(--ink);color:#e8e4dc;padding:13px 18px;font-family:var(--mono);font-size:10px;letter-spacing:2px;text-transform:uppercase;display:flex;align-items:center;gap:10px;}\n.sb-icon{font-size:16px;}\n.step-block-body{padding:0;}\n.step-row{display:flex;gap:0;border-bottom:1px solid var(--border);}\n.step-row:last-child{border-bottom:none;}\n.step-num{background:var(--surface);min-width:46px;display:flex;align-items:flex-start;justify-content:center;padding:16px 6px;font-family:var(--mono);font-size:11px;font-weight:700;color:var(--muted);flex-shrink:0;border-right:1px solid var(--border);}\n.step-content{padding:14px 18px;flex:1;}\n.step-q{font-weight:600;font-size:14px;color:var(--ink);margin-bottom:10px;}\n.step-options{display:flex;flex-direction:column;gap:6px;}\n.step-option{display:flex;gap:10px;align-items:flex-start;padding:9px 13px;border-radius:5px;font-size:13px;line-height:1.65;}\n.opt-yes{background:#edf8f2;border:1px solid #b8ddc8;}\n.opt-no{background:#fdf6e8;border:1px solid #e8c870;}\n.opt-mid{background:#edf2fb;border:1px solid #b8c8e8;}\n.opt-any{background:#f4f0fb;border:1px solid #c8b8e8;}\n.opt-arrow{font-family:var(--mono);font-size:12px;font-weight:700;flex-shrink:0;margin-top:1px;min-width:120px;}\n.opt-yes .opt-arrow{color:#1a7a4a;}\n.opt-no .opt-arrow{color:#b8720a;}\n.opt-mid .opt-arrow{color:#1a4f8a;}\n.opt-any .opt-arrow{color:#5a3c9a;}\n.opt-text{flex:1;color:#3a3830;}\n.concept-grid{display:grid;grid-template-columns:1fr;gap:0;margin:20px 0;border:1px solid var(--border);border-radius:8px;overflow:hidden;}\n.concept-row{display:flex;gap:0;border-bottom:1px solid var(--border);}\n.concept-row:last-child{border-bottom:none;}\n.concept-term{background:var(--ink);color:#e8b84b;font-family:var(--mono);font-size:11.5px;font-weight:600;min-width:155px;padding:14px 16px;flex-shrink:0;border-right:1px solid #2a2820;display:flex;align-items:flex-start;line-height:1.5;}\n.concept-def{padding:13px 16px;flex:1;font-size:13.5px;color:#3a3830;line-height:1.7;background:#fff;}\n.concept-def strong{color:var(--ink);}\n.concept-def code{background:var(--surface);padding:1px 5px;border-radius:3px;font-family:var(--mono);font-size:11px;color:var(--blue);}\n@media(max-width:560px){.concept-row{flex-direction:column;}.concept-term{min-width:auto;border-right:none;border-bottom:1px solid #2a2820;}.opt-arrow{min-width:80px;}}\n\n\n\n.tier-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:14px;margin:24px 0;}\n.tier-card{background:white;border:1px solid var(--border);border-radius:8px;padding:20px;position:relative;overflow:hidden;}\n.tier-card::before{content:'';position:absolute;top:0;left:0;right:0;height:4px;}\n.tier-card.hot::before{background:var(--red);}\n.tier-card.warm::before{background:var(--amber);}\n.tier-card.cold::before{background:var(--blue);}\n.tier-card.cdn::before{background:var(--green);}\n\n</style>\n</head>\n<body>\n<div class=\"hero\">\n  <div class=\"hero-inner\">\n    <div class=\"hero-tag\">System Design \u00b7 FAANG Interview Prep \u00b7 Manish-Almanac</div>\n    <h1>Caching<br><em>Redis, Memcached & CDN</em></h1>\n    <p class=\"hero-sub\">Every caching strategy, eviction policy, Redis data structure, and invalidation pattern \u2014 explained from first principles with real system design examples.</p>\n    <div class=\"db-pills\"><span class=\"db-pill\" style=\"border-color:#c0392b;color:#c0392b;background:rgba(192,57,43,.08)\">Redis</span><span class=\"db-pill\" style=\"border-color:#1a7a4a;color:#1a7a4a;background:rgba(26,122,74,.08)\">Memcached</span><span class=\"db-pill\" style=\"border-color:#1a4f8a;color:#1a4f8a;background:rgba(26,79,138,.08)\">Cache-Aside</span><span class=\"db-pill\" style=\"border-color:#b8720a;color:#b8720a;background:rgba(184,114,10,.08)\">Write-Through</span><span class=\"db-pill\" style=\"border-color:#6040a0;color:#6040a0;background:rgba(96,64,160,.08)\">Eviction</span><span class=\"db-pill\" style=\"border-color:#1287b1;color:#1287b1;background:rgba(18,135,177,.08)\">CDN</span></div>\n  </div>\n</div>\n<nav class=\"nav\"><a href=\"#why\">Why Cache</a><a href=\"#hierarchy\">Hierarchy</a><a href=\"#strategies\">Write Strategies</a><a href=\"#eviction\">Eviction</a><a href=\"#redis\">Redis Deep Dive</a><a href=\"#examples\">System Design</a><a href=\"#decision\">Decision Tree</a><a href=\"#followups\">Follow-ups</a></nav>\n<div class=\"wrap\">\n\n<section id=\"why\">\n  <div class=\"sec-tag\">00 \u00b7 Why Caching Exists</div>\n  <h2>The single reason every system needs a cache</h2>\n  <p>A database read on a cold system takes 1\u201310ms. A cache hit takes 0.1\u20131ms. At 100K requests/sec, that difference is the line between a system that works and one that collapses. But caching is not just about speed \u2014 it is about <strong>protecting your database from traffic it was never designed to handle</strong>.</p>\n  <div class=\"analogy\">\n    <div class=\"analogy-label\">The library analogy \u2014 for a complete layman</div>\n    <div class=\"analogy-text\">\n      A library (database) has every book ever written. But fetching any book takes a librarian 10 minutes. So you keep the 100 most popular books on a desk beside you (cache). When someone asks for a book, you check your desk first. 99% of the time it's there \u2014 instant. Only 1% of requests require the 10-minute librarian trip.<br><br>\n      <strong>The cache hit rate is everything.</strong> A 99% hit rate means your database handles 1% of original traffic. A 90% hit rate means 10% \u2014 still 10x less. A 50% hit rate barely helps at all.\n    </div>\n  </div>\n  <div class=\"callout cl-amber\">\n    <div class=\"cl-lbl\">The interview framing</div>\n    <p>Never say \"I'll add a cache\" without answering: <strong>(1) What exactly gets cached?</strong> (2) What is the cache key? (3) When does it get invalidated? (4) What is the consistency trade-off? Interviewers give no credit for \"add Redis\" \u2014 they want the strategy.</p>\n  </div>\n</section>\n\n<section id=\"hierarchy\">\n  <div class=\"sec-tag\">01 \u00b7 Cache Hierarchy</div>\n  <h2>The four layers \u2014 where caching lives</h2>\n  <div class=\"tier-grid\">\n    <div class=\"tier-card cdn\">\n      <div class=\"db-logo\">\ud83c\udf0d</div>\n      <div class=\"db-name\">CDN Edge Cache</div>\n      <div class=\"db-type\">Nearest PoP \u00b7 HTTP \u00b7 Global</div>\n      <div class=\"db-tagline\">Caches static assets and cacheable API responses at 200+ edge nodes worldwide. Serves from &lt;10ms anywhere. Absorbs 90\u201399% of static traffic before it touches your servers.</div>\n      <div class=\"db-born\">Cloudflare \u00b7 Fastly \u00b7 Akamai \u00b7 AWS CloudFront</div>\n    </div>\n    <div class=\"tier-card hot\">\n      <div class=\"db-logo\">\ud83d\udd25</div>\n      <div class=\"db-name\">Application Cache</div>\n      <div class=\"db-type\">In-Process \u00b7 RAM \u00b7 Single Node</div>\n      <div class=\"db-tagline\">In-memory cache inside the application process (Guava Cache, Caffeine, Python dict). Sub-microsecond access. No network hop. Limited to one server's RAM. Not shared across instances.</div>\n      <div class=\"db-born\">Caffeine (Java) \u00b7 Guava \u00b7 Python functools.lru_cache</div>\n    </div>\n    <div class=\"tier-card warm\">\n      <div class=\"db-logo\">\u26a1</div>\n      <div class=\"db-name\">Distributed Cache</div>\n      <div class=\"db-type\">Shared \u00b7 Network \u00b7 Multi-Node</div>\n      <div class=\"db-tagline\">Shared cache accessible by all app servers. Sub-millisecond over LAN. Survives server restarts. The default choice for any horizontally-scaled system \u2014 all app instances share the same view.</div>\n      <div class=\"db-born\">Redis \u00b7 Memcached \u00b7 AWS ElastiCache \u00b7 Aerospike</div>\n    </div>\n    <div class=\"tier-card cold\">\n      <div class=\"db-logo\">\ud83d\uddc4\ufe0f</div>\n      <div class=\"db-name\">Database Buffer Pool</div>\n      <div class=\"db-type\">Internal \u00b7 OS Page Cache \u00b7 Transparent</div>\n      <div class=\"db-tagline\">PostgreSQL/MySQL's internal page cache. Frequently accessed pages stay in RAM automatically. You don't control it directly \u2014 but proper indexing ensures hot data stays cached here.</div>\n      <div class=\"db-born\">PostgreSQL shared_buffers \u00b7 InnoDB buffer pool \u00b7 OS page cache</div>\n    </div>\n  </div>\n</section>\n\n<section id=\"strategies\">\n  <div class=\"sec-tag\">02 \u00b7 Write Strategies</div>\n  <h2>The four write patterns \u2014 this is what interviewers test</h2>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">Cache-Aside<br><span style=\"font-size:10px;font-weight:400;color:#6a6458\">(Lazy Loading)</span></div>\n      <div class=\"concept-def\"><strong>Application manages the cache explicitly. Most common pattern.</strong><br>\n        Read: check cache \u2192 if miss, read DB \u2192 write result to cache \u2192 return.<br>\n        Write: write to DB \u2192 <em>invalidate or update</em> cache entry.<br>\n        <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Only caches data that is actually requested. Cache can survive a restart (just misses until warmed). Resilient \u2014 cache failure doesn't break reads.</span><br>\n        <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 Cache miss penalty: 3 operations instead of 1. Race condition: two threads can miss simultaneously, both read DB, both write cache (use distributed lock or short TTL).</span><br>\n        <span style=\"color:#5a5848;font-size:12.5px;\">Used by: most read-heavy systems \u2014 social feeds, product pages, user profiles.</span>\n      </div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">Write-Through</div>\n      <div class=\"concept-def\"><strong>Every write goes to cache AND database synchronously before returning.</strong><br>\n        Write: write cache \u2192 write DB \u2192 return success.<br>\n        Read: always hits cache (always fresh).<br>\n        <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Cache is always consistent with DB. No stale reads. No cache miss on subsequent reads.</span><br>\n        <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 Write latency = cache write + DB write (two hops). Caches data that may never be read (write-heavy systems waste cache space).</span><br>\n        <span style=\"color:#5a5848;font-size:12.5px;\">Used by: systems where reads must be fresh \u2014 financial dashboards, inventory systems.</span>\n      </div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">Write-Behind<br><span style=\"font-size:10px;font-weight:400;color:#6a6458\">(Write-Back)</span></div>\n      <div class=\"concept-def\"><strong>Write to cache immediately, persist to DB asynchronously in the background.</strong><br>\n        Write: write cache \u2192 return success \u2192 background job flushes to DB.<br>\n        <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Fastest write latency \u2014 single cache write. Batches DB writes (10x fewer DB operations). Great for high-write-frequency data (view counters, like counts).</span><br>\n        <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 Data loss risk: if cache crashes before flush, writes are lost. Not safe for financial data. Complex recovery logic needed.</span><br>\n        <span style=\"color:#5a5848;font-size:12.5px;\">Used by: counters, analytics, non-critical state. Redis itself uses write-back for AOF persistence.</span>\n      </div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">Refresh-Ahead<br><span style=\"font-size:10px;font-weight:400;color:#6a6458\">(Read-Through)</span></div>\n      <div class=\"concept-def\"><strong>Cache automatically refreshes hot entries before they expire, predicting future reads.</strong><br>\n        Cache layer intercepts reads. On miss: fetches from DB, caches, returns. Proactively re-fetches keys nearing expiry if they were recently accessed.<br>\n        <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 No cache miss latency for hot data. Application code never touches DB directly \u2014 clean separation.</span><br>\n        <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 May cache stale data if prediction is wrong. Requires a separate refresh thread/process.</span><br>\n        <span style=\"color:#5a5848;font-size:12.5px;\">Used by: read-through cache libraries (Ehcache, Spring Cache), Redis with background refresh logic.</span>\n      </div>\n    </div>\n  </div>\n\n  <h3>Cache Invalidation \u2014 The Hardest Problem in Caching</h3>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">TTL (Time-to-Live)</div>\n      <div class=\"concept-def\"><strong>Every cache entry expires after N seconds.</strong> Simplest approach. After expiry, next read re-fetches from DB.<br>\n        <code>SET user:123 {json} EX 3600</code> \u2014 expires in 1 hour.<br>\n        <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 No invalidation logic needed. Self-healing \u2014 stale data auto-purges.</span><br>\n        <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 Data is stale for up to TTL seconds after an update. TTL too short = many misses. TTL too long = stale data shown to users.</span>\n      </div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">Event-Driven<br>Invalidation</div>\n      <div class=\"concept-def\"><strong>When data changes, explicitly delete or update the cache entry.</strong><br>\n        User updates profile \u2192 <code>DEL user:123</code> in Redis \u2192 next read re-fetches fresh data.<br>\n        <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Immediately consistent. No stale window.</span><br>\n        <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 Cache and DB writes must be atomic \u2014 if cache delete succeeds but DB write fails (or vice versa), you have inconsistency. Use transactional outbox pattern or delete-after-DB-commit.</span>\n      </div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">Cache Stampede<br><span style=\"font-size:10px;font-weight:400;color:#6a6458\">(Thundering Herd)</span></div>\n      <div class=\"concept-def\"><strong>A popular key expires \u2192 thousands of simultaneous requests all miss \u2192 all hit the DB simultaneously \u2192 DB falls over.</strong><br>\n        Scenario: trending video cached with 10-minute TTL. At expiry, 50K requests/sec all miss simultaneously.<br>\n        <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 The cache that was protecting your DB is now the reason your DB dies.</span><br>\n        <strong>Fixes:</strong><br>\n        \u2022 <strong>Mutex lock</strong>: first thread to miss acquires a lock, fetches DB, populates cache. Others wait, then read from cache.<br>\n        \u2022 <strong>Probabilistic early expiry</strong>: slightly before TTL, a fraction of requests proactively refresh.<br>\n        \u2022 <strong>Jitter</strong>: randomise TTL (\u00b110%) so not all keys expire simultaneously.<br>\n        \u2022 <strong>Stale-while-revalidate</strong>: return stale value immediately, refresh in background.\n      </div>\n    </div>\n  </div>\n</section>\n\n<section id=\"eviction\">\n  <div class=\"sec-tag\">03 \u00b7 Eviction Policies</div>\n  <h2>What gets removed when the cache is full</h2>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\"><div class=\"concept-term\">LRU<br>(Least Recently Used)</div><div class=\"concept-def\"><strong>Evict the entry that was accessed longest ago.</strong> Implemented as a doubly-linked list + hashmap. O(1) get and put. Most common default.<br><span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Works well when recency correlates with future access. A user just viewed their profile \u2014 it should stay cached.</span><br><span style=\"color:#b83030;font-size:12.5px;\">\u26a0 A single large sequential scan (backup job reading all users) pollutes the cache with one-time data, evicting actually-hot entries.</span><br><span style=\"color:#5a5848;font-size:12.5px;\">Redis default policy: allkeys-lru. Used by: most web application caches.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">LFU<br>(Least Frequently Used)</div><div class=\"concept-def\"><strong>Evict the entry accessed fewest times total.</strong> Tracks a frequency counter per key. O(1) with a min-heap + frequency buckets (complex implementation).<br><span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Better for workloads with stable hot keys (celebrity user profiles, popular products). Resists cache pollution from one-time scans.</span><br><span style=\"color:#b83030;font-size:12.5px;\">\u26a0 New keys start with frequency=1 \u2014 they get evicted immediately even if they'll be accessed 1M times tomorrow. Requires frequency decay to handle shifting popularity.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">TTL-Based</div><div class=\"concept-def\"><strong>Evict entries whose TTL has expired.</strong> Passive expiry (evict on access if expired) + active expiry (background sweep). Redis uses both.<br><span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Natural fit for session caches, API response caches where staleness has a defined bound.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Redis Policies</div><div class=\"concept-def\"><strong>Redis has 8 eviction policies. The most important:</strong><br>\n      <code>noeviction</code> \u2014 return error when full (safest, but breaks writes)<br>\n      <code>allkeys-lru</code> \u2014 LRU across all keys (most common)<br>\n      <code>volatile-lru</code> \u2014 LRU only among keys with TTL set<br>\n      <code>allkeys-lfu</code> \u2014 LFU across all keys (Redis 4+)<br>\n      <code>allkeys-random</code> \u2014 random eviction (surprisingly effective for uniform workloads)<br>\n      <span style=\"color:#5a5848;font-size:12.5px;\">Set via <code>maxmemory-policy</code> config. Always set <code>maxmemory</code> or Redis will consume all available RAM.</span>\n    </div></div>\n  </div>\n</section>\n\n<section id=\"redis\">\n  <div class=\"sec-tag\">04 \u00b7 Redis Deep Dive</div>\n  <h2>Redis data structures \u2014 the right tool for each problem</h2>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\"><div class=\"concept-term\">String</div><div class=\"concept-def\"><strong>Binary-safe value up to 512MB. The catch-all type.</strong><br>\n      Use for: JSON blobs, HTML fragments, counters, session tokens.<br>\n      <code>SET user:123 \"{name:Alice}\" EX 3600</code><br>\n      <code>INCR pageview:home</code> \u2014 atomic counter, no race condition.<br>\n      <span style=\"color:#5a5848;font-size:12.5px;\">INCR/DECR are atomic \u2014 the only safe way to do distributed counters without locks.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Hash</div><div class=\"concept-def\"><strong>Field-value map within one key. Ideal for objects.</strong><br>\n      <code>HSET user:123 name Alice age 30 city Bangalore</code><br>\n      <code>HGET user:123 name</code> \u2014 fetch one field without deserializing the whole object.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 More memory-efficient than separate string keys per field. Update one field without reading/writing the entire object. Used by: user profiles, shopping carts.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Sorted Set (ZSET)</div><div class=\"concept-def\"><strong>Set of unique members, each with a float score. Ordered by score. O(log N) operations.</strong><br>\n      <code>ZADD leaderboard 9241038 user:alice</code><br>\n      <code>ZREVRANGE leaderboard 0 9 WITHSCORES</code> \u2014 top 10 with scores.<br>\n      <code>ZINCRBY leaderboard 847 vid:abc</code> \u2014 atomic increment.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 The backbone of Top-K, leaderboards, rate limiting windows, priority queues. Used by: Top-K system, gaming leaderboards, Twitter trending.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Set</div><div class=\"concept-def\"><strong>Unordered collection of unique strings. O(1) add/remove/lookup.</strong><br>\n      <code>SADD online:users user:123 user:456</code><br>\n      <code>SISMEMBER online:users user:123</code> \u2014 is user online?<br>\n      <code>SUNION followers:alice followers:bob</code> \u2014 union of sets.<br>\n      <span style=\"color:#5a5848;font-size:12.5px;\">Used for: online presence, unique visitors per day, tag systems, friend intersections (SINTER).</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">List</div><div class=\"concept-def\"><strong>Doubly-linked list. O(1) push/pop from both ends.</strong><br>\n      <code>LPUSH feed:user:123 post:789</code> \u2014 prepend to feed.<br>\n      <code>LRANGE feed:user:123 0 19</code> \u2014 fetch first 20 items.<br>\n      <code>BRPOP queue:emails 30</code> \u2014 blocking pop (simple message queue).<br>\n      <span style=\"color:#5a5848;font-size:12.5px;\">Used for: activity feeds, simple task queues, recent items lists. BRPOP pattern = lightweight job queue without Kafka overhead.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">HyperLogLog</div><div class=\"concept-def\"><strong>Probabilistic cardinality estimator. Counts unique items using ~12KB regardless of cardinality.</strong><br>\n      <code>PFADD unique:visitors:2026-03-21 user:123 user:456</code><br>\n      <code>PFCOUNT unique:visitors:2026-03-21</code> \u2014 returns ~100M unique visitors using 12KB RAM. Error rate: \u00b10.81%.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Count 1 billion unique visitors using 12KB. A HashSet for the same would need ~8GB. Used by: DAU metrics, unique video views, distinct IP counting.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Pub/Sub &amp; Streams</div><div class=\"concept-def\"><strong>Pub/Sub: fire-and-forget broadcasting. Streams: persistent, replayable event log (mini Kafka).</strong><br>\n      <code>PUBLISH notifications:user:123 \"New message from Alice\"</code><br>\n      <code>XADD events * type view entity_id vid_abc</code> \u2014 append to stream.<br>\n      <code>XREAD COUNT 100 STREAMS events 0</code> \u2014 read from stream.<br>\n      <span style=\"color:#5a5848;font-size:12.5px;\">Pub/Sub: real-time notifications between app servers. Streams: durable event log for small-scale streaming (not a Kafka replacement at scale).</span></div></div>\n  </div>\n\n  <h3>Redis Cluster vs Sentinel \u2014 When to Use Each</h3>\n  <div class=\"comp-table-wrap\">\n  <table class=\"comp-table\">\n    <thead><tr><th>Dimension</th><th>Redis Sentinel</th><th>Redis Cluster</th></tr></thead>\n    <tbody>\n      <tr><td class=\"row-head\">Purpose</td><td>High availability (HA) \u2014 automatic failover</td><td>Horizontal scaling + HA</td></tr>\n      <tr><td class=\"row-head\">Data distribution</td><td>All data on primary + replicas (full copy)</td><td>Sharded across 16,384 hash slots</td></tr>\n      <tr><td class=\"row-head\">Scaling</td><td>Scale reads via replicas; writes on one primary</td><td>Scale writes across multiple primaries</td></tr>\n      <tr><td class=\"row-head\">Max data</td><td>Single primary's RAM (~100s GB)</td><td>Sum of all primaries' RAM (TBs)</td></tr>\n      <tr><td class=\"row-head\">Multi-key ops</td><td><span class=\"good\">All supported</span></td><td><span class=\"warn\">Only if keys on same slot (use hash tags)</span></td></tr>\n      <tr><td class=\"row-head\">Complexity</td><td>Simple \u2014 just 3 sentinel nodes</td><td>Complex \u2014 resharding, gossip protocol</td></tr>\n      <tr><td class=\"row-head\">Use when</td><td>Dataset fits in one server's RAM</td><td>Dataset exceeds one server's RAM or need write scale-out</td></tr>\n    </tbody>\n  </table>\n  </div>\n</section>\n\n<section id=\"examples\">\n  <div class=\"sec-tag\">05 \u00b7 System Design Examples</div>\n  <h2>Caching decisions in real systems</h2>\n\n  <div class=\"sd-example\">\n    <div class=\"sd-example-head\"><div class=\"sd-example-title\">Twitter / X \u2014 Social Feed</div><span class=\"sd-example-tag\">READ-HEAVY \u00b7 FAN-OUT</span></div>\n    <div class=\"sd-example-body\">\n      <div class=\"choice-row\"><div class=\"choice-label\">FEED CACHE</div><div class=\"choice-val\"><span class=\"badge b-g\">Redis List \u2713</span> Each user's pre-computed feed stored as a Redis List (LPUSH on new tweet, LRANGE for reads). Cache-aside with TTL=24h. 99% of feed reads are cache hits \u2014 the DB never sees them. Key: <code>feed:user:{id}</code>.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">TWEET CONTENT</div><div class=\"choice-val\"><span class=\"badge b-g\">Redis String \u2713</span> Individual tweet JSON cached as a String with TTL=1h. Celebrity tweets get longer TTL (>24h) because they're read millions of times. Key: <code>tweet:{id}</code>.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">TRENDING</div><div class=\"choice-val\"><span class=\"badge b-g\">Redis ZSET \u2713</span> Hashtag counts in a sorted set. <code>ZINCRBY trending:1h #WorldCup 1</code> per event. <code>ZREVRANGE trending:1h 0 9</code> returns top 10. Sub-millisecond at any scale.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">INVALIDATION</div><div class=\"choice-val\">User deletes a tweet \u2192 <code>DEL tweet:{id}</code> + rebuild affected feeds. TTL as safety net for stale data. Eventual consistency is acceptable \u2014 seeing a deleted tweet for 1 minute is tolerable for Twitter's use case.</div></div>\n    </div>\n  </div>\n\n  <div class=\"sd-example\">\n    <div class=\"sd-example-head\"><div class=\"sd-example-title\">E-Commerce \u2014 Product Catalog</div><span class=\"sd-example-tag\">WRITE-RARE \u00b7 READ-HEAVY</span></div>\n    <div class=\"sd-example-body\">\n      <div class=\"choice-row\"><div class=\"choice-label\">PRODUCT PAGE</div><div class=\"choice-val\"><span class=\"badge b-g\">CDN + Redis \u2713</span> Static product HTML cached at CDN edge (TTL=10min). Inventory count cached in Redis String with TTL=30s. CDN handles 95% of product page traffic. Redis handles inventory checks without hitting DB.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">INVENTORY</div><div class=\"choice-val\"><span class=\"badge b-g\">Redis DECR \u2713</span> <code>DECRBY inventory:{sku} {qty}</code> \u2014 atomic decrement. If result &lt; 0, rollback: <code>INCRBY inventory:{sku} {qty}</code> and reject order. No DB needed for inventory check during purchase flow.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">FLASH SALE</div><div class=\"choice-val\">During a flash sale (10K requests/sec for one SKU), cache stampede risk is extreme. Solution: Redis lock (<code>SET lock:{sku} 1 NX EX 5</code>) + pre-warm cache 5 minutes before sale. Only the lock-holder refreshes the cache; others read stale value briefly.</div></div>\n    </div>\n  </div>\n</section>\n\n<section id=\"decision\">\n  <div class=\"sec-tag\">06 \u00b7 Decision Framework</div>\n  <h2>How to talk about caching in an interview</h2>\n  <div class=\"step-block\">\n    <div class=\"step-block-header\"><span class=\"sb-icon\">\ud83c\udfaf</span>Caching Strategy \u2014 Answer These in Order</div>\n    <div class=\"step-block-body\">\n      <div class=\"step-row\"><div class=\"step-num\">01</div><div class=\"step-content\">\n        <div class=\"step-q\">What is the read-to-write ratio?</div>\n        <div class=\"step-options\">\n          <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">Read-heavy (&gt;10:1) \u2192</span><span class=\"opt-text\"><strong>Cache aggressively.</strong> Cache-aside or read-through. High cache hit rate justifies complexity. Most social, e-commerce, and media systems fall here.</span></div>\n          <div class=\"step-option opt-no\"><span class=\"opt-arrow\">Write-heavy \u2192</span><span class=\"opt-text\"><strong>Cache carefully.</strong> Write-behind for non-critical counters. Cache invalidation complexity may outweigh benefit. Consider whether caching actually helps.</span></div>\n        </div>\n      </div></div>\n      <div class=\"step-row\"><div class=\"step-num\">02</div><div class=\"step-content\">\n        <div class=\"step-q\">Can you tolerate stale data? For how long?</div>\n        <div class=\"step-options\">\n          <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">Yes (seconds/minutes OK) \u2192</span><span class=\"opt-text\"><strong>TTL-based invalidation.</strong> Simple, no code coupling. Social feed, product descriptions, user profiles \u2014 all tolerate seconds of staleness.</span></div>\n          <div class=\"step-option opt-no\"><span class=\"opt-arrow\">No (must be fresh) \u2192</span><span class=\"opt-text\"><strong>Event-driven invalidation + write-through.</strong> Financial balances, inventory counts, seat availability \u2014 must be consistent. Use shorter TTL as safety net too.</span></div>\n        </div>\n      </div></div>\n      <div class=\"step-row\"><div class=\"step-num\">03</div><div class=\"step-content\">\n        <div class=\"step-q\">What is your data structure need?</div>\n        <div class=\"step-options\">\n          <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">Simple key-value \u2192</span><span class=\"opt-text\"><strong>Memcached</strong> (simpler, multi-threaded, pure LRU) or <strong>Redis String</strong>. Memcached is faster for simple string caching with multiple CPU cores.</span></div>\n          <div class=\"step-option opt-mid\"><span class=\"opt-arrow\">Rich structures (sorted sets, counters, lists) \u2192</span><span class=\"opt-text\"><strong>Redis.</strong> No contest. Sorted sets for leaderboards, atomic INCR for counters, Lists for queues, HyperLogLog for cardinality.</span></div>\n          <div class=\"step-option opt-no\"><span class=\"opt-arrow\">Persistence needed \u2192</span><span class=\"opt-text\"><strong>Redis with AOF/RDB.</strong> Memcached is pure in-memory \u2014 no persistence. Redis can persist to disk and survive restarts.</span></div>\n        </div>\n      </div></div>\n      <div class=\"step-row\"><div class=\"step-num\">04</div><div class=\"step-content\">\n        <div class=\"step-q\">What is the data size and access pattern?</div>\n        <div class=\"step-options\">\n          <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">Small hot dataset (&lt;100GB) \u2192</span><span class=\"opt-text\"><strong>Redis Sentinel.</strong> All data fits on one primary. Simple HA with automatic failover. No sharding complexity.</span></div>\n          <div class=\"step-option opt-no\"><span class=\"opt-arrow\">Large dataset or high write throughput \u2192</span><span class=\"opt-text\"><strong>Redis Cluster.</strong> Horizontal sharding across multiple primaries. Scale both data size and write throughput. More operational complexity.</span></div>\n        </div>\n      </div></div>\n    </div>\n  </div>\n</section>\n\n<section id=\"followups\">\n  <div class=\"sec-tag\">07 \u00b7 Interview Follow-ups</div>\n  <h2>Every hard follow-up, answered</h2>\n  <div class=\"faq-item\"><div class=\"faq-q\" onclick=\"toggle(this)\">Redis is single-threaded \u2014 how does it handle 1M requests/sec?<span class=\"tog\">+</span></div>\n  <div class=\"faq-a\"><strong>Redis's event loop is single-threaded for command processing, but that is actually its strength, not its weakness.</strong><br><br>Since commands execute serially, there are no lock contention or deadlock issues. Redis commands are in-memory operations taking microseconds \u2014 the bottleneck is never CPU, it is always network I/O. Redis 6+ added multithreaded I/O for reading/writing the network buffers, while keeping command execution single-threaded. Result: 1\u201310M operations/sec on a single instance depending on command complexity and payload size.<br><br>When you need more throughput: Redis Cluster shards load across multiple independent single-threaded instances. 10 nodes = ~10M ops/sec aggregate throughput.</div></div>\n  <div class=\"faq-item\"><div class=\"faq-q\" onclick=\"toggle(this)\">How do you handle cache consistency in a microservices architecture?<span class=\"tog\">+</span></div>\n  <div class=\"faq-a\"><strong>This is one of the hardest distributed systems problems. Three patterns, in order of complexity:</strong><br><br><strong>1. TTL + eventual consistency</strong>: Each service caches with a short TTL (30s\u20135min). Stale data is guaranteed to expire. Simple, no coordination. Works for most social/media use cases where slight staleness is acceptable.<br><br><strong>2. Event-driven invalidation</strong>: When Service A updates user data, it publishes a <code>UserUpdated</code> event to Kafka. Service B consumes the event and deletes/updates its cache. Consistent eventually. Risk: if the event is lost, cache stays stale indefinitely \u2014 mitigate with TTL as backup.<br><br><strong>3. Cache ownership</strong>: Each data domain is owned by one service. Other services must call that service's API to read data \u2014 they cannot cache it themselves. Eliminates invalidation problem entirely at the cost of added latency on every cross-service read.</div></div>\n  <div class=\"faq-item\"><div class=\"faq-q\" onclick=\"toggle(this)\">What is the difference between Redis and Memcached? When do you pick each?<span class=\"tog\">+</span></div>\n  <div class=\"faq-a\"><strong>Memcached is a simpler, faster, multi-threaded string cache. Redis is a full data structure server.</strong><br><br><strong>Pick Memcached when:</strong> You need pure key-value string caching, you have a multi-core server and want to saturate all cores (Memcached is truly multi-threaded), you do not need persistence or replication, and you want the absolute simplest operational footprint.<br><br><strong>Pick Redis when:</strong> You need any data structure beyond strings (sorted sets, lists, hashes), you need atomic operations (INCR, LPUSH), you need persistence (AOF/RDB for crash recovery), you need Pub/Sub or Streams, or you need built-in replication and cluster mode.<br><br><strong>In practice at FAANG:</strong> Redis has won. The operational overhead of maintaining two different cache systems (Redis for rich structures, Memcached for simple caching) is rarely worth the marginal performance difference. Most teams standardize on Redis for everything.</div></div>\n  <div class=\"faq-item\"><div class=\"faq-q\" onclick=\"toggle(this)\">How does Redis persistence work \u2014 RDB vs AOF?<span class=\"tog\">+</span></div>\n  <div class=\"faq-a\"><strong>Redis has two persistence mechanisms that can be used independently or together.</strong><br><br><strong>RDB (Redis Database Backup)</strong>: Point-in-time snapshot written to disk periodically (every N seconds if M keys changed). Fast to restore \u2014 single compact binary file. Risk: data since last snapshot is lost on crash. Used for: disaster recovery, backups, cache warm-up after restart.<br><br><strong>AOF (Append-Only File)</strong>: Every write command is appended to a log file. On restart, Redis replays the log. Three fsync options: always (safest, slowest), every second (good balance \u2014 max 1 second data loss), never (OS decides, fastest). AOF rewrite periodically compacts the log. Used for: when you cannot afford data loss.<br><br><strong>Recommendation</strong>: Use both for critical data \u2014 RDB for fast restarts + AOF for durability. For pure cache use cases where data can be reconstructed from the DB, disable persistence entirely for maximum performance.</div></div>\n</section>\n\n</div>\n<div class=\"footer\">CACHING \u00b7 REDIS \u00b7 MEMCACHED \u00b7 EVICTION \u00b7 INVALIDATION \u00b7 CDN \u00b7 MANISH-ALMANAC</div>\n\u003cscript>function toggle(el){el.parentElement.classList.toggle('open');}<\/script>\n</body>\n</html>", tag: 'Caching' },
  consistent_hashing: { title: 'Consistent Hashing', srcdoc: "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Consistent Hashing: Partitioning at Scale</title>\n<link href=\"https://fonts.googleapis.com/css2?family=Playfair+Display:wght@700;900&family=Source+Sans+3:wght@300;400;500;600&family=JetBrains+Mono:wght@400;600&display=swap\" rel=\"stylesheet\">\n<style>\n\n:root{--ink:#0f0e0c;--page:#f7f5f0;--surface:#eeecea;--surface2:#e5e2dc;--border:#d4d0c8;--muted:#7a7568;--pg:#336791;--pg-bg:#eef4fb;--mg:#13aa52;--mg-bg:#edfaf2;--dy:#ff9900;--dy-bg:#fff8ec;--ca:#1287b1;--ca-bg:#eaf6fb;--red:#c0392b;--red-bg:#fdf0ee;--green:#1a7a4a;--green-bg:#edf8f2;--amber:#b8720a;--amber-bg:#fdf6e8;--blue:#1a4f8a;--blue-bg:#edf2fb;--mono:'JetBrains Mono',monospace;--serif:'Playfair Display',serif;--sans:'Source Sans 3',sans-serif;}\n*{box-sizing:border-box;margin:0;padding:0;}html{scroll-behavior:smooth;}\nbody{background:var(--page);color:var(--ink);font-family:var(--sans);font-size:15px;line-height:1.75;}\n.hero{background:var(--ink);color:#e8e4dc;padding:72px 24px 56px;position:relative;overflow:hidden;}\n.hero::before{content:'';position:absolute;inset:0;background:repeating-linear-gradient(45deg,transparent,transparent 40px,rgba(255,255,255,.015) 40px,rgba(255,255,255,.015) 41px);}\n.hero-inner{max-width:960px;margin:0 auto;position:relative;}\n.hero-tag{font-family:var(--mono);font-size:10px;letter-spacing:4px;color:#6a6458;text-transform:uppercase;margin-bottom:20px;}\nh1{font-family:var(--serif);font-size:clamp(32px,5vw,58px);font-weight:900;line-height:1.05;letter-spacing:-.5px;margin-bottom:20px;color:#f0ece4;}\nh1 em{color:#e8b84b;font-style:normal;}\n.hero-sub{font-size:15px;color:#7a7060;max-width:640px;line-height:1.7;margin-bottom:32px;}\n.db-pills{display:flex;flex-wrap:wrap;gap:8px;}\n.db-pill{font-family:var(--mono);font-size:10px;padding:5px 14px;border-radius:3px;border:1px solid;letter-spacing:.5px;}\n.pill-pg{border-color:#336791;color:#336791;background:rgba(51,103,145,.08);}\n.pill-mg{border-color:#13aa52;color:#13aa52;background:rgba(19,170,82,.08);}\n.pill-dy{border-color:#ff9900;color:#cc7a00;background:rgba(255,153,0,.08);}\n.pill-ca{border-color:#1287b1;color:#1287b1;background:rgba(18,135,177,.08);}\n.nav{position:sticky;top:0;z-index:100;background:var(--ink);border-bottom:1px solid #1e1c18;display:flex;overflow-x:auto;scrollbar-width:none;padding:0 20px;}\n.nav::-webkit-scrollbar{display:none;}\n.nav a{font-family:var(--mono);font-size:10px;letter-spacing:1px;color:#4a4840;text-decoration:none;padding:14px 12px;white-space:nowrap;border-bottom:2px solid transparent;transition:.18s;}\n.nav a:hover{color:#e8b84b;border-color:#e8b84b;}\n.wrap{max-width:960px;margin:0 auto;padding:0 20px;}\nsection{padding:56px 0 36px;border-bottom:2px solid var(--border);}\nsection:last-child{border:none;}\n.sec-tag{font-family:var(--mono);font-size:9px;letter-spacing:4px;text-transform:uppercase;color:var(--muted);margin-bottom:8px;display:flex;align-items:center;gap:10px;}\n.sec-tag::before{content:'';width:20px;height:1px;background:var(--border);}\nh2{font-family:var(--serif);font-size:clamp(22px,3.5vw,32px);font-weight:700;line-height:1.15;margin-bottom:18px;}\nh3{font-family:var(--sans);font-size:17px;font-weight:600;margin:32px 0 10px;border-bottom:1px solid var(--border);padding-bottom:6px;}\nh4{font-size:13px;font-weight:600;margin:16px 0 6px;text-transform:uppercase;letter-spacing:.5px;}\np{color:#3a3830;font-size:14.5px;margin-bottom:12px;}\nstrong{color:var(--ink);}\ncode{font-family:var(--mono);font-size:11.5px;background:var(--surface2);padding:1px 5px;border-radius:3px;color:var(--blue);}\n.db-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:14px;margin:24px 0;}\n.db-card{background:white;border:1px solid var(--border);border-radius:8px;padding:20px;position:relative;overflow:hidden;}\n.db-card::before{content:'';position:absolute;top:0;left:0;right:0;height:4px;}\n.db-card.pg::before{background:var(--pg);}\n.db-card.mg::before{background:var(--mg);}\n.db-card.dy::before{background:var(--dy);}\n.db-card.ca::before{background:var(--ca);}\n.db-logo{font-size:22px;margin-bottom:6px;}\n.db-name{font-family:var(--serif);font-size:17px;font-weight:700;margin-bottom:4px;}\n.db-type{font-family:var(--mono);font-size:9px;letter-spacing:2px;color:var(--muted);margin-bottom:10px;text-transform:uppercase;}\n.db-tagline{font-size:13px;color:#5a5848;line-height:1.55;}\n.db-born{font-family:var(--mono);font-size:9px;color:var(--muted);margin-top:8px;}\n.analogy{background:var(--ink);color:#c8c4b8;border-radius:8px;padding:24px 28px;margin:24px 0;}\n.analogy-label{font-family:var(--mono);font-size:9px;letter-spacing:3px;color:#6a6458;margin-bottom:10px;text-transform:uppercase;}\n.analogy-text{font-size:15px;line-height:1.75;color:#d8d4c8;}\n.analogy-text strong{color:#e8b84b;}\n.callout{border-radius:4px;padding:14px 18px;margin:18px 0;font-size:13.5px;border-left:3px solid;line-height:1.65;}\n.callout p{font-size:13.5px;margin-bottom:6px;}\n.callout p:last-child{margin:0;}\n.cl-blue{background:var(--blue-bg);border-color:var(--blue);color:#1a2a4a;}\n.cl-green{background:var(--green-bg);border-color:var(--green);color:#0a2a1a;}\n.cl-amber{background:var(--amber-bg);border-color:var(--amber);color:#3a2a08;}\n.cl-red{background:var(--red-bg);border-color:var(--red);color:#3a0a08;}\n.cl-lbl{font-family:var(--mono);font-size:9px;letter-spacing:3px;text-transform:uppercase;margin-bottom:6px;opacity:.7;}\n.codeblock{background:var(--ink);border-radius:6px;padding:20px 22px;font-family:var(--mono);font-size:11.5px;line-height:2;overflow-x:auto;margin:14px 0;color:#c8c4b8;border:1px solid #1e1c18;}\n.codeblock .c{color:#3e3d36;}.codeblock .k{color:#e8b84b;}.codeblock .s{color:#8bc4a0;}.codeblock .n{color:#e8946a;}.codeblock .t{color:#7aaee0;}.codeblock .g{color:#a8d878;}.codeblock .r{color:#e87878;}\n.comp-table{width:100%;border-collapse:collapse;margin:20px 0;font-size:13px;}\n.comp-table th{padding:10px 14px;border:1px solid var(--border);background:var(--surface2);font-family:var(--mono);font-size:9px;letter-spacing:1.5px;text-transform:uppercase;color:var(--muted);}\n.comp-table td{padding:11px 14px;border:1px solid var(--border);vertical-align:top;color:#3a3830;line-height:1.6;}\n.comp-table .row-head{font-family:var(--mono);font-size:11px;font-weight:600;background:var(--surface);color:var(--ink);white-space:nowrap;}\n.good{color:var(--green);font-weight:600;}.warn{color:var(--amber);font-weight:600;}.bad{color:var(--red);font-weight:600;}\n.dot{display:inline-block;width:9px;height:9px;border-radius:50%;margin-right:4px;vertical-align:middle;}\n.dot.g{background:var(--green);}.dot.a{background:var(--amber);}.dot.r{background:var(--red);}\n.use-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:14px;margin:20px 0;}\n.use-card{border:1px solid var(--border);border-radius:6px;padding:18px;background:white;}\n.use-card-head{font-family:var(--mono);font-size:11px;font-weight:600;margin-bottom:10px;display:flex;align-items:center;gap:8px;}\n.use-card ul{padding-left:16px;font-size:13px;color:#4a4838;line-height:1.7;}\n.use-card ul li{margin-bottom:4px;}\n.shard-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:14px;margin:20px 0;}\n.shard-card{background:var(--ink);border-radius:8px;padding:20px;color:#c8c4b8;}\n.shard-title{font-family:var(--mono);font-size:10px;letter-spacing:2px;color:#6a6458;margin-bottom:10px;text-transform:uppercase;}\n.shard-name{font-family:var(--serif);font-size:16px;font-weight:700;color:#e8b84b;margin-bottom:8px;}\n.shard-body{font-size:12.5px;line-height:1.65;color:#a8a49c;}\n.shard-verdict{margin-top:10px;font-family:var(--mono);font-size:10px;padding:4px 10px;border-radius:3px;display:inline-block;}\n.sv-easy{background:rgba(26,122,74,.2);color:#5ac882;}.sv-med{background:rgba(184,114,10,.2);color:#e8943a;}.sv-hard{background:rgba(192,57,43,.2);color:#e87868;}\n.faq-item{border:1px solid var(--border);border-radius:4px;margin-bottom:8px;overflow:hidden;}\n.faq-q{padding:14px 18px;display:flex;justify-content:space-between;align-items:center;cursor:pointer;background:white;font-size:14px;font-weight:500;color:var(--ink);user-select:none;}\n.faq-q:hover{background:var(--surface);}\n.faq-q .tog{font-size:18px;color:#e8b84b;flex-shrink:0;margin-left:12px;transition:transform .2s;font-family:var(--mono);}\n.faq-a{display:none;padding:18px;background:var(--surface);font-size:13.5px;color:#3a3830;line-height:1.75;border-top:1px solid var(--border);}\n.faq-item.open .faq-a{display:block;}.faq-item.open .tog{transform:rotate(45deg);}\n.sd-example{background:white;border:1px solid var(--border);border-radius:8px;margin:20px 0;overflow:hidden;}\n.sd-example-head{background:var(--ink);padding:14px 20px;display:flex;align-items:center;gap:12px;}\n.sd-example-title{font-family:var(--serif);font-size:16px;color:#f0ece4;font-weight:700;}\n.sd-example-tag{font-family:var(--mono);font-size:9px;letter-spacing:2px;color:#6a6458;border:1px solid #2e2c28;padding:3px 8px;border-radius:2px;}\n.sd-example-body{padding:20px;}\n.choice-row{display:flex;gap:10px;align-items:flex-start;padding:10px 0;border-bottom:1px solid var(--border);font-size:13px;}\n.choice-row:last-child{border:none;}\n.choice-label{font-family:var(--mono);font-size:10px;letter-spacing:1px;color:var(--muted);width:120px;flex-shrink:0;padding-top:2px;}\n.choice-val{flex:1;color:#3a3830;line-height:1.6;}\n.badge{display:inline-block;font-family:var(--mono);font-size:9px;padding:2px 7px;border-radius:2px;border:1px solid;margin-right:4px;font-weight:500;}\n.b-pg{background:var(--pg-bg);border-color:var(--pg);color:var(--pg);}.b-mg{background:var(--mg-bg);border-color:var(--mg);color:var(--mg);}.b-dy{background:var(--dy-bg);border-color:var(--dy);color:#b06000;}.b-ca{background:var(--ca-bg);border-color:var(--ca);color:var(--ca);}.b-g{background:var(--green-bg);border-color:var(--green);color:var(--green);}.b-r{background:var(--red-bg);border-color:var(--red);color:var(--red);}.b-a{background:var(--amber-bg);border-color:var(--amber);color:var(--amber);}\n.footer{background:var(--ink);text-align:center;padding:36px 20px;font-family:var(--mono);font-size:10px;color:#3a3830;letter-spacing:2px;}\n\n.step-block{background:#fff;border:1px solid var(--border);border-radius:8px;margin:20px 0;overflow:hidden;}\n.step-block-header{background:var(--ink);color:#e8e4dc;padding:13px 18px;font-family:var(--mono);font-size:10px;letter-spacing:2px;text-transform:uppercase;display:flex;align-items:center;gap:10px;}\n.sb-icon{font-size:16px;}\n.step-block-body{padding:0;}\n.step-row{display:flex;gap:0;border-bottom:1px solid var(--border);}\n.step-row:last-child{border-bottom:none;}\n.step-num{background:var(--surface);min-width:46px;display:flex;align-items:flex-start;justify-content:center;padding:16px 6px;font-family:var(--mono);font-size:11px;font-weight:700;color:var(--muted);flex-shrink:0;border-right:1px solid var(--border);}\n.step-content{padding:14px 18px;flex:1;}\n.step-q{font-weight:600;font-size:14px;color:var(--ink);margin-bottom:10px;}\n.step-options{display:flex;flex-direction:column;gap:6px;}\n.step-option{display:flex;gap:10px;align-items:flex-start;padding:9px 13px;border-radius:5px;font-size:13px;line-height:1.65;}\n.opt-yes{background:#edf8f2;border:1px solid #b8ddc8;}\n.opt-no{background:#fdf6e8;border:1px solid #e8c870;}\n.opt-mid{background:#edf2fb;border:1px solid #b8c8e8;}\n.opt-any{background:#f4f0fb;border:1px solid #c8b8e8;}\n.opt-arrow{font-family:var(--mono);font-size:12px;font-weight:700;flex-shrink:0;margin-top:1px;min-width:120px;}\n.opt-yes .opt-arrow{color:#1a7a4a;}\n.opt-no .opt-arrow{color:#b8720a;}\n.opt-mid .opt-arrow{color:#1a4f8a;}\n.opt-any .opt-arrow{color:#5a3c9a;}\n.opt-text{flex:1;color:#3a3830;}\n.concept-grid{display:grid;grid-template-columns:1fr;gap:0;margin:20px 0;border:1px solid var(--border);border-radius:8px;overflow:hidden;}\n.concept-row{display:flex;gap:0;border-bottom:1px solid var(--border);}\n.concept-row:last-child{border-bottom:none;}\n.concept-term{background:var(--ink);color:#e8b84b;font-family:var(--mono);font-size:11.5px;font-weight:600;min-width:155px;padding:14px 16px;flex-shrink:0;border-right:1px solid #2a2820;display:flex;align-items:flex-start;line-height:1.5;}\n.concept-def{padding:13px 16px;flex:1;font-size:13.5px;color:#3a3830;line-height:1.7;background:#fff;}\n.concept-def strong{color:var(--ink);}\n.concept-def code{background:var(--surface);padding:1px 5px;border-radius:3px;font-family:var(--mono);font-size:11px;color:var(--blue);}\n@media(max-width:560px){.concept-row{flex-direction:column;}.concept-term{min-width:auto;border-right:none;border-bottom:1px solid #2a2820;}.opt-arrow{min-width:80px;}}\n\n\n\n</style>\n</head>\n<body>\n<div class=\"hero\">\n  <div class=\"hero-inner\">\n    <div class=\"hero-tag\">System Design \u00b7 FAANG Interview Prep \u00b7 Manish-Almanac</div>\n    <h1>Consistent Hashing<br><em>Partitioning at Scale</em></h1>\n    <p class=\"hero-sub\">Why naive hashing breaks, how the ring works, virtual nodes, hot spots, and how Cassandra, Redis Cluster and DynamoDB actually implement it.</p>\n    <div class=\"db-pills\"><span class=\"db-pill\" style=\"border-color:#1a7a4a;color:#1a7a4a;background:rgba(26,122,74,.08)\">Hash Ring</span><span class=\"db-pill\" style=\"border-color:#1a4f8a;color:#1a4f8a;background:rgba(26,79,138,.08)\">Virtual Nodes</span><span class=\"db-pill\" style=\"border-color:#b8720a;color:#b8720a;background:rgba(184,114,10,.08)\">Hash Slots</span><span class=\"db-pill\" style=\"border-color:#c0392b;color:#c0392b;background:rgba(192,57,43,.08)\">Hot Spots</span></div>\n  </div>\n</div>\n<nav class=\"nav\"><a href=\"#problem\">The Problem</a><a href=\"#how\">How It Works</a><a href=\"#comparison\">Strategies</a><a href=\"#hotspot\">Hot Spots</a><a href=\"#real\">Real Systems</a><a href=\"#followups\">Follow-ups</a></nav>\n<div class=\"wrap\">\n\n<section id=\"problem\">\n  <div class=\"sec-tag\">00 \u00b7 The Problem</div>\n  <h2>Why naive hashing breaks when you add or remove servers</h2>\n  <p>You have 3 servers and use <code>hash(key) % 3</code> to route requests. Server 2 goes down. Now you have 2 servers. <code>hash(key) % 2</code> gives completely different results \u2014 every key maps to a different server. <strong>100% of your cached data is now on the wrong server.</strong> Your entire cache is invalidated simultaneously. Your database collapses.</p>\n  <div class=\"analogy\">\n    <div class=\"analogy-label\">The seating chart analogy</div>\n    <div class=\"analogy-text\">\n      A restaurant has 10 tables. Each guest is assigned <code>hash(name) % 10</code>. Works perfectly. Then one table is removed \u2014 now 9 tables, and <strong>nearly every guest is now \"assigned\" to a different table</strong>. Total chaos.<br><br>\n      <strong>Consistent hashing</strong> is like arranging all tables in a circle and assigning each guest to the nearest table clockwise. Remove one table \u2014 only that table's guests need to move to the next table. Everyone else stays exactly where they were.\n    </div>\n  </div>\n</section>\n\n<section id=\"how\">\n  <div class=\"sec-tag\">01 \u00b7 How It Works</div>\n  <h2>The ring \u2014 step by step</h2>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\"><div class=\"concept-term\">The Hash Ring</div><div class=\"concept-def\"><strong>Imagine a circle with positions 0 to 2\u00b3\u00b2 (about 4 billion).</strong> Both servers and keys are hashed onto this circle using the same hash function.<br>\n      Servers: <code>hash(\"server-A\") \u2192 position 12M</code>, <code>hash(\"server-B\") \u2192 position 1.8B</code>, <code>hash(\"server-C\") \u2192 position 3.1B</code><br>\n      Keys: <code>hash(\"user:123\") \u2192 position 900M</code><br>\n      <span style=\"color:#5a5848;font-size:12.5px;\">To find which server owns a key: start at the key's position and walk clockwise until you hit a server. user:123 at 900M \u2192 nearest server clockwise is server-B at 1.8B.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Adding a Server</div><div class=\"concept-def\"><strong>New server-D hashes to position 1.2B.</strong> It sits between server-A (12M) and server-B (1.8B).<br>\n      Only keys between 12M and 1.2B (previously owned by server-B) now move to server-D.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Only ~1/N of keys need to move when adding the Nth server. All other keys stay on their current server.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Removing a Server</div><div class=\"concept-def\"><strong>Server-B (position 1.8B) goes down.</strong> Its keys now walk clockwise to server-C (3.1B).<br>\n      Only server-B's keys need to be fetched from DB (cache miss). All other servers' keys are unaffected.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Only ~1/N of keys are disrupted on server failure, vs 100% with naive hashing.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Virtual Nodes</div><div class=\"concept-def\"><strong>The problem with basic consistent hashing: non-uniform distribution.</strong> With only 3 real servers, one server might own 60% of the ring and another only 10%.<br>\n      <strong>Solution: virtual nodes (vnodes).</strong> Each physical server gets 100\u20131000 positions on the ring:<br>\n      <code>hash(\"server-A#1\") \u2192 12M, hash(\"server-A#2\") \u2192 890M, hash(\"server-A#3\") \u2192 2.1B ...</code><br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Load is distributed much more evenly. Larger servers can have more vnodes. Used by: Cassandra (default 256 vnodes), DynamoDB, Redis Cluster.</span></div></div>\n  </div>\n</section>\n\n<section id=\"comparison\">\n  <div class=\"sec-tag\">02 \u00b7 Partition Strategies Compared</div>\n  <h2>Four ways to shard data \u2014 and when each breaks</h2>\n  <table class=\"comp-table\">\n    <thead><tr><th>Strategy</th><th>How It Works</th><th>Advantage</th><th>Failure Mode</th><th>Used By</th></tr></thead>\n    <tbody>\n      <tr><td class=\"row-head\">Naive Hash<br>key % N</td><td>Hash key, take modulo of server count</td><td>Simple, uniform distribution</td><td class=\"bad\">100% remapping on any topology change</td><td>Single-node systems only</td></tr>\n      <tr><td class=\"row-head\">Range Sharding</td><td>A\u2013F on shard 1, G\u2013M on shard 2, N\u2013Z on shard 3</td><td>Range queries efficient, predictable</td><td class=\"warn\">Hot spots: \"S\" surnames dominate one shard</td><td>HBase, CockroachDB, BigTable</td></tr>\n      <tr><td class=\"row-head\">Consistent Hashing</td><td>Ring: key routes to nearest server clockwise</td><td>Only 1/N keys move on topology change</td><td class=\"warn\">Non-uniform without vnodes; hotspot on popular keys</td><td>Cassandra, DynamoDB, Memcached</td></tr>\n      <tr><td class=\"row-head\">Hash Slots<br>(Redis Cluster)</td><td>16,384 fixed slots. key \u2192 slot \u2192 server mapping</td><td>Deterministic, easy resharding, flexible assignment</td><td class=\"warn\">Cross-slot multi-key ops need hash tags</td><td>Redis Cluster</td></tr>\n    </tbody>\n  </table>\n</section>\n\n<section id=\"hotspot\">\n  <div class=\"sec-tag\">03 \u00b7 The Hot Spot Problem</div>\n  <h2>Consistent hashing does not solve hot keys \u2014 here is what does</h2>\n  <div class=\"callout cl-red\">\n    <div class=\"cl-lbl\">\u26a0 The interview trap</div>\n    <p>Candidates often say \"I'll use consistent hashing to distribute load evenly.\" Interviewers immediately ask: <strong>\"What about a celebrity user with 50M followers? All their post writes hash to one node.\"</strong> Consistent hashing distributes <em>keys</em> evenly \u2014 it does not help when one key receives disproportionate traffic.</p>\n  </div>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\"><div class=\"concept-term\">Key Salting</div><div class=\"concept-def\"><strong>Append a random suffix to distribute one hot key across multiple nodes.</strong><br>\n      Instead of writing to <code>celebrity:123</code>, write to <code>celebrity:123#0</code> through <code>celebrity:123#7</code> (8 shards).<br>\n      Reads: scatter-gather across all 8 shards, sum/merge results.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Distributes write load 8x. Used for: hot counters (view counts), celebrity post writes.</span><br>\n      <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 Read complexity \u2014 must query all shards and aggregate. Adds latency for reads.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Write Fan-Out</div><div class=\"concept-def\"><strong>Pre-compute and write results to each consumer's own shard.</strong><br>\n      Celebrity posts to 50M followers: instead of one write + 50M reads, write the post to each follower's feed shard at write time.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Reads are trivially cheap \u2014 each user's feed is pre-computed on their own node. Twitter uses fan-out on write for most users.</span><br>\n      <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 Expensive for celebrities (50M writes per post). Hybrid: fan-out for regular users, lazy load for celebrities (fan-out on read).</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Local Caching</div><div class=\"concept-def\"><strong>Cache hot keys in-process on every app server.</strong><br>\n      Celebrity user profile read millions of times/minute \u2192 cache in Caffeine/Guava on each app server. Zero network hops for reads.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Eliminates hot spot entirely for read-only data. Used for: configuration, feature flags, reference data that rarely changes.</span><br>\n      <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 Inconsistency across servers \u2014 each has its own copy. Use short TTL + push invalidation.</span></div></div>\n  </div>\n</section>\n\n<section id=\"real\">\n  <div class=\"sec-tag\">04 \u00b7 Real Implementations</div>\n  <h2>How Cassandra, Redis Cluster, and DynamoDB actually do it</h2>\n  <div class=\"sd-example\">\n    <div class=\"sd-example-head\"><div class=\"sd-example-title\">Cassandra \u2014 Token Ring with Vnodes</div><span class=\"sd-example-tag\">CONSISTENT HASHING</span></div>\n    <div class=\"sd-example-body\">\n      <div class=\"choice-row\"><div class=\"choice-label\">MECHANISM</div><div class=\"choice-val\">Cassandra uses Murmur3 hash to place both nodes and keys on a token ring (range: -2\u2076\u00b3 to 2\u2076\u00b3). Each node is assigned 256 virtual tokens by default, giving it 256 positions on the ring. Data is replicated to the next N nodes clockwise (N = replication factor).</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">ADDING A NODE</div><div class=\"choice-val\">New node joins the ring with 256 vnodes. Cassandra automatically streams data from existing nodes to the new node for only the token ranges it now owns. Other nodes are unaffected. No downtime, no manual resharding.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">COORDINATOR</div><div class=\"choice-val\">Any node can be the coordinator for any request. The coordinator hashes the key, identifies which nodes own it (via the ring), and routes the request \u2014 then returns the result to the client. Clients can connect to any node.</div></div>\n    </div>\n  </div>\n  <div class=\"sd-example\">\n    <div class=\"sd-example-head\"><div class=\"sd-example-title\">Redis Cluster \u2014 Hash Slot Assignment</div><span class=\"sd-example-tag\">HASH SLOTS</span></div>\n    <div class=\"sd-example-body\">\n      <div class=\"choice-row\"><div class=\"choice-label\">16,384 SLOTS</div><div class=\"choice-val\">Redis Cluster uses 16,384 fixed hash slots (not a ring). Key \u2192 CRC16(key) % 16384 \u2192 slot number. Each master node owns a range of slots (e.g., node A: 0\u20135460, node B: 5461\u201310922, node C: 10923\u201316383). Adding a node = reassigning some slots to it.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">HASH TAGS</div><div class=\"choice-val\">Multi-key operations (MGET, transactions) require all keys to be on the same slot. Use hash tags: <code>{user:123}.profile</code> and <code>{user:123}.settings</code> \u2014 the <code>{...}</code> part determines the slot. Both keys land on the same node, enabling multi-key ops.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">MOVED REDIRECT</div><div class=\"choice-val\">Client sends GET to wrong node \u2192 node responds with <code>MOVED 7892 node-B:6380</code> \u2192 client redirects to correct node. Smart clients cache the slot\u2192node mapping and go direct after first lookup.</div></div>\n    </div>\n  </div>\n</section>\n\n<section id=\"followups\">\n  <div class=\"sec-tag\">05 \u00b7 Follow-ups</div>\n  <h2>Every hard follow-up, answered</h2>\n  <div class=\"faq-item\"><div class=\"faq-q\" onclick=\"toggle(this)\">Why 16,384 slots in Redis Cluster \u2014 why not more or fewer?<span class=\"tog\">+</span></div>\n  <div class=\"faq-a\"><strong>16,384 was chosen as a practical balance between cluster message size and flexibility.</strong><br><br>Each Redis node sends heartbeat messages to all other nodes containing a bitmap of which slots it owns. 16,384 slots = 16,384 bits = 2KB bitmap. This fits comfortably in a small network packet. Redis's creator Antirez noted that with 1,000 nodes (an extremely large cluster), 16 slots per node is still enough granularity. More slots would increase heartbeat message size unnecessarily.</div></div>\n  <div class=\"faq-item\"><div class=\"faq-q\" onclick=\"toggle(this)\">What is rendezvous hashing and when is it better than consistent hashing?<span class=\"tog\">+</span></div>\n  <div class=\"faq-a\"><strong>Rendezvous hashing (HRW \u2014 Highest Random Weight) is an alternative that achieves the same minimal disruption property without requiring a ring data structure.</strong><br><br>Algorithm: to assign key K to a server, compute <code>hash(K, server_i)</code> for every server, pick the server with the highest hash value. On server removal, only that server's keys are reassigned \u2014 they each independently recompute and pick the next-highest server.<br><br><strong>Advantages over consistent hashing</strong>: No ring data structure needed. No virtual nodes complexity. Perfect load distribution by default. Any client can independently compute the assignment without shared state.<br><br><strong>Disadvantage</strong>: O(N) computation to assign one key (must compute hash for every server). With 1,000 servers and millions of keys per second, this becomes expensive. Consistent hashing with a sorted ring is O(log N).<br><br>Used by: CDNs (Akamai's original), some load balancers. Less common in distributed databases where ring-based approaches dominate.</div></div>\n  <div class=\"faq-item\"><div class=\"faq-q\" onclick=\"toggle(this)\">How does consistent hashing handle data replication across nodes?<span class=\"tog\">+</span></div>\n  <div class=\"faq-a\"><strong>In systems using consistent hashing with replication (like Cassandra), a key is stored on not just the nearest node but the next N nodes clockwise.</strong><br><br>Example with replication factor 3: key hashes to position 900M. Server-B is at 1.8B (primary). Server-C at 3.1B (first replica). Server-A at 12M + 4B wraparound (second replica). All three nodes store a copy.<br><br>Writes go to all 3 (with configurable consistency: ONE/QUORUM/ALL). Reads can come from any of the 3. This means the ring simultaneously handles both partitioning (which set of nodes owns this key) and replication (which specific N nodes in that set).<br><br>Node failure: the ring automatically re-routes to the surviving replicas. Once a new node is added, it receives a copy of the data it should own via a streaming repair process (Cassandra's repair mechanism).</div></div>\n</section>\n</div>\n<div class=\"footer\">CONSISTENT HASHING \u00b7 PARTITIONING \u00b7 VNODES \u00b7 REDIS CLUSTER \u00b7 CASSANDRA \u00b7 MANISH-ALMANAC</div>\n\u003cscript>function toggle(el){el.parentElement.classList.toggle('open');}<\/script>\n</body>\n</html>", tag: 'Partitioning' },
  rate_limiting: { title: 'Rate Limiting & Throttling', srcdoc: "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Rate Limiting & Throttling</title>\n<link href=\"https://fonts.googleapis.com/css2?family=Playfair+Display:wght@700;900&family=Source+Sans+3:wght@300;400;500;600&family=JetBrains+Mono:wght@400;600&display=swap\" rel=\"stylesheet\">\n<style>\n\n:root{--ink:#0f0e0c;--page:#f7f5f0;--surface:#eeecea;--surface2:#e5e2dc;--border:#d4d0c8;--muted:#7a7568;--pg:#336791;--pg-bg:#eef4fb;--mg:#13aa52;--mg-bg:#edfaf2;--dy:#ff9900;--dy-bg:#fff8ec;--ca:#1287b1;--ca-bg:#eaf6fb;--red:#c0392b;--red-bg:#fdf0ee;--green:#1a7a4a;--green-bg:#edf8f2;--amber:#b8720a;--amber-bg:#fdf6e8;--blue:#1a4f8a;--blue-bg:#edf2fb;--mono:'JetBrains Mono',monospace;--serif:'Playfair Display',serif;--sans:'Source Sans 3',sans-serif;}\n*{box-sizing:border-box;margin:0;padding:0;}html{scroll-behavior:smooth;}\nbody{background:var(--page);color:var(--ink);font-family:var(--sans);font-size:15px;line-height:1.75;}\n.hero{background:var(--ink);color:#e8e4dc;padding:72px 24px 56px;position:relative;overflow:hidden;}\n.hero::before{content:'';position:absolute;inset:0;background:repeating-linear-gradient(45deg,transparent,transparent 40px,rgba(255,255,255,.015) 40px,rgba(255,255,255,.015) 41px);}\n.hero-inner{max-width:960px;margin:0 auto;position:relative;}\n.hero-tag{font-family:var(--mono);font-size:10px;letter-spacing:4px;color:#6a6458;text-transform:uppercase;margin-bottom:20px;}\nh1{font-family:var(--serif);font-size:clamp(32px,5vw,58px);font-weight:900;line-height:1.05;letter-spacing:-.5px;margin-bottom:20px;color:#f0ece4;}\nh1 em{color:#e8b84b;font-style:normal;}\n.hero-sub{font-size:15px;color:#7a7060;max-width:640px;line-height:1.7;margin-bottom:32px;}\n.db-pills{display:flex;flex-wrap:wrap;gap:8px;}\n.db-pill{font-family:var(--mono);font-size:10px;padding:5px 14px;border-radius:3px;border:1px solid;letter-spacing:.5px;}\n.pill-pg{border-color:#336791;color:#336791;background:rgba(51,103,145,.08);}\n.pill-mg{border-color:#13aa52;color:#13aa52;background:rgba(19,170,82,.08);}\n.pill-dy{border-color:#ff9900;color:#cc7a00;background:rgba(255,153,0,.08);}\n.pill-ca{border-color:#1287b1;color:#1287b1;background:rgba(18,135,177,.08);}\n.nav{position:sticky;top:0;z-index:100;background:var(--ink);border-bottom:1px solid #1e1c18;display:flex;overflow-x:auto;scrollbar-width:none;padding:0 20px;}\n.nav::-webkit-scrollbar{display:none;}\n.nav a{font-family:var(--mono);font-size:10px;letter-spacing:1px;color:#4a4840;text-decoration:none;padding:14px 12px;white-space:nowrap;border-bottom:2px solid transparent;transition:.18s;}\n.nav a:hover{color:#e8b84b;border-color:#e8b84b;}\n.wrap{max-width:960px;margin:0 auto;padding:0 20px;}\nsection{padding:56px 0 36px;border-bottom:2px solid var(--border);}\nsection:last-child{border:none;}\n.sec-tag{font-family:var(--mono);font-size:9px;letter-spacing:4px;text-transform:uppercase;color:var(--muted);margin-bottom:8px;display:flex;align-items:center;gap:10px;}\n.sec-tag::before{content:'';width:20px;height:1px;background:var(--border);}\nh2{font-family:var(--serif);font-size:clamp(22px,3.5vw,32px);font-weight:700;line-height:1.15;margin-bottom:18px;}\nh3{font-family:var(--sans);font-size:17px;font-weight:600;margin:32px 0 10px;border-bottom:1px solid var(--border);padding-bottom:6px;}\nh4{font-size:13px;font-weight:600;margin:16px 0 6px;text-transform:uppercase;letter-spacing:.5px;}\np{color:#3a3830;font-size:14.5px;margin-bottom:12px;}\nstrong{color:var(--ink);}\ncode{font-family:var(--mono);font-size:11.5px;background:var(--surface2);padding:1px 5px;border-radius:3px;color:var(--blue);}\n.db-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:14px;margin:24px 0;}\n.db-card{background:white;border:1px solid var(--border);border-radius:8px;padding:20px;position:relative;overflow:hidden;}\n.db-card::before{content:'';position:absolute;top:0;left:0;right:0;height:4px;}\n.db-card.pg::before{background:var(--pg);}\n.db-card.mg::before{background:var(--mg);}\n.db-card.dy::before{background:var(--dy);}\n.db-card.ca::before{background:var(--ca);}\n.db-logo{font-size:22px;margin-bottom:6px;}\n.db-name{font-family:var(--serif);font-size:17px;font-weight:700;margin-bottom:4px;}\n.db-type{font-family:var(--mono);font-size:9px;letter-spacing:2px;color:var(--muted);margin-bottom:10px;text-transform:uppercase;}\n.db-tagline{font-size:13px;color:#5a5848;line-height:1.55;}\n.db-born{font-family:var(--mono);font-size:9px;color:var(--muted);margin-top:8px;}\n.analogy{background:var(--ink);color:#c8c4b8;border-radius:8px;padding:24px 28px;margin:24px 0;}\n.analogy-label{font-family:var(--mono);font-size:9px;letter-spacing:3px;color:#6a6458;margin-bottom:10px;text-transform:uppercase;}\n.analogy-text{font-size:15px;line-height:1.75;color:#d8d4c8;}\n.analogy-text strong{color:#e8b84b;}\n.callout{border-radius:4px;padding:14px 18px;margin:18px 0;font-size:13.5px;border-left:3px solid;line-height:1.65;}\n.callout p{font-size:13.5px;margin-bottom:6px;}\n.callout p:last-child{margin:0;}\n.cl-blue{background:var(--blue-bg);border-color:var(--blue);color:#1a2a4a;}\n.cl-green{background:var(--green-bg);border-color:var(--green);color:#0a2a1a;}\n.cl-amber{background:var(--amber-bg);border-color:var(--amber);color:#3a2a08;}\n.cl-red{background:var(--red-bg);border-color:var(--red);color:#3a0a08;}\n.cl-lbl{font-family:var(--mono);font-size:9px;letter-spacing:3px;text-transform:uppercase;margin-bottom:6px;opacity:.7;}\n.codeblock{background:var(--ink);border-radius:6px;padding:20px 22px;font-family:var(--mono);font-size:11.5px;line-height:2;overflow-x:auto;margin:14px 0;color:#c8c4b8;border:1px solid #1e1c18;}\n.codeblock .c{color:#3e3d36;}.codeblock .k{color:#e8b84b;}.codeblock .s{color:#8bc4a0;}.codeblock .n{color:#e8946a;}.codeblock .t{color:#7aaee0;}.codeblock .g{color:#a8d878;}.codeblock .r{color:#e87878;}\n.comp-table{width:100%;border-collapse:collapse;margin:20px 0;font-size:13px;}\n.comp-table th{padding:10px 14px;border:1px solid var(--border);background:var(--surface2);font-family:var(--mono);font-size:9px;letter-spacing:1.5px;text-transform:uppercase;color:var(--muted);}\n.comp-table td{padding:11px 14px;border:1px solid var(--border);vertical-align:top;color:#3a3830;line-height:1.6;}\n.comp-table .row-head{font-family:var(--mono);font-size:11px;font-weight:600;background:var(--surface);color:var(--ink);white-space:nowrap;}\n.good{color:var(--green);font-weight:600;}.warn{color:var(--amber);font-weight:600;}.bad{color:var(--red);font-weight:600;}\n.dot{display:inline-block;width:9px;height:9px;border-radius:50%;margin-right:4px;vertical-align:middle;}\n.dot.g{background:var(--green);}.dot.a{background:var(--amber);}.dot.r{background:var(--red);}\n.use-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:14px;margin:20px 0;}\n.use-card{border:1px solid var(--border);border-radius:6px;padding:18px;background:white;}\n.use-card-head{font-family:var(--mono);font-size:11px;font-weight:600;margin-bottom:10px;display:flex;align-items:center;gap:8px;}\n.use-card ul{padding-left:16px;font-size:13px;color:#4a4838;line-height:1.7;}\n.use-card ul li{margin-bottom:4px;}\n.shard-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:14px;margin:20px 0;}\n.shard-card{background:var(--ink);border-radius:8px;padding:20px;color:#c8c4b8;}\n.shard-title{font-family:var(--mono);font-size:10px;letter-spacing:2px;color:#6a6458;margin-bottom:10px;text-transform:uppercase;}\n.shard-name{font-family:var(--serif);font-size:16px;font-weight:700;color:#e8b84b;margin-bottom:8px;}\n.shard-body{font-size:12.5px;line-height:1.65;color:#a8a49c;}\n.shard-verdict{margin-top:10px;font-family:var(--mono);font-size:10px;padding:4px 10px;border-radius:3px;display:inline-block;}\n.sv-easy{background:rgba(26,122,74,.2);color:#5ac882;}.sv-med{background:rgba(184,114,10,.2);color:#e8943a;}.sv-hard{background:rgba(192,57,43,.2);color:#e87868;}\n.faq-item{border:1px solid var(--border);border-radius:4px;margin-bottom:8px;overflow:hidden;}\n.faq-q{padding:14px 18px;display:flex;justify-content:space-between;align-items:center;cursor:pointer;background:white;font-size:14px;font-weight:500;color:var(--ink);user-select:none;}\n.faq-q:hover{background:var(--surface);}\n.faq-q .tog{font-size:18px;color:#e8b84b;flex-shrink:0;margin-left:12px;transition:transform .2s;font-family:var(--mono);}\n.faq-a{display:none;padding:18px;background:var(--surface);font-size:13.5px;color:#3a3830;line-height:1.75;border-top:1px solid var(--border);}\n.faq-item.open .faq-a{display:block;}.faq-item.open .tog{transform:rotate(45deg);}\n.sd-example{background:white;border:1px solid var(--border);border-radius:8px;margin:20px 0;overflow:hidden;}\n.sd-example-head{background:var(--ink);padding:14px 20px;display:flex;align-items:center;gap:12px;}\n.sd-example-title{font-family:var(--serif);font-size:16px;color:#f0ece4;font-weight:700;}\n.sd-example-tag{font-family:var(--mono);font-size:9px;letter-spacing:2px;color:#6a6458;border:1px solid #2e2c28;padding:3px 8px;border-radius:2px;}\n.sd-example-body{padding:20px;}\n.choice-row{display:flex;gap:10px;align-items:flex-start;padding:10px 0;border-bottom:1px solid var(--border);font-size:13px;}\n.choice-row:last-child{border:none;}\n.choice-label{font-family:var(--mono);font-size:10px;letter-spacing:1px;color:var(--muted);width:120px;flex-shrink:0;padding-top:2px;}\n.choice-val{flex:1;color:#3a3830;line-height:1.6;}\n.badge{display:inline-block;font-family:var(--mono);font-size:9px;padding:2px 7px;border-radius:2px;border:1px solid;margin-right:4px;font-weight:500;}\n.b-pg{background:var(--pg-bg);border-color:var(--pg);color:var(--pg);}.b-mg{background:var(--mg-bg);border-color:var(--mg);color:var(--mg);}.b-dy{background:var(--dy-bg);border-color:var(--dy);color:#b06000;}.b-ca{background:var(--ca-bg);border-color:var(--ca);color:var(--ca);}.b-g{background:var(--green-bg);border-color:var(--green);color:var(--green);}.b-r{background:var(--red-bg);border-color:var(--red);color:var(--red);}.b-a{background:var(--amber-bg);border-color:var(--amber);color:var(--amber);}\n.footer{background:var(--ink);text-align:center;padding:36px 20px;font-family:var(--mono);font-size:10px;color:#3a3830;letter-spacing:2px;}\n\n.step-block{background:#fff;border:1px solid var(--border);border-radius:8px;margin:20px 0;overflow:hidden;}\n.step-block-header{background:var(--ink);color:#e8e4dc;padding:13px 18px;font-family:var(--mono);font-size:10px;letter-spacing:2px;text-transform:uppercase;display:flex;align-items:center;gap:10px;}\n.sb-icon{font-size:16px;}\n.step-block-body{padding:0;}\n.step-row{display:flex;gap:0;border-bottom:1px solid var(--border);}\n.step-row:last-child{border-bottom:none;}\n.step-num{background:var(--surface);min-width:46px;display:flex;align-items:flex-start;justify-content:center;padding:16px 6px;font-family:var(--mono);font-size:11px;font-weight:700;color:var(--muted);flex-shrink:0;border-right:1px solid var(--border);}\n.step-content{padding:14px 18px;flex:1;}\n.step-q{font-weight:600;font-size:14px;color:var(--ink);margin-bottom:10px;}\n.step-options{display:flex;flex-direction:column;gap:6px;}\n.step-option{display:flex;gap:10px;align-items:flex-start;padding:9px 13px;border-radius:5px;font-size:13px;line-height:1.65;}\n.opt-yes{background:#edf8f2;border:1px solid #b8ddc8;}\n.opt-no{background:#fdf6e8;border:1px solid #e8c870;}\n.opt-mid{background:#edf2fb;border:1px solid #b8c8e8;}\n.opt-any{background:#f4f0fb;border:1px solid #c8b8e8;}\n.opt-arrow{font-family:var(--mono);font-size:12px;font-weight:700;flex-shrink:0;margin-top:1px;min-width:120px;}\n.opt-yes .opt-arrow{color:#1a7a4a;}\n.opt-no .opt-arrow{color:#b8720a;}\n.opt-mid .opt-arrow{color:#1a4f8a;}\n.opt-any .opt-arrow{color:#5a3c9a;}\n.opt-text{flex:1;color:#3a3830;}\n.concept-grid{display:grid;grid-template-columns:1fr;gap:0;margin:20px 0;border:1px solid var(--border);border-radius:8px;overflow:hidden;}\n.concept-row{display:flex;gap:0;border-bottom:1px solid var(--border);}\n.concept-row:last-child{border-bottom:none;}\n.concept-term{background:var(--ink);color:#e8b84b;font-family:var(--mono);font-size:11.5px;font-weight:600;min-width:155px;padding:14px 16px;flex-shrink:0;border-right:1px solid #2a2820;display:flex;align-items:flex-start;line-height:1.5;}\n.concept-def{padding:13px 16px;flex:1;font-size:13.5px;color:#3a3830;line-height:1.7;background:#fff;}\n.concept-def strong{color:var(--ink);}\n.concept-def code{background:var(--surface);padding:1px 5px;border-radius:3px;font-family:var(--mono);font-size:11px;color:var(--blue);}\n@media(max-width:560px){.concept-row{flex-direction:column;}.concept-term{min-width:auto;border-right:none;border-bottom:1px solid #2a2820;}.opt-arrow{min-width:80px;}}\n\n\n\n</style>\n</head>\n<body>\n<div class=\"hero\">\n  <div class=\"hero-inner\">\n    <div class=\"hero-tag\">System Design \u00b7 FAANG Interview Prep \u00b7 Manish-Almanac</div>\n    <h1>Rate Limiting & Throttling<br><em>Token bucket, leaky bucket, sliding window \u2014 every algorithm explained with distributed implementation patterns and real system design examples.</em></h1>\n    <p class=\"hero-sub\">Token bucket, leaky bucket, sliding window \u2014 every algorithm explained with distributed implementation patterns and real system design examples.</p>\n    <div class=\"db-pills\"><span class=\"db-pill\" style=\"border-color:#1a7a4a;color:#1a7a4a;background:rgba(26,122,74,.08)\">Token Bucket</span><span class=\"db-pill\" style=\"border-color:#c0392b;color:#c0392b;background:rgba(192,57,43,.08)\">Sliding Window</span><span class=\"db-pill\" style=\"border-color:#1a4f8a;color:#1a4f8a;background:rgba(26,79,138,.08)\">Redis INCR</span><span class=\"db-pill\" style=\"border-color:#b8720a;color:#b8720a;background:rgba(184,114,10,.08)\">Leaky Bucket</span></div>\n  </div>\n</div>\n<nav class=\"nav\"><a href=\"#why\">Why Rate Limit</a><a href=\"#algorithms\">Algorithms</a><a href=\"#distributed\">Distributed</a><a href=\"#examples\">System Design</a><a href=\"#decision\">Decision Tree</a><a href=\"#followups\">Follow-ups</a></nav>\n<div class=\"wrap\">\n\n<section id=\"why\">\n  <div class=\"sec-tag\">00 \u00b7 Why Rate Limiting</div>\n  <h2>What breaks without it</h2>\n  <p>Without rate limiting: one bad actor (or a bug in a client) sends 100K requests/second to your API. Your database collapses. Every other user is impacted. Rate limiting is the first line of defence \u2014 it protects your system from both malicious abuse and accidental overload.</p>\n  <div class=\"callout cl-amber\">\n    <div class=\"cl-lbl\">Real examples of why this matters</div>\n    <p><strong>Stripe:</strong> Charges per API call. A bug in customer code loops 10K calls/sec. Without rate limiting: customer pays $10K/sec unexpectedly AND Stripe's infra is impacted.</p>\n    <p><strong>Twitter API:</strong> 300 requests per 15-minute window per user. Prevents scrapers from harvesting all tweets while ensuring legitimate app developers can build.</p>\n    <p><strong>Payment APIs:</strong> Max 10 login attempts per minute per IP. Prevents brute-force credential stuffing attacks.</p>\n  </div>\n</section>\n\n<section id=\"algorithms\">\n  <div class=\"sec-tag\">01 \u00b7 The Four Algorithms</div>\n  <h2>Token bucket, leaky bucket, fixed window, sliding window log</h2>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">Token Bucket</div>\n      <div class=\"concept-def\"><strong>A bucket holds up to N tokens. Tokens refill at rate R per second. Each request consumes 1 token. No tokens = rejected.</strong><br>\n        Example: bucket capacity=100, refill rate=10/sec. A burst of 100 requests is allowed immediately (uses all tokens). Then max 10/sec until refilled.<br>\n        <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Allows bursts up to bucket size. Smooth average rate enforcement. Memory: O(1) per user (just store token count + last refill time).</span><br>\n        <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 Allows requests at exactly the boundary \u2014 two full bursts are possible at the start and end of a window.</span><br>\n        <span style=\"color:#5a5848;font-size:12.5px;\">Used by: AWS API Gateway, Stripe, most REST API rate limiters. <strong>The industry standard algorithm.</strong></span>\n      </div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">Leaky Bucket</div>\n      <div class=\"concept-def\"><strong>Requests enter a queue (the bucket). They are processed at a fixed rate (the leak). If the queue is full, requests are dropped.</strong><br>\n        Example: process 10 requests/sec regardless of how many arrive. Smooths out bursts entirely.<br>\n        <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Perfectly smooth outbound rate. No bursts. Protects downstream services from traffic spikes.</span><br>\n        <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 Bursts are queued, not served fast \u2014 legitimate spikes experience latency, not rejection. If queue fills, recent requests are dropped even if earlier ones were slow.</span><br>\n        <span style=\"color:#5a5848;font-size:12.5px;\">Used by: traffic shaping in networking, protecting database connection pools.</span>\n      </div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">Fixed Window</div>\n      <div class=\"concept-def\"><strong>Count requests per fixed time window (e.g., per minute). Reset counter at window boundary.</strong><br>\n        Example: 100 requests/minute. Counter at 14:03:00 resets at 14:04:00.<br>\n        <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Simplest to implement. <code>INCR counter:user:minute:1403</code> in Redis.</span><br>\n        <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 <strong>Boundary attack</strong>: 100 requests at 14:03:59 + 100 requests at 14:04:01 = 200 requests in 2 seconds (both within their respective windows). Actual rate is 2x the limit at the window boundary.</span>\n      </div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">Sliding Window Log</div>\n      <div class=\"concept-def\"><strong>Store a timestamp log of every request. For each new request, count logs in the last N seconds. Reject if count exceeds limit.</strong><br>\n        Redis: <code>ZADD log:user:123 {timestamp} {timestamp}</code>. <code>ZREMRANGEBYSCORE log 0 (now-window)</code>. <code>ZCARD log</code> = request count.<br>\n        <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Perfectly accurate. No boundary attack. Truly enforces the rolling window.</span><br>\n        <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 Memory: O(requests) per user. At 1000 req/min and 1M users, that is 1 billion log entries. Only practical for low-rate, critical endpoints (login, payment).</span>\n      </div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">Sliding Window Counter</div>\n      <div class=\"concept-def\"><strong>Hybrid: fixed window counters with interpolation to approximate sliding window. Best of both.</strong><br>\n        Store counter for current window and previous window. Weighted estimate:<br>\n        <code>count = prev_window * (1 - elapsed/window_size) + curr_window</code><br>\n        <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 O(1) memory. Accurate enough (Cloudflare uses this \u2014 they found &lt;0.003% of requests are incorrectly rate-limited). The practical production choice.</span><br>\n        <span style=\"color:#5a5848;font-size:12.5px;\">Used by: Cloudflare, most high-scale rate limiting systems.</span>\n      </div>\n    </div>\n  </div>\n</section>\n\n<section id=\"distributed\">\n  <div class=\"sec-tag\">02 \u00b7 Distributed Rate Limiting</div>\n  <h2>How to rate limit across 100 app servers</h2>\n  <div class=\"callout cl-blue\">\n    <div class=\"cl-lbl\">The core challenge</div>\n    <p>Each app server sees only its fraction of total traffic. If you rate-limit locally (100 req/min per server \u00d7 100 servers = 10,000 req/min global), your rate limit means nothing. You need a shared counter that all servers update atomically.</p>\n  </div>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\"><div class=\"concept-term\">Redis INCR Pattern</div><div class=\"concept-def\"><strong>The standard approach: shared Redis counter with atomic increment.</strong><br>\n      <code>MULTI</code><br>\n      <code>INCR ratelimit:{user_id}:{window}</code><br>\n      <code>EXPIRE ratelimit:{user_id}:{window} 60</code><br>\n      <code>EXEC</code><br>\n      If result &gt; limit \u2192 reject with 429. Redis's single-threaded INCR is atomic \u2014 no race conditions.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Simple, correct, fast (&lt;1ms). Works for token bucket too: Lua script atomically checks and decrements token count.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Redis Lua Script</div><div class=\"concept-def\"><strong>For token bucket \u2014 atomically check and decrement in one round trip.</strong><br>\n      <code>local tokens = redis.call('GET', KEYS[1])</code><br>\n      <code>if tokens and tonumber(tokens) > 0 then</code><br>\n      <code>  redis.call('DECR', KEYS[1]); return 1</code><br>\n      <code>else return 0 end</code><br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Lua scripts execute atomically in Redis \u2014 no race between check and decrement. Libraries like redis-rate-limiter use exactly this.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Local Approximate<br>+ Sync</div><div class=\"concept-def\"><strong>Each server maintains a local counter, periodically syncing to Redis.</strong><br>\n      Each server allows up to limit/N requests locally (N = server count). Every 100ms, sync actual count to Redis and refresh local quota.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Reduces Redis calls by 100x. Much more scalable for high-throughput APIs.</span><br>\n      <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 Up to 100ms window where slightly over-limit requests are allowed. Acceptable for most use cases.</span></div></div>\n  </div>\n</section>\n\n<section id=\"examples\">\n  <div class=\"sec-tag\">03 \u00b7 System Design Examples</div>\n  <h2>Rate limiting in real systems</h2>\n  <div class=\"sd-example\">\n    <div class=\"sd-example-head\"><div class=\"sd-example-title\">API Gateway Rate Limiting</div><span class=\"sd-example-tag\">MULTI-DIMENSIONAL</span></div>\n    <div class=\"sd-example-body\">\n      <div class=\"choice-row\"><div class=\"choice-label\">PER USER</div><div class=\"choice-val\"><span class=\"badge b-g\">Token Bucket \u2713</span> 1000 req/min per authenticated user. Key: <code>ratelimit:user:{id}:minute</code>. Allows legitimate burst traffic (developer hitting API in a loop) while preventing abuse.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">PER IP</div><div class=\"choice-val\"><span class=\"badge b-g\">Sliding Window \u2713</span> 100 req/min per IP for unauthenticated requests. Stops credential stuffing (many login attempts from same IP). Key: <code>ratelimit:ip:{hash(ip)}:minute</code>. Hash the IP to avoid storing raw IPs (privacy).</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">PER ENDPOINT</div><div class=\"choice-val\">Different limits per endpoint: <code>POST /login</code> = 5/min, <code>GET /feed</code> = 300/min, <code>POST /payment</code> = 10/min. The sensitivity of the endpoint determines the limit.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">RESPONSE HEADERS</div><div class=\"choice-val\">Always return: <code>X-RateLimit-Limit: 1000</code>, <code>X-RateLimit-Remaining: 743</code>, <code>X-RateLimit-Reset: 1742383200</code>. Clients use these to back off gracefully before hitting 429.</div></div>\n    </div>\n  </div>\n  <div class=\"sd-example\">\n    <div class=\"sd-example-head\"><div class=\"sd-example-title\">Notification System</div><span class=\"sd-example-tag\">SPAM PREVENTION</span></div>\n    <div class=\"sd-example-body\">\n      <div class=\"choice-row\"><div class=\"choice-label\">PER USER/CHANNEL</div><div class=\"choice-val\">Max 2 SMS per user per 10 minutes. Max 5 emails per user per hour. Max 10 push notifications per user per day. Multi-dimensional limits using separate Redis counters per dimension: <code>ratelimit:sms:{user}:10min</code>.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">GLOBAL SEND RATE</div><div class=\"choice-val\">Email provider (SendGrid) limits to 100K emails/hour. Token bucket at the sender level: fill 100K tokens/hour, each email consumes 1. If empty \u2192 queue for next hour window rather than dropping.</div></div>\n    </div>\n  </div>\n</section>\n\n<section id=\"decision\">\n  <div class=\"sec-tag\">04 \u00b7 Decision Tree</div>\n  <h2>Which algorithm to pick</h2>\n  <div class=\"step-block\">\n    <div class=\"step-block-header\"><span class=\"sb-icon\">\ud83c\udfaf</span>Rate Limiting Algorithm Selection</div>\n    <div class=\"step-block-body\">\n      <div class=\"step-row\"><div class=\"step-num\">01</div><div class=\"step-content\">\n        <div class=\"step-q\">Do you need to allow bursts?</div>\n        <div class=\"step-options\">\n          <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">YES (burst OK) \u2192</span><span class=\"opt-text\"><strong>Token Bucket.</strong> Accumulates tokens when idle, releases in bursts. Standard for REST APIs. Stripe, AWS, Twilio all use token bucket.</span></div>\n          <div class=\"step-option opt-no\"><span class=\"opt-arrow\">NO (strict smooth rate) \u2192</span><span class=\"opt-text\"><strong>Leaky Bucket.</strong> Enforces exactly R requests/second with no bursting. Use for protecting downstream services that can only handle a fixed rate.</span></div>\n        </div>\n      </div></div>\n      <div class=\"step-row\"><div class=\"step-num\">02</div><div class=\"step-content\">\n        <div class=\"step-q\">How important is precision vs simplicity?</div>\n        <div class=\"step-options\">\n          <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">Precision critical \u2192</span><span class=\"opt-text\"><strong>Sliding Window Log.</strong> Perfectly accurate but O(req) memory per user. Only use for high-value low-rate endpoints (login, payment, account creation).</span></div>\n          <div class=\"step-option opt-mid\"><span class=\"opt-arrow\">Balanced \u2192</span><span class=\"opt-text\"><strong>Sliding Window Counter.</strong> 0.003% inaccuracy, O(1) memory. Production choice for most high-scale systems. Cloudflare's approach.</span></div>\n          <div class=\"step-option opt-no\"><span class=\"opt-arrow\">Simplicity first \u2192</span><span class=\"opt-text\"><strong>Fixed Window.</strong> Single Redis INCR. Boundary attack is acceptable if limits are conservative (set limit 2x lower to account for the boundary doubling).</span></div>\n        </div>\n      </div></div>\n      <div class=\"step-row\"><div class=\"step-num\">03</div><div class=\"step-content\">\n        <div class=\"step-q\">What is the enforcement layer?</div>\n        <div class=\"step-options\">\n          <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">API Gateway \u2192</span><span class=\"opt-text\">Rate limit at the gateway (Kong, AWS API Gateway, Envoy). Centralized, language-agnostic, enforced before traffic hits your services.</span></div>\n          <div class=\"step-option opt-mid\"><span class=\"opt-arrow\">Application level \u2192</span><span class=\"opt-text\">Redis-backed middleware in your service. More granular (can access business logic for tiered limits). Used for per-feature or per-plan limits.</span></div>\n          <div class=\"step-option opt-no\"><span class=\"opt-arrow\">Service mesh \u2192</span><span class=\"opt-text\">Istio/Envoy sidecar proxies enforce rate limits between services. Used for internal service-to-service rate limiting in microservice architectures.</span></div>\n        </div>\n      </div></div>\n    </div>\n  </div>\n</section>\n\n<section id=\"followups\">\n  <div class=\"sec-tag\">05 \u00b7 Follow-ups</div>\n  <h2>Every hard follow-up, answered</h2>\n  <div class=\"faq-item\"><div class=\"faq-q\" onclick=\"toggle(this)\">How do you handle rate limiting for distributed clients \u2014 e.g., a user calling from multiple devices?<span class=\"tog\">+</span></div>\n  <div class=\"faq-a\"><strong>Rate limit on the authenticated user identity (user_id from JWT), not on the device or IP.</strong><br><br>The user_id is consistent across all their devices. The Redis key <code>ratelimit:user:{user_id}:{window}</code> is incremented by every request regardless of which device or IP it comes from. This means a user signing in on phone + laptop + tablet all share the same quota \u2014 preventing circumvention by using multiple devices.<br><br>IP-based limiting is additive and separate \u2014 it is used for unauthenticated endpoints (login page, signup) to prevent automated attacks before authentication.</div></div>\n  <div class=\"faq-item\"><div class=\"faq-q\" onclick=\"toggle(this)\">What happens if the rate limit store (Redis) goes down?<span class=\"tog\">+</span></div>\n  <div class=\"faq-a\"><strong>You have two choices and you must pick one explicitly \u2014 there is no \"right answer,\" only a trade-off.</strong><br><br><strong>Fail open (allow all traffic)</strong>: If Redis is unavailable, do not rate limit. 100% of requests are served. Risk: abuse during the outage window. Appropriate when: availability is more important than abuse prevention (most consumer APIs).<br><br><strong>Fail closed (reject all traffic)</strong>: If Redis is unavailable, reject with 429 or 503. No abuse during outage. Risk: legitimate users are blocked. Appropriate when: abuse has high cost (payment APIs, authentication endpoints).<br><br><strong>In practice</strong>: Use local fallback counters. Each app server tracks its own count. If Redis is down, enforce limit/N per server (N = server count). Slightly inaccurate but functional. Redis sentinel/cluster with automatic failover ensures outages are rare and brief.</div></div>\n  <div class=\"faq-item\"><div class=\"faq-q\" onclick=\"toggle(this)\">How do you implement tiered rate limits (free vs pro vs enterprise)?<span class=\"tog\">+</span></div>\n  <div class=\"faq-a\"><strong>Store the user's tier in their JWT or a fast lookup cache, then apply tier-specific limits.</strong><br><br>\n  Approach:<br>\n  1. JWT contains <code>\"tier\": \"pro\"</code> \u2014 decoded at the rate limit middleware with zero extra lookups.<br>\n  2. Tier \u2192 limit mapping stored in config: <code>{\"free\": 100, \"pro\": 1000, \"enterprise\": 100000}</code><br>\n  3. Rate limit key includes tier for isolation: <code>ratelimit:{tier}:{user_id}:{window}</code><br><br>\n  Why include tier in the key: so upgrading from free to pro immediately gives the new limit without needing to reset the counter. The free counter is simply no longer checked.<br><br>\n  For enterprise customers with custom limits: store their limit in Redis itself: <code>ratelimit:config:{user_id}</code> = their custom limit. Fallback to tier default if not set.</div></div>\n</section>\n</div>\n<div class=\"footer\">RATE LIMITING \u00b7 TOKEN BUCKET \u00b7 SLIDING WINDOW \u00b7 REDIS \u00b7 THROTTLING \u00b7 MANISH-ALMANAC</div>\n\u003cscript>function toggle(el){el.parentElement.classList.toggle('open');}<\/script>\n</body>\n</html>", tag: 'Rate Limiting' },
  distributed_systems: { title: 'Distributed Systems Fundamentals', srcdoc: "<!DOCTYPE html>\n<html lang=\"en\"><head><meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Distributed Systems: Fundamentals</title>\n<link href=\"https://fonts.googleapis.com/css2?family=Playfair+Display:wght@700;900&family=Source+Sans+3:wght@300;400;500;600&family=JetBrains+Mono:wght@400;600&display=swap\" rel=\"stylesheet\">\n<style>\n:root{--ink:#0f0e0c;--page:#f7f5f0;--surface:#eeecea;--surface2:#e5e2dc;--border:#d4d0c8;--muted:#7a7568;--pg:#336791;--pg-bg:#eef4fb;--mg:#13aa52;--mg-bg:#edfaf2;--dy:#ff9900;--dy-bg:#fff8ec;--ca:#1287b1;--ca-bg:#eaf6fb;--red:#c0392b;--red-bg:#fdf0ee;--green:#1a7a4a;--green-bg:#edf8f2;--amber:#b8720a;--amber-bg:#fdf6e8;--blue:#1a4f8a;--blue-bg:#edf2fb;--mono:'JetBrains Mono',monospace;--serif:'Playfair Display',serif;--sans:'Source Sans 3',sans-serif;}\n*{box-sizing:border-box;margin:0;padding:0;}html{scroll-behavior:smooth;}\nbody{background:var(--page);color:var(--ink);font-family:var(--sans);font-size:15px;line-height:1.75;}\n.hero{background:var(--ink);color:#e8e4dc;padding:72px 24px 56px;position:relative;overflow:hidden;}\n.hero::before{content:'';position:absolute;inset:0;background:repeating-linear-gradient(45deg,transparent,transparent 40px,rgba(255,255,255,.015) 40px,rgba(255,255,255,.015) 41px);}\n.hero-inner{max-width:960px;margin:0 auto;position:relative;}\n.hero-tag{font-family:var(--mono);font-size:10px;letter-spacing:4px;color:#6a6458;text-transform:uppercase;margin-bottom:20px;}\nh1{font-family:var(--serif);font-size:clamp(32px,5vw,58px);font-weight:900;line-height:1.05;letter-spacing:-.5px;margin-bottom:20px;color:#f0ece4;}\nh1 em{color:#e8b84b;font-style:normal;}\n.hero-sub{font-size:15px;color:#7a7060;max-width:640px;line-height:1.7;margin-bottom:32px;}\n.db-pills{display:flex;flex-wrap:wrap;gap:8px;}\n.db-pill{font-family:var(--mono);font-size:10px;padding:5px 14px;border-radius:3px;border:1px solid;letter-spacing:.5px;}\n.pill-pg{border-color:#336791;color:#336791;background:rgba(51,103,145,.08);}\n.pill-mg{border-color:#13aa52;color:#13aa52;background:rgba(19,170,82,.08);}\n.pill-dy{border-color:#ff9900;color:#cc7a00;background:rgba(255,153,0,.08);}\n.pill-ca{border-color:#1287b1;color:#1287b1;background:rgba(18,135,177,.08);}\n.nav{position:sticky;top:0;z-index:100;background:var(--ink);border-bottom:1px solid #1e1c18;display:flex;overflow-x:auto;scrollbar-width:none;padding:0 20px;}\n.nav::-webkit-scrollbar{display:none;}\n.nav a{font-family:var(--mono);font-size:10px;letter-spacing:1px;color:#4a4840;text-decoration:none;padding:14px 12px;white-space:nowrap;border-bottom:2px solid transparent;transition:.18s;}\n.nav a:hover{color:#e8b84b;border-color:#e8b84b;}\n.wrap{max-width:960px;margin:0 auto;padding:0 20px;}\nsection{padding:56px 0 36px;border-bottom:2px solid var(--border);}\nsection:last-child{border:none;}\n.sec-tag{font-family:var(--mono);font-size:9px;letter-spacing:4px;text-transform:uppercase;color:var(--muted);margin-bottom:8px;display:flex;align-items:center;gap:10px;}\n.sec-tag::before{content:'';width:20px;height:1px;background:var(--border);}\nh2{font-family:var(--serif);font-size:clamp(22px,3.5vw,32px);font-weight:700;line-height:1.15;margin-bottom:18px;}\nh3{font-family:var(--sans);font-size:17px;font-weight:600;margin:32px 0 10px;border-bottom:1px solid var(--border);padding-bottom:6px;}\nh4{font-size:13px;font-weight:600;margin:16px 0 6px;text-transform:uppercase;letter-spacing:.5px;}\np{color:#3a3830;font-size:14.5px;margin-bottom:12px;}\nstrong{color:var(--ink);}\ncode{font-family:var(--mono);font-size:11.5px;background:var(--surface2);padding:1px 5px;border-radius:3px;color:var(--blue);}\n.db-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:14px;margin:24px 0;}\n.db-card{background:white;border:1px solid var(--border);border-radius:8px;padding:20px;position:relative;overflow:hidden;}\n.db-card::before{content:'';position:absolute;top:0;left:0;right:0;height:4px;}\n.db-card.pg::before{background:var(--pg);}\n.db-card.mg::before{background:var(--mg);}\n.db-card.dy::before{background:var(--dy);}\n.db-card.ca::before{background:var(--ca);}\n.db-logo{font-size:22px;margin-bottom:6px;}\n.db-name{font-family:var(--serif);font-size:17px;font-weight:700;margin-bottom:4px;}\n.db-type{font-family:var(--mono);font-size:9px;letter-spacing:2px;color:var(--muted);margin-bottom:10px;text-transform:uppercase;}\n.db-tagline{font-size:13px;color:#5a5848;line-height:1.55;}\n.db-born{font-family:var(--mono);font-size:9px;color:var(--muted);margin-top:8px;}\n.analogy{background:var(--ink);color:#c8c4b8;border-radius:8px;padding:24px 28px;margin:24px 0;}\n.analogy-label{font-family:var(--mono);font-size:9px;letter-spacing:3px;color:#6a6458;margin-bottom:10px;text-transform:uppercase;}\n.analogy-text{font-size:15px;line-height:1.75;color:#d8d4c8;}\n.analogy-text strong{color:#e8b84b;}\n.callout{border-radius:4px;padding:14px 18px;margin:18px 0;font-size:13.5px;border-left:3px solid;line-height:1.65;}\n.callout p{font-size:13.5px;margin-bottom:6px;}\n.callout p:last-child{margin:0;}\n.cl-blue{background:var(--blue-bg);border-color:var(--blue);color:#1a2a4a;}\n.cl-green{background:var(--green-bg);border-color:var(--green);color:#0a2a1a;}\n.cl-amber{background:var(--amber-bg);border-color:var(--amber);color:#3a2a08;}\n.cl-red{background:var(--red-bg);border-color:var(--red);color:#3a0a08;}\n.cl-lbl{font-family:var(--mono);font-size:9px;letter-spacing:3px;text-transform:uppercase;margin-bottom:6px;opacity:.7;}\n.codeblock{background:var(--ink);border-radius:6px;padding:20px 22px;font-family:var(--mono);font-size:11.5px;line-height:2;overflow-x:auto;margin:14px 0;color:#c8c4b8;border:1px solid #1e1c18;}\n.codeblock .c{color:#3e3d36;}.codeblock .k{color:#e8b84b;}.codeblock .s{color:#8bc4a0;}.codeblock .n{color:#e8946a;}.codeblock .t{color:#7aaee0;}.codeblock .g{color:#a8d878;}.codeblock .r{color:#e87878;}\n.comp-table{width:100%;border-collapse:collapse;margin:20px 0;font-size:13px;}\n.comp-table th{padding:10px 14px;border:1px solid var(--border);background:var(--surface2);font-family:var(--mono);font-size:9px;letter-spacing:1.5px;text-transform:uppercase;color:var(--muted);}\n.comp-table td{padding:11px 14px;border:1px solid var(--border);vertical-align:top;color:#3a3830;line-height:1.6;}\n.comp-table .row-head{font-family:var(--mono);font-size:11px;font-weight:600;background:var(--surface);color:var(--ink);white-space:nowrap;}\n.good{color:var(--green);font-weight:600;}.warn{color:var(--amber);font-weight:600;}.bad{color:var(--red);font-weight:600;}\n.dot{display:inline-block;width:9px;height:9px;border-radius:50%;margin-right:4px;vertical-align:middle;}\n.dot.g{background:var(--green);}.dot.a{background:var(--amber);}.dot.r{background:var(--red);}\n.use-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:14px;margin:20px 0;}\n.use-card{border:1px solid var(--border);border-radius:6px;padding:18px;background:white;}\n.use-card-head{font-family:var(--mono);font-size:11px;font-weight:600;margin-bottom:10px;display:flex;align-items:center;gap:8px;}\n.use-card ul{padding-left:16px;font-size:13px;color:#4a4838;line-height:1.7;}\n.use-card ul li{margin-bottom:4px;}\n.shard-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:14px;margin:20px 0;}\n.shard-card{background:var(--ink);border-radius:8px;padding:20px;color:#c8c4b8;}\n.shard-title{font-family:var(--mono);font-size:10px;letter-spacing:2px;color:#6a6458;margin-bottom:10px;text-transform:uppercase;}\n.shard-name{font-family:var(--serif);font-size:16px;font-weight:700;color:#e8b84b;margin-bottom:8px;}\n.shard-body{font-size:12.5px;line-height:1.65;color:#a8a49c;}\n.shard-verdict{margin-top:10px;font-family:var(--mono);font-size:10px;padding:4px 10px;border-radius:3px;display:inline-block;}\n.sv-easy{background:rgba(26,122,74,.2);color:#5ac882;}.sv-med{background:rgba(184,114,10,.2);color:#e8943a;}.sv-hard{background:rgba(192,57,43,.2);color:#e87868;}\n.faq-item{border:1px solid var(--border);border-radius:4px;margin-bottom:8px;overflow:hidden;}\n.faq-q{padding:14px 18px;display:flex;justify-content:space-between;align-items:center;cursor:pointer;background:white;font-size:14px;font-weight:500;color:var(--ink);user-select:none;}\n.faq-q:hover{background:var(--surface);}\n.faq-q .tog{font-size:18px;color:#e8b84b;flex-shrink:0;margin-left:12px;transition:transform .2s;font-family:var(--mono);}\n.faq-a{display:none;padding:18px;background:var(--surface);font-size:13.5px;color:#3a3830;line-height:1.75;border-top:1px solid var(--border);}\n.faq-item.open .faq-a{display:block;}.faq-item.open .tog{transform:rotate(45deg);}\n.sd-example{background:white;border:1px solid var(--border);border-radius:8px;margin:20px 0;overflow:hidden;}\n.sd-example-head{background:var(--ink);padding:14px 20px;display:flex;align-items:center;gap:12px;}\n.sd-example-title{font-family:var(--serif);font-size:16px;color:#f0ece4;font-weight:700;}\n.sd-example-tag{font-family:var(--mono);font-size:9px;letter-spacing:2px;color:#6a6458;border:1px solid #2e2c28;padding:3px 8px;border-radius:2px;}\n.sd-example-body{padding:20px;}\n.choice-row{display:flex;gap:10px;align-items:flex-start;padding:10px 0;border-bottom:1px solid var(--border);font-size:13px;}\n.choice-row:last-child{border:none;}\n.choice-label{font-family:var(--mono);font-size:10px;letter-spacing:1px;color:var(--muted);width:120px;flex-shrink:0;padding-top:2px;}\n.choice-val{flex:1;color:#3a3830;line-height:1.6;}\n.badge{display:inline-block;font-family:var(--mono);font-size:9px;padding:2px 7px;border-radius:2px;border:1px solid;margin-right:4px;font-weight:500;}\n.b-pg{background:var(--pg-bg);border-color:var(--pg);color:var(--pg);}.b-mg{background:var(--mg-bg);border-color:var(--mg);color:var(--mg);}.b-dy{background:var(--dy-bg);border-color:var(--dy);color:#b06000;}.b-ca{background:var(--ca-bg);border-color:var(--ca);color:var(--ca);}.b-g{background:var(--green-bg);border-color:var(--green);color:var(--green);}.b-r{background:var(--red-bg);border-color:var(--red);color:var(--red);}.b-a{background:var(--amber-bg);border-color:var(--amber);color:var(--amber);}\n.footer{background:var(--ink);text-align:center;padding:36px 20px;font-family:var(--mono);font-size:10px;color:#3a3830;letter-spacing:2px;}\n\n.step-block{background:#fff;border:1px solid var(--border);border-radius:8px;margin:20px 0;overflow:hidden;}\n.step-block-header{background:var(--ink);color:#e8e4dc;padding:13px 18px;font-family:var(--mono);font-size:10px;letter-spacing:2px;text-transform:uppercase;display:flex;align-items:center;gap:10px;}\n.sb-icon{font-size:16px;}\n.step-block-body{padding:0;}\n.step-row{display:flex;gap:0;border-bottom:1px solid var(--border);}\n.step-row:last-child{border-bottom:none;}\n.step-num{background:var(--surface);min-width:46px;display:flex;align-items:flex-start;justify-content:center;padding:16px 6px;font-family:var(--mono);font-size:11px;font-weight:700;color:var(--muted);flex-shrink:0;border-right:1px solid var(--border);}\n.step-content{padding:14px 18px;flex:1;}\n.step-q{font-weight:600;font-size:14px;color:var(--ink);margin-bottom:10px;}\n.step-options{display:flex;flex-direction:column;gap:6px;}\n.step-option{display:flex;gap:10px;align-items:flex-start;padding:9px 13px;border-radius:5px;font-size:13px;line-height:1.65;}\n.opt-yes{background:#edf8f2;border:1px solid #b8ddc8;}\n.opt-no{background:#fdf6e8;border:1px solid #e8c870;}\n.opt-mid{background:#edf2fb;border:1px solid #b8c8e8;}\n.opt-any{background:#f4f0fb;border:1px solid #c8b8e8;}\n.opt-arrow{font-family:var(--mono);font-size:12px;font-weight:700;flex-shrink:0;margin-top:1px;min-width:120px;}\n.opt-yes .opt-arrow{color:#1a7a4a;}\n.opt-no .opt-arrow{color:#b8720a;}\n.opt-mid .opt-arrow{color:#1a4f8a;}\n.opt-any .opt-arrow{color:#5a3c9a;}\n.opt-text{flex:1;color:#3a3830;}\n.concept-grid{display:grid;grid-template-columns:1fr;gap:0;margin:20px 0;border:1px solid var(--border);border-radius:8px;overflow:hidden;}\n.concept-row{display:flex;gap:0;border-bottom:1px solid var(--border);}\n.concept-row:last-child{border-bottom:none;}\n.concept-term{background:var(--ink);color:#e8b84b;font-family:var(--mono);font-size:11.5px;font-weight:600;min-width:155px;padding:14px 16px;flex-shrink:0;border-right:1px solid #2a2820;display:flex;align-items:flex-start;line-height:1.5;}\n.concept-def{padding:13px 16px;flex:1;font-size:13.5px;color:#3a3830;line-height:1.7;background:#fff;}\n.concept-def strong{color:var(--ink);}\n.concept-def code{background:var(--surface);padding:1px 5px;border-radius:3px;font-family:var(--mono);font-size:11px;color:var(--blue);}\n@media(max-width:560px){.concept-row{flex-direction:column;}.concept-term{min-width:auto;border-right:none;border-bottom:1px solid #2a2820;}.opt-arrow{min-width:80px;}}\n\n</style>\n</head><body>\n<div class=\"hero\"><div class=\"hero-inner\">\n  <div class=\"hero-tag\">System Design \u00b7 FAANG Interview Prep \u00b7 Manish-Almanac</div>\n  <h1>Distributed Systems<br><em>Fundamentals</em></h1>\n  <p class=\"hero-sub\">CAP theorem, PACELC, consensus (Raft), distributed transactions (Saga vs 2PC), distributed locking (Redlock), and vector clocks \u2014 from first principles to production patterns.</p>\n  <div class=\"db-pills\"><span class=\"db-pill\" style=\"border-color:#1a4f8a;color:#1a4f8a;background:rgba(26,79,138,.08)\">CAP</span><span class=\"db-pill\" style=\"border-color:#1a7a4a;color:#1a7a4a;background:rgba(26,122,74,.08)\">Raft</span><span class=\"db-pill\" style=\"border-color:#b8720a;color:#b8720a;background:rgba(184,114,10,.08)\">Saga</span><span class=\"db-pill\" style=\"border-color:#c0392b;color:#c0392b;background:rgba(192,57,43,.08)\">2PC</span><span class=\"db-pill\" style=\"border-color:#6040a0;color:#6040a0;background:rgba(96,64,160,.08)\">Redlock</span></div>\n</div></div>\n<nav class=\"nav\"><a href=\"#cap\">CAP Theorem</a><a href=\"#consensus\">Consensus</a><a href=\"#transactions\">Distributed Tx</a><a href=\"#locks\">Distributed Locks</a><a href=\"#clocks\">Clocks & Ordering</a><a href=\"#followups\">Follow-ups</a></nav>\n<div class=\"wrap\">\n<section id=\"cap\">\n  <div class=\"sec-tag\">00 \u00b7 CAP Theorem</div>\n  <h2>The constraint every distributed system lives with</h2>\n  <p>CAP theorem: a distributed system can guarantee at most two of Consistency, Availability, and Partition Tolerance. Since network partitions <em>always happen</em> in real distributed systems, the real choice is <strong>CP vs AP</strong> \u2014 not \"do we handle partitions.\"</p>\n  <div class=\"analogy\">\n    <div class=\"analogy-label\">CAP in plain English</div>\n    <div class=\"analogy-text\">\n      Your bank has two branches. The network between them goes down.<br><br>\n      <strong>CP (Consistency + Partition Tolerance):</strong> Both branches stop accepting deposits until the network is restored. No one gets a wrong balance. But the service is unavailable during the outage.<br><br>\n      <strong>AP (Availability + Partition Tolerance):</strong> Both branches keep accepting deposits and serving customers independently. Service stays up. But when the network restores, one branch might show \u20b95,000 and the other \u20b97,000 for the same account \u2014 they need to reconcile.<br><br>\n      <strong>The choice is: would you rather return an error, or return potentially stale data?</strong>\n    </div>\n  </div>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\"><div class=\"concept-term\">PACELC Extension</div><div class=\"concept-def\"><strong>CAP only describes behaviour during a partition. PACELC also describes the trade-off during normal operation:</strong><br>\n      If Partition \u2192 choose Availability or Consistency (the CA in CAP)<br>\n      Else (normal) \u2192 choose Latency or Consistency<br>\n      <span style=\"color:#5a5848;font-size:12.5px;\">Even when no partition exists, you must decide: do you want the lowest latency (return from nearest replica, may be slightly stale) or the strongest consistency (always read from primary, higher latency)?<br>DynamoDB: PA/EL \u2014 available during partition, low latency during normal. HBase: PC/EC \u2014 consistent always, higher latency.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Linearisability</div><div class=\"concept-def\"><strong>The strongest consistency model. Every operation appears to happen at a single point in time, in the order clients observe.</strong><br>\n      If client A writes X=1 and client B subsequently reads X, B must see 1 \u2014 not a previous value.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Operations look as if they happened on a single machine. No surprises. Required for: financial transactions, distributed locks, leader election.</span><br>\n      <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 Requires coordination (consensus) across nodes. High latency. Not scalable to high throughput across geographies.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Eventual Consistency</div><div class=\"concept-def\"><strong>If no new updates are made, all replicas will eventually converge to the same value.</strong><br>\n      Reads may return stale data during the convergence window (typically milliseconds to seconds).<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Highest availability and lowest latency. Scales globally. Acceptable for: social feeds, product descriptions, DNS, shopping carts.</span><br>\n      <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 Applications must handle stale reads gracefully. Conflicts (two writes to the same key) need resolution strategy (LWW, CRDT, vector clocks).</span></div></div>\n  </div>\n</section>\n\n<section id=\"consensus\">\n  <div class=\"sec-tag\">01 \u00b7 Consensus</div>\n  <h2>Raft \u2014 how distributed systems agree on one truth</h2>\n  <p>Consensus is the problem of getting multiple nodes to agree on a single value even when some nodes crash or messages are delayed. Every distributed database, distributed lock, and leader election uses consensus internally.</p>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\"><div class=\"concept-term\">Leader Election</div><div class=\"concept-def\"><strong>Raft elects one leader at a time. All writes go through the leader. Followers only accept writes from the current leader.</strong><br>\n      If no heartbeat from leader for election timeout (150\u2013300ms), followers start a new election. Candidate requests votes. First to get majority (N/2 + 1) becomes new leader.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Simple mental model: one leader, clear authority. Used by: etcd, CockroachDB, TiKV, Kafka (KRaft mode).</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Log Replication</div><div class=\"concept-def\"><strong>Every write is appended to the leader's log. Leader replicates to followers. Once a majority acknowledges, the write is committed and applied.</strong><br>\n      Committed = durable even if the leader crashes. Followers will elect a new leader and apply the committed log.<br>\n      <span style=\"color:#5a5848;font-size:12.5px;\">This is exactly how Kafka replication works (ISR \u2014 in-sync replicas). Exactly how etcd stores Kubernetes cluster state. Exactly how CockroachDB achieves ACID transactions across nodes.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Why Not Paxos</div><div class=\"concept-def\"><strong>Paxos is theoretically equivalent to Raft but notoriously difficult to understand and implement correctly.</strong><br>\n      Raft was explicitly designed to be understandable \u2014 the original paper is titled \"Raft: In Search of an Understandable Consensus Algorithm.\"<br>\n      <span style=\"color:#5a5848;font-size:12.5px;\">In interviews: say \"I'd use Raft\" \u2014 it is the modern consensus algorithm of choice and you can explain it. Paxos is largely of historical interest.</span></div></div>\n  </div>\n</section>\n\n<section id=\"transactions\">\n  <div class=\"sec-tag\">02 \u00b7 Distributed Transactions</div>\n  <h2>2PC and the Saga pattern \u2014 when ACID crosses service boundaries</h2>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\"><div class=\"concept-term\">Two-Phase Commit (2PC)</div><div class=\"concept-def\"><strong>A coordinator asks all participants to prepare (can you commit?), then commits only if all say yes.</strong><br>\n      Phase 1 (Prepare): Coordinator asks all nodes to lock resources and vote yes/no.<br>\n      Phase 2 (Commit): If all voted yes \u2192 commit. If any voted no \u2192 rollback all.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Atomicity guaranteed across nodes. All commit or none do.</span><br>\n      <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 <strong>Blocking protocol:</strong> if coordinator crashes after Phase 1, participants are locked waiting forever (holding resources). Tight coupling between services. Performance: 2 round trips minimum. Used in: traditional databases (PostgreSQL distributed transactions, XA protocol). <strong>Avoid in microservices.</strong></span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Saga Pattern</div><div class=\"concept-def\"><strong>Break a distributed transaction into a sequence of local transactions, each with a compensating transaction to undo it on failure.</strong><br>\n      Example \u2014 e-commerce order: (1) Reserve inventory \u2192 (2) Charge payment \u2192 (3) Create shipment. If step 3 fails: cancel shipment + refund payment (compensation) + release inventory.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 No distributed locks. Services remain independent. Failures handled gracefully via compensation. The correct pattern for microservices.</span><br>\n      <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 Eventual consistency only \u2014 other services see intermediate states (payment charged before shipment confirmed). Compensation logic must be idempotent. Complex to reason about.</span><br>\n      <span style=\"color:#5a5848;font-size:12.5px;\">Two implementations: Choreography (events trigger next step) or Orchestration (a saga coordinator directs each step). Orchestration is easier to monitor and debug.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Idempotency</div><div class=\"concept-def\"><strong>Making the same operation multiple times has the same effect as doing it once.</strong><br>\n      Critical for: retries (network failures mean requests may be delivered twice), payment processing (charge card once even if confirmed twice).<br>\n      Implementation: client sends a unique <code>idempotency-key</code> header. Server stores <code>(idempotency_key \u2192 result)</code>. On duplicate: return stored result without re-executing.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Safe retries. Exactly-once semantics. Used by: Stripe (idempotency keys on all payment APIs), Kafka producers (enable.idempotence=true).</span></div></div>\n  </div>\n</section>\n\n<section id=\"locks\">\n  <div class=\"sec-tag\">03 \u00b7 Distributed Locking</div>\n  <h2>Redlock and why distributed locks are hard</h2>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\"><div class=\"concept-term\">Redis SETNX Pattern</div><div class=\"concept-def\"><strong>Simple distributed lock using Redis SET NX EX.</strong><br>\n      <code>SET lock:{resource} {unique_id} NX EX 30</code><br>\n      NX = only set if not exists (acquire lock). EX 30 = auto-expire in 30 seconds (prevent deadlock if holder crashes).<br>\n      Release: Lua script to atomically check owner + delete: <code>if GET == unique_id then DEL lock</code><br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Works correctly with a single Redis instance. Simple, widely used.</span><br>\n      <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 Single Redis node is a single point of failure. If Redis crashes, lock is lost. Works for most use cases where brief lock loss is acceptable.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Redlock Algorithm</div><div class=\"concept-def\"><strong>Acquire lock on majority of N independent Redis nodes (N=5 recommended). Lock is held only if majority acquired within timeout.</strong><br>\n      Steps: (1) Get current time. (2) Try acquiring lock on all 5 nodes in sequence. (3) Lock succeeds if acquired on \u22653 nodes AND total elapsed time &lt; lock TTL. (4) Release all on failure.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Survives failure of minority of Redis nodes. No single point of failure.</span><br>\n      <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 Martin Kleppmann identified a flaw: clock skew and GC pauses can cause two clients to both believe they hold the lock. For truly critical systems (financial), use a CP system like ZooKeeper or etcd for locks.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">etcd / ZooKeeper Locks</div><div class=\"concept-def\"><strong>For strong guarantees: use a CP distributed system built on Raft consensus.</strong><br>\n      etcd <code>PUT /locks/resource?prevExist=false</code> \u2014 atomic compare-and-set. Uses Raft to ensure only one leader can acquire the lock cluster-wide.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Correct under all failure scenarios. Linearisable \u2014 no two clients can simultaneously believe they hold the lock. Used by: Kubernetes for leader election, distributed job schedulers.</span><br>\n      <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 Higher latency than Redis (Raft round trip). Operational complexity of running etcd/ZooKeeper cluster.</span></div></div>\n  </div>\n</section>\n\n<section id=\"clocks\">\n  <div class=\"sec-tag\">04 \u00b7 Clocks & Ordering</div>\n  <h2>Why you cannot trust timestamps in distributed systems</h2>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\"><div class=\"concept-term\">Clock Skew</div><div class=\"concept-def\"><strong>Different servers have slightly different clocks, even with NTP. Typical skew: 1\u2013100ms. Maximum observed: seconds.</strong><br>\n      Problem: Server A timestamps event at 14:00:01.000, Server B at 14:00:00.998. B's event appears \"before\" A's despite happening after.<br>\n      <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 Never use wall-clock timestamps for event ordering in distributed systems. \"Last Write Wins\" based on timestamps will silently discard correct data.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Logical Clocks<br>(Lamport)</div><div class=\"concept-def\"><strong>A counter that increments on every event and is included in every message. Receiving a message with counter C \u2192 set local counter to max(local, C) + 1.</strong><br>\n      Guarantees: if event A causally precedes event B, then Lamport(A) &lt; Lamport(B).<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Causal ordering without synchronized clocks. Simple to implement.</span><br>\n      <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 Cannot tell if two events are concurrent (no causal relationship between them).</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Vector Clocks</div><div class=\"concept-def\"><strong>One counter per node. Captures causality and detects concurrent events.</strong><br>\n      Node A: [A:1, B:0, C:0]. Sends to B: B updates to [A:1, B:1, C:0]. If two events have incomparable vector clocks, they are concurrent (conflict).<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Detects conflicts precisely. Amazon Dynamo uses vector clocks for conflict detection in shopping carts.</span><br>\n      <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 Vector grows with number of nodes. Conflict resolution still needs application logic.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Google TrueTime</div><div class=\"concept-def\"><strong>Google Spanner's approach: GPS + atomic clocks provide a bounded uncertainty interval [earliest, latest] for the current time. Spanner waits out this uncertainty before committing.</strong><br>\n      Uncertainty: ~7ms. Spanner commits with at least 7ms delay to ensure all nodes agree on ordering.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Enables external consistency (linearisability) globally across datacenters. The only system that achieves this at global scale.</span><br>\n      <span style=\"color:#5a5848;font-size:12.5px;\">You cannot replicate TrueTime without specialized hardware. For most systems: use logical clocks or a single-region Raft-based system.</span></div></div>\n  </div>\n</section>\n\n<section id=\"followups\">\n  <div class=\"sec-tag\">05 \u00b7 Follow-ups</div>\n  <h2>Every hard follow-up, answered</h2>\n  <div class=\"faq-item\"><div class=\"faq-q\" onclick=\"toggle(this)\">How do you handle split-brain in a distributed system?<span class=\"tog\">+</span></div>\n  <div class=\"faq-a\"><strong>Split-brain: a network partition causes two groups of nodes to both believe they are the leader/primary, leading to divergent writes.</strong><br><br><strong>Prevention strategies:</strong><br>1. <strong>Quorum writes</strong>: a write only succeeds if acknowledged by majority (N/2+1). During partition, the minority partition cannot achieve quorum and stops accepting writes. Only the majority side proceeds. Used by: Raft, Cassandra QUORUM writes.<br><br>2. <strong>Fencing tokens</strong>: every time a new leader is elected, it receives a monotonically increasing token. Storage systems reject writes with older tokens. Even if the old leader thinks it is still active, its writes are rejected.<br><br>3. <strong>Lease-based leadership</strong>: leader holds a lease (timed lock). If it cannot renew before expiry, it steps down voluntarily. Used by: Kubernetes leader election via etcd.</div></div>\n  <div class=\"faq-item\"><div class=\"faq-q\" onclick=\"toggle(this)\">What is the difference between linearisability and serializability?<span class=\"tog\">+</span></div>\n  <div class=\"faq-a\"><strong>These are often confused but refer to different properties at different levels.</strong><br><br><strong>Linearisability</strong> is about <em>single operations</em> on a single object (key). It means every read-write operation appears to happen atomically at a single point in time. It is a property of a single key's history.<br><br><strong>Serializability</strong> is about <em>transactions</em> (groups of operations, possibly on multiple keys). It means the result of concurrent transactions is equivalent to some serial (one-at-a-time) execution. It is a property of the database's transaction isolation.<br><br><strong>Strict Serializability (Linearisable Serializability)</strong> = both: transactions are serialized AND operations appear instantaneous. This is what Spanner and CockroachDB provide. The strongest guarantee, but most expensive.</div></div>\n  <div class=\"faq-item\"><div class=\"faq-q\" onclick=\"toggle(this)\">How does the Saga pattern handle a payment failure mid-order?<span class=\"tog\">+</span></div>\n  <div class=\"faq-a\"><strong>Compensating transactions undo the effects of already-completed steps.</strong><br><br>Order saga steps: Reserve Inventory \u2192 Charge Payment \u2192 Create Shipment \u2192 Send Confirmation.<br><br>Failure at step 2 (payment declined):<br>1. Shipment not yet created \u2014 skip<br>2. <strong>Compensating transaction for step 1</strong>: call Inventory Service with \"release reservation for order X.\" Must be idempotent \u2014 if this fails and retries, it should not double-release.<br>3. Return \"payment failed\" to user.<br><br><strong>Key insight</strong>: compensating transactions must be idempotent and durable. Store the saga state in a database so you can resume compensation after a crash. This is what orchestration-based Sagas (e.g., AWS Step Functions, Temporal.io) manage for you automatically.</div></div>\n</section></div>\n<div class=\"footer\">DISTRIBUTED SYSTEMS \u00b7 CAP \u00b7 RAFT \u00b7 SAGA \u00b7 IDEMPOTENCY \u00b7 VECTOR CLOCKS \u00b7 MANISH-ALMANAC</div>\n\u003cscript>function toggle(el){el.parentElement.classList.toggle('open');}<\/script>\n</body></html>", tag: 'Distributed Sys' },
  load_balancing: { title: 'Load Balancing & Proxies', srcdoc: "<!DOCTYPE html>\n<html lang=\"en\"><head><meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Load Balancing: Proxies & Gateways</title>\n<link href=\"https://fonts.googleapis.com/css2?family=Playfair+Display:wght@700;900&family=Source+Sans+3:wght@300;400;500;600&family=JetBrains+Mono:wght@400;600&display=swap\" rel=\"stylesheet\">\n<style>\n:root{--ink:#0f0e0c;--page:#f7f5f0;--surface:#eeecea;--surface2:#e5e2dc;--border:#d4d0c8;--muted:#7a7568;--pg:#336791;--pg-bg:#eef4fb;--mg:#13aa52;--mg-bg:#edfaf2;--dy:#ff9900;--dy-bg:#fff8ec;--ca:#1287b1;--ca-bg:#eaf6fb;--red:#c0392b;--red-bg:#fdf0ee;--green:#1a7a4a;--green-bg:#edf8f2;--amber:#b8720a;--amber-bg:#fdf6e8;--blue:#1a4f8a;--blue-bg:#edf2fb;--mono:'JetBrains Mono',monospace;--serif:'Playfair Display',serif;--sans:'Source Sans 3',sans-serif;}\n*{box-sizing:border-box;margin:0;padding:0;}html{scroll-behavior:smooth;}\nbody{background:var(--page);color:var(--ink);font-family:var(--sans);font-size:15px;line-height:1.75;}\n.hero{background:var(--ink);color:#e8e4dc;padding:72px 24px 56px;position:relative;overflow:hidden;}\n.hero::before{content:'';position:absolute;inset:0;background:repeating-linear-gradient(45deg,transparent,transparent 40px,rgba(255,255,255,.015) 40px,rgba(255,255,255,.015) 41px);}\n.hero-inner{max-width:960px;margin:0 auto;position:relative;}\n.hero-tag{font-family:var(--mono);font-size:10px;letter-spacing:4px;color:#6a6458;text-transform:uppercase;margin-bottom:20px;}\nh1{font-family:var(--serif);font-size:clamp(32px,5vw,58px);font-weight:900;line-height:1.05;letter-spacing:-.5px;margin-bottom:20px;color:#f0ece4;}\nh1 em{color:#e8b84b;font-style:normal;}\n.hero-sub{font-size:15px;color:#7a7060;max-width:640px;line-height:1.7;margin-bottom:32px;}\n.db-pills{display:flex;flex-wrap:wrap;gap:8px;}\n.db-pill{font-family:var(--mono);font-size:10px;padding:5px 14px;border-radius:3px;border:1px solid;letter-spacing:.5px;}\n.pill-pg{border-color:#336791;color:#336791;background:rgba(51,103,145,.08);}\n.pill-mg{border-color:#13aa52;color:#13aa52;background:rgba(19,170,82,.08);}\n.pill-dy{border-color:#ff9900;color:#cc7a00;background:rgba(255,153,0,.08);}\n.pill-ca{border-color:#1287b1;color:#1287b1;background:rgba(18,135,177,.08);}\n.nav{position:sticky;top:0;z-index:100;background:var(--ink);border-bottom:1px solid #1e1c18;display:flex;overflow-x:auto;scrollbar-width:none;padding:0 20px;}\n.nav::-webkit-scrollbar{display:none;}\n.nav a{font-family:var(--mono);font-size:10px;letter-spacing:1px;color:#4a4840;text-decoration:none;padding:14px 12px;white-space:nowrap;border-bottom:2px solid transparent;transition:.18s;}\n.nav a:hover{color:#e8b84b;border-color:#e8b84b;}\n.wrap{max-width:960px;margin:0 auto;padding:0 20px;}\nsection{padding:56px 0 36px;border-bottom:2px solid var(--border);}\nsection:last-child{border:none;}\n.sec-tag{font-family:var(--mono);font-size:9px;letter-spacing:4px;text-transform:uppercase;color:var(--muted);margin-bottom:8px;display:flex;align-items:center;gap:10px;}\n.sec-tag::before{content:'';width:20px;height:1px;background:var(--border);}\nh2{font-family:var(--serif);font-size:clamp(22px,3.5vw,32px);font-weight:700;line-height:1.15;margin-bottom:18px;}\nh3{font-family:var(--sans);font-size:17px;font-weight:600;margin:32px 0 10px;border-bottom:1px solid var(--border);padding-bottom:6px;}\nh4{font-size:13px;font-weight:600;margin:16px 0 6px;text-transform:uppercase;letter-spacing:.5px;}\np{color:#3a3830;font-size:14.5px;margin-bottom:12px;}\nstrong{color:var(--ink);}\ncode{font-family:var(--mono);font-size:11.5px;background:var(--surface2);padding:1px 5px;border-radius:3px;color:var(--blue);}\n.db-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:14px;margin:24px 0;}\n.db-card{background:white;border:1px solid var(--border);border-radius:8px;padding:20px;position:relative;overflow:hidden;}\n.db-card::before{content:'';position:absolute;top:0;left:0;right:0;height:4px;}\n.db-card.pg::before{background:var(--pg);}\n.db-card.mg::before{background:var(--mg);}\n.db-card.dy::before{background:var(--dy);}\n.db-card.ca::before{background:var(--ca);}\n.db-logo{font-size:22px;margin-bottom:6px;}\n.db-name{font-family:var(--serif);font-size:17px;font-weight:700;margin-bottom:4px;}\n.db-type{font-family:var(--mono);font-size:9px;letter-spacing:2px;color:var(--muted);margin-bottom:10px;text-transform:uppercase;}\n.db-tagline{font-size:13px;color:#5a5848;line-height:1.55;}\n.db-born{font-family:var(--mono);font-size:9px;color:var(--muted);margin-top:8px;}\n.analogy{background:var(--ink);color:#c8c4b8;border-radius:8px;padding:24px 28px;margin:24px 0;}\n.analogy-label{font-family:var(--mono);font-size:9px;letter-spacing:3px;color:#6a6458;margin-bottom:10px;text-transform:uppercase;}\n.analogy-text{font-size:15px;line-height:1.75;color:#d8d4c8;}\n.analogy-text strong{color:#e8b84b;}\n.callout{border-radius:4px;padding:14px 18px;margin:18px 0;font-size:13.5px;border-left:3px solid;line-height:1.65;}\n.callout p{font-size:13.5px;margin-bottom:6px;}\n.callout p:last-child{margin:0;}\n.cl-blue{background:var(--blue-bg);border-color:var(--blue);color:#1a2a4a;}\n.cl-green{background:var(--green-bg);border-color:var(--green);color:#0a2a1a;}\n.cl-amber{background:var(--amber-bg);border-color:var(--amber);color:#3a2a08;}\n.cl-red{background:var(--red-bg);border-color:var(--red);color:#3a0a08;}\n.cl-lbl{font-family:var(--mono);font-size:9px;letter-spacing:3px;text-transform:uppercase;margin-bottom:6px;opacity:.7;}\n.codeblock{background:var(--ink);border-radius:6px;padding:20px 22px;font-family:var(--mono);font-size:11.5px;line-height:2;overflow-x:auto;margin:14px 0;color:#c8c4b8;border:1px solid #1e1c18;}\n.codeblock .c{color:#3e3d36;}.codeblock .k{color:#e8b84b;}.codeblock .s{color:#8bc4a0;}.codeblock .n{color:#e8946a;}.codeblock .t{color:#7aaee0;}.codeblock .g{color:#a8d878;}.codeblock .r{color:#e87878;}\n.comp-table{width:100%;border-collapse:collapse;margin:20px 0;font-size:13px;}\n.comp-table th{padding:10px 14px;border:1px solid var(--border);background:var(--surface2);font-family:var(--mono);font-size:9px;letter-spacing:1.5px;text-transform:uppercase;color:var(--muted);}\n.comp-table td{padding:11px 14px;border:1px solid var(--border);vertical-align:top;color:#3a3830;line-height:1.6;}\n.comp-table .row-head{font-family:var(--mono);font-size:11px;font-weight:600;background:var(--surface);color:var(--ink);white-space:nowrap;}\n.good{color:var(--green);font-weight:600;}.warn{color:var(--amber);font-weight:600;}.bad{color:var(--red);font-weight:600;}\n.dot{display:inline-block;width:9px;height:9px;border-radius:50%;margin-right:4px;vertical-align:middle;}\n.dot.g{background:var(--green);}.dot.a{background:var(--amber);}.dot.r{background:var(--red);}\n.use-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:14px;margin:20px 0;}\n.use-card{border:1px solid var(--border);border-radius:6px;padding:18px;background:white;}\n.use-card-head{font-family:var(--mono);font-size:11px;font-weight:600;margin-bottom:10px;display:flex;align-items:center;gap:8px;}\n.use-card ul{padding-left:16px;font-size:13px;color:#4a4838;line-height:1.7;}\n.use-card ul li{margin-bottom:4px;}\n.shard-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:14px;margin:20px 0;}\n.shard-card{background:var(--ink);border-radius:8px;padding:20px;color:#c8c4b8;}\n.shard-title{font-family:var(--mono);font-size:10px;letter-spacing:2px;color:#6a6458;margin-bottom:10px;text-transform:uppercase;}\n.shard-name{font-family:var(--serif);font-size:16px;font-weight:700;color:#e8b84b;margin-bottom:8px;}\n.shard-body{font-size:12.5px;line-height:1.65;color:#a8a49c;}\n.shard-verdict{margin-top:10px;font-family:var(--mono);font-size:10px;padding:4px 10px;border-radius:3px;display:inline-block;}\n.sv-easy{background:rgba(26,122,74,.2);color:#5ac882;}.sv-med{background:rgba(184,114,10,.2);color:#e8943a;}.sv-hard{background:rgba(192,57,43,.2);color:#e87868;}\n.faq-item{border:1px solid var(--border);border-radius:4px;margin-bottom:8px;overflow:hidden;}\n.faq-q{padding:14px 18px;display:flex;justify-content:space-between;align-items:center;cursor:pointer;background:white;font-size:14px;font-weight:500;color:var(--ink);user-select:none;}\n.faq-q:hover{background:var(--surface);}\n.faq-q .tog{font-size:18px;color:#e8b84b;flex-shrink:0;margin-left:12px;transition:transform .2s;font-family:var(--mono);}\n.faq-a{display:none;padding:18px;background:var(--surface);font-size:13.5px;color:#3a3830;line-height:1.75;border-top:1px solid var(--border);}\n.faq-item.open .faq-a{display:block;}.faq-item.open .tog{transform:rotate(45deg);}\n.sd-example{background:white;border:1px solid var(--border);border-radius:8px;margin:20px 0;overflow:hidden;}\n.sd-example-head{background:var(--ink);padding:14px 20px;display:flex;align-items:center;gap:12px;}\n.sd-example-title{font-family:var(--serif);font-size:16px;color:#f0ece4;font-weight:700;}\n.sd-example-tag{font-family:var(--mono);font-size:9px;letter-spacing:2px;color:#6a6458;border:1px solid #2e2c28;padding:3px 8px;border-radius:2px;}\n.sd-example-body{padding:20px;}\n.choice-row{display:flex;gap:10px;align-items:flex-start;padding:10px 0;border-bottom:1px solid var(--border);font-size:13px;}\n.choice-row:last-child{border:none;}\n.choice-label{font-family:var(--mono);font-size:10px;letter-spacing:1px;color:var(--muted);width:120px;flex-shrink:0;padding-top:2px;}\n.choice-val{flex:1;color:#3a3830;line-height:1.6;}\n.badge{display:inline-block;font-family:var(--mono);font-size:9px;padding:2px 7px;border-radius:2px;border:1px solid;margin-right:4px;font-weight:500;}\n.b-pg{background:var(--pg-bg);border-color:var(--pg);color:var(--pg);}.b-mg{background:var(--mg-bg);border-color:var(--mg);color:var(--mg);}.b-dy{background:var(--dy-bg);border-color:var(--dy);color:#b06000;}.b-ca{background:var(--ca-bg);border-color:var(--ca);color:var(--ca);}.b-g{background:var(--green-bg);border-color:var(--green);color:var(--green);}.b-r{background:var(--red-bg);border-color:var(--red);color:var(--red);}.b-a{background:var(--amber-bg);border-color:var(--amber);color:var(--amber);}\n.footer{background:var(--ink);text-align:center;padding:36px 20px;font-family:var(--mono);font-size:10px;color:#3a3830;letter-spacing:2px;}\n\n.step-block{background:#fff;border:1px solid var(--border);border-radius:8px;margin:20px 0;overflow:hidden;}\n.step-block-header{background:var(--ink);color:#e8e4dc;padding:13px 18px;font-family:var(--mono);font-size:10px;letter-spacing:2px;text-transform:uppercase;display:flex;align-items:center;gap:10px;}\n.sb-icon{font-size:16px;}\n.step-block-body{padding:0;}\n.step-row{display:flex;gap:0;border-bottom:1px solid var(--border);}\n.step-row:last-child{border-bottom:none;}\n.step-num{background:var(--surface);min-width:46px;display:flex;align-items:flex-start;justify-content:center;padding:16px 6px;font-family:var(--mono);font-size:11px;font-weight:700;color:var(--muted);flex-shrink:0;border-right:1px solid var(--border);}\n.step-content{padding:14px 18px;flex:1;}\n.step-q{font-weight:600;font-size:14px;color:var(--ink);margin-bottom:10px;}\n.step-options{display:flex;flex-direction:column;gap:6px;}\n.step-option{display:flex;gap:10px;align-items:flex-start;padding:9px 13px;border-radius:5px;font-size:13px;line-height:1.65;}\n.opt-yes{background:#edf8f2;border:1px solid #b8ddc8;}\n.opt-no{background:#fdf6e8;border:1px solid #e8c870;}\n.opt-mid{background:#edf2fb;border:1px solid #b8c8e8;}\n.opt-any{background:#f4f0fb;border:1px solid #c8b8e8;}\n.opt-arrow{font-family:var(--mono);font-size:12px;font-weight:700;flex-shrink:0;margin-top:1px;min-width:120px;}\n.opt-yes .opt-arrow{color:#1a7a4a;}\n.opt-no .opt-arrow{color:#b8720a;}\n.opt-mid .opt-arrow{color:#1a4f8a;}\n.opt-any .opt-arrow{color:#5a3c9a;}\n.opt-text{flex:1;color:#3a3830;}\n.concept-grid{display:grid;grid-template-columns:1fr;gap:0;margin:20px 0;border:1px solid var(--border);border-radius:8px;overflow:hidden;}\n.concept-row{display:flex;gap:0;border-bottom:1px solid var(--border);}\n.concept-row:last-child{border-bottom:none;}\n.concept-term{background:var(--ink);color:#e8b84b;font-family:var(--mono);font-size:11.5px;font-weight:600;min-width:155px;padding:14px 16px;flex-shrink:0;border-right:1px solid #2a2820;display:flex;align-items:flex-start;line-height:1.5;}\n.concept-def{padding:13px 16px;flex:1;font-size:13.5px;color:#3a3830;line-height:1.7;background:#fff;}\n.concept-def strong{color:var(--ink);}\n.concept-def code{background:var(--surface);padding:1px 5px;border-radius:3px;font-family:var(--mono);font-size:11px;color:var(--blue);}\n@media(max-width:560px){.concept-row{flex-direction:column;}.concept-term{min-width:auto;border-right:none;border-bottom:1px solid #2a2820;}.opt-arrow{min-width:80px;}}\n\n</style>\n</head><body>\n<div class=\"hero\"><div class=\"hero-inner\">\n  <div class=\"hero-tag\">System Design \u00b7 FAANG Interview Prep \u00b7 Manish-Almanac</div>\n  <h1>Load Balancing<br><em>Proxies & Gateways</em></h1>\n  <p class=\"hero-sub\">L4 vs L7, load balancing algorithms, circuit breakers, API Gateway vs service mesh, and zero-downtime deployments \u2014 every concept needed for system design interviews.</p>\n  <div class=\"db-pills\"><span class=\"db-pill\" style=\"border-color:#1a4f8a;color:#1a4f8a;background:rgba(26,79,138,.08)\">L4 / L7</span><span class=\"db-pill\" style=\"border-color:#1a7a4a;color:#1a7a4a;background:rgba(26,122,74,.08)\">Nginx</span><span class=\"db-pill\" style=\"border-color:#b8720a;color:#b8720a;background:rgba(184,114,10,.08)\">Envoy</span><span class=\"db-pill\" style=\"border-color:#c0392b;color:#c0392b;background:rgba(192,57,43,.08)\">Circuit Breaker</span><span class=\"db-pill\" style=\"border-color:#6040a0;color:#6040a0;background:rgba(96,64,160,.08)\">Service Mesh</span></div>\n</div></div>\n<nav class=\"nav\"><a href=\"#why\">Why LB</a><a href=\"#l4vsl7\">L4 vs L7</a><a href=\"#algorithms\">Algorithms</a><a href=\"#patterns\">Advanced Patterns</a><a href=\"#examples\">System Design</a><a href=\"#followups\">Follow-ups</a></nav>\n<div class=\"wrap\">\n<section id=\"why\">\n  <div class=\"sec-tag\">00 \u00b7 Why Load Balancing</div>\n  <h2>The first component in every system diagram</h2>\n  <p>A single server handling all traffic is a single point of failure and a performance ceiling. Load balancers distribute traffic across a fleet of servers, enabling horizontal scaling and eliminating single points of failure. In every FAANG system design diagram, the first arrow after \"Client\" points to a load balancer.</p>\n  <div class=\"analogy\">\n    <div class=\"analogy-label\">The supermarket checkout analogy</div>\n    <div class=\"analogy-text\">\n      A supermarket has 10 checkout lanes. A greeter (load balancer) at the entrance directs each customer to the shortest queue. Without the greeter, everyone crowds into lane 1 while lanes 2\u201310 sit empty.<br><br>\n      <strong>L4 load balancer</strong> = greeter who only looks at which lane is least busy (doesn't care what's in your cart).<br>\n      <strong>L7 load balancer</strong> = greeter who reads your items and sends produce-only carts to lane 3 (express), bulk items to lane 7 (large cart), etc.\n    </div>\n  </div>\n</section>\n\n<section id=\"l4vsl7\">\n  <div class=\"sec-tag\">01 \u00b7 L4 vs L7</div>\n  <h2>The most important distinction in load balancing</h2>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\"><div class=\"concept-term\">L4 (Transport Layer)</div><div class=\"concept-def\"><strong>Routes based on IP address and TCP/UDP port only. Does not inspect packet contents.</strong><br>\n      Decision: \"This TCP connection from 1.2.3.4 goes to server B.\"<br>\n      One TCP connection between client and server \u2014 the LB just forwards packets.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Extremely fast \u2014 no parsing overhead. Works for any protocol (TCP, UDP, SMTP, MySQL). Lower latency. Used for high-throughput, low-overhead routing.</span><br>\n      <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 Cannot make routing decisions based on URL, headers, cookies, or content. Cannot terminate SSL. Cannot implement application-level health checks.</span><br>\n      <span style=\"color:#5a5848;font-size:12.5px;\">Examples: AWS NLB (Network Load Balancer), HAProxy in TCP mode, Linux IPVS.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">L7 (Application Layer)</div><div class=\"concept-def\"><strong>Inspects HTTP headers, URL paths, cookies, and body to make routing decisions. Terminates the client connection and opens a new one to the backend.</strong><br>\n      Decision: \"This POST /api/payments request goes to the payments service. This GET /images/ request goes to the static content service.\"<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 URL-based routing (path-based or host-based). SSL termination (decrypts once at LB, unencrypted to backends). A/B testing and canary deploys. Rate limiting. Request/response transformation. Advanced health checks (HTTP 200 check, not just TCP connect).</span><br>\n      <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 Higher CPU overhead (parses every HTTP request). Slightly higher latency. Cannot handle raw TCP/UDP workloads.</span><br>\n      <span style=\"color:#5a5848;font-size:12.5px;\">Examples: AWS ALB, Nginx, Envoy, Traefik, HAProxy in HTTP mode.</span></div></div>\n  </div>\n</section>\n\n<section id=\"algorithms\">\n  <div class=\"sec-tag\">02 \u00b7 Algorithms</div>\n  <h2>How the LB decides which server gets the request</h2>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\"><div class=\"concept-term\">Round Robin</div><div class=\"concept-def\"><strong>Distribute requests evenly in rotation: server 1, 2, 3, 1, 2, 3...</strong><br>\n      Simple and fair for homogeneous servers with similar request costs.<br>\n      <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 Fails when servers have different capacities or when request cost varies (a 10ms request and a 5-second request are treated identically).</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Weighted Round Robin</div><div class=\"concept-def\"><strong>Servers get traffic proportional to their weight.</strong> Server A (32 cores) gets 2x traffic of Server B (16 cores).<br>\n      Useful during rolling deploys: new servers start with weight=0, gradually increased.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Handles heterogeneous fleets. Natural fit for canary deployments (weight new version at 5%).</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Least Connections</div><div class=\"concept-def\"><strong>Route to the server with fewest active connections currently.</strong><br>\n      Ideal for long-lived connections or variable request duration (WebSocket, video streaming, large file uploads).<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Naturally load-balances when request durations vary. A slow server accumulates connections and receives fewer new ones.</span><br>\n      <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 Requires the LB to track active connections per server \u2014 state overhead.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Consistent Hash</div><div class=\"concept-def\"><strong>Route requests from the same source (IP or user ID) to the same server consistently.</strong><br>\n      Required for: WebSocket connections (must reach the same server), stateful sessions without a shared cache, server-side caching (cache warm on one server).<br>\n      <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 Can create hot spots if one user generates disproportionate traffic. Server removal disrupts affected users.</span></div></div>\n  </div>\n</section>\n\n<section id=\"patterns\">\n  <div class=\"sec-tag\">03 \u00b7 Advanced Patterns</div>\n  <h2>Circuit breaker, health checks, and service mesh</h2>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\"><div class=\"concept-term\">Health Checks</div><div class=\"concept-def\"><strong>LB continuously probes backends. Unhealthy servers are removed from rotation.</strong><br>\n      Passive: track error rate and latency from real traffic. Remove servers exceeding threshold.<br>\n      Active: LB sends <code>GET /health</code> every 10s. If 3 consecutive failures \u2192 mark unhealthy \u2192 remove from pool.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Automatic removal of crashed instances without human intervention. Required for zero-downtime deployments.</span><br>\n      <span style=\"color:#5a5848;font-size:12.5px;\">Return 200 only when truly healthy: DB connected, dependencies up, startup complete. Not just \"process is running.\"</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Circuit Breaker</div><div class=\"concept-def\"><strong>Stop sending requests to a failing service instead of letting failures cascade.</strong><br>\n      Three states: Closed (normal) \u2192 Open (failures exceed threshold, stop sending) \u2192 Half-Open (send probe requests to check recovery).<br>\n      Example: Payment service is down. Without circuit breaker: all requests queue up, threads exhaust, your entire API times out. With circuit breaker: immediately return \"payment service unavailable\" and redirect to fallback.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Prevents cascade failures. Fast failure response. Used by: Netflix Hystrix, Envoy, Istio, Spring Cloud Circuit Breaker.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">API Gateway vs<br>Reverse Proxy vs<br>Service Mesh</div><div class=\"concept-def\"><strong>Three different things that are often confused:</strong><br>\n      <strong>Reverse Proxy</strong>: Sits in front of servers, forwards requests. Handles SSL, caching, compression. Example: Nginx.<br>\n      <strong>API Gateway</strong>: Smart reverse proxy with auth, rate limiting, request routing by path, API versioning, request/response transformation. Example: Kong, AWS API Gateway.<br>\n      <strong>Service Mesh</strong>: Sidecar proxies (Envoy) injected next to every service. Handles service-to-service communication: mTLS, circuit breaking, load balancing, distributed tracing \u2014 all without changing application code. Example: Istio, Linkerd.<br>\n      <span style=\"color:#5a5848;font-size:12.5px;\">Use API Gateway for external traffic (public API). Use service mesh for internal service-to-service traffic at large scale.</span></div></div>\n  </div>\n</section>\n\n<section id=\"examples\">\n  <div class=\"sec-tag\">04 \u00b7 System Design Examples</div>\n  <h2>Load balancing decisions in real systems</h2>\n  <div class=\"sd-example\">\n    <div class=\"sd-example-head\"><div class=\"sd-example-title\">Uber \u2014 Multi-Tier Load Balancing</div><span class=\"sd-example-tag\">GLOBAL SCALE</span></div>\n    <div class=\"sd-example-body\">\n      <div class=\"choice-row\"><div class=\"choice-label\">GLOBAL DNS</div><div class=\"choice-val\">AWS Route 53 with latency-based routing directs users to nearest region (Bangalore \u2192 Mumbai region, New York \u2192 us-east). Geo-routing at DNS layer before any L4/L7 balancer is involved.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">EDGE (L4)</div><div class=\"choice-val\">AWS NLB handles raw TCP traffic at the edge of each region. Terminates TCP efficiently. Routes to L7 cluster. Handles DDoS mitigation via AWS Shield.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">APPLICATION (L7)</div><div class=\"choice-val\"><span class=\"badge b-g\">Envoy \u2713</span> Path-based routing: <code>/api/rides</code> \u2192 Ride Service, <code>/api/payments</code> \u2192 Payment Service. Handles auth (JWT validation), rate limiting, circuit breaking to downstream services.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">WEBSOCKET</div><div class=\"choice-val\">Driver location WebSocket connections use consistent hash by driver_id \u2192 always reach same WebSocket server. Redis pub/sub propagates location updates to other servers if rider is on a different server.</div></div>\n    </div>\n  </div>\n</section>\n\n<section id=\"followups\">\n  <div class=\"sec-tag\">05 \u00b7 Follow-ups</div>\n  <h2>Every hard follow-up, answered</h2>\n  <div class=\"faq-item\"><div class=\"faq-q\" onclick=\"toggle(this)\">How do you achieve zero-downtime deployments with a load balancer?<span class=\"tog\">+</span></div>\n  <div class=\"faq-a\"><strong>Rolling deployment with connection draining.</strong><br><br>\n  1. Take server-1 out of rotation: set its weight to 0 in the LB. New requests stop going to it.<br>\n  2. <strong>Connection draining</strong>: wait for existing connections on server-1 to complete naturally (or timeout after 30s). During this period, server-1 still serves in-flight requests but receives no new ones.<br>\n  3. Deploy new version to server-1. Wait for health check to pass.<br>\n  4. Add server-1 back to rotation. Repeat for server-2, etc.<br><br>\n  For databases: <strong>blue-green deployment</strong> \u2014 spin up a complete new fleet, promote when ready. Instant cutover with instant rollback. Requires double infrastructure temporarily.</div></div>\n  <div class=\"faq-item\"><div class=\"faq-q\" onclick=\"toggle(this)\">Is the load balancer itself a single point of failure?<span class=\"tog\">+</span></div>\n  <div class=\"faq-a\"><strong>Yes \u2014 and the mitigation is to run multiple LBs with automatic failover.</strong><br><br>\n  For managed cloud LBs (AWS ALB/NLB): AWS runs them as a managed service across multiple AZs automatically. Not your problem.<br><br>\n  For self-managed LBs: run two Nginx/HAProxy instances in active-passive with keepalived. keepalived uses VRRP (Virtual Router Redundancy Protocol) \u2014 a virtual IP floats to whichever Nginx is healthy. If primary dies, virtual IP moves to secondary in &lt;1 second. DNS points to the virtual IP, not to either specific host.<br><br>\n  At Google/Netflix scale: use anycast routing \u2014 the same IP address is announced from multiple data centers. BGP routing automatically sends users to the nearest available one. Individual LB failures are invisible to users.</div></div>\n</section></div>\n<div class=\"footer\">LOAD BALANCING \u00b7 L4 \u00b7 L7 \u00b7 NGINX \u00b7 ENVOY \u00b7 CIRCUIT BREAKER \u00b7 API GATEWAY \u00b7 SERVICE MESH \u00b7 MANISH-ALMANAC</div>\n\u003cscript>function toggle(el){el.parentElement.classList.toggle('open');}<\/script>\n</body></html>", tag: 'Infra' },
  search: { title: 'Search & Elasticsearch', srcdoc: "<!DOCTYPE html>\n<html lang=\"en\"><head><meta charset=\"UTF-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Search: Elasticsearch & Inverted Index</title>\n<link href=\"https://fonts.googleapis.com/css2?family=Playfair+Display:wght@700;900&family=Source+Sans+3:wght@300;400;500;600&family=JetBrains+Mono:wght@400;600&display=swap\" rel=\"stylesheet\">\n<style>\n:root{--ink:#0f0e0c;--page:#f7f5f0;--surface:#eeecea;--surface2:#e5e2dc;--border:#d4d0c8;--muted:#7a7568;--pg:#336791;--pg-bg:#eef4fb;--mg:#13aa52;--mg-bg:#edfaf2;--dy:#ff9900;--dy-bg:#fff8ec;--ca:#1287b1;--ca-bg:#eaf6fb;--red:#c0392b;--red-bg:#fdf0ee;--green:#1a7a4a;--green-bg:#edf8f2;--amber:#b8720a;--amber-bg:#fdf6e8;--blue:#1a4f8a;--blue-bg:#edf2fb;--mono:'JetBrains Mono',monospace;--serif:'Playfair Display',serif;--sans:'Source Sans 3',sans-serif;}\n*{box-sizing:border-box;margin:0;padding:0;}html{scroll-behavior:smooth;}\nbody{background:var(--page);color:var(--ink);font-family:var(--sans);font-size:15px;line-height:1.75;}\n.hero{background:var(--ink);color:#e8e4dc;padding:72px 24px 56px;position:relative;overflow:hidden;}\n.hero::before{content:'';position:absolute;inset:0;background:repeating-linear-gradient(45deg,transparent,transparent 40px,rgba(255,255,255,.015) 40px,rgba(255,255,255,.015) 41px);}\n.hero-inner{max-width:960px;margin:0 auto;position:relative;}\n.hero-tag{font-family:var(--mono);font-size:10px;letter-spacing:4px;color:#6a6458;text-transform:uppercase;margin-bottom:20px;}\nh1{font-family:var(--serif);font-size:clamp(32px,5vw,58px);font-weight:900;line-height:1.05;letter-spacing:-.5px;margin-bottom:20px;color:#f0ece4;}\nh1 em{color:#e8b84b;font-style:normal;}\n.hero-sub{font-size:15px;color:#7a7060;max-width:640px;line-height:1.7;margin-bottom:32px;}\n.db-pills{display:flex;flex-wrap:wrap;gap:8px;}\n.db-pill{font-family:var(--mono);font-size:10px;padding:5px 14px;border-radius:3px;border:1px solid;letter-spacing:.5px;}\n.pill-pg{border-color:#336791;color:#336791;background:rgba(51,103,145,.08);}\n.pill-mg{border-color:#13aa52;color:#13aa52;background:rgba(19,170,82,.08);}\n.pill-dy{border-color:#ff9900;color:#cc7a00;background:rgba(255,153,0,.08);}\n.pill-ca{border-color:#1287b1;color:#1287b1;background:rgba(18,135,177,.08);}\n.nav{position:sticky;top:0;z-index:100;background:var(--ink);border-bottom:1px solid #1e1c18;display:flex;overflow-x:auto;scrollbar-width:none;padding:0 20px;}\n.nav::-webkit-scrollbar{display:none;}\n.nav a{font-family:var(--mono);font-size:10px;letter-spacing:1px;color:#4a4840;text-decoration:none;padding:14px 12px;white-space:nowrap;border-bottom:2px solid transparent;transition:.18s;}\n.nav a:hover{color:#e8b84b;border-color:#e8b84b;}\n.wrap{max-width:960px;margin:0 auto;padding:0 20px;}\nsection{padding:56px 0 36px;border-bottom:2px solid var(--border);}\nsection:last-child{border:none;}\n.sec-tag{font-family:var(--mono);font-size:9px;letter-spacing:4px;text-transform:uppercase;color:var(--muted);margin-bottom:8px;display:flex;align-items:center;gap:10px;}\n.sec-tag::before{content:'';width:20px;height:1px;background:var(--border);}\nh2{font-family:var(--serif);font-size:clamp(22px,3.5vw,32px);font-weight:700;line-height:1.15;margin-bottom:18px;}\nh3{font-family:var(--sans);font-size:17px;font-weight:600;margin:32px 0 10px;border-bottom:1px solid var(--border);padding-bottom:6px;}\nh4{font-size:13px;font-weight:600;margin:16px 0 6px;text-transform:uppercase;letter-spacing:.5px;}\np{color:#3a3830;font-size:14.5px;margin-bottom:12px;}\nstrong{color:var(--ink);}\ncode{font-family:var(--mono);font-size:11.5px;background:var(--surface2);padding:1px 5px;border-radius:3px;color:var(--blue);}\n.db-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:14px;margin:24px 0;}\n.db-card{background:white;border:1px solid var(--border);border-radius:8px;padding:20px;position:relative;overflow:hidden;}\n.db-card::before{content:'';position:absolute;top:0;left:0;right:0;height:4px;}\n.db-card.pg::before{background:var(--pg);}\n.db-card.mg::before{background:var(--mg);}\n.db-card.dy::before{background:var(--dy);}\n.db-card.ca::before{background:var(--ca);}\n.db-logo{font-size:22px;margin-bottom:6px;}\n.db-name{font-family:var(--serif);font-size:17px;font-weight:700;margin-bottom:4px;}\n.db-type{font-family:var(--mono);font-size:9px;letter-spacing:2px;color:var(--muted);margin-bottom:10px;text-transform:uppercase;}\n.db-tagline{font-size:13px;color:#5a5848;line-height:1.55;}\n.db-born{font-family:var(--mono);font-size:9px;color:var(--muted);margin-top:8px;}\n.analogy{background:var(--ink);color:#c8c4b8;border-radius:8px;padding:24px 28px;margin:24px 0;}\n.analogy-label{font-family:var(--mono);font-size:9px;letter-spacing:3px;color:#6a6458;margin-bottom:10px;text-transform:uppercase;}\n.analogy-text{font-size:15px;line-height:1.75;color:#d8d4c8;}\n.analogy-text strong{color:#e8b84b;}\n.callout{border-radius:4px;padding:14px 18px;margin:18px 0;font-size:13.5px;border-left:3px solid;line-height:1.65;}\n.callout p{font-size:13.5px;margin-bottom:6px;}\n.callout p:last-child{margin:0;}\n.cl-blue{background:var(--blue-bg);border-color:var(--blue);color:#1a2a4a;}\n.cl-green{background:var(--green-bg);border-color:var(--green);color:#0a2a1a;}\n.cl-amber{background:var(--amber-bg);border-color:var(--amber);color:#3a2a08;}\n.cl-red{background:var(--red-bg);border-color:var(--red);color:#3a0a08;}\n.cl-lbl{font-family:var(--mono);font-size:9px;letter-spacing:3px;text-transform:uppercase;margin-bottom:6px;opacity:.7;}\n.codeblock{background:var(--ink);border-radius:6px;padding:20px 22px;font-family:var(--mono);font-size:11.5px;line-height:2;overflow-x:auto;margin:14px 0;color:#c8c4b8;border:1px solid #1e1c18;}\n.codeblock .c{color:#3e3d36;}.codeblock .k{color:#e8b84b;}.codeblock .s{color:#8bc4a0;}.codeblock .n{color:#e8946a;}.codeblock .t{color:#7aaee0;}.codeblock .g{color:#a8d878;}.codeblock .r{color:#e87878;}\n.comp-table{width:100%;border-collapse:collapse;margin:20px 0;font-size:13px;}\n.comp-table th{padding:10px 14px;border:1px solid var(--border);background:var(--surface2);font-family:var(--mono);font-size:9px;letter-spacing:1.5px;text-transform:uppercase;color:var(--muted);}\n.comp-table td{padding:11px 14px;border:1px solid var(--border);vertical-align:top;color:#3a3830;line-height:1.6;}\n.comp-table .row-head{font-family:var(--mono);font-size:11px;font-weight:600;background:var(--surface);color:var(--ink);white-space:nowrap;}\n.good{color:var(--green);font-weight:600;}.warn{color:var(--amber);font-weight:600;}.bad{color:var(--red);font-weight:600;}\n.dot{display:inline-block;width:9px;height:9px;border-radius:50%;margin-right:4px;vertical-align:middle;}\n.dot.g{background:var(--green);}.dot.a{background:var(--amber);}.dot.r{background:var(--red);}\n.use-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:14px;margin:20px 0;}\n.use-card{border:1px solid var(--border);border-radius:6px;padding:18px;background:white;}\n.use-card-head{font-family:var(--mono);font-size:11px;font-weight:600;margin-bottom:10px;display:flex;align-items:center;gap:8px;}\n.use-card ul{padding-left:16px;font-size:13px;color:#4a4838;line-height:1.7;}\n.use-card ul li{margin-bottom:4px;}\n.shard-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:14px;margin:20px 0;}\n.shard-card{background:var(--ink);border-radius:8px;padding:20px;color:#c8c4b8;}\n.shard-title{font-family:var(--mono);font-size:10px;letter-spacing:2px;color:#6a6458;margin-bottom:10px;text-transform:uppercase;}\n.shard-name{font-family:var(--serif);font-size:16px;font-weight:700;color:#e8b84b;margin-bottom:8px;}\n.shard-body{font-size:12.5px;line-height:1.65;color:#a8a49c;}\n.shard-verdict{margin-top:10px;font-family:var(--mono);font-size:10px;padding:4px 10px;border-radius:3px;display:inline-block;}\n.sv-easy{background:rgba(26,122,74,.2);color:#5ac882;}.sv-med{background:rgba(184,114,10,.2);color:#e8943a;}.sv-hard{background:rgba(192,57,43,.2);color:#e87868;}\n.faq-item{border:1px solid var(--border);border-radius:4px;margin-bottom:8px;overflow:hidden;}\n.faq-q{padding:14px 18px;display:flex;justify-content:space-between;align-items:center;cursor:pointer;background:white;font-size:14px;font-weight:500;color:var(--ink);user-select:none;}\n.faq-q:hover{background:var(--surface);}\n.faq-q .tog{font-size:18px;color:#e8b84b;flex-shrink:0;margin-left:12px;transition:transform .2s;font-family:var(--mono);}\n.faq-a{display:none;padding:18px;background:var(--surface);font-size:13.5px;color:#3a3830;line-height:1.75;border-top:1px solid var(--border);}\n.faq-item.open .faq-a{display:block;}.faq-item.open .tog{transform:rotate(45deg);}\n.sd-example{background:white;border:1px solid var(--border);border-radius:8px;margin:20px 0;overflow:hidden;}\n.sd-example-head{background:var(--ink);padding:14px 20px;display:flex;align-items:center;gap:12px;}\n.sd-example-title{font-family:var(--serif);font-size:16px;color:#f0ece4;font-weight:700;}\n.sd-example-tag{font-family:var(--mono);font-size:9px;letter-spacing:2px;color:#6a6458;border:1px solid #2e2c28;padding:3px 8px;border-radius:2px;}\n.sd-example-body{padding:20px;}\n.choice-row{display:flex;gap:10px;align-items:flex-start;padding:10px 0;border-bottom:1px solid var(--border);font-size:13px;}\n.choice-row:last-child{border:none;}\n.choice-label{font-family:var(--mono);font-size:10px;letter-spacing:1px;color:var(--muted);width:120px;flex-shrink:0;padding-top:2px;}\n.choice-val{flex:1;color:#3a3830;line-height:1.6;}\n.badge{display:inline-block;font-family:var(--mono);font-size:9px;padding:2px 7px;border-radius:2px;border:1px solid;margin-right:4px;font-weight:500;}\n.b-pg{background:var(--pg-bg);border-color:var(--pg);color:var(--pg);}.b-mg{background:var(--mg-bg);border-color:var(--mg);color:var(--mg);}.b-dy{background:var(--dy-bg);border-color:var(--dy);color:#b06000;}.b-ca{background:var(--ca-bg);border-color:var(--ca);color:var(--ca);}.b-g{background:var(--green-bg);border-color:var(--green);color:var(--green);}.b-r{background:var(--red-bg);border-color:var(--red);color:var(--red);}.b-a{background:var(--amber-bg);border-color:var(--amber);color:var(--amber);}\n.footer{background:var(--ink);text-align:center;padding:36px 20px;font-family:var(--mono);font-size:10px;color:#3a3830;letter-spacing:2px;}\n\n.step-block{background:#fff;border:1px solid var(--border);border-radius:8px;margin:20px 0;overflow:hidden;}\n.step-block-header{background:var(--ink);color:#e8e4dc;padding:13px 18px;font-family:var(--mono);font-size:10px;letter-spacing:2px;text-transform:uppercase;display:flex;align-items:center;gap:10px;}\n.sb-icon{font-size:16px;}\n.step-block-body{padding:0;}\n.step-row{display:flex;gap:0;border-bottom:1px solid var(--border);}\n.step-row:last-child{border-bottom:none;}\n.step-num{background:var(--surface);min-width:46px;display:flex;align-items:flex-start;justify-content:center;padding:16px 6px;font-family:var(--mono);font-size:11px;font-weight:700;color:var(--muted);flex-shrink:0;border-right:1px solid var(--border);}\n.step-content{padding:14px 18px;flex:1;}\n.step-q{font-weight:600;font-size:14px;color:var(--ink);margin-bottom:10px;}\n.step-options{display:flex;flex-direction:column;gap:6px;}\n.step-option{display:flex;gap:10px;align-items:flex-start;padding:9px 13px;border-radius:5px;font-size:13px;line-height:1.65;}\n.opt-yes{background:#edf8f2;border:1px solid #b8ddc8;}\n.opt-no{background:#fdf6e8;border:1px solid #e8c870;}\n.opt-mid{background:#edf2fb;border:1px solid #b8c8e8;}\n.opt-any{background:#f4f0fb;border:1px solid #c8b8e8;}\n.opt-arrow{font-family:var(--mono);font-size:12px;font-weight:700;flex-shrink:0;margin-top:1px;min-width:120px;}\n.opt-yes .opt-arrow{color:#1a7a4a;}\n.opt-no .opt-arrow{color:#b8720a;}\n.opt-mid .opt-arrow{color:#1a4f8a;}\n.opt-any .opt-arrow{color:#5a3c9a;}\n.opt-text{flex:1;color:#3a3830;}\n.concept-grid{display:grid;grid-template-columns:1fr;gap:0;margin:20px 0;border:1px solid var(--border);border-radius:8px;overflow:hidden;}\n.concept-row{display:flex;gap:0;border-bottom:1px solid var(--border);}\n.concept-row:last-child{border-bottom:none;}\n.concept-term{background:var(--ink);color:#e8b84b;font-family:var(--mono);font-size:11.5px;font-weight:600;min-width:155px;padding:14px 16px;flex-shrink:0;border-right:1px solid #2a2820;display:flex;align-items:flex-start;line-height:1.5;}\n.concept-def{padding:13px 16px;flex:1;font-size:13.5px;color:#3a3830;line-height:1.7;background:#fff;}\n.concept-def strong{color:var(--ink);}\n.concept-def code{background:var(--surface);padding:1px 5px;border-radius:3px;font-family:var(--mono);font-size:11px;color:var(--blue);}\n@media(max-width:560px){.concept-row{flex-direction:column;}.concept-term{min-width:auto;border-right:none;border-bottom:1px solid #2a2820;}.opt-arrow{min-width:80px;}}\n\n</style></head><body>\n<div class=\"hero\"><div class=\"hero-inner\">\n  <div class=\"hero-tag\">System Design \u00b7 FAANG Interview Prep \u00b7 Manish-Almanac</div>\n  <h1>Search<br><em>Elasticsearch & Inverted Index</em></h1>\n  <p class=\"hero-sub\">How search works from first principles \u2014 inverted index, BM25 relevance, Elasticsearch architecture, typeahead design, and vector search.</p>\n  <div class=\"db-pills\"><span class=\"db-pill\" style=\"border-color:#c0392b;color:#c0392b;background:#c0392b18\">Elasticsearch</span><span class=\"db-pill\" style=\"border-color:#1a4f8a;color:#1a4f8a;background:#1a4f8a18\">Inverted Index</span><span class=\"db-pill\" style=\"border-color:#1a7a4a;color:#1a7a4a;background:#1a7a4a18\">BM25</span><span class=\"db-pill\" style=\"border-color:#b8720a;color:#b8720a;background:#b8720a18\">Typeahead</span><span class=\"db-pill\" style=\"border-color:#6040a0;color:#6040a0;background:#6040a018\">Vector Search</span></div>\n</div></div>\n<nav class=\"nav\"><a href=\"#intuition\">Why Search</a><a href=\"#inverted\">Inverted Index</a><a href=\"#elasticsearch\">ES Architecture</a><a href=\"#typeahead\">Typeahead</a><a href=\"#examples\">System Design</a><a href=\"#followups\">Follow-ups</a></nav>\n<div class=\"wrap\">\n<section id=\"intuition\">\n  <div class=\"sec-tag\">00 \u00b7 Core Intuition</div>\n  <h2>Why a database cannot do what a search engine does</h2>\n  <p>A SQL database index finds exact values fast: <code>WHERE user_id = 123</code>. But <code>WHERE body LIKE '%distributed systems%'</code> requires a full table scan \u2014 every row, every time. At 1 billion documents, that takes minutes. A search engine can answer this in milliseconds because it inverts the problem entirely.</p>\n  <div class=\"analogy\">\n    <div class=\"analogy-label\">The book index analogy</div>\n    <div class=\"analogy-text\">\n      A database is a book read cover-to-cover to find a word. Slow.<br><br>\n      A search engine is a book with an index at the back: \"distributed systems \u2192 pages 12, 47, 203, 891.\" You go directly to those pages. That back-of-book index is an <strong>inverted index</strong> \u2014 and it is the entire secret of how search works.\n    </div>\n  </div>\n</section>\n\n<section id=\"inverted\">\n  <div class=\"sec-tag\">01 \u00b7 Inverted Index</div>\n  <h2>The data structure that powers every search engine</h2>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\"><div class=\"concept-term\">How It Works</div><div class=\"concept-def\"><strong>An inverted index maps each unique term to the list of documents containing it.</strong><br>\n      Documents: Doc1=\"Redis is fast\", Doc2=\"Redis scales well\", Doc3=\"Kafka is fast\"<br>\n      Inverted index:<br>\n      <code>redis   \u2192 [Doc1, Doc2]</code><br>\n      <code>fast    \u2192 [Doc1, Doc3]</code><br>\n      <code>is      \u2192 [Doc1, Doc3]</code><br>\n      <code>scales  \u2192 [Doc2]</code><br>\n      Query \"redis fast\" \u2192 intersection of [Doc1,Doc2] and [Doc1,Doc3] \u2192 <strong>Doc1</strong> (contains both terms)</div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Posting List</div><div class=\"concept-def\"><strong>For each term, the index stores not just document IDs but positions and frequencies.</strong><br>\n      <code>redis \u2192 [(Doc1, freq:1, pos:[0]), (Doc2, freq:1, pos:[0])]</code><br>\n      Position enables phrase queries: \"redis cluster\" requires \"redis\" and \"cluster\" to be adjacent.<br>\n      Frequency enables relevance scoring \u2014 a document mentioning \"redis\" 20 times ranks higher than one mentioning it once.</div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Text Analysis Pipeline</div><div class=\"concept-def\"><strong>Before indexing, text passes through an analysis pipeline that normalises it.</strong><br>\n      1. <strong>Tokenization</strong>: \"Redis is Fast!\" \u2192 [\"Redis\", \"is\", \"Fast\"]<br>\n      2. <strong>Lowercasing</strong>: \u2192 [\"redis\", \"is\", \"fast\"]<br>\n      3. <strong>Stop word removal</strong>: \u2192 [\"redis\", \"fast\"] (removes \"is\")<br>\n      4. <strong>Stemming/Lemmatization</strong>: \"running\" \u2192 \"run\", \"faster\" \u2192 \"fast\"<br>\n      <span style=\"color:#5a5848;font-size:12.5px;\">The same pipeline must run at query time. \"Running Redis\" \u2192 [\"run\", \"redis\"] \u2192 matches documents containing \"run\" or \"redis\" in any form.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">TF-IDF / BM25</div><div class=\"concept-def\"><strong>Relevance scoring: not all matches are equal.</strong><br>\n      <strong>TF (Term Frequency)</strong>: how often does the term appear in this document? More occurrences = more relevant.<br>\n      <strong>IDF (Inverse Document Frequency)</strong>: how rare is the term across all documents? \"the\" appears everywhere \u2014 low IDF, low importance. \"Kafka\" appears rarely \u2014 high IDF, high importance.<br>\n      <strong>BM25</strong>: modern improvement over TF-IDF used by Elasticsearch. Prevents very long documents from dominating just because they mention a term more times.<br>\n      <span style=\"color:#5a5848;font-size:12.5px;\">Elasticsearch uses BM25 by default. You can boost specific fields (title matches worth 3x body matches).</span></div></div>\n  </div>\n</section>\n\n<section id=\"elasticsearch\">\n  <div class=\"sec-tag\">02 \u00b7 Elasticsearch Architecture</div>\n  <h2>How ES scales to billions of documents</h2>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\"><div class=\"concept-term\">Index \u2192 Shards</div><div class=\"concept-def\"><strong>An Elasticsearch index is split into N primary shards. Each shard is a complete, independent Lucene index.</strong><br>\n      Index \"tweets\" with 5 shards: each shard holds ~20% of documents. Queries fan out to all 5 shards in parallel, results merged by the coordinator.<br>\n      <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 Shard count is set at creation and cannot be changed (except via reindex). Over-sharding (too many small shards) is as harmful as under-sharding (too few large ones). Rule of thumb: aim for 10\u201350GB per shard.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Replication</div><div class=\"concept-def\"><strong>Each primary shard has N replica shards on different nodes.</strong><br>\n      Writes: go to primary, primary replicates to replicas.<br>\n      Reads: can be served by primary or any replica \u2014 distributes read load.<br>\n      Node failure: replica promoted to primary automatically.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Replicas both provide HA and increase read throughput. 5 shards \u00d7 2 replicas = 15 Lucene indexes total across the cluster.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Near Real-Time<br>(NRT) Search</div><div class=\"concept-def\"><strong>Newly indexed documents are searchable within ~1 second, not immediately.</strong><br>\n      Lucene writes to an in-memory buffer \u2192 every 1 second, refreshed to a new segment (searchable) \u2192 eventually merged into larger segments.<br>\n      <span style=\"color:#5a5848;font-size:12.5px;\">This is why Elasticsearch is \"near real-time\" not \"real-time.\" To force immediate visibility: <code>?refresh=true</code> on indexing \u2014 forces a refresh but hurts write throughput. Only use for critical flows.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Lucene Segments</div><div class=\"concept-def\"><strong>Lucene (the underlying library) writes data in immutable segments.</strong><br>\n      New documents \u2192 write buffer \u2192 periodic flush \u2192 new immutable segment. Background merges combine small segments into larger ones (like Cassandra SSTables, like ClickHouse parts).<br>\n      <span style=\"color:#5a5848;font-size:12.5px;\">Deletes are soft-deletes (marked, not removed) until a merge happens. This is why delete-heavy workloads require periodic forced merges to reclaim space.</span></div></div>\n  </div>\n</section>\n\n<section id=\"typeahead\">\n  <div class=\"sec-tag\">03 \u00b7 Typeahead / Autocomplete</div>\n  <h2>Design: search-as-you-type at FAANG scale</h2>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\"><div class=\"concept-term\">Prefix Trie</div><div class=\"concept-def\"><strong>A tree where each node is a character. Every path from root to leaf is a word. O(L) lookup for a prefix of length L \u2014 regardless of vocabulary size.</strong><br>\n      To find all words starting with \"redis\": traverse to node 'r'\u2192'e'\u2192'd'\u2192'i'\u2192's', return all words in subtree.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Fast prefix lookup. Memory-efficient with shared prefixes. Used by: Google Suggest backend, IDE autocomplete.</span><br>\n      <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 Storing popularity scores in a trie and returning top-K results requires augmenting each node with a max-heap \u2014 complex. Sharding a trie across machines is non-trivial.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Elasticsearch<br>Completion Suggester</div><div class=\"concept-def\"><strong>Built-in completion suggester using an in-memory FST (Finite State Transducer) \u2014 more memory-efficient than a trie.</strong><br>\n      Index time: store completion field with weight (popularity score).<br>\n      Query: <code>suggest: {prefix: \"red\", field: \"title.completion\", size: 5}</code><br>\n      Returns top-5 completions by weight instantly.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Easy to implement on top of existing ES infrastructure. Handles millions of suggestions in milliseconds.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Redis ZSET Approach</div><div class=\"concept-def\"><strong>Store all prefixes as ZSET members scored by popularity. For \"redis\", store \"r\", \"re\", \"red\", \"redi\", \"redis\" all pointing to the suggestion with its popularity score.</strong><br>\n      <code>ZRANGEBYLEX suggestions \"[redis\" \"[redis\u00ff\" LIMIT 0 5</code><br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Extremely fast (sub-ms). Works well for known vocabulary (hashtags, product names). Easy to update popularity in real time with ZINCRBY.</span><br>\n      <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 Storage: O(L \u00d7 V) where L is avg word length and V is vocabulary size. For a 10M-word vocabulary, this becomes large.</span></div></div>\n  </div>\n</section>\n\n<section id=\"examples\">\n  <div class=\"sec-tag\">04 \u00b7 System Design Examples</div>\n  <h2>Search in real systems</h2>\n  <div class=\"sd-example\">\n    <div class=\"sd-example-head\"><div class=\"sd-example-title\">Twitter Search</div><span class=\"sd-example-tag\">500M TWEETS/DAY</span></div>\n    <div class=\"sd-example-body\">\n      <div class=\"choice-row\"><div class=\"choice-label\">WRITE PATH</div><div class=\"choice-val\">New tweet \u2192 Kafka \u2192 Indexing Service \u2192 Elasticsearch. The Kafka buffer decouples tweet volume from ES indexing rate. ES indexes ~6K tweets/sec sustained. NRT lag: ~1 second before searchable.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">SEARCH</div><div class=\"choice-val\"><span class=\"badge b-g\">Elasticsearch \u2713</span> Full-text BM25 scoring + recency boost + engagement boost. Query rewriting: \"from:elonmusk\" \u2192 field-specific filter. Hashtag search: exact term match on the hashtag field (no tokenization).</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">TRENDING</div><div class=\"choice-val\">Trending hashtags NOT from ES \u2014 from a streaming Count-Min Sketch pipeline (Kafka + Flink + Redis ZSET). ES is too slow for trending (requires aggregation queries). The two systems complement each other.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">WHY NOT SQL</div><div class=\"choice-val\"><code>LIKE '%distributed%'</code> on 500M tweets = full table scan = minutes. Elasticsearch full-text search on same data = milliseconds. Not even close.</div></div>\n    </div>\n  </div>\n</section>\n\n<section id=\"followups\">\n  <div class=\"sec-tag\">05 \u00b7 Follow-ups</div>\n  <h2>Every hard follow-up, answered</h2>\n  <div class=\"faq-item\"><div class=\"faq-q\" onclick=\"toggle(this)\">How do you keep Elasticsearch in sync with your primary database?<span class=\"tog\">+</span></div>\n  <div class=\"faq-a\"><strong>Two patterns, with very different trade-offs:</strong><br><br><strong>1. Dual write</strong>: Application writes to DB AND ES in the same request. Simple but dangerous \u2014 if ES write fails, you have inconsistency with no way to detect it. Acceptable only for non-critical search.<br><br><strong>2. Change Data Capture (CDC)</strong>: Debezium (or similar) reads the PostgreSQL WAL (Write-Ahead Log) and publishes every change to Kafka. An ES indexing consumer reads from Kafka and keeps ES in sync. This is the production approach:<br>\u2014 Source of truth is always the DB<br>\u2014 ES is an eventually consistent read replica<br>\u2014 On ES failure, reindex from DB<br>\u2014 Typical lag: 100ms\u20132s<br><br>Tools: Debezium + Kafka + Elasticsearch Kafka Connector. Used by: LinkedIn, Airbnb, Shopify.</div></div>\n  <div class=\"faq-item\"><div class=\"faq-q\" onclick=\"toggle(this)\">What is vector search and when do you need it?<span class=\"tog\">+</span></div>\n  <div class=\"faq-a\"><strong>Vector search finds documents semantically similar to a query, not just exact keyword matches.</strong><br><br>Classic inverted index search for \"fast database\" would not return a document about \"high-performance data store\" \u2014 different words, even if same meaning. Vector search uses ML embeddings (e.g., OpenAI text-embedding-ada-002) to convert both query and documents to dense vectors in the same semantic space. Documents near the query vector in that space are semantically similar.<br><br><strong>Implementation</strong>: index document embeddings in a vector database (Pinecone, Weaviate, Milvus, or Elasticsearch with kNN). Query: embed the query text \u2192 find K nearest neighbours using approximate nearest neighbour (HNSW algorithm).<br><br><strong>When to use</strong>: semantic search (\"show me articles about making databases fast\"), recommendation (\"more content like this\"), Q&A (RAG \u2014 Retrieval Augmented Generation for LLMs).<br><br><strong>Hybrid search</strong>: combine keyword BM25 + vector KNN scores (Reciprocal Rank Fusion). Best of both worlds \u2014 used by production AI search systems.</div></div>\n</section></div>\n<div class=\"footer\">SEARCH \u00b7 ELASTICSEARCH \u00b7 INVERTED INDEX \u00b7 BM25 \u00b7 TYPEAHEAD \u00b7 VECTOR SEARCH \u00b7 MANISH-ALMANAC</div>\n\u003cscript>function toggle(el){el.parentElement.classList.toggle('open');}<\/script>\n</body></html>", tag: 'Search' },
  object_storage: { title: 'Object Storage: S3 & Blob Store', srcdoc: "<!DOCTYPE html>\n<html lang=\"en\"><head><meta charset=\"UTF-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Object Storage: S3 & Blob Store</title>\n<link href=\"https://fonts.googleapis.com/css2?family=Playfair+Display:wght@700;900&family=Source+Sans+3:wght@300;400;500;600&family=JetBrains+Mono:wght@400;600&display=swap\" rel=\"stylesheet\">\n<style>\n:root{--ink:#0f0e0c;--page:#f7f5f0;--surface:#eeecea;--surface2:#e5e2dc;--border:#d4d0c8;--muted:#7a7568;--pg:#336791;--pg-bg:#eef4fb;--mg:#13aa52;--mg-bg:#edfaf2;--dy:#ff9900;--dy-bg:#fff8ec;--ca:#1287b1;--ca-bg:#eaf6fb;--red:#c0392b;--red-bg:#fdf0ee;--green:#1a7a4a;--green-bg:#edf8f2;--amber:#b8720a;--amber-bg:#fdf6e8;--blue:#1a4f8a;--blue-bg:#edf2fb;--mono:'JetBrains Mono',monospace;--serif:'Playfair Display',serif;--sans:'Source Sans 3',sans-serif;}\n*{box-sizing:border-box;margin:0;padding:0;}html{scroll-behavior:smooth;}\nbody{background:var(--page);color:var(--ink);font-family:var(--sans);font-size:15px;line-height:1.75;}\n.hero{background:var(--ink);color:#e8e4dc;padding:72px 24px 56px;position:relative;overflow:hidden;}\n.hero::before{content:'';position:absolute;inset:0;background:repeating-linear-gradient(45deg,transparent,transparent 40px,rgba(255,255,255,.015) 40px,rgba(255,255,255,.015) 41px);}\n.hero-inner{max-width:960px;margin:0 auto;position:relative;}\n.hero-tag{font-family:var(--mono);font-size:10px;letter-spacing:4px;color:#6a6458;text-transform:uppercase;margin-bottom:20px;}\nh1{font-family:var(--serif);font-size:clamp(32px,5vw,58px);font-weight:900;line-height:1.05;letter-spacing:-.5px;margin-bottom:20px;color:#f0ece4;}\nh1 em{color:#e8b84b;font-style:normal;}\n.hero-sub{font-size:15px;color:#7a7060;max-width:640px;line-height:1.7;margin-bottom:32px;}\n.db-pills{display:flex;flex-wrap:wrap;gap:8px;}\n.db-pill{font-family:var(--mono);font-size:10px;padding:5px 14px;border-radius:3px;border:1px solid;letter-spacing:.5px;}\n.pill-pg{border-color:#336791;color:#336791;background:rgba(51,103,145,.08);}\n.pill-mg{border-color:#13aa52;color:#13aa52;background:rgba(19,170,82,.08);}\n.pill-dy{border-color:#ff9900;color:#cc7a00;background:rgba(255,153,0,.08);}\n.pill-ca{border-color:#1287b1;color:#1287b1;background:rgba(18,135,177,.08);}\n.nav{position:sticky;top:0;z-index:100;background:var(--ink);border-bottom:1px solid #1e1c18;display:flex;overflow-x:auto;scrollbar-width:none;padding:0 20px;}\n.nav::-webkit-scrollbar{display:none;}\n.nav a{font-family:var(--mono);font-size:10px;letter-spacing:1px;color:#4a4840;text-decoration:none;padding:14px 12px;white-space:nowrap;border-bottom:2px solid transparent;transition:.18s;}\n.nav a:hover{color:#e8b84b;border-color:#e8b84b;}\n.wrap{max-width:960px;margin:0 auto;padding:0 20px;}\nsection{padding:56px 0 36px;border-bottom:2px solid var(--border);}\nsection:last-child{border:none;}\n.sec-tag{font-family:var(--mono);font-size:9px;letter-spacing:4px;text-transform:uppercase;color:var(--muted);margin-bottom:8px;display:flex;align-items:center;gap:10px;}\n.sec-tag::before{content:'';width:20px;height:1px;background:var(--border);}\nh2{font-family:var(--serif);font-size:clamp(22px,3.5vw,32px);font-weight:700;line-height:1.15;margin-bottom:18px;}\nh3{font-family:var(--sans);font-size:17px;font-weight:600;margin:32px 0 10px;border-bottom:1px solid var(--border);padding-bottom:6px;}\nh4{font-size:13px;font-weight:600;margin:16px 0 6px;text-transform:uppercase;letter-spacing:.5px;}\np{color:#3a3830;font-size:14.5px;margin-bottom:12px;}\nstrong{color:var(--ink);}\ncode{font-family:var(--mono);font-size:11.5px;background:var(--surface2);padding:1px 5px;border-radius:3px;color:var(--blue);}\n.db-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:14px;margin:24px 0;}\n.db-card{background:white;border:1px solid var(--border);border-radius:8px;padding:20px;position:relative;overflow:hidden;}\n.db-card::before{content:'';position:absolute;top:0;left:0;right:0;height:4px;}\n.db-card.pg::before{background:var(--pg);}\n.db-card.mg::before{background:var(--mg);}\n.db-card.dy::before{background:var(--dy);}\n.db-card.ca::before{background:var(--ca);}\n.db-logo{font-size:22px;margin-bottom:6px;}\n.db-name{font-family:var(--serif);font-size:17px;font-weight:700;margin-bottom:4px;}\n.db-type{font-family:var(--mono);font-size:9px;letter-spacing:2px;color:var(--muted);margin-bottom:10px;text-transform:uppercase;}\n.db-tagline{font-size:13px;color:#5a5848;line-height:1.55;}\n.db-born{font-family:var(--mono);font-size:9px;color:var(--muted);margin-top:8px;}\n.analogy{background:var(--ink);color:#c8c4b8;border-radius:8px;padding:24px 28px;margin:24px 0;}\n.analogy-label{font-family:var(--mono);font-size:9px;letter-spacing:3px;color:#6a6458;margin-bottom:10px;text-transform:uppercase;}\n.analogy-text{font-size:15px;line-height:1.75;color:#d8d4c8;}\n.analogy-text strong{color:#e8b84b;}\n.callout{border-radius:4px;padding:14px 18px;margin:18px 0;font-size:13.5px;border-left:3px solid;line-height:1.65;}\n.callout p{font-size:13.5px;margin-bottom:6px;}\n.callout p:last-child{margin:0;}\n.cl-blue{background:var(--blue-bg);border-color:var(--blue);color:#1a2a4a;}\n.cl-green{background:var(--green-bg);border-color:var(--green);color:#0a2a1a;}\n.cl-amber{background:var(--amber-bg);border-color:var(--amber);color:#3a2a08;}\n.cl-red{background:var(--red-bg);border-color:var(--red);color:#3a0a08;}\n.cl-lbl{font-family:var(--mono);font-size:9px;letter-spacing:3px;text-transform:uppercase;margin-bottom:6px;opacity:.7;}\n.codeblock{background:var(--ink);border-radius:6px;padding:20px 22px;font-family:var(--mono);font-size:11.5px;line-height:2;overflow-x:auto;margin:14px 0;color:#c8c4b8;border:1px solid #1e1c18;}\n.codeblock .c{color:#3e3d36;}.codeblock .k{color:#e8b84b;}.codeblock .s{color:#8bc4a0;}.codeblock .n{color:#e8946a;}.codeblock .t{color:#7aaee0;}.codeblock .g{color:#a8d878;}.codeblock .r{color:#e87878;}\n.comp-table{width:100%;border-collapse:collapse;margin:20px 0;font-size:13px;}\n.comp-table th{padding:10px 14px;border:1px solid var(--border);background:var(--surface2);font-family:var(--mono);font-size:9px;letter-spacing:1.5px;text-transform:uppercase;color:var(--muted);}\n.comp-table td{padding:11px 14px;border:1px solid var(--border);vertical-align:top;color:#3a3830;line-height:1.6;}\n.comp-table .row-head{font-family:var(--mono);font-size:11px;font-weight:600;background:var(--surface);color:var(--ink);white-space:nowrap;}\n.good{color:var(--green);font-weight:600;}.warn{color:var(--amber);font-weight:600;}.bad{color:var(--red);font-weight:600;}\n.dot{display:inline-block;width:9px;height:9px;border-radius:50%;margin-right:4px;vertical-align:middle;}\n.dot.g{background:var(--green);}.dot.a{background:var(--amber);}.dot.r{background:var(--red);}\n.use-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:14px;margin:20px 0;}\n.use-card{border:1px solid var(--border);border-radius:6px;padding:18px;background:white;}\n.use-card-head{font-family:var(--mono);font-size:11px;font-weight:600;margin-bottom:10px;display:flex;align-items:center;gap:8px;}\n.use-card ul{padding-left:16px;font-size:13px;color:#4a4838;line-height:1.7;}\n.use-card ul li{margin-bottom:4px;}\n.shard-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:14px;margin:20px 0;}\n.shard-card{background:var(--ink);border-radius:8px;padding:20px;color:#c8c4b8;}\n.shard-title{font-family:var(--mono);font-size:10px;letter-spacing:2px;color:#6a6458;margin-bottom:10px;text-transform:uppercase;}\n.shard-name{font-family:var(--serif);font-size:16px;font-weight:700;color:#e8b84b;margin-bottom:8px;}\n.shard-body{font-size:12.5px;line-height:1.65;color:#a8a49c;}\n.shard-verdict{margin-top:10px;font-family:var(--mono);font-size:10px;padding:4px 10px;border-radius:3px;display:inline-block;}\n.sv-easy{background:rgba(26,122,74,.2);color:#5ac882;}.sv-med{background:rgba(184,114,10,.2);color:#e8943a;}.sv-hard{background:rgba(192,57,43,.2);color:#e87868;}\n.faq-item{border:1px solid var(--border);border-radius:4px;margin-bottom:8px;overflow:hidden;}\n.faq-q{padding:14px 18px;display:flex;justify-content:space-between;align-items:center;cursor:pointer;background:white;font-size:14px;font-weight:500;color:var(--ink);user-select:none;}\n.faq-q:hover{background:var(--surface);}\n.faq-q .tog{font-size:18px;color:#e8b84b;flex-shrink:0;margin-left:12px;transition:transform .2s;font-family:var(--mono);}\n.faq-a{display:none;padding:18px;background:var(--surface);font-size:13.5px;color:#3a3830;line-height:1.75;border-top:1px solid var(--border);}\n.faq-item.open .faq-a{display:block;}.faq-item.open .tog{transform:rotate(45deg);}\n.sd-example{background:white;border:1px solid var(--border);border-radius:8px;margin:20px 0;overflow:hidden;}\n.sd-example-head{background:var(--ink);padding:14px 20px;display:flex;align-items:center;gap:12px;}\n.sd-example-title{font-family:var(--serif);font-size:16px;color:#f0ece4;font-weight:700;}\n.sd-example-tag{font-family:var(--mono);font-size:9px;letter-spacing:2px;color:#6a6458;border:1px solid #2e2c28;padding:3px 8px;border-radius:2px;}\n.sd-example-body{padding:20px;}\n.choice-row{display:flex;gap:10px;align-items:flex-start;padding:10px 0;border-bottom:1px solid var(--border);font-size:13px;}\n.choice-row:last-child{border:none;}\n.choice-label{font-family:var(--mono);font-size:10px;letter-spacing:1px;color:var(--muted);width:120px;flex-shrink:0;padding-top:2px;}\n.choice-val{flex:1;color:#3a3830;line-height:1.6;}\n.badge{display:inline-block;font-family:var(--mono);font-size:9px;padding:2px 7px;border-radius:2px;border:1px solid;margin-right:4px;font-weight:500;}\n.b-pg{background:var(--pg-bg);border-color:var(--pg);color:var(--pg);}.b-mg{background:var(--mg-bg);border-color:var(--mg);color:var(--mg);}.b-dy{background:var(--dy-bg);border-color:var(--dy);color:#b06000;}.b-ca{background:var(--ca-bg);border-color:var(--ca);color:var(--ca);}.b-g{background:var(--green-bg);border-color:var(--green);color:var(--green);}.b-r{background:var(--red-bg);border-color:var(--red);color:var(--red);}.b-a{background:var(--amber-bg);border-color:var(--amber);color:var(--amber);}\n.footer{background:var(--ink);text-align:center;padding:36px 20px;font-family:var(--mono);font-size:10px;color:#3a3830;letter-spacing:2px;}\n\n.step-block{background:#fff;border:1px solid var(--border);border-radius:8px;margin:20px 0;overflow:hidden;}\n.step-block-header{background:var(--ink);color:#e8e4dc;padding:13px 18px;font-family:var(--mono);font-size:10px;letter-spacing:2px;text-transform:uppercase;display:flex;align-items:center;gap:10px;}\n.sb-icon{font-size:16px;}\n.step-block-body{padding:0;}\n.step-row{display:flex;gap:0;border-bottom:1px solid var(--border);}\n.step-row:last-child{border-bottom:none;}\n.step-num{background:var(--surface);min-width:46px;display:flex;align-items:flex-start;justify-content:center;padding:16px 6px;font-family:var(--mono);font-size:11px;font-weight:700;color:var(--muted);flex-shrink:0;border-right:1px solid var(--border);}\n.step-content{padding:14px 18px;flex:1;}\n.step-q{font-weight:600;font-size:14px;color:var(--ink);margin-bottom:10px;}\n.step-options{display:flex;flex-direction:column;gap:6px;}\n.step-option{display:flex;gap:10px;align-items:flex-start;padding:9px 13px;border-radius:5px;font-size:13px;line-height:1.65;}\n.opt-yes{background:#edf8f2;border:1px solid #b8ddc8;}\n.opt-no{background:#fdf6e8;border:1px solid #e8c870;}\n.opt-mid{background:#edf2fb;border:1px solid #b8c8e8;}\n.opt-any{background:#f4f0fb;border:1px solid #c8b8e8;}\n.opt-arrow{font-family:var(--mono);font-size:12px;font-weight:700;flex-shrink:0;margin-top:1px;min-width:120px;}\n.opt-yes .opt-arrow{color:#1a7a4a;}\n.opt-no .opt-arrow{color:#b8720a;}\n.opt-mid .opt-arrow{color:#1a4f8a;}\n.opt-any .opt-arrow{color:#5a3c9a;}\n.opt-text{flex:1;color:#3a3830;}\n.concept-grid{display:grid;grid-template-columns:1fr;gap:0;margin:20px 0;border:1px solid var(--border);border-radius:8px;overflow:hidden;}\n.concept-row{display:flex;gap:0;border-bottom:1px solid var(--border);}\n.concept-row:last-child{border-bottom:none;}\n.concept-term{background:var(--ink);color:#e8b84b;font-family:var(--mono);font-size:11.5px;font-weight:600;min-width:155px;padding:14px 16px;flex-shrink:0;border-right:1px solid #2a2820;display:flex;align-items:flex-start;line-height:1.5;}\n.concept-def{padding:13px 16px;flex:1;font-size:13.5px;color:#3a3830;line-height:1.7;background:#fff;}\n.concept-def strong{color:var(--ink);}\n.concept-def code{background:var(--surface);padding:1px 5px;border-radius:3px;font-family:var(--mono);font-size:11px;color:var(--blue);}\n@media(max-width:560px){.concept-row{flex-direction:column;}.concept-term{min-width:auto;border-right:none;border-bottom:1px solid #2a2820;}.opt-arrow{min-width:80px;}}\n\n</style></head><body>\n<div class=\"hero\"><div class=\"hero-inner\">\n  <div class=\"hero-tag\">System Design \u00b7 FAANG Interview Prep \u00b7 Manish-Almanac</div>\n  <h1>Object Storage<br><em>S3 & Blob Store</em></h1>\n  <p class=\"hero-sub\">S3 vs block vs file storage, multipart uploads, pre-signed URLs, storage classes, and CDN integration \u2014 everything for media and data lake system designs.</p>\n  <div class=\"db-pills\"><span class=\"db-pill\" style=\"border-color:#c0392b;color:#c0392b;background:#c0392b18\">S3 / GCS</span><span class=\"db-pill\" style=\"border-color:#1a4f8a;color:#1a4f8a;background:#1a4f8a18\">Multipart Upload</span><span class=\"db-pill\" style=\"border-color:#1a7a4a;color:#1a7a4a;background:#1a7a4a18\">Pre-Signed URLs</span><span class=\"db-pill\" style=\"border-color:#b8720a;color:#b8720a;background:#b8720a18\">Storage Classes</span><span class=\"db-pill\" style=\"border-color:#6040a0;color:#6040a0;background:#6040a018\">CDN Origin</span></div>\n</div></div>\n<nav class=\"nav\"><a href=\"#what\">Storage Types</a><a href=\"#internals\">S3 Internals</a><a href=\"#examples\">System Design</a><a href=\"#followups\">Follow-ups</a></nav>\n<div class=\"wrap\">\n<section id=\"what\">\n  <div class=\"sec-tag\">00 \u00b7 What Is Object Storage</div>\n  <h2>S3 vs Block Storage vs File Storage</h2>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\"><div class=\"concept-term\">Object Storage (S3)</div><div class=\"concept-def\"><strong>Stores data as flat objects \u2014 each object is a file with a key (path), value (bytes), and metadata.</strong> No directory hierarchy (though keys can have slashes to simulate it).<br>\n      Access: HTTP GET/PUT. Each object immutable after write. Unlimited scale. Cheap ($0.023/GB/month).<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Unlimited scale. Cheap. HTTP accessible from anywhere. Perfect for: images, videos, logs, backups, data lakes. Used by: Netflix (video), Instagram (photos), Dropbox (files).</span><br>\n      <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 High latency for small random reads (~50\u2013200ms). No in-place updates. No filesystem semantics (no rename, no locking).</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Block Storage (EBS)</div><div class=\"concept-def\"><strong>Raw storage volumes attached to a VM. The OS sees it as a disk \u2014 format with any filesystem.</strong><br>\n      Sub-millisecond latency. Random reads/writes. Required for databases (PostgreSQL, MySQL need a filesystem).<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Low latency. Random access. Required for any software that needs a real filesystem (databases, OS volumes).</span><br>\n      <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 Attached to one instance at a time. Fixed capacity (must resize manually). Expensive ($0.10/GB/month vs S3's $0.023).</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">File Storage (EFS/NFS)</div><div class=\"concept-def\"><strong>Shared filesystem mounted by multiple instances simultaneously. Files, directories, locking semantics.</strong><br>\n      Multiple EC2 instances can read/write the same files concurrently.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Shared access across instances. POSIX filesystem. No refactoring of existing code that uses files.</span><br>\n      <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 Higher latency than block storage. More expensive. Rarely needed in modern cloud-native designs (S3 has replaced most file storage use cases).</span></div></div>\n  </div>\n</section>\n\n<section id=\"internals\">\n  <div class=\"sec-tag\">01 \u00b7 S3 Internals</div>\n  <h2>How S3 actually works under the hood</h2>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\"><div class=\"concept-term\">Consistency Model</div><div class=\"concept-def\"><strong>S3 provides strong read-after-write consistency for all operations (since December 2020).</strong><br>\n      After a successful PUT, subsequent GET will return the new object. After DELETE, subsequent GET returns 404. No more \"eventually consistent\" surprises.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 You can safely read immediately after writing. No need for artificial delays or consistency workarounds.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Multipart Upload</div><div class=\"concept-def\"><strong>For files &gt;100MB: upload in parallel chunks, then assemble.</strong><br>\n      1. Initiate: <code>POST /object?uploads</code> \u2192 returns uploadId<br>\n      2. Upload parts: <code>PUT /object?partNumber=1&uploadId=X</code> (each part \u22655MB)<br>\n      3. Complete: <code>POST /object?uploadId=X</code> with list of part ETags<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Parallel uploads (5\u201310x faster for large files). Resume interrupted uploads. Each part is independently verified with MD5. Required for files &gt;5GB (single PUT limit).</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Pre-Signed URLs</div><div class=\"concept-def\"><strong>Temporarily grant a user direct access to an S3 object without exposing your credentials.</strong><br>\n      Server generates a signed URL valid for N seconds: <code>aws s3 presign s3://bucket/video.mp4 --expires-in 3600</code><br>\n      User uses URL directly to upload or download \u2014 bypasses your server entirely.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Client uploads directly to S3 \u2014 your server never sees the bytes. Offloads bandwidth and CPU. Standard pattern for all file upload systems (Instagram, Dropbox, Google Drive).</span><br>\n      <span style=\"color:#5a5848;font-size:12.5px;\">Flow: Client \u2192 GET /upload-url \u2192 Server \u2192 Pre-signed URL \u2192 Client PUT directly to S3 \u2192 Client notifies Server of completion.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Storage Classes</div><div class=\"concept-def\"><strong>Different cost/access speed tiers for different data lifecycle stages:</strong><br>\n      <code>Standard</code>: frequently accessed, ~$0.023/GB/month, &lt;100ms access<br>\n      <code>Standard-IA</code>: infrequent access, ~$0.0125/GB/month, retrieval fee per GB<br>\n      <code>Glacier Instant</code>: archive, ~$0.004/GB/month, millisecond retrieval<br>\n      <code>Glacier Deep Archive</code>: long-term archive, ~$0.00099/GB/month, 12-hour retrieval<br>\n      <span style=\"color:#5a5848;font-size:12.5px;\">Use Lifecycle Policies to automatically transition objects: new uploads \u2192 Standard \u2192 after 30 days \u2192 IA \u2192 after 1 year \u2192 Glacier. Common for log files and video archives.</span></div></div>\n  </div>\n</section>\n\n<section id=\"examples\">\n  <div class=\"sec-tag\">02 \u00b7 System Design Examples</div>\n  <h2>Object storage in real systems</h2>\n  <div class=\"sd-example\">\n    <div class=\"sd-example-head\"><div class=\"sd-example-title\">Instagram \u2014 Photo Upload Flow</div><span class=\"sd-example-tag\">MEDIA UPLOAD</span></div>\n    <div class=\"sd-example-body\">\n      <div class=\"choice-row\"><div class=\"choice-label\">UPLOAD</div><div class=\"choice-val\">Client requests pre-signed URL from API server. API server generates URL scoped to that user's bucket path, valid for 5 minutes. Client uploads directly to S3 \u2014 API server never receives image bytes. Reduces server bandwidth by 100%.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">PROCESSING</div><div class=\"choice-val\">S3 PUT triggers a Lambda (or SQS notification \u2192 EC2 worker). Worker: resize to 3 resolutions (thumbnail/feed/full), apply filters, extract EXIF metadata, write processed versions back to S3, update DB with S3 keys.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">DELIVERY</div><div class=\"choice-val\">All S3 objects served through CloudFront CDN. CDN caches at 200+ edge locations. User in Tokyo gets the image from Tokyo edge, not from S3 in us-east-1. ~10ms delivery globally vs ~200ms from origin.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">LIFECYCLE</div><div class=\"choice-val\">Stories expire after 24h: S3 Object expiry policy automatically deletes after 24h. Old posts after 1 year \u2192 transition to S3 Infrequent Access (saves ~45% storage cost). Deleted posts \u2192 immediate Object Delete + CDN invalidation.</div></div>\n    </div>\n  </div>\n</section>\n\n<section id=\"followups\">\n  <div class=\"sec-tag\">03 \u00b7 Follow-ups</div>\n  <h2>Every hard follow-up, answered</h2>\n  <div class=\"faq-item\"><div class=\"faq-q\" onclick=\"toggle(this)\">How do you handle large file uploads reliably over unreliable mobile connections?<span class=\"tog\">+</span></div>\n  <div class=\"faq-a\"><strong>Multipart upload with client-side resumable upload logic.</strong><br><br>\n  1. Client splits file into 5\u201310MB chunks before starting the upload.<br>\n  2. Client requests a multipart upload ID from your server. Server calls S3 to initiate and returns the uploadId.<br>\n  3. Client uploads chunks in parallel (3\u20135 simultaneous chunks for speed). Each chunk is independent \u2014 a failed chunk can be retried without restarting the whole upload.<br>\n  4. Client tracks which chunks succeeded locally (localStorage or a server-side record).<br>\n  5. If connection drops mid-upload, client resumes from the last successful chunk on reconnect.<br>\n  6. When all chunks are confirmed, client notifies your server, which calls S3's CompleteMultipartUpload.<br><br>\n  Tools: AWS SDK has built-in multipart upload with retry logic. tus.io is an open protocol for resumable uploads. Used by: Google Drive, Dropbox, YouTube for all video uploads.</div></div>\n  <div class=\"faq-item\"><div class=\"faq-q\" onclick=\"toggle(this)\">How do you design a Dropbox-like file sync system?<span class=\"tog\">+</span></div>\n  <div class=\"faq-a\"><strong>Core challenge: efficiently sync only changed parts of large files across devices.</strong><br><br>\n  <strong>Chunked storage</strong>: files are split into 4\u20138MB content-addressed chunks. Each chunk is identified by its SHA-256 hash. Only changed chunks need to be uploaded on modification.<br><br>\n  <strong>Delta sync</strong>: if you edit a 1GB file by changing one paragraph, only the 2\u20133 chunks containing that paragraph change. Only those chunks are uploaded. File metadata (which chunk IDs comprise the file) is updated. Other devices download only the new chunks.<br><br>\n  <strong>Deduplication</strong>: if two users upload identical files, the chunks are deduplicated \u2014 stored once, referenced by both. Dropbox saved ~2PB of storage via deduplication.<br><br>\n  <strong>Conflict handling</strong>: if two devices modify the same file while offline, both versions are kept \u2014 user sees \"conflicted copy\" and manually resolves. Alternatively: vector clocks to track causality and auto-merge text files (like Google Docs CRDT).</div></div>\n</section></div>\n<div class=\"footer\">OBJECT STORAGE \u00b7 S3 \u00b7 GCS \u00b7 MULTIPART UPLOAD \u00b7 PRE-SIGNED URLs \u00b7 CDN \u00b7 MANISH-ALMANAC</div>\n\u003cscript>function toggle(el){el.parentElement.classList.toggle('open');}<\/script>\n</body></html>", tag: 'Storage' },
  message_queues: { title: 'Message Queues: SQS & RabbitMQ', srcdoc: "<!DOCTYPE html>\n<html lang=\"en\"><head><meta charset=\"UTF-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Message Queues: SQS, RabbitMQ vs Kafka</title>\n<link href=\"https://fonts.googleapis.com/css2?family=Playfair+Display:wght@700;900&family=Source+Sans+3:wght@300;400;500;600&family=JetBrains+Mono:wght@400;600&display=swap\" rel=\"stylesheet\">\n<style>\n:root{--ink:#0f0e0c;--page:#f7f5f0;--surface:#eeecea;--surface2:#e5e2dc;--border:#d4d0c8;--muted:#7a7568;--pg:#336791;--pg-bg:#eef4fb;--mg:#13aa52;--mg-bg:#edfaf2;--dy:#ff9900;--dy-bg:#fff8ec;--ca:#1287b1;--ca-bg:#eaf6fb;--red:#c0392b;--red-bg:#fdf0ee;--green:#1a7a4a;--green-bg:#edf8f2;--amber:#b8720a;--amber-bg:#fdf6e8;--blue:#1a4f8a;--blue-bg:#edf2fb;--mono:'JetBrains Mono',monospace;--serif:'Playfair Display',serif;--sans:'Source Sans 3',sans-serif;}\n*{box-sizing:border-box;margin:0;padding:0;}html{scroll-behavior:smooth;}\nbody{background:var(--page);color:var(--ink);font-family:var(--sans);font-size:15px;line-height:1.75;}\n.hero{background:var(--ink);color:#e8e4dc;padding:72px 24px 56px;position:relative;overflow:hidden;}\n.hero::before{content:'';position:absolute;inset:0;background:repeating-linear-gradient(45deg,transparent,transparent 40px,rgba(255,255,255,.015) 40px,rgba(255,255,255,.015) 41px);}\n.hero-inner{max-width:960px;margin:0 auto;position:relative;}\n.hero-tag{font-family:var(--mono);font-size:10px;letter-spacing:4px;color:#6a6458;text-transform:uppercase;margin-bottom:20px;}\nh1{font-family:var(--serif);font-size:clamp(32px,5vw,58px);font-weight:900;line-height:1.05;letter-spacing:-.5px;margin-bottom:20px;color:#f0ece4;}\nh1 em{color:#e8b84b;font-style:normal;}\n.hero-sub{font-size:15px;color:#7a7060;max-width:640px;line-height:1.7;margin-bottom:32px;}\n.db-pills{display:flex;flex-wrap:wrap;gap:8px;}\n.db-pill{font-family:var(--mono);font-size:10px;padding:5px 14px;border-radius:3px;border:1px solid;letter-spacing:.5px;}\n.pill-pg{border-color:#336791;color:#336791;background:rgba(51,103,145,.08);}\n.pill-mg{border-color:#13aa52;color:#13aa52;background:rgba(19,170,82,.08);}\n.pill-dy{border-color:#ff9900;color:#cc7a00;background:rgba(255,153,0,.08);}\n.pill-ca{border-color:#1287b1;color:#1287b1;background:rgba(18,135,177,.08);}\n.nav{position:sticky;top:0;z-index:100;background:var(--ink);border-bottom:1px solid #1e1c18;display:flex;overflow-x:auto;scrollbar-width:none;padding:0 20px;}\n.nav::-webkit-scrollbar{display:none;}\n.nav a{font-family:var(--mono);font-size:10px;letter-spacing:1px;color:#4a4840;text-decoration:none;padding:14px 12px;white-space:nowrap;border-bottom:2px solid transparent;transition:.18s;}\n.nav a:hover{color:#e8b84b;border-color:#e8b84b;}\n.wrap{max-width:960px;margin:0 auto;padding:0 20px;}\nsection{padding:56px 0 36px;border-bottom:2px solid var(--border);}\nsection:last-child{border:none;}\n.sec-tag{font-family:var(--mono);font-size:9px;letter-spacing:4px;text-transform:uppercase;color:var(--muted);margin-bottom:8px;display:flex;align-items:center;gap:10px;}\n.sec-tag::before{content:'';width:20px;height:1px;background:var(--border);}\nh2{font-family:var(--serif);font-size:clamp(22px,3.5vw,32px);font-weight:700;line-height:1.15;margin-bottom:18px;}\nh3{font-family:var(--sans);font-size:17px;font-weight:600;margin:32px 0 10px;border-bottom:1px solid var(--border);padding-bottom:6px;}\nh4{font-size:13px;font-weight:600;margin:16px 0 6px;text-transform:uppercase;letter-spacing:.5px;}\np{color:#3a3830;font-size:14.5px;margin-bottom:12px;}\nstrong{color:var(--ink);}\ncode{font-family:var(--mono);font-size:11.5px;background:var(--surface2);padding:1px 5px;border-radius:3px;color:var(--blue);}\n.db-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:14px;margin:24px 0;}\n.db-card{background:white;border:1px solid var(--border);border-radius:8px;padding:20px;position:relative;overflow:hidden;}\n.db-card::before{content:'';position:absolute;top:0;left:0;right:0;height:4px;}\n.db-card.pg::before{background:var(--pg);}\n.db-card.mg::before{background:var(--mg);}\n.db-card.dy::before{background:var(--dy);}\n.db-card.ca::before{background:var(--ca);}\n.db-logo{font-size:22px;margin-bottom:6px;}\n.db-name{font-family:var(--serif);font-size:17px;font-weight:700;margin-bottom:4px;}\n.db-type{font-family:var(--mono);font-size:9px;letter-spacing:2px;color:var(--muted);margin-bottom:10px;text-transform:uppercase;}\n.db-tagline{font-size:13px;color:#5a5848;line-height:1.55;}\n.db-born{font-family:var(--mono);font-size:9px;color:var(--muted);margin-top:8px;}\n.analogy{background:var(--ink);color:#c8c4b8;border-radius:8px;padding:24px 28px;margin:24px 0;}\n.analogy-label{font-family:var(--mono);font-size:9px;letter-spacing:3px;color:#6a6458;margin-bottom:10px;text-transform:uppercase;}\n.analogy-text{font-size:15px;line-height:1.75;color:#d8d4c8;}\n.analogy-text strong{color:#e8b84b;}\n.callout{border-radius:4px;padding:14px 18px;margin:18px 0;font-size:13.5px;border-left:3px solid;line-height:1.65;}\n.callout p{font-size:13.5px;margin-bottom:6px;}\n.callout p:last-child{margin:0;}\n.cl-blue{background:var(--blue-bg);border-color:var(--blue);color:#1a2a4a;}\n.cl-green{background:var(--green-bg);border-color:var(--green);color:#0a2a1a;}\n.cl-amber{background:var(--amber-bg);border-color:var(--amber);color:#3a2a08;}\n.cl-red{background:var(--red-bg);border-color:var(--red);color:#3a0a08;}\n.cl-lbl{font-family:var(--mono);font-size:9px;letter-spacing:3px;text-transform:uppercase;margin-bottom:6px;opacity:.7;}\n.codeblock{background:var(--ink);border-radius:6px;padding:20px 22px;font-family:var(--mono);font-size:11.5px;line-height:2;overflow-x:auto;margin:14px 0;color:#c8c4b8;border:1px solid #1e1c18;}\n.codeblock .c{color:#3e3d36;}.codeblock .k{color:#e8b84b;}.codeblock .s{color:#8bc4a0;}.codeblock .n{color:#e8946a;}.codeblock .t{color:#7aaee0;}.codeblock .g{color:#a8d878;}.codeblock .r{color:#e87878;}\n.comp-table{width:100%;border-collapse:collapse;margin:20px 0;font-size:13px;}\n.comp-table th{padding:10px 14px;border:1px solid var(--border);background:var(--surface2);font-family:var(--mono);font-size:9px;letter-spacing:1.5px;text-transform:uppercase;color:var(--muted);}\n.comp-table td{padding:11px 14px;border:1px solid var(--border);vertical-align:top;color:#3a3830;line-height:1.6;}\n.comp-table .row-head{font-family:var(--mono);font-size:11px;font-weight:600;background:var(--surface);color:var(--ink);white-space:nowrap;}\n.good{color:var(--green);font-weight:600;}.warn{color:var(--amber);font-weight:600;}.bad{color:var(--red);font-weight:600;}\n.dot{display:inline-block;width:9px;height:9px;border-radius:50%;margin-right:4px;vertical-align:middle;}\n.dot.g{background:var(--green);}.dot.a{background:var(--amber);}.dot.r{background:var(--red);}\n.use-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:14px;margin:20px 0;}\n.use-card{border:1px solid var(--border);border-radius:6px;padding:18px;background:white;}\n.use-card-head{font-family:var(--mono);font-size:11px;font-weight:600;margin-bottom:10px;display:flex;align-items:center;gap:8px;}\n.use-card ul{padding-left:16px;font-size:13px;color:#4a4838;line-height:1.7;}\n.use-card ul li{margin-bottom:4px;}\n.shard-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:14px;margin:20px 0;}\n.shard-card{background:var(--ink);border-radius:8px;padding:20px;color:#c8c4b8;}\n.shard-title{font-family:var(--mono);font-size:10px;letter-spacing:2px;color:#6a6458;margin-bottom:10px;text-transform:uppercase;}\n.shard-name{font-family:var(--serif);font-size:16px;font-weight:700;color:#e8b84b;margin-bottom:8px;}\n.shard-body{font-size:12.5px;line-height:1.65;color:#a8a49c;}\n.shard-verdict{margin-top:10px;font-family:var(--mono);font-size:10px;padding:4px 10px;border-radius:3px;display:inline-block;}\n.sv-easy{background:rgba(26,122,74,.2);color:#5ac882;}.sv-med{background:rgba(184,114,10,.2);color:#e8943a;}.sv-hard{background:rgba(192,57,43,.2);color:#e87868;}\n.faq-item{border:1px solid var(--border);border-radius:4px;margin-bottom:8px;overflow:hidden;}\n.faq-q{padding:14px 18px;display:flex;justify-content:space-between;align-items:center;cursor:pointer;background:white;font-size:14px;font-weight:500;color:var(--ink);user-select:none;}\n.faq-q:hover{background:var(--surface);}\n.faq-q .tog{font-size:18px;color:#e8b84b;flex-shrink:0;margin-left:12px;transition:transform .2s;font-family:var(--mono);}\n.faq-a{display:none;padding:18px;background:var(--surface);font-size:13.5px;color:#3a3830;line-height:1.75;border-top:1px solid var(--border);}\n.faq-item.open .faq-a{display:block;}.faq-item.open .tog{transform:rotate(45deg);}\n.sd-example{background:white;border:1px solid var(--border);border-radius:8px;margin:20px 0;overflow:hidden;}\n.sd-example-head{background:var(--ink);padding:14px 20px;display:flex;align-items:center;gap:12px;}\n.sd-example-title{font-family:var(--serif);font-size:16px;color:#f0ece4;font-weight:700;}\n.sd-example-tag{font-family:var(--mono);font-size:9px;letter-spacing:2px;color:#6a6458;border:1px solid #2e2c28;padding:3px 8px;border-radius:2px;}\n.sd-example-body{padding:20px;}\n.choice-row{display:flex;gap:10px;align-items:flex-start;padding:10px 0;border-bottom:1px solid var(--border);font-size:13px;}\n.choice-row:last-child{border:none;}\n.choice-label{font-family:var(--mono);font-size:10px;letter-spacing:1px;color:var(--muted);width:120px;flex-shrink:0;padding-top:2px;}\n.choice-val{flex:1;color:#3a3830;line-height:1.6;}\n.badge{display:inline-block;font-family:var(--mono);font-size:9px;padding:2px 7px;border-radius:2px;border:1px solid;margin-right:4px;font-weight:500;}\n.b-pg{background:var(--pg-bg);border-color:var(--pg);color:var(--pg);}.b-mg{background:var(--mg-bg);border-color:var(--mg);color:var(--mg);}.b-dy{background:var(--dy-bg);border-color:var(--dy);color:#b06000;}.b-ca{background:var(--ca-bg);border-color:var(--ca);color:var(--ca);}.b-g{background:var(--green-bg);border-color:var(--green);color:var(--green);}.b-r{background:var(--red-bg);border-color:var(--red);color:var(--red);}.b-a{background:var(--amber-bg);border-color:var(--amber);color:var(--amber);}\n.footer{background:var(--ink);text-align:center;padding:36px 20px;font-family:var(--mono);font-size:10px;color:#3a3830;letter-spacing:2px;}\n\n.step-block{background:#fff;border:1px solid var(--border);border-radius:8px;margin:20px 0;overflow:hidden;}\n.step-block-header{background:var(--ink);color:#e8e4dc;padding:13px 18px;font-family:var(--mono);font-size:10px;letter-spacing:2px;text-transform:uppercase;display:flex;align-items:center;gap:10px;}\n.sb-icon{font-size:16px;}\n.step-block-body{padding:0;}\n.step-row{display:flex;gap:0;border-bottom:1px solid var(--border);}\n.step-row:last-child{border-bottom:none;}\n.step-num{background:var(--surface);min-width:46px;display:flex;align-items:flex-start;justify-content:center;padding:16px 6px;font-family:var(--mono);font-size:11px;font-weight:700;color:var(--muted);flex-shrink:0;border-right:1px solid var(--border);}\n.step-content{padding:14px 18px;flex:1;}\n.step-q{font-weight:600;font-size:14px;color:var(--ink);margin-bottom:10px;}\n.step-options{display:flex;flex-direction:column;gap:6px;}\n.step-option{display:flex;gap:10px;align-items:flex-start;padding:9px 13px;border-radius:5px;font-size:13px;line-height:1.65;}\n.opt-yes{background:#edf8f2;border:1px solid #b8ddc8;}\n.opt-no{background:#fdf6e8;border:1px solid #e8c870;}\n.opt-mid{background:#edf2fb;border:1px solid #b8c8e8;}\n.opt-any{background:#f4f0fb;border:1px solid #c8b8e8;}\n.opt-arrow{font-family:var(--mono);font-size:12px;font-weight:700;flex-shrink:0;margin-top:1px;min-width:120px;}\n.opt-yes .opt-arrow{color:#1a7a4a;}\n.opt-no .opt-arrow{color:#b8720a;}\n.opt-mid .opt-arrow{color:#1a4f8a;}\n.opt-any .opt-arrow{color:#5a3c9a;}\n.opt-text{flex:1;color:#3a3830;}\n.concept-grid{display:grid;grid-template-columns:1fr;gap:0;margin:20px 0;border:1px solid var(--border);border-radius:8px;overflow:hidden;}\n.concept-row{display:flex;gap:0;border-bottom:1px solid var(--border);}\n.concept-row:last-child{border-bottom:none;}\n.concept-term{background:var(--ink);color:#e8b84b;font-family:var(--mono);font-size:11.5px;font-weight:600;min-width:155px;padding:14px 16px;flex-shrink:0;border-right:1px solid #2a2820;display:flex;align-items:flex-start;line-height:1.5;}\n.concept-def{padding:13px 16px;flex:1;font-size:13.5px;color:#3a3830;line-height:1.7;background:#fff;}\n.concept-def strong{color:var(--ink);}\n.concept-def code{background:var(--surface);padding:1px 5px;border-radius:3px;font-family:var(--mono);font-size:11px;color:var(--blue);}\n@media(max-width:560px){.concept-row{flex-direction:column;}.concept-term{min-width:auto;border-right:none;border-bottom:1px solid #2a2820;}.opt-arrow{min-width:80px;}}\n\n</style></head><body>\n<div class=\"hero\"><div class=\"hero-inner\">\n  <div class=\"hero-tag\">System Design \u00b7 FAANG Interview Prep \u00b7 Manish-Almanac</div>\n  <h1>Message Queues<br><em>SQS, RabbitMQ vs Kafka</em></h1>\n  <p class=\"hero-sub\">Queue vs stream, dead letter queues, fan-out, backpressure, exactly-once patterns \u2014 when to use each and how to make the right choice in system design interviews.</p>\n  <div class=\"db-pills\"><span class=\"db-pill\" style=\"border-color:#c0392b;color:#c0392b;background:#c0392b18\">SQS</span><span class=\"db-pill\" style=\"border-color:#1a7a4a;color:#1a7a4a;background:#1a7a4a18\">RabbitMQ</span><span class=\"db-pill\" style=\"border-color:#1a4f8a;color:#1a4f8a;background:#1a4f8a18\">Fan-Out</span><span class=\"db-pill\" style=\"border-color:#b8720a;color:#b8720a;background:#b8720a18\">DLQ</span><span class=\"db-pill\" style=\"border-color:#6040a0;color:#6040a0;background:#6040a018\">At-Least-Once</span></div>\n</div></div>\n<nav class=\"nav\"><a href=\"#queues-vs-streams\">Queue vs Stream</a><a href=\"#patterns\">Patterns</a><a href=\"#sqs\">SQS vs RabbitMQ</a><a href=\"#examples\">System Design</a><a href=\"#followups\">Follow-ups</a></nav>\n<div class=\"wrap\">\n<section id=\"queues-vs-streams\">\n  <div class=\"sec-tag\">00 \u00b7 The Critical Distinction</div>\n  <h2>Message Queue vs Event Stream \u2014 they are not the same</h2>\n  <div class=\"analogy\">\n    <div class=\"analogy-label\">Queue vs Stream \u2014 the post office analogy</div>\n    <div class=\"analogy-text\">\n      <strong>Message Queue (SQS/RabbitMQ)</strong> = a post office. A letter is delivered to one recipient and then destroyed. If you want two people to read it, send two letters. The post office's job is to deliver and confirm delivery.<br><br>\n      <strong>Event Stream (Kafka)</strong> = a newspaper printing plant. Every paper is kept on record for 7 days. Any subscriber can read any edition at any time. Multiple readers get the same paper independently.\n    </div>\n  </div>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\"><div class=\"concept-term\">Message Queue</div><div class=\"concept-def\"><strong>One consumer reads a message. Once consumed and acknowledged, it is deleted.</strong><br>\n      Point-to-point: one message \u2192 one consumer. Or fan-out: publish to topic \u2192 one copy per subscriber queue.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Ideal for task distribution: \"process this image resize job\" \u2014 you want exactly one worker to do it, not all of them. Built-in dead letter queues, retry logic, visibility timeout.</span><br>\n      <span style=\"color:#5a5848;font-size:12.5px;\">Examples: SQS, RabbitMQ, ActiveMQ. Use for: email sending, image processing, order fulfillment tasks.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Event Stream</div><div class=\"concept-def\"><strong>Messages are retained. Multiple independent consumers can read all messages, each at their own pace.</strong><br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Replay: Flink crashed? Replay from last offset. Multiple consumers: Flink, ClickHouse, and S3 all read the same stream independently.</span><br>\n      <span style=\"color:#5a5848;font-size:12.5px;\">Examples: Kafka, Kinesis, Pulsar. Use for: event sourcing, streaming analytics, audit logs, feeding multiple downstream systems.</span></div></div>\n  </div>\n</section>\n\n<section id=\"patterns\">\n  <div class=\"sec-tag\">01 \u00b7 Queue Patterns</div>\n  <h2>Dead letter queues, fan-out, priority, and backpressure</h2>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\"><div class=\"concept-term\">Dead Letter Queue (DLQ)</div><div class=\"concept-def\"><strong>When a message fails processing N times, it moves to a DLQ instead of being silently dropped.</strong><br>\n      Flow: message enters queue \u2192 worker fails to process \u2192 message becomes visible again after visibility timeout \u2192 after 3 retries \u2192 moved to DLQ.<br>\n      DLQ stores failed messages for investigation and reprocessing.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 No silent data loss. Failed messages are preserved and inspectable. Essential for production systems \u2014 without DLQ, a bad message can block a queue forever (poison pill).</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Visibility Timeout</div><div class=\"concept-def\"><strong>When a worker picks up a message, it becomes invisible to other workers for N seconds (the visibility timeout).</strong><br>\n      If the worker completes processing: explicitly deletes the message.<br>\n      If the worker crashes: timeout expires, message becomes visible again for another worker to pick up.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Automatic retry on worker failure. At-least-once delivery guarantee. Set timeout to 2x your expected processing time.</span><br>\n      <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 At-least-once means duplicates are possible (worker completes but crashes before deleting). Make your consumers idempotent.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Fan-Out Pattern</div><div class=\"concept-def\"><strong>One message triggers multiple independent processing pipelines.</strong><br>\n      SNS (pub/sub topic) + multiple SQS queues: publish to SNS \u2192 SNS delivers a copy to each subscribed SQS queue \u2192 each queue has its own consumer processing independently.<br>\n      Example: new order event \u2192 (1) fulfillment queue, (2) analytics queue, (3) notification queue \u2014 all independent.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Decoupled services. New consumers added without touching the publisher. Each consumer has its own DLQ.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Backpressure</div><div class=\"concept-def\"><strong>When consumers cannot keep up with producers, the queue grows. Backpressure signals the producer to slow down.</strong><br>\n      Strategies:<br>\n      \u2022 <strong>Queue depth alarm</strong>: CloudWatch alarm when SQS depth &gt; 10K \u2192 auto-scale consumers.<br>\n      \u2022 <strong>Producer rate limiting</strong>: producer checks queue depth before sending; slows if deep.<br>\n      \u2022 <strong>Blocking send</strong>: Kafka producer blocks when buffer is full (internal backpressure).<br>\n      <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 Without backpressure: queue grows unbounded \u2192 OOM or unbounded delay \u2192 cascading failure. Always monitor queue depth.</span></div></div>\n  </div>\n</section>\n\n<section id=\"sqs\">\n  <div class=\"sec-tag\">02 \u00b7 SQS vs RabbitMQ</div>\n  <h2>When to use each</h2>\n  <table class=\"comp-table\">\n    <thead><tr><th>Dimension</th><th>AWS SQS</th><th>RabbitMQ</th></tr></thead>\n    <tbody>\n      <tr><td class=\"row-head\">Type</td><td>Fully managed, serverless</td><td>Self-managed broker</td></tr>\n      <tr><td class=\"row-head\">Ordering</td><td>Standard: best-effort. FIFO: guaranteed</td><td>Per-queue FIFO guaranteed</td></tr>\n      <tr><td class=\"row-head\">Throughput</td><td><span class=\"good\">Unlimited (auto-scales)</span></td><td><span class=\"warn\">~50K msg/sec per broker, cluster for more</span></td></tr>\n      <tr><td class=\"row-head\">Routing</td><td>Basic (queue per destination)</td><td><span class=\"good\">Rich exchanges: direct, fanout, topic, headers</span></td></tr>\n      <tr><td class=\"row-head\">Ops burden</td><td><span class=\"good\">Zero</span></td><td><span class=\"warn\">Medium \u2014 manage cluster, quorum, memory</span></td></tr>\n      <tr><td class=\"row-head\">Message retention</td><td>Up to 14 days (deleted on consume)</td><td>Configurable (deleted on consume)</td></tr>\n      <tr><td class=\"row-head\">Protocols</td><td>HTTP/SQS API only</td><td>AMQP, MQTT, STOMP, HTTP</td></tr>\n      <tr><td class=\"row-head\">Use when</td><td>AWS-native, variable load, zero ops</td><td>Complex routing, multi-protocol, existing AMQP</td></tr>\n    </tbody>\n  </table>\n</section>\n\n<section id=\"examples\">\n  <div class=\"sec-tag\">03 \u00b7 System Design Examples</div>\n  <h2>Message queues in real systems</h2>\n  <div class=\"sd-example\">\n    <div class=\"sd-example-head\"><div class=\"sd-example-title\">E-Commerce Order Processing</div><span class=\"sd-example-tag\">ASYNC \u00b7 FAULT-TOLERANT</span></div>\n    <div class=\"sd-example-body\">\n      <div class=\"choice-row\"><div class=\"choice-label\">ORDER PLACED</div><div class=\"choice-val\">User places order \u2192 API writes order to DB \u2192 publishes OrderPlaced event to SNS \u2192 SNS fans out to: (1) Fulfillment SQS Queue, (2) Notification SQS Queue, (3) Analytics SQS Queue. User gets immediate HTTP 200 \u2014 async processing happens independently.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">FULFILLMENT</div><div class=\"choice-val\">Worker picks OrderPlaced from Fulfillment Queue \u2192 reserves inventory \u2192 creates shipment \u2192 publishes OrderFulfilled. Visibility timeout = 5 minutes (enough for fulfillment). DLQ captures failed orders after 3 retries \u2014 ops team investigates.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">VS KAFKA</div><div class=\"choice-val\">Why not Kafka here? Each order should be processed exactly once by fulfillment (point-to-point), not broadcast. SQS's delete-on-consume guarantees one fulfillment per order. Kafka would require consumer group management to achieve the same \u2014 more complex for this use case.</div></div>\n    </div>\n  </div>\n</section>\n\n<section id=\"followups\">\n  <div class=\"sec-tag\">04 \u00b7 Follow-ups</div>\n  <h2>Every hard follow-up, answered</h2>\n  <div class=\"faq-item\"><div class=\"faq-q\" onclick=\"toggle(this)\">How do you guarantee exactly-once processing with SQS (which is at-least-once)?<span class=\"tog\">+</span></div>\n  <div class=\"faq-a\"><strong>SQS Standard queues guarantee at-least-once delivery \u2014 duplicates are possible. Make your consumers idempotent.</strong><br><br>\n  <strong>Option 1 \u2014 SQS FIFO queues</strong>: exactly-once within a 5-minute deduplication window. Include a MessageDeduplicationId \u2014 if the same ID is submitted twice, SQS discards the duplicate. Cost: 3x price of Standard queues, lower throughput (3K msg/sec vs unlimited).<br><br>\n  <strong>Option 2 \u2014 Idempotent consumers</strong>: check if this messageId has been processed before. Store processed message IDs in Redis (SET with TTL=24h) or a DB dedup table. Before processing: <code>SET processed:{messageId} 1 NX EX 86400</code> \u2014 if NX succeeds (key did not exist), process. Otherwise, skip as duplicate. Delete SQS message either way.<br><br>\n  <strong>Option 3 \u2014 Idempotent operations</strong>: design your processing so that doing it twice has the same result as once. Example: <code>UPDATE orders SET status='fulfilled' WHERE id=X AND status='pending'</code> \u2014 running this twice only updates once (second run finds status is already 'fulfilled').</div></div>\n  <div class=\"faq-item\"><div class=\"faq-q\" onclick=\"toggle(this)\">When should you use a message queue vs calling the downstream service directly?<span class=\"tog\">+</span></div>\n  <div class=\"faq-a\"><strong>Use a queue when temporal decoupling adds value. Use direct calls when it does not.</strong><br><br>\n  <strong>Use a message queue when:</strong><br>\n  \u2014 The downstream service might be slow, unavailable, or experiencing load spikes that you want to absorb<br>\n  \u2014 Processing can be deferred (email sends, video transcoding, report generation)<br>\n  \u2014 You need to fan out to multiple downstream systems<br>\n  \u2014 You need automatic retry on failure without complex retry logic in your code<br>\n  \u2014 Processing throughput is bursty (queue smooths it out)<br><br>\n  <strong>Use direct calls (synchronous) when:</strong><br>\n  \u2014 The caller needs the result to continue (payment confirmation, authentication check)<br>\n  \u2014 Latency SLA is tight (&lt;100ms \u2014 queue adds overhead)<br>\n  \u2014 The operation is simple and the downstream service is reliable<br>\n  \u2014 You need to return errors to the user immediately<br><br>\n  <strong>Rule of thumb</strong>: can the user proceed without waiting for this operation? If yes \u2192 queue. If no \u2192 synchronous call.</div></div>\n</section></div>\n<div class=\"footer\">MESSAGE QUEUES \u00b7 SQS \u00b7 RABBITMQ \u00b7 DLQ \u00b7 FAN-OUT \u00b7 AT-LEAST-ONCE \u00b7 MANISH-ALMANAC</div>\n\u003cscript>function toggle(el){el.parentElement.classList.toggle('open');}<\/script>\n</body></html>", tag: 'Queues' },
  cdn_edge: { title: 'CDN & Edge Computing', srcdoc: "<!DOCTYPE html>\n<html lang=\"en\"><head><meta charset=\"UTF-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>CDN & Edge: Cloudflare, CloudFront, Fastly</title>\n<link href=\"https://fonts.googleapis.com/css2?family=Playfair+Display:wght@700;900&family=Source+Sans+3:wght@300;400;500;600&family=JetBrains+Mono:wght@400;600&display=swap\" rel=\"stylesheet\">\n<style>\n:root{--ink:#0f0e0c;--page:#f7f5f0;--surface:#eeecea;--surface2:#e5e2dc;--border:#d4d0c8;--muted:#7a7568;--pg:#336791;--pg-bg:#eef4fb;--mg:#13aa52;--mg-bg:#edfaf2;--dy:#ff9900;--dy-bg:#fff8ec;--ca:#1287b1;--ca-bg:#eaf6fb;--red:#c0392b;--red-bg:#fdf0ee;--green:#1a7a4a;--green-bg:#edf8f2;--amber:#b8720a;--amber-bg:#fdf6e8;--blue:#1a4f8a;--blue-bg:#edf2fb;--mono:'JetBrains Mono',monospace;--serif:'Playfair Display',serif;--sans:'Source Sans 3',sans-serif;}\n*{box-sizing:border-box;margin:0;padding:0;}html{scroll-behavior:smooth;}\nbody{background:var(--page);color:var(--ink);font-family:var(--sans);font-size:15px;line-height:1.75;}\n.hero{background:var(--ink);color:#e8e4dc;padding:72px 24px 56px;position:relative;overflow:hidden;}\n.hero::before{content:'';position:absolute;inset:0;background:repeating-linear-gradient(45deg,transparent,transparent 40px,rgba(255,255,255,.015) 40px,rgba(255,255,255,.015) 41px);}\n.hero-inner{max-width:960px;margin:0 auto;position:relative;}\n.hero-tag{font-family:var(--mono);font-size:10px;letter-spacing:4px;color:#6a6458;text-transform:uppercase;margin-bottom:20px;}\nh1{font-family:var(--serif);font-size:clamp(32px,5vw,58px);font-weight:900;line-height:1.05;letter-spacing:-.5px;margin-bottom:20px;color:#f0ece4;}\nh1 em{color:#e8b84b;font-style:normal;}\n.hero-sub{font-size:15px;color:#7a7060;max-width:640px;line-height:1.7;margin-bottom:32px;}\n.db-pills{display:flex;flex-wrap:wrap;gap:8px;}\n.db-pill{font-family:var(--mono);font-size:10px;padding:5px 14px;border-radius:3px;border:1px solid;letter-spacing:.5px;}\n.pill-pg{border-color:#336791;color:#336791;background:rgba(51,103,145,.08);}\n.pill-mg{border-color:#13aa52;color:#13aa52;background:rgba(19,170,82,.08);}\n.pill-dy{border-color:#ff9900;color:#cc7a00;background:rgba(255,153,0,.08);}\n.pill-ca{border-color:#1287b1;color:#1287b1;background:rgba(18,135,177,.08);}\n.nav{position:sticky;top:0;z-index:100;background:var(--ink);border-bottom:1px solid #1e1c18;display:flex;overflow-x:auto;scrollbar-width:none;padding:0 20px;}\n.nav::-webkit-scrollbar{display:none;}\n.nav a{font-family:var(--mono);font-size:10px;letter-spacing:1px;color:#4a4840;text-decoration:none;padding:14px 12px;white-space:nowrap;border-bottom:2px solid transparent;transition:.18s;}\n.nav a:hover{color:#e8b84b;border-color:#e8b84b;}\n.wrap{max-width:960px;margin:0 auto;padding:0 20px;}\nsection{padding:56px 0 36px;border-bottom:2px solid var(--border);}\nsection:last-child{border:none;}\n.sec-tag{font-family:var(--mono);font-size:9px;letter-spacing:4px;text-transform:uppercase;color:var(--muted);margin-bottom:8px;display:flex;align-items:center;gap:10px;}\n.sec-tag::before{content:'';width:20px;height:1px;background:var(--border);}\nh2{font-family:var(--serif);font-size:clamp(22px,3.5vw,32px);font-weight:700;line-height:1.15;margin-bottom:18px;}\nh3{font-family:var(--sans);font-size:17px;font-weight:600;margin:32px 0 10px;border-bottom:1px solid var(--border);padding-bottom:6px;}\nh4{font-size:13px;font-weight:600;margin:16px 0 6px;text-transform:uppercase;letter-spacing:.5px;}\np{color:#3a3830;font-size:14.5px;margin-bottom:12px;}\nstrong{color:var(--ink);}\ncode{font-family:var(--mono);font-size:11.5px;background:var(--surface2);padding:1px 5px;border-radius:3px;color:var(--blue);}\n.db-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:14px;margin:24px 0;}\n.db-card{background:white;border:1px solid var(--border);border-radius:8px;padding:20px;position:relative;overflow:hidden;}\n.db-card::before{content:'';position:absolute;top:0;left:0;right:0;height:4px;}\n.db-card.pg::before{background:var(--pg);}\n.db-card.mg::before{background:var(--mg);}\n.db-card.dy::before{background:var(--dy);}\n.db-card.ca::before{background:var(--ca);}\n.db-logo{font-size:22px;margin-bottom:6px;}\n.db-name{font-family:var(--serif);font-size:17px;font-weight:700;margin-bottom:4px;}\n.db-type{font-family:var(--mono);font-size:9px;letter-spacing:2px;color:var(--muted);margin-bottom:10px;text-transform:uppercase;}\n.db-tagline{font-size:13px;color:#5a5848;line-height:1.55;}\n.db-born{font-family:var(--mono);font-size:9px;color:var(--muted);margin-top:8px;}\n.analogy{background:var(--ink);color:#c8c4b8;border-radius:8px;padding:24px 28px;margin:24px 0;}\n.analogy-label{font-family:var(--mono);font-size:9px;letter-spacing:3px;color:#6a6458;margin-bottom:10px;text-transform:uppercase;}\n.analogy-text{font-size:15px;line-height:1.75;color:#d8d4c8;}\n.analogy-text strong{color:#e8b84b;}\n.callout{border-radius:4px;padding:14px 18px;margin:18px 0;font-size:13.5px;border-left:3px solid;line-height:1.65;}\n.callout p{font-size:13.5px;margin-bottom:6px;}\n.callout p:last-child{margin:0;}\n.cl-blue{background:var(--blue-bg);border-color:var(--blue);color:#1a2a4a;}\n.cl-green{background:var(--green-bg);border-color:var(--green);color:#0a2a1a;}\n.cl-amber{background:var(--amber-bg);border-color:var(--amber);color:#3a2a08;}\n.cl-red{background:var(--red-bg);border-color:var(--red);color:#3a0a08;}\n.cl-lbl{font-family:var(--mono);font-size:9px;letter-spacing:3px;text-transform:uppercase;margin-bottom:6px;opacity:.7;}\n.codeblock{background:var(--ink);border-radius:6px;padding:20px 22px;font-family:var(--mono);font-size:11.5px;line-height:2;overflow-x:auto;margin:14px 0;color:#c8c4b8;border:1px solid #1e1c18;}\n.codeblock .c{color:#3e3d36;}.codeblock .k{color:#e8b84b;}.codeblock .s{color:#8bc4a0;}.codeblock .n{color:#e8946a;}.codeblock .t{color:#7aaee0;}.codeblock .g{color:#a8d878;}.codeblock .r{color:#e87878;}\n.comp-table{width:100%;border-collapse:collapse;margin:20px 0;font-size:13px;}\n.comp-table th{padding:10px 14px;border:1px solid var(--border);background:var(--surface2);font-family:var(--mono);font-size:9px;letter-spacing:1.5px;text-transform:uppercase;color:var(--muted);}\n.comp-table td{padding:11px 14px;border:1px solid var(--border);vertical-align:top;color:#3a3830;line-height:1.6;}\n.comp-table .row-head{font-family:var(--mono);font-size:11px;font-weight:600;background:var(--surface);color:var(--ink);white-space:nowrap;}\n.good{color:var(--green);font-weight:600;}.warn{color:var(--amber);font-weight:600;}.bad{color:var(--red);font-weight:600;}\n.dot{display:inline-block;width:9px;height:9px;border-radius:50%;margin-right:4px;vertical-align:middle;}\n.dot.g{background:var(--green);}.dot.a{background:var(--amber);}.dot.r{background:var(--red);}\n.use-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:14px;margin:20px 0;}\n.use-card{border:1px solid var(--border);border-radius:6px;padding:18px;background:white;}\n.use-card-head{font-family:var(--mono);font-size:11px;font-weight:600;margin-bottom:10px;display:flex;align-items:center;gap:8px;}\n.use-card ul{padding-left:16px;font-size:13px;color:#4a4838;line-height:1.7;}\n.use-card ul li{margin-bottom:4px;}\n.shard-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:14px;margin:20px 0;}\n.shard-card{background:var(--ink);border-radius:8px;padding:20px;color:#c8c4b8;}\n.shard-title{font-family:var(--mono);font-size:10px;letter-spacing:2px;color:#6a6458;margin-bottom:10px;text-transform:uppercase;}\n.shard-name{font-family:var(--serif);font-size:16px;font-weight:700;color:#e8b84b;margin-bottom:8px;}\n.shard-body{font-size:12.5px;line-height:1.65;color:#a8a49c;}\n.shard-verdict{margin-top:10px;font-family:var(--mono);font-size:10px;padding:4px 10px;border-radius:3px;display:inline-block;}\n.sv-easy{background:rgba(26,122,74,.2);color:#5ac882;}.sv-med{background:rgba(184,114,10,.2);color:#e8943a;}.sv-hard{background:rgba(192,57,43,.2);color:#e87868;}\n.faq-item{border:1px solid var(--border);border-radius:4px;margin-bottom:8px;overflow:hidden;}\n.faq-q{padding:14px 18px;display:flex;justify-content:space-between;align-items:center;cursor:pointer;background:white;font-size:14px;font-weight:500;color:var(--ink);user-select:none;}\n.faq-q:hover{background:var(--surface);}\n.faq-q .tog{font-size:18px;color:#e8b84b;flex-shrink:0;margin-left:12px;transition:transform .2s;font-family:var(--mono);}\n.faq-a{display:none;padding:18px;background:var(--surface);font-size:13.5px;color:#3a3830;line-height:1.75;border-top:1px solid var(--border);}\n.faq-item.open .faq-a{display:block;}.faq-item.open .tog{transform:rotate(45deg);}\n.sd-example{background:white;border:1px solid var(--border);border-radius:8px;margin:20px 0;overflow:hidden;}\n.sd-example-head{background:var(--ink);padding:14px 20px;display:flex;align-items:center;gap:12px;}\n.sd-example-title{font-family:var(--serif);font-size:16px;color:#f0ece4;font-weight:700;}\n.sd-example-tag{font-family:var(--mono);font-size:9px;letter-spacing:2px;color:#6a6458;border:1px solid #2e2c28;padding:3px 8px;border-radius:2px;}\n.sd-example-body{padding:20px;}\n.choice-row{display:flex;gap:10px;align-items:flex-start;padding:10px 0;border-bottom:1px solid var(--border);font-size:13px;}\n.choice-row:last-child{border:none;}\n.choice-label{font-family:var(--mono);font-size:10px;letter-spacing:1px;color:var(--muted);width:120px;flex-shrink:0;padding-top:2px;}\n.choice-val{flex:1;color:#3a3830;line-height:1.6;}\n.badge{display:inline-block;font-family:var(--mono);font-size:9px;padding:2px 7px;border-radius:2px;border:1px solid;margin-right:4px;font-weight:500;}\n.b-pg{background:var(--pg-bg);border-color:var(--pg);color:var(--pg);}.b-mg{background:var(--mg-bg);border-color:var(--mg);color:var(--mg);}.b-dy{background:var(--dy-bg);border-color:var(--dy);color:#b06000;}.b-ca{background:var(--ca-bg);border-color:var(--ca);color:var(--ca);}.b-g{background:var(--green-bg);border-color:var(--green);color:var(--green);}.b-r{background:var(--red-bg);border-color:var(--red);color:var(--red);}.b-a{background:var(--amber-bg);border-color:var(--amber);color:var(--amber);}\n.footer{background:var(--ink);text-align:center;padding:36px 20px;font-family:var(--mono);font-size:10px;color:#3a3830;letter-spacing:2px;}\n\n.step-block{background:#fff;border:1px solid var(--border);border-radius:8px;margin:20px 0;overflow:hidden;}\n.step-block-header{background:var(--ink);color:#e8e4dc;padding:13px 18px;font-family:var(--mono);font-size:10px;letter-spacing:2px;text-transform:uppercase;display:flex;align-items:center;gap:10px;}\n.sb-icon{font-size:16px;}\n.step-block-body{padding:0;}\n.step-row{display:flex;gap:0;border-bottom:1px solid var(--border);}\n.step-row:last-child{border-bottom:none;}\n.step-num{background:var(--surface);min-width:46px;display:flex;align-items:flex-start;justify-content:center;padding:16px 6px;font-family:var(--mono);font-size:11px;font-weight:700;color:var(--muted);flex-shrink:0;border-right:1px solid var(--border);}\n.step-content{padding:14px 18px;flex:1;}\n.step-q{font-weight:600;font-size:14px;color:var(--ink);margin-bottom:10px;}\n.step-options{display:flex;flex-direction:column;gap:6px;}\n.step-option{display:flex;gap:10px;align-items:flex-start;padding:9px 13px;border-radius:5px;font-size:13px;line-height:1.65;}\n.opt-yes{background:#edf8f2;border:1px solid #b8ddc8;}\n.opt-no{background:#fdf6e8;border:1px solid #e8c870;}\n.opt-mid{background:#edf2fb;border:1px solid #b8c8e8;}\n.opt-any{background:#f4f0fb;border:1px solid #c8b8e8;}\n.opt-arrow{font-family:var(--mono);font-size:12px;font-weight:700;flex-shrink:0;margin-top:1px;min-width:120px;}\n.opt-yes .opt-arrow{color:#1a7a4a;}\n.opt-no .opt-arrow{color:#b8720a;}\n.opt-mid .opt-arrow{color:#1a4f8a;}\n.opt-any .opt-arrow{color:#5a3c9a;}\n.opt-text{flex:1;color:#3a3830;}\n.concept-grid{display:grid;grid-template-columns:1fr;gap:0;margin:20px 0;border:1px solid var(--border);border-radius:8px;overflow:hidden;}\n.concept-row{display:flex;gap:0;border-bottom:1px solid var(--border);}\n.concept-row:last-child{border-bottom:none;}\n.concept-term{background:var(--ink);color:#e8b84b;font-family:var(--mono);font-size:11.5px;font-weight:600;min-width:155px;padding:14px 16px;flex-shrink:0;border-right:1px solid #2a2820;display:flex;align-items:flex-start;line-height:1.5;}\n.concept-def{padding:13px 16px;flex:1;font-size:13.5px;color:#3a3830;line-height:1.7;background:#fff;}\n.concept-def strong{color:var(--ink);}\n.concept-def code{background:var(--surface);padding:1px 5px;border-radius:3px;font-family:var(--mono);font-size:11px;color:var(--blue);}\n@media(max-width:560px){.concept-row{flex-direction:column;}.concept-term{min-width:auto;border-right:none;border-bottom:1px solid #2a2820;}.opt-arrow{min-width:80px;}}\n\n</style></head><body>\n<div class=\"hero\"><div class=\"hero-inner\">\n  <div class=\"hero-tag\">System Design \u00b7 FAANG Interview Prep \u00b7 Manish-Almanac</div>\n  <h1>CDN & Edge<br><em>Cloudflare, CloudFront, Fastly</em></h1>\n  <p class=\"hero-sub\">PoP architecture, pull vs push, cache invalidation, HLS video streaming, edge compute, DDoS mitigation \u2014 every CDN concept for system design interviews.</p>\n  <div class=\"db-pills\"><span class=\"db-pill\" style=\"border-color:#c0392b;color:#c0392b;background:#c0392b18\">Cloudflare</span><span class=\"db-pill\" style=\"border-color:#1a4f8a;color:#1a4f8a;background:#1a4f8a18\">CloudFront</span><span class=\"db-pill\" style=\"border-color:#1a7a4a;color:#1a7a4a;background:#1a7a4a18\">HLS/DASH</span><span class=\"db-pill\" style=\"border-color:#b8720a;color:#b8720a;background:#b8720a18\">Edge Compute</span><span class=\"db-pill\" style=\"border-color:#6040a0;color:#6040a0;background:#6040a018\">DDoS</span></div>\n</div></div>\n<nav class=\"nav\"><a href=\"#what\">What CDNs Do</a><a href=\"#how\">How They Work</a><a href=\"#video\">Video Streaming</a><a href=\"#edge-compute\">Edge Compute</a><a href=\"#followups\">Follow-ups</a></nav>\n<div class=\"wrap\">\n<section id=\"what\">\n  <div class=\"sec-tag\">00 \u00b7 What a CDN Does</div>\n  <h2>Serving content from 200 cities instead of one data centre</h2>\n  <div class=\"analogy\">\n    <div class=\"analogy-label\">The warehouse vs corner shop analogy</div>\n    <div class=\"analogy-text\">\n      Your origin server is a central warehouse in Mumbai. A user in Tokyo requests a video.<br><br>\n      <strong>Without CDN</strong>: request travels Mumbai \u2192 Tokyo (~150ms round trip). At 10MB/s, a 1GB video takes 100 seconds to deliver from origin to the user.<br><br>\n      <strong>With CDN</strong>: A CDN edge node in Tokyo has a cached copy. Same video served at ~1ms latency from the nearby PoP (Point of Presence). The origin server is never involved.<br><br>\n      The CDN's job: be a corner shop stocking the 100 most popular items, so customers do not have to travel to the warehouse for common requests.\n    </div>\n  </div>\n</section>\n\n<section id=\"how\">\n  <div class=\"sec-tag\">01 \u00b7 How CDNs Work</div>\n  <h2>PoP architecture, pull vs push, and cache invalidation</h2>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\"><div class=\"concept-term\">PoP & Anycast</div><div class=\"concept-def\"><strong>CDNs have 200+ Points of Presence (PoPs) worldwide. Anycast routing sends users to the nearest PoP automatically.</strong><br>\n      Anycast: multiple PoPs announce the same IP address. BGP routing sends the user's packet to the geographically nearest PoP \u2014 no DNS lookup delay, no manual geo-routing config.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Cloudflare: 200+ cities. Akamai: 4,000+ PoPs. Fastly: 50+ PoPs but higher bandwidth capacity. User latency: &lt;20ms to nearest PoP anywhere in the world.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Pull CDN (Lazy)</div><div class=\"concept-def\"><strong>CDN fetches content from origin on the first request (cache miss), then caches it.</strong><br>\n      First user in Tokyo requests <code>/images/photo.jpg</code> \u2192 CDN Tokyo misses \u2192 fetches from origin \u2192 caches \u2192 serves. All subsequent Tokyo users get it from cache.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 No management needed. Content is cached on demand. Automatically distributes popular content globally. Suitable for most web assets.</span><br>\n      <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 First user in each region gets origin latency (cache miss penalty). Content that is never requested globally stays uncached.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Push CDN (Eager)</div><div class=\"concept-def\"><strong>You proactively upload content to all CDN PoPs before any user requests it.</strong><br>\n      Before a product launch: push all assets to 200+ PoPs. First user in Tokyo gets the asset from cache (zero miss).<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Zero cache miss latency. Guaranteed availability. Ideal for: software releases, video premiere events, product launch assets.</span><br>\n      <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 Management overhead. You pay for storage at all PoPs even if content is never requested there. Not suitable for dynamic or user-specific content.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Cache Invalidation</div><div class=\"concept-def\"><strong>When origin content changes, you need to tell CDN edge nodes to drop their cached copies.</strong><br>\n      <strong>TTL expiry</strong>: set a short <code>Cache-Control: max-age=300</code>. Stale for up to 5 minutes.<br>\n      <strong>Cache purge API</strong>: Cloudflare/CloudFront have APIs to immediately invalidate specific URLs or patterns. Used when you push a critical fix.<br>\n      <strong>Cache versioning</strong>: embed version in filename \u2014 <code>app.v2.3.js</code>. Old URL still cached (fine), new URL fetched fresh. Zero-downtime asset updates.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Best practice: use cache versioning for static assets (infinite TTL + version in URL). Use short TTL for semi-dynamic content. Use purge API for emergency fixes.</span></div></div>\n  </div>\n</section>\n\n<section id=\"video\">\n  <div class=\"sec-tag\">02 \u00b7 Video Streaming via CDN</div>\n  <h2>HLS, DASH, and adaptive bitrate \u2014 how Netflix/YouTube actually work</h2>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\"><div class=\"concept-term\">Adaptive Bitrate (ABR)</div><div class=\"concept-def\"><strong>Video is encoded at multiple quality levels. The player automatically switches quality based on network speed.</strong><br>\n      A 2-hour movie is encoded at: 360p (1Mbps), 720p (4Mbps), 1080p (8Mbps), 4K (25Mbps).<br>\n      Player measures available bandwidth every few seconds and requests the appropriate quality.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Smooth playback despite varying network conditions. Starts at low quality (immediate playback) and upgrades as bandwidth permits.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">HLS Segmentation</div><div class=\"concept-def\"><strong>Video is split into 2\u201310 second segments stored as individual files. A manifest file (.m3u8) lists all segments.</strong><br>\n      Player downloads manifest \u2192 fetches segments sequentially \u2192 each segment is cached independently by CDN.<br>\n      <code>index.m3u8</code> \u2192 <code>segment001.ts, segment002.ts ...</code><br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 CDN caches each segment independently. Popular segments (the first 10 seconds every viewer watches) have extremely high cache hit rates. Seeks jump to the correct segment URL directly.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">CDN Role in Video</div><div class=\"concept-def\"><strong>Video segments are static files \u2192 perfect for CDN caching.</strong><br>\n      Netflix: 3 copies of each segment stored in S3 (origin). CloudFront caches hot segments at 200+ PoPs. Popular shows: 99%+ cache hit rate. Long-tail content: served from origin.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Netflix offloads ~95% of video bytes to CDN. Origin bandwidth savings: enormous. User experience: consistent quality regardless of Netflix's origin capacity.</span></div></div>\n  </div>\n</section>\n\n<section id=\"edge-compute\">\n  <div class=\"sec-tag\">03 \u00b7 Edge Compute</div>\n  <h2>Running code at the CDN edge</h2>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\"><div class=\"concept-term\">What Is Edge Compute</div><div class=\"concept-def\"><strong>Run serverless code at the CDN PoP, close to the user \u2014 before the request reaches your origin.</strong><br>\n      Examples: Cloudflare Workers, AWS Lambda@Edge, Fastly Compute@Edge.<br>\n      Use for: A/B testing (redirect 10% of users to new version at edge), auth token validation (validate JWT at edge, reject bad tokens before they hit origin), geo-based redirects, request transformation.</div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">CDN for DDoS</div><div class=\"concept-def\"><strong>CDN absorbs DDoS attacks at the edge \u2014 attack traffic never reaches your origin.</strong><br>\n      A 1Tbps DDoS attack is distributed across 200 PoPs. Each absorbs 5Gbps \u2014 trivial for a large PoP. Your 10Gbps origin link never sees the attack.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Cloudflare's network capacity: 100+ Tbps. The largest DDoS attacks ever recorded were absorbed by Cloudflare without origin impact. Used by: every large web property (including FAANG).</span></div></div>\n  </div>\n</section>\n\n<section id=\"followups\">\n  <div class=\"sec-tag\">04 \u00b7 Follow-ups</div>\n  <h2>Every hard follow-up, answered</h2>\n  <div class=\"faq-item\"><div class=\"faq-q\" onclick=\"toggle(this)\">How do you cache personalised or authenticated content at the CDN?<span class=\"tog\">+</span></div>\n  <div class=\"faq-a\"><strong>The standard CDN model caches public content. Personalised content requires one of three approaches:</strong><br><br>\n  <strong>1. Edge side includes (ESI)</strong>: The page has a public frame (cached) with placeholder tags for personalised sections. CDN fetches only the personalised fragment from origin (small request) and assembles the full page. Used by: Akamai ESI, Varnish.<br><br>\n  <strong>2. Split the response</strong>: API returns a public body + a personalised section. Public body cached at CDN (TTL=1h). Personalised section fetched fresh from origin on each request (bypass cache). Combine on the client.<br><br>\n  <strong>3. Cache by session/user segment</strong>: CDN can cache separate copies per cache key, including cookies or auth headers: <code>Vary: Authorization</code>. But this effectively defeats caching for large user populations (one cache entry per user). Only viable for small user pools or role-based segmentation (admin vs regular user).<br><br>\n  <strong>General rule</strong>: use CDN for the parts of your response that are genuinely the same for all users. Fetch personalised parts dynamically. The split between cacheable and dynamic is a key architectural decision.</div></div>\n  <div class=\"faq-item\"><div class=\"faq-q\" onclick=\"toggle(this)\">Cloudflare vs CloudFront vs Fastly \u2014 which should you use?<span class=\"tog\">+</span></div>\n  <div class=\"faq-a\"><strong>All three are production-grade. The decision is usually driven by cloud commitment and specific feature needs.</strong><br><br>\n  <strong>CloudFront (AWS)</strong>: Best choice if you are already on AWS. Native integration with S3 (origin), ALB, API Gateway, Lambda@Edge. Pricing: per-GB transfer + per-request. Can get expensive at very high volume. Management via AWS Console/IaC (Terraform, CDK).<br><br>\n  <strong>Cloudflare</strong>: Independent of cloud provider. Largest network (200+ PoPs, 100+ Tbps). Best DDoS protection. Workers are the most capable edge compute. Generous free tier. Flat pricing at enterprise scale (often cheaper than CloudFront for high-volume). Best choice for: security-first setups, cloud-agnostic architectures, maximising CDN network size.<br><br>\n  <strong>Fastly</strong>: Fewer PoPs but very high capacity at each. Instant purge API (&lt;150ms globally) \u2014 critical for news sites and real-time content. Varnish-based \u2014 very developer-friendly cache configuration. Best choice for: media companies, news sites, any use case where sub-second cache invalidation is critical.</div></div>\n</section></div>\n<div class=\"footer\">CDN \u00b7 EDGE \u00b7 CLOUDFLARE \u00b7 CLOUDFRONT \u00b7 HLS \u00b7 ADAPTIVE BITRATE \u00b7 DDOS \u00b7 MANISH-ALMANAC</div>\n\u003cscript>function toggle(el){el.parentElement.classList.toggle('open');}<\/script>\n</body></html>", tag: 'CDN' },
  observability: { title: 'Monitoring & Observability', srcdoc: "<!DOCTYPE html>\n<html lang=\"en\"><head><meta charset=\"UTF-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Monitoring & Observability: The Three Pillars</title>\n<link href=\"https://fonts.googleapis.com/css2?family=Playfair+Display:wght@700;900&family=Source+Sans+3:wght@300;400;500;600&family=JetBrains+Mono:wght@400;600&display=swap\" rel=\"stylesheet\">\n<style>\n:root{--ink:#0f0e0c;--page:#f7f5f0;--surface:#eeecea;--surface2:#e5e2dc;--border:#d4d0c8;--muted:#7a7568;--pg:#336791;--pg-bg:#eef4fb;--mg:#13aa52;--mg-bg:#edfaf2;--dy:#ff9900;--dy-bg:#fff8ec;--ca:#1287b1;--ca-bg:#eaf6fb;--red:#c0392b;--red-bg:#fdf0ee;--green:#1a7a4a;--green-bg:#edf8f2;--amber:#b8720a;--amber-bg:#fdf6e8;--blue:#1a4f8a;--blue-bg:#edf2fb;--mono:'JetBrains Mono',monospace;--serif:'Playfair Display',serif;--sans:'Source Sans 3',sans-serif;}\n*{box-sizing:border-box;margin:0;padding:0;}html{scroll-behavior:smooth;}\nbody{background:var(--page);color:var(--ink);font-family:var(--sans);font-size:15px;line-height:1.75;}\n.hero{background:var(--ink);color:#e8e4dc;padding:72px 24px 56px;position:relative;overflow:hidden;}\n.hero::before{content:'';position:absolute;inset:0;background:repeating-linear-gradient(45deg,transparent,transparent 40px,rgba(255,255,255,.015) 40px,rgba(255,255,255,.015) 41px);}\n.hero-inner{max-width:960px;margin:0 auto;position:relative;}\n.hero-tag{font-family:var(--mono);font-size:10px;letter-spacing:4px;color:#6a6458;text-transform:uppercase;margin-bottom:20px;}\nh1{font-family:var(--serif);font-size:clamp(32px,5vw,58px);font-weight:900;line-height:1.05;letter-spacing:-.5px;margin-bottom:20px;color:#f0ece4;}\nh1 em{color:#e8b84b;font-style:normal;}\n.hero-sub{font-size:15px;color:#7a7060;max-width:640px;line-height:1.7;margin-bottom:32px;}\n.db-pills{display:flex;flex-wrap:wrap;gap:8px;}\n.db-pill{font-family:var(--mono);font-size:10px;padding:5px 14px;border-radius:3px;border:1px solid;letter-spacing:.5px;}\n.pill-pg{border-color:#336791;color:#336791;background:rgba(51,103,145,.08);}\n.pill-mg{border-color:#13aa52;color:#13aa52;background:rgba(19,170,82,.08);}\n.pill-dy{border-color:#ff9900;color:#cc7a00;background:rgba(255,153,0,.08);}\n.pill-ca{border-color:#1287b1;color:#1287b1;background:rgba(18,135,177,.08);}\n.nav{position:sticky;top:0;z-index:100;background:var(--ink);border-bottom:1px solid #1e1c18;display:flex;overflow-x:auto;scrollbar-width:none;padding:0 20px;}\n.nav::-webkit-scrollbar{display:none;}\n.nav a{font-family:var(--mono);font-size:10px;letter-spacing:1px;color:#4a4840;text-decoration:none;padding:14px 12px;white-space:nowrap;border-bottom:2px solid transparent;transition:.18s;}\n.nav a:hover{color:#e8b84b;border-color:#e8b84b;}\n.wrap{max-width:960px;margin:0 auto;padding:0 20px;}\nsection{padding:56px 0 36px;border-bottom:2px solid var(--border);}\nsection:last-child{border:none;}\n.sec-tag{font-family:var(--mono);font-size:9px;letter-spacing:4px;text-transform:uppercase;color:var(--muted);margin-bottom:8px;display:flex;align-items:center;gap:10px;}\n.sec-tag::before{content:'';width:20px;height:1px;background:var(--border);}\nh2{font-family:var(--serif);font-size:clamp(22px,3.5vw,32px);font-weight:700;line-height:1.15;margin-bottom:18px;}\nh3{font-family:var(--sans);font-size:17px;font-weight:600;margin:32px 0 10px;border-bottom:1px solid var(--border);padding-bottom:6px;}\nh4{font-size:13px;font-weight:600;margin:16px 0 6px;text-transform:uppercase;letter-spacing:.5px;}\np{color:#3a3830;font-size:14.5px;margin-bottom:12px;}\nstrong{color:var(--ink);}\ncode{font-family:var(--mono);font-size:11.5px;background:var(--surface2);padding:1px 5px;border-radius:3px;color:var(--blue);}\n.db-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:14px;margin:24px 0;}\n.db-card{background:white;border:1px solid var(--border);border-radius:8px;padding:20px;position:relative;overflow:hidden;}\n.db-card::before{content:'';position:absolute;top:0;left:0;right:0;height:4px;}\n.db-card.pg::before{background:var(--pg);}\n.db-card.mg::before{background:var(--mg);}\n.db-card.dy::before{background:var(--dy);}\n.db-card.ca::before{background:var(--ca);}\n.db-logo{font-size:22px;margin-bottom:6px;}\n.db-name{font-family:var(--serif);font-size:17px;font-weight:700;margin-bottom:4px;}\n.db-type{font-family:var(--mono);font-size:9px;letter-spacing:2px;color:var(--muted);margin-bottom:10px;text-transform:uppercase;}\n.db-tagline{font-size:13px;color:#5a5848;line-height:1.55;}\n.db-born{font-family:var(--mono);font-size:9px;color:var(--muted);margin-top:8px;}\n.analogy{background:var(--ink);color:#c8c4b8;border-radius:8px;padding:24px 28px;margin:24px 0;}\n.analogy-label{font-family:var(--mono);font-size:9px;letter-spacing:3px;color:#6a6458;margin-bottom:10px;text-transform:uppercase;}\n.analogy-text{font-size:15px;line-height:1.75;color:#d8d4c8;}\n.analogy-text strong{color:#e8b84b;}\n.callout{border-radius:4px;padding:14px 18px;margin:18px 0;font-size:13.5px;border-left:3px solid;line-height:1.65;}\n.callout p{font-size:13.5px;margin-bottom:6px;}\n.callout p:last-child{margin:0;}\n.cl-blue{background:var(--blue-bg);border-color:var(--blue);color:#1a2a4a;}\n.cl-green{background:var(--green-bg);border-color:var(--green);color:#0a2a1a;}\n.cl-amber{background:var(--amber-bg);border-color:var(--amber);color:#3a2a08;}\n.cl-red{background:var(--red-bg);border-color:var(--red);color:#3a0a08;}\n.cl-lbl{font-family:var(--mono);font-size:9px;letter-spacing:3px;text-transform:uppercase;margin-bottom:6px;opacity:.7;}\n.codeblock{background:var(--ink);border-radius:6px;padding:20px 22px;font-family:var(--mono);font-size:11.5px;line-height:2;overflow-x:auto;margin:14px 0;color:#c8c4b8;border:1px solid #1e1c18;}\n.codeblock .c{color:#3e3d36;}.codeblock .k{color:#e8b84b;}.codeblock .s{color:#8bc4a0;}.codeblock .n{color:#e8946a;}.codeblock .t{color:#7aaee0;}.codeblock .g{color:#a8d878;}.codeblock .r{color:#e87878;}\n.comp-table{width:100%;border-collapse:collapse;margin:20px 0;font-size:13px;}\n.comp-table th{padding:10px 14px;border:1px solid var(--border);background:var(--surface2);font-family:var(--mono);font-size:9px;letter-spacing:1.5px;text-transform:uppercase;color:var(--muted);}\n.comp-table td{padding:11px 14px;border:1px solid var(--border);vertical-align:top;color:#3a3830;line-height:1.6;}\n.comp-table .row-head{font-family:var(--mono);font-size:11px;font-weight:600;background:var(--surface);color:var(--ink);white-space:nowrap;}\n.good{color:var(--green);font-weight:600;}.warn{color:var(--amber);font-weight:600;}.bad{color:var(--red);font-weight:600;}\n.dot{display:inline-block;width:9px;height:9px;border-radius:50%;margin-right:4px;vertical-align:middle;}\n.dot.g{background:var(--green);}.dot.a{background:var(--amber);}.dot.r{background:var(--red);}\n.use-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:14px;margin:20px 0;}\n.use-card{border:1px solid var(--border);border-radius:6px;padding:18px;background:white;}\n.use-card-head{font-family:var(--mono);font-size:11px;font-weight:600;margin-bottom:10px;display:flex;align-items:center;gap:8px;}\n.use-card ul{padding-left:16px;font-size:13px;color:#4a4838;line-height:1.7;}\n.use-card ul li{margin-bottom:4px;}\n.shard-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:14px;margin:20px 0;}\n.shard-card{background:var(--ink);border-radius:8px;padding:20px;color:#c8c4b8;}\n.shard-title{font-family:var(--mono);font-size:10px;letter-spacing:2px;color:#6a6458;margin-bottom:10px;text-transform:uppercase;}\n.shard-name{font-family:var(--serif);font-size:16px;font-weight:700;color:#e8b84b;margin-bottom:8px;}\n.shard-body{font-size:12.5px;line-height:1.65;color:#a8a49c;}\n.shard-verdict{margin-top:10px;font-family:var(--mono);font-size:10px;padding:4px 10px;border-radius:3px;display:inline-block;}\n.sv-easy{background:rgba(26,122,74,.2);color:#5ac882;}.sv-med{background:rgba(184,114,10,.2);color:#e8943a;}.sv-hard{background:rgba(192,57,43,.2);color:#e87868;}\n.faq-item{border:1px solid var(--border);border-radius:4px;margin-bottom:8px;overflow:hidden;}\n.faq-q{padding:14px 18px;display:flex;justify-content:space-between;align-items:center;cursor:pointer;background:white;font-size:14px;font-weight:500;color:var(--ink);user-select:none;}\n.faq-q:hover{background:var(--surface);}\n.faq-q .tog{font-size:18px;color:#e8b84b;flex-shrink:0;margin-left:12px;transition:transform .2s;font-family:var(--mono);}\n.faq-a{display:none;padding:18px;background:var(--surface);font-size:13.5px;color:#3a3830;line-height:1.75;border-top:1px solid var(--border);}\n.faq-item.open .faq-a{display:block;}.faq-item.open .tog{transform:rotate(45deg);}\n.sd-example{background:white;border:1px solid var(--border);border-radius:8px;margin:20px 0;overflow:hidden;}\n.sd-example-head{background:var(--ink);padding:14px 20px;display:flex;align-items:center;gap:12px;}\n.sd-example-title{font-family:var(--serif);font-size:16px;color:#f0ece4;font-weight:700;}\n.sd-example-tag{font-family:var(--mono);font-size:9px;letter-spacing:2px;color:#6a6458;border:1px solid #2e2c28;padding:3px 8px;border-radius:2px;}\n.sd-example-body{padding:20px;}\n.choice-row{display:flex;gap:10px;align-items:flex-start;padding:10px 0;border-bottom:1px solid var(--border);font-size:13px;}\n.choice-row:last-child{border:none;}\n.choice-label{font-family:var(--mono);font-size:10px;letter-spacing:1px;color:var(--muted);width:120px;flex-shrink:0;padding-top:2px;}\n.choice-val{flex:1;color:#3a3830;line-height:1.6;}\n.badge{display:inline-block;font-family:var(--mono);font-size:9px;padding:2px 7px;border-radius:2px;border:1px solid;margin-right:4px;font-weight:500;}\n.b-pg{background:var(--pg-bg);border-color:var(--pg);color:var(--pg);}.b-mg{background:var(--mg-bg);border-color:var(--mg);color:var(--mg);}.b-dy{background:var(--dy-bg);border-color:var(--dy);color:#b06000;}.b-ca{background:var(--ca-bg);border-color:var(--ca);color:var(--ca);}.b-g{background:var(--green-bg);border-color:var(--green);color:var(--green);}.b-r{background:var(--red-bg);border-color:var(--red);color:var(--red);}.b-a{background:var(--amber-bg);border-color:var(--amber);color:var(--amber);}\n.footer{background:var(--ink);text-align:center;padding:36px 20px;font-family:var(--mono);font-size:10px;color:#3a3830;letter-spacing:2px;}\n\n.step-block{background:#fff;border:1px solid var(--border);border-radius:8px;margin:20px 0;overflow:hidden;}\n.step-block-header{background:var(--ink);color:#e8e4dc;padding:13px 18px;font-family:var(--mono);font-size:10px;letter-spacing:2px;text-transform:uppercase;display:flex;align-items:center;gap:10px;}\n.sb-icon{font-size:16px;}\n.step-block-body{padding:0;}\n.step-row{display:flex;gap:0;border-bottom:1px solid var(--border);}\n.step-row:last-child{border-bottom:none;}\n.step-num{background:var(--surface);min-width:46px;display:flex;align-items:flex-start;justify-content:center;padding:16px 6px;font-family:var(--mono);font-size:11px;font-weight:700;color:var(--muted);flex-shrink:0;border-right:1px solid var(--border);}\n.step-content{padding:14px 18px;flex:1;}\n.step-q{font-weight:600;font-size:14px;color:var(--ink);margin-bottom:10px;}\n.step-options{display:flex;flex-direction:column;gap:6px;}\n.step-option{display:flex;gap:10px;align-items:flex-start;padding:9px 13px;border-radius:5px;font-size:13px;line-height:1.65;}\n.opt-yes{background:#edf8f2;border:1px solid #b8ddc8;}\n.opt-no{background:#fdf6e8;border:1px solid #e8c870;}\n.opt-mid{background:#edf2fb;border:1px solid #b8c8e8;}\n.opt-any{background:#f4f0fb;border:1px solid #c8b8e8;}\n.opt-arrow{font-family:var(--mono);font-size:12px;font-weight:700;flex-shrink:0;margin-top:1px;min-width:120px;}\n.opt-yes .opt-arrow{color:#1a7a4a;}\n.opt-no .opt-arrow{color:#b8720a;}\n.opt-mid .opt-arrow{color:#1a4f8a;}\n.opt-any .opt-arrow{color:#5a3c9a;}\n.opt-text{flex:1;color:#3a3830;}\n.concept-grid{display:grid;grid-template-columns:1fr;gap:0;margin:20px 0;border:1px solid var(--border);border-radius:8px;overflow:hidden;}\n.concept-row{display:flex;gap:0;border-bottom:1px solid var(--border);}\n.concept-row:last-child{border-bottom:none;}\n.concept-term{background:var(--ink);color:#e8b84b;font-family:var(--mono);font-size:11.5px;font-weight:600;min-width:155px;padding:14px 16px;flex-shrink:0;border-right:1px solid #2a2820;display:flex;align-items:flex-start;line-height:1.5;}\n.concept-def{padding:13px 16px;flex:1;font-size:13.5px;color:#3a3830;line-height:1.7;background:#fff;}\n.concept-def strong{color:var(--ink);}\n.concept-def code{background:var(--surface);padding:1px 5px;border-radius:3px;font-family:var(--mono);font-size:11px;color:var(--blue);}\n@media(max-width:560px){.concept-row{flex-direction:column;}.concept-term{min-width:auto;border-right:none;border-bottom:1px solid #2a2820;}.opt-arrow{min-width:80px;}}\n\n</style></head><body>\n<div class=\"hero\"><div class=\"hero-inner\">\n  <div class=\"hero-tag\">System Design \u00b7 FAANG Interview Prep \u00b7 Manish-Almanac</div>\n  <h1>Monitoring & Observability<br><em>The Three Pillars</em></h1>\n  <p class=\"hero-sub\">Metrics, logs, traces \u2014 SLI/SLO/SLA, error budgets, four golden signals, Prometheus/Grafana, distributed tracing and alerting best practices.</p>\n  <div class=\"db-pills\"><span class=\"db-pill\" style=\"border-color:#c0392b;color:#c0392b;background:#c0392b18\">Prometheus</span><span class=\"db-pill\" style=\"border-color:#1a4f8a;color:#1a4f8a;background:#1a4f8a18\">Jaeger / OTEL</span><span class=\"db-pill\" style=\"border-color:#1a7a4a;color:#1a7a4a;background:#1a7a4a18\">SLO / SLA</span><span class=\"db-pill\" style=\"border-color:#b8720a;color:#b8720a;background:#b8720a18\">Golden Signals</span><span class=\"db-pill\" style=\"border-color:#6040a0;color:#6040a0;background:#6040a018\">Error Budget</span></div>\n</div></div>\n<nav class=\"nav\"><a href=\"#three-pillars\">Three Pillars</a><a href=\"#slo\">SLI/SLO/SLA</a><a href=\"#tools\">Tools & Signals</a><a href=\"#followups\">Follow-ups</a></nav>\n<div class=\"wrap\">\n<section id=\"three-pillars\">\n  <div class=\"sec-tag\">00 \u00b7 The Three Pillars</div>\n  <h2>Metrics, Logs, and Traces \u2014 why you need all three</h2>\n  <div class=\"analogy\">\n    <div class=\"analogy-label\">The hospital analogy \u2014 for a complete layman</div>\n    <div class=\"analogy-text\">\n      Your system is a patient. Observability is how doctors understand what is happening inside.<br><br>\n      <strong>Metrics</strong> are the vital signs: heart rate 72bpm, blood pressure 120/80. Numbers over time. They tell you something is wrong but not why.<br><br>\n      <strong>Logs</strong> are the doctor's notes: \"14:23:01 \u2014 patient reported chest pain. 14:23:45 \u2014 administered aspirin.\" Text events at specific times. They tell you what happened, step by step.<br><br>\n      <strong>Traces</strong> are the MRI scan: shows exactly which organ is causing the problem, how blood flows through each one, and where the blockage is. For distributed systems: shows exactly which service caused the latency.\n    </div>\n  </div>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\"><div class=\"concept-term\">Metrics</div><div class=\"concept-def\"><strong>Numeric measurements over time. Aggregated, efficient, alertable.</strong><br>\n      Examples: requests/sec, p99 latency, error rate, CPU usage, DB connections.<br>\n      Storage: time-series databases (Prometheus, InfluxDB) designed for fast aggregation over time ranges.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Cheap to store (numbers, not text). Fast to query. Essential for dashboards and alerting. Answer: \"is something wrong?\"</span><br>\n      <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 Cannot tell you why something is wrong. High cardinality metrics (one time series per user ID) explode storage costs.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Logs</div><div class=\"concept-def\"><strong>Text records of discrete events. Timestamped. Searchable.</strong><br>\n      Examples: \"ERROR: DB connection failed \u2014 timeout after 5000ms\", \"INFO: user:123 logged in from IP 1.2.3.4\"<br>\n      Storage: Elasticsearch (ELK stack) or Loki (cheaper, label-based).<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Rich context. Exact error messages. Correlate events by user/session/request ID. Answer: \"what exactly happened?\"</span><br>\n      <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 Expensive to store at high volume. Unstructured logs are hard to query \u2014 use structured JSON logging. Do not log sensitive data.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Traces</div><div class=\"concept-def\"><strong>Records the path of a single request through all microservices, with timing at each hop.</strong><br>\n      A user request spawns a trace with a unique trace_id. Each service call is a span. The trace shows: API Gateway (10ms) \u2192 Auth Service (5ms) \u2192 Product Service (200ms) \u2192 DB query (180ms of that 200ms).<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Immediately identifies which service is slow. Essential for microservices. Answer: \"which service is causing the problem?\"</span><br>\n      <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 Requires instrumentation in every service. Storage costs proportional to request volume \u00d7 service count. Use sampling (store 1% of traces, all error traces).</span></div></div>\n  </div>\n</section>\n\n<section id=\"slo\">\n  <div class=\"sec-tag\">01 \u00b7 SLI, SLO, SLA</div>\n  <h2>How to define and measure reliability \u2014 Director-level expected</h2>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\"><div class=\"concept-term\">SLI<br>(Service Level Indicator)</div><div class=\"concept-def\"><strong>A quantitative measure of service behaviour. The thing you actually measure.</strong><br>\n      Examples: request success rate (% of requests returning non-5xx), p99 latency (99th percentile response time), availability (% of time service is up).<br>\n      <span style=\"color:#5a5848;font-size:12.5px;\">SLIs are the raw measurements. Choose SLIs that directly reflect the user experience.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">SLO<br>(Service Level Objective)</div><div class=\"concept-def\"><strong>The target for your SLI. The internal goal your team commits to.</strong><br>\n      Examples: \"99.9% of requests complete successfully\" (three nines), \"p99 latency \u2264 200ms\", \"availability \u2265 99.95% per month\".<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 SLOs drive engineering decisions. If you are burning your error budget, prioritise reliability work. If you are comfortably meeting SLOs, invest in features.</span><br>\n      <span style=\"color:#5a5848;font-size:12.5px;\">99.9% availability = 8.7 hours downtime/year. 99.99% = 52 minutes. 99.999% = 5 minutes. Know these numbers.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">SLA<br>(Service Level Agreement)</div><div class=\"concept-def\"><strong>The contractual commitment to customers, with financial penalties for breach.</strong><br>\n      AWS EC2 SLA: 99.99% availability. If violated: customer gets service credits.<br>\n      <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 SLA should be more conservative than your SLO. Your internal SLO is 99.95% so you have headroom before violating the 99.9% SLA you've contractually committed to customers.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Error Budget</div><div class=\"concept-def\"><strong>The amount of unreliability you are allowed per period before violating your SLO.</strong><br>\n      SLO: 99.9% success rate over 30 days. That is 0.1% allowed failures = 43.2 minutes of downtime allowed per month.<br>\n      If you deploy a bad release and burn 30 minutes of error budget, you have 13 minutes left that month.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Error budgets make reliability discussions data-driven. \"We cannot deploy this risky feature \u2014 we have only 5 minutes of error budget left this month.\"</span><br>\n      <span style=\"color:#5a5848;font-size:12.5px;\">Google SRE invented this concept. It is the key metric for Director-level reliability conversations.</span></div></div>\n  </div>\n</section>\n\n<section id=\"tools\">\n  <div class=\"sec-tag\">02 \u00b7 Tools & Golden Signals</div>\n  <h2>Prometheus, Grafana, Jaeger, and the four golden signals</h2>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\"><div class=\"concept-term\">Four Golden Signals<br>(Google SRE Book)</div><div class=\"concept-def\"><strong>The four metrics that matter most for any service:</strong><br>\n      1. <strong>Latency</strong>: how long it takes to serve a request. Track p50, p95, p99 separately \u2014 averages hide outliers.<br>\n      2. <strong>Traffic</strong>: demand on your system (requests/sec, messages/sec, transactions/sec).<br>\n      3. <strong>Errors</strong>: rate of failed requests (5xx errors, exceptions, timeouts).<br>\n      4. <strong>Saturation</strong>: how \"full\" your service is (CPU %, memory %, DB connection pool utilisation, queue depth).<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 If you only monitor these four for every service, you will catch 90% of production incidents before users notice.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Prometheus + Grafana</div><div class=\"concept-def\"><strong>The standard open-source metrics stack.</strong><br>\n      Prometheus: pulls metrics from /metrics endpoints every 15s. Stores as time-series. PromQL query language for aggregations.<br>\n      Grafana: dashboards on top of Prometheus (and many other sources). Pre-built dashboards for Kubernetes, PostgreSQL, Redis, etc.<br>\n      <code>rate(http_requests_total{status=~\"5..\"}[5m])</code> \u2014 error rate over last 5 minutes.<br>\n      <span style=\"color:#5a5848;font-size:12.5px;\">Used by: Grafana Labs (obviously), Uber, DigitalOcean, dozens of FAANG-adjacent companies. Kubernetes ships Prometheus-compatible metrics by default.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Distributed Tracing<br>(Jaeger / Zipkin)</div><div class=\"concept-def\"><strong>OpenTelemetry is the emerging standard for instrumentation. One SDK, plugs into any backend (Jaeger, Zipkin, Tempo, Datadog).</strong><br>\n      Instrument your code once with OpenTelemetry SDK \u2192 export traces to Jaeger \u2192 visualise spans in the Jaeger UI.<br>\n      trace_id propagated in headers: <code>traceparent: 00-{trace_id}-{span_id}-01</code><br>\n      All services that receive this header add their span to the same trace.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 OpenTelemetry is vendor-neutral \u2014 switch backends without re-instrumenting. Used by: Google Cloud Trace, AWS X-Ray, Datadog, New Relic all accept OTLP format.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Structured Logging</div><div class=\"concept-def\"><strong>Log as JSON instead of plain text. Every field is queryable.</strong><br>\n      Bad: <code>\"ERROR: user 123 failed login from 1.2.3.4 at 14:23:01\"</code> \u2014 requires regex to parse.<br>\n      Good: <code>{\"level\":\"error\",\"event\":\"login_failed\",\"user_id\":123,\"ip\":\"1.2.3.4\",\"ts\":\"14:23:01\"}</code> \u2014 directly filterable in Elasticsearch or Loki.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Filter all errors for user:123 in seconds. Correlate across services by request_id. Aggregate error types. Essential for production debugging at scale.</span></div></div>\n  </div>\n</section>\n\n<section id=\"followups\">\n  <div class=\"sec-tag\">03 \u00b7 Follow-ups</div>\n  <h2>Every hard follow-up, answered</h2>\n  <div class=\"faq-item\"><div class=\"faq-q\" onclick=\"toggle(this)\">How do you set meaningful SLOs \u2014 how do you know what 99.9% vs 99.99% means for your system?<span class=\"tog\">+</span></div>\n  <div class=\"faq-a\"><strong>Start with what users actually notice, not an arbitrary number.</strong><br><br>\n  <strong>Step 1 \u2014 Measure current reliability</strong>: what is your actual success rate over the last 30 days? This is your baseline. Setting an SLO below current performance is pointless.<br><br>\n  <strong>Step 2 \u2014 Understand user tolerance</strong>: what level of error do users actually experience and complain about? For a social feed, a 0.1% error rate might be imperceptible. For a payment API, even 0.01% errors (one in 10,000 payments failing) would cause serious complaints.<br><br>\n  <strong>Step 3 \u2014 Cost of reliability</strong>: going from 99.9% to 99.99% availability typically requires: redundant infrastructure, geographic distribution, more complex failure handling. Is the engineering investment justified by the product need?<br><br>\n  <strong>Typical starting points</strong>: User-facing read API: 99.9%. User-facing write API: 99.95%. Payment processing: 99.99%. Internal infrastructure services: 99.5%. Batch processing: 99%.</div></div>\n  <div class=\"faq-item\"><div class=\"faq-q\" onclick=\"toggle(this)\">How do you avoid alert fatigue while still catching real incidents?<span class=\"tog\">+</span></div>\n  <div class=\"faq-a\"><strong>Alert on symptoms, not causes. Alert on SLO burn rate, not on individual metric thresholds.</strong><br><br>\n  <strong>The anti-pattern</strong>: \"Alert when CPU &gt; 80%.\" CPU spikes happen constantly and usually resolve without user impact. Engineers learn to ignore the alerts (alert fatigue). When a real incident happens, it is buried in noise.<br><br>\n  <strong>Better approach \u2014 SLO burn rate alerting</strong>: alert when you are burning your error budget faster than sustainable. \"Alert when error rate over the last 1 hour would exhaust the monthly error budget in 2 days.\" This alert is high-signal \u2014 it means users are actually experiencing problems at a rate that will violate your SLO.<br><br>\n  <strong>Alert design rules</strong>:<br>\n  1. Every alert must be actionable \u2014 if there is no runbook for it, delete it<br>\n  2. Alerts should page at most once per incident, not continuously<br>\n  3. Alert on p99 latency, not p50 \u2014 averages hide the long tail that users experience<br>\n  4. Distinguish page (wake someone up) vs ticket (fix in business hours) severity</div></div>\n</section></div>\n<div class=\"footer\">MONITORING \u00b7 OBSERVABILITY \u00b7 PROMETHEUS \u00b7 JAEGER \u00b7 SLO \u00b7 ERROR BUDGET \u00b7 GOLDEN SIGNALS \u00b7 MANISH-ALMANAC</div>\n\u003cscript>function toggle(el){el.parentElement.classList.toggle('open');}<\/script>\n</body></html>", tag: 'Observability' }
};

function openCollection(){
  document.getElementById('list').style.display='none';
  document.getElementById('coll-panel').classList.add('open');
}
function closeCollection(){
  document.getElementById('coll-item').classList.remove('open');
  var f=document.getElementById('ci-iframe');if(f)f.srcdoc='';
  document.getElementById('coll-panel').classList.remove('open');
  document.getElementById('list').style.display='block';
}
function openCollItem(id){
  var item=COLLECTION_DATA[id];
  if(!item)return;
  document.getElementById('ci-title').textContent=item.title;
  var iframe=document.getElementById('ci-iframe');
  document.getElementById('coll-item').classList.add('open');
  if(item.srcdoc){
    /* embedded — works on file://, GitHub Pages, everywhere */
    iframe.srcdoc=item.srcdoc;
  } else {
    /* fetch-based — for cms/topk/ai_handbook standalone files */
    iframe.srcdoc='<div style="font-family:-apple-system,sans-serif;padding:40px 24px;text-align:center;color:#aaa;font-size:14px">Loading…</div>';
    fetch(item.file)
      .then(function(r){ if(!r.ok)throw new Error('HTTP '+r.status); return r.text(); })
      .then(function(html){ iframe.srcdoc=html; })
      .catch(function(e){
        iframe.srcdoc='<div style="font-family:-apple-system,sans-serif;padding:40px 24px;color:#c00;font-size:14px">Could not load '+item.file+'.<br><small>'+e.message+'</small><br><br><small>Run via server: <code>python3 -m http.server</code></small></div>';
      });
  }
}
function closeCollItem(){
  document.getElementById('coll-item').classList.remove('open');
  /* Clear iframe to stop any running scripts */
  setTimeout(function(){
    var f=document.getElementById('ci-iframe');
    if(f)f.srcdoc='';
  },50);
}

function initCollection(){
  var pairs=[
    ['btn_collection',   function(){openCollection();}],
    ['btn_coll_back',    function(){closeCollection();}],
    ['btn_ci_back',      function(){closeCollItem();}],
    ['btn_coll_cms',     function(){openCollItem('cms');}],
    ['btn_coll_topk',    function(){openCollItem('topk');}],
    ['btn_coll_ai',      function(){openCollItem('ai_handbook');}],
    ['btn_coll_databases',function(){openCollItem('databases');}],
    ['btn_coll_olap',    function(){openCollItem('olap');}],
    ['btn_coll_streaming',function(){openCollItem('streaming');}],
    ['btn_coll_protocols',function(){openCollItem('protocols');}],
    ['btn_coll_caching',function(){openCollItem('caching');}],
    ['btn_coll_consistent_hashing',function(){openCollItem('consistent_hashing');}],
    ['btn_coll_rate_limiting',function(){openCollItem('rate_limiting');}],
    ['btn_coll_distributed_systems',function(){openCollItem('distributed_systems');}],
    ['btn_coll_load_balancing',function(){openCollItem('load_balancing');}],
    ['btn_coll_search',function(){openCollItem('search');}],
    ['btn_coll_object_storage',function(){openCollItem('object_storage');}],
    ['btn_coll_message_queues',function(){openCollItem('message_queues');}],
    ['btn_coll_cdn_edge',function(){openCollItem('cdn_edge');}],
    ['btn_coll_observability',function(){openCollItem('observability');}]
  ];
  pairs.forEach(function(p){
    var el=document.getElementById(p[0]);
    if(el) el.addEventListener('click',p[1]);
  });
}
